Object.assign(window.TEM8_DICTIONARY, {"transcript":{"media":{"uk":"media/uk/transcript__gb_1.mp3","us":"media/us/transcript__us_1.mp3"},"oxford":{"phon":"ˈtrænskrɪpt","pos":"noun","senses":[{"en":"a written or printed copy of words that have been spoken","cn":"抄本；誊本；打印本","ex":{"en":"a transcript of the interview","cn":"采访内容的文字稿"}},{"en":"an official record of a student’s work that shows the courses they have taken and the grades they have achieved","cn":"学生成绩报告单","lab":"especially North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(根据录音或笔记整理的)笔录本，文字本，转写本","en":"A transcript of a conversation or speech is a written text of it, based on a recording or notes.","ex":{"en":"They wouldn't let me have a transcript of the interview.","cn":"他们拒绝给我一份采访的文字整理稿。"}}]},"examples":[{"en":"a transcript of the interview","cn":"采访内容的文字稿"},{"en":"A transcript of the tapes was presented in court.","cn":"在法庭上出示了这些磁带的转录本。"}]},"trusts":{"lemma":"trust","media":{"uk":"media/uk/trust__gb_1.mp3","us":"media/us/trust__us_1.mp3"}},"training":{"media":{"uk":"media/uk/training__gb_1.mp3","us":"media/us/training__us_1.mp3"},"oxford":{"phon":"ˈtreɪnɪŋ","pos":"noun","senses":[{"en":"the process of learning the skills that you need to do a job","cn":"训练；培训","lab":"British English","ex":{"en":"staff training","cn":"职工培训"}},{"en":"the process of preparing to take part in a sports competition by doing physical exercise","cn":"（为参加体育比赛而进行的）训练，锻炼","ex":{"en":"He suffered an ankle injury during training this week.","cn":"他在本周的训练中脚踝受伤。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"训练;培训","en":"Training is the process of learning the skills that you need for a particular job or activity.","ex":{"en":"He called for much higher spending on education and training","cn":"他呼吁在教育和培训方面加大投入。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(为了健身或体育活动而进行的)训练，锻炼","en":"Training is physical exercise that you do regularly in order to keep fit or to prepare for an activity such as a race.","ex":{"en":"The emphasis is on developing fitness through exercises and training.","cn":"重点在于通过锻炼促进健康。"}}]},"examples":[{"en":"Few candidates had received any training in management.","cn":"没有几个应聘者接受过管理培训。"},{"en":"to be in training for a race","cn":"在进行赛跑训练"}],"base":"train"},"trucks":{"lemma":"truck","media":{"img":["media/pic/trucks_comp.jpg"]}},"transparent":{"media":{"uk":"media/uk/transparent__gb_1.mp3","us":"media/us/transparent__us_1.mp3"},"oxford":{"phon":"trænsˈpærənt","pos":"adjective","senses":[{"en":"allowing you to see through it","cn":"透明的；清澈的","ex":{"en":"The insect's wings are almost transparent.","cn":"这昆虫的翅膀几乎是透明的。"}},{"en":"that you can easily see is false; allowing you to see the truth easily","cn":"易识破的；易看穿的；显而易见的","ex":{"en":"a transparent attempt to buy votes","cn":"明显收买选票的企图"}},{"en":"easy to understand","cn":"容易理解的；易懂的","ex":{"en":"a campaign to make official documents more transparent","cn":"简化公文语言的运动"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"透明的;清澈的","en":"If an object or substance is transparent, you can see through it.","ex":{"en":"...a sheet of transparent coloured plastic","cn":"透明有色塑料板"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易懂的;明晰的;一目了然的","en":"If a situation, system, or activity is transparent, it is easily understood or recognized.","ex":{"en":"We are now striving hard to establish a transparent parliamentary democracy…","cn":"我们现在正努力建立明晰的议会民主制。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易识破的;易察觉的","en":"You use transparent to describe a statement or action that is obviously dishonest or wrong, and that you think will not deceive people.","ex":{"en":"…a transparent effort by officials to blame foreigners…","cn":"官员指摘外国人的明显企图"}}]},"examples":[{"en":"The insect's wings are almost transparent.","cn":"这昆虫的翅膀几乎是透明的。"},{"en":"Am I that transparent? (= are my intentions that obvious?)","cn":"我的动机看来那么明显吗？"}]},"tray":{"media":{"img":["media/pic/packaging_comp.jpg","media/thumb/tray.jpg"],"uk":"media/uk/tray__gb_1.mp3","us":"media/us/tray__us_1.mp3"},"oxford":{"phon":"treɪ","pos":"noun","senses":[{"en":"a flat piece of wood, metal or plastic with raised edges, used for carrying or holding things, especially food","cn":"盘；托盘；碟","ex":{"en":"He brought her breakfast in bed on a tray.","cn":"他把早餐用托盘给她送到床上。"}},{"en":"a shallow plastic box, used for various purposes","cn":"（各种用途的）浅塑料盒","ex":{"en":"a seed tray (= for planting seeds in)","cn":"育苗盘"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"托盘;盘;碟","en":"A tray is a flat piece of wood, plastic, or metal, which usually has raised edges and which is used for carrying things, especially food and drinks."}]},"examples":[{"en":"He brought her breakfast in bed on a tray.","cn":"他把早餐用托盘给她送到床上。"},{"en":"She came in with a tray of drinks.","cn":"她端着一托盘饮料走进来。"}]},"trust":{"media":{"uk":"media/uk/trust__gb_1.mp3","us":"media/us/trust__us_1.mp3"},"oxford":{"phon":"trʌst","pos":"noun","senses":[{"en":"the belief that somebody/something is good, sincere, honest, etc. and will not try to harm or trick you","cn":"相信；信任；信赖","g":"[uncountable]","ex":{"en":"Our partnership is based on trust.","cn":"我们的伙伴关系建立在互相信任的基础上。"}},{"en":"the belief that something is true or correct or that you can rely on it","cn":"相信；认为可靠","g":"[uncountable]","ex":{"en":"We place so much trust in computers that it gets a little scary.","cn":"我们对计算机如此信赖，真让人有点害怕。"}},{"en":"an arrangement by which an organization or a group of people has legal control of money or property that has been given to somebody, usually until that person reaches a particular age; an amount of money or property that is controlled in this way","cn":"委托；信托；信托财产","g":"[countable, uncountable]","lab":"law","ex":{"en":"He set up a trust for his children.","cn":"他为子女安排好了信托财产。"}},{"en":"an organization or a group of people that invests money that is given or lent to it and uses the profits to help a charity","cn":"受托基金机构；受托团体","g":"[countable]","lab":"law","ex":{"en":"a charitable trust","cn":"慈善基金机构"}},{"en":"a group of companies that work together illegally to reduce competition, control prices, etc.","cn":"托拉斯（为减少竞争、操纵价格等而非法联合的企业组织）","g":"[countable]","lab":"especially North American English, business，，","ex":{"en":"anti-trust laws","cn":"反托拉斯法"}},{"en":"to have confidence in somebody; to believe that somebody is good, sincere, honest, etc.","cn":"信任；信赖；相信（某人的善良、真诚等）","ex":{"en":"She trusts Alan implicitly.","cn":"她绝对信任艾伦。"},"pos":"verb"},{"en":"to believe that something is true or correct or that you can rely on it","cn":"相信；认为可靠","ex":{"en":"He trusted her judgement.","cn":"他相信她的判断力。"},"pos":"verb"},{"en":"to hope and expect that something is true","cn":"想；希望；期望","lab":"formal","ex":{"en":"I trust (that) you have no objections to our proposals?","cn":"我想你不反对我们的建议吧？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"信任;信赖","en":"If you trust someone, you believe that they are honest and sincere and will not deliberately do anything to harm you.","ex":{"en":"'I trust you completely,' he said","cn":"“我完全信任你，”他说。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"信任;信赖","en":"Your trust in someone is your belief that they are honest and sincere and will not deliberately do anything to harm you.","ex":{"en":"He destroyed me and my trust in men","cn":"他毁了我，也摧毁了我对男人的信任。"}},{"pos":"VERB 动词","cn":"相信(某人会做某事)","en":"If you trust someone to do something, you believe that they will do it.","ex":{"en":"That's why I must trust you to keep this secret","cn":"那就是为什么我必须得相信你会保守这个秘密的原因。"}},{"pos":"VERB 动词","cn":"托付;托交","en":"If you trust someone with something important or valuable, you allow them to look after it or deal with it.","ex":{"en":"This could make your superiors hesitate to trust you with major responsibilities","cn":"这样会使上级不敢对你委以重任。"}},{"pos":"VERB 动词","cn":"确信;觉得…可靠;对…放心","en":"If you do not trust something, you feel that it is not safe or reliable.","ex":{"en":"She nodded, not trusting her own voice","cn":"她只点点头，没有说话。"}},{"pos":"VERB 动词","cn":"相信;认为…是正确的","en":"If you trust someone's judgment or advice, you believe that it is good or right.","ex":{"en":"Jake has raised two smashing kids and I trust his judgement…","cn":"杰克养大了两个了不起的孩子，我相信他的判断。"}},{"pos":"VERB 动词","cn":"希望…是对的;估计…是对的","en":"If you say you trust that something is true, you mean you hope and expect that it is true.","ex":{"en":"I trust you will take the earliest opportunity to make a full apology","cn":"我想你会一抓住机会就诚恳道歉的。"}},{"pos":"VERB 动词","cn":"坚信;深信;信仰","en":"If you trust in someone or something, you believe strongly in them, and do not doubt their powers or their good intentions.","ex":{"en":"He was a pastor who trusted in the Lord who lived to preach.","cn":"作为一名牧师，他相信上帝是用一生去传教的。"}},{"pos":"N-COUNT 可数名词","cn":"(财产)信托，托管","en":"A trust is a financial arrangement in which a group of people or an organization keeps and invests money for someone.","ex":{"en":"You could also set up a trust so the children can't spend any inheritance until they are a certain age…","cn":"你也可以设立财产信托，这样孩子们只有达到一定年龄才能动用遗产。"}},{"pos":"N-COUNT 可数名词","cn":"信托基金机构;财产托管机构","en":"A trust is a group of people or an organization that has control of an amount of money or property and invests it on behalf of other people or as a charity.","ex":{"en":"He had set up two charitable trusts","cn":"他已设立了两个慈善信托机构。"}},{"pos":"N-COUNT 可数名词","cn":"公立医院(由政府资助、独立经营)","en":"In Britain, a trust or a trust hospital is a public hospital that receives its funding directly from the national government. It has its own board of governors and is not controlled by the local health authority.","ex":{"en":"St Mary's Hospital in Paddington became a self-governing trust this week.","cn":"帕丁顿的圣玛丽医院这周成为政府资助的独立经营医院。"}},{"pos":"PHRASE 短语","cn":"受托管;被托管","en":"If something valuable is kept in trust, it is held and protected by a group of people or an organization on behalf of other people.","ex":{"en":"The British Library holds its collection in trust for the nation","cn":"大不列颠图书馆为国家保存被托管藏书。"}},{"pos":"PHRASE 短语","cn":"完全相信;对…毫不置疑","en":"If you take something on trust after having heard or read it, you believe it completely without checking it.","ex":{"en":"He was adamant that the allegations were untrue, so I took him on trust.","cn":"他坚持认为那些指控不属实，因此我也完全相信他。"}},{"pos":"","cn":"","en":"tried and trusted→see: ;"},{"pos":"","cn":"","en":"相关词组：trust to"}]},"examples":[{"en":"I stumbled along in the dark, trusting to luck to find the right door.","cn":"我摸黑跌跌撞撞地往前走，希望凭运气能找对门。"},{"en":"The money will be held in trust until she is 18.","cn":"这笔钱将由人代管到她 18 岁为止。"}]},"trends":{"lemma":"trend"},"truly":{"media":{"uk":"media/uk/truly__gb_1.mp3","us":"media/us/truly__us_1.mp3"},"oxford":{"phon":"ˈtruːli","pos":"adverb","senses":[{"en":"used to emphasize that a particular statement, feeling, etc. is sincere or real","cn":"（用于说法、感觉等）真诚地，诚恳地，衷心地","ex":{"en":"She truly believes that none of this is her fault.","cn":"她真的认为这一切都不是她的错。"}},{"en":"used to emphasize a particular quality","cn":"（指性质）真正，确实","ex":{"en":"The results are truly amazing.","cn":"结果真是太惊人了。"}},{"en":"used to emphasize that a particular description is accurate or correct","cn":"（指描述）确切，准确，精确，确实","lab":"informal","ex":{"en":"a truly democratic system of government","cn":"真正的民主政体"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"真正地;完全地","en":"You use truly to emphasize that something has all the features or qualities of a particular thing, or is the case to the fullest possible extent.","ex":{"en":"...a truly democratic system","cn":"真正民主的制度"}},{"pos":"ADV 副词","cn":"非常;很","en":"You can use truly in order to emphasize your description of something.","ex":{"en":"...a truly splendid man","cn":"非常优秀的人"}},{"pos":"ADV 副词","cn":"由衷地;真诚地;真挚地","en":"You use truly to emphasize that feelings are genuine and sincere.","ex":{"en":"Believe me, Susan, I am truly sorry","cn":"相信我，苏珊，我实在感到抱歉。"}},{"pos":"ADV 副词","cn":"的确;真的","en":"You can use truly in order to emphasize that what you are saying is true.","ex":{"en":"I truly never minded caring for Rusty…","cn":"我真的从不介意照顾拉斯蒂。"}},{"pos":"","cn":"","en":"well and truly→see: ;"},{"pos":"CONVENTION 惯用语","cn":"(用于正式信件末尾)你忠实的","en":"You write Yours truly at the end of a formal letter to someone you do not know very well. You write your signature after the words 'Yours truly'.","ex":{"en":"Yours truly, Phil Turner.","cn":"菲尔·特纳谨启"}},{"pos":"PHRASE 短语","cn":"我，鄙人","en":"You can say yours truly as a way of referring to yourself.","ex":{"en":"Yours truly was awoken by a shout: 'Ahoy there!'","cn":"鄙人被一声大喊惊醒：“喂！”"}}]},"examples":[{"en":"I'm truly sorry that things had to end like this.","cn":"事情落到这样的结局，我从内心里感到歉疚。"},{"en":"Steve came first, Robin second, and yours truly came last.","cn":"史蒂夫最先，罗宾第二，鄙人最后。"}]},"transforms":{"lemma":"transform"},"trial":{"media":{"uk":"media/uk/trial__gb_1.mp3","us":"media/us/trial__us_1.mp3"},"oxford":{"phon":"ˈtraɪəl","pos":"noun","senses":[{"en":"a formal examination of evidence in court by a judge and often a jury, to decide if somebody accused of a crime is guilty or not","cn":"（法院的）审讯，审理，审判","g":"[uncountable, countable]","lab":"especially North American English","sc":"law","ex":{"en":"a murder/criminal trial","cn":"谋杀案／刑事案的审理"}},{"en":"the process of testing the ability, quality or performance of somebody/something, especially before you make a final decision about them","cn":"（对能力、质量、性能等的）试验，试用","g":"[countable, uncountable]","sc":"test","ex":{"en":"a field/randomized/controlled trial","cn":"现场/随机/对照试验"}},{"en":"a competition or series of tests to find the best players for a sports team or an important event","cn":"预赛；选拔赛","g":"[countable, usually plural]","lab":"North American English also","sc":"in sport","ex":{"en":"Olympic trials","cn":"奥林匹克运动会选拔赛"}},{"en":"an event at which animals compete or perform","cn":"比赛；表演","g":"[countable, usually plural]","sc":"for animals","ex":{"en":"horse trials","cn":"马匹比赛"}},{"en":"an experience or a person that causes difficulties for somebody","cn":"令人伤脑筋的事；惹麻烦的人；考验","g":"[countable]","lab":"figurative","sc":"difficult experience","ex":{"en":"the trials and tribulations of married life","cn":"婚姻生活的考验与磨炼"}},{"en":"to test the ability, quality or performance of something to see if it will be effective or successful","cn":"测试（能力、质量、性能等）；试验；试用","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"审讯;审理;审判","en":"A trial is a formal meeting in a law court, at which a judge and jury listen to evidence and decide whether a person is guilty of a crime.","ex":{"en":"New evidence showed the police lied at the trial","cn":"新的证据表明警方在审讯时撒了谎。"}},{"pos":"N-VAR 可变名词","cn":"试验;试用","en":"A trial is an experiment in which you test something by using it or doing it for a period of time to see how well it works. If something is on trial, it is being tested in this way.","ex":{"en":"They have been treated with this drug in clinical trials","cn":"他们已在临床试验中接受过这种药物的治疗。"}},{"pos":"N-COUNT 可数名词","cn":"(人员的)试用，试用期","en":"If someone gives you a trial for a job, or if you are on trial, you do the job for a short period of time to see if you are suitable for it.","ex":{"en":"He had just given a trial to a young woman who said she had previous experience","cn":"他刚给了一位声称自己有从业经验的年轻女子一次试用机会。"}},{"pos":"N-COUNT 可数名词","cn":"磨难;痛苦;麻烦","en":"If you refer to the trials of a situation, you mean the unpleasant things that you experience in it.","ex":{"en":"...the trials of adolescence.","cn":"青春期的苦恼"}},{"pos":"N-COUNT 可数名词","cn":"预赛;选拔赛;测试赛","en":"In some sports or outdoor activities, trials are a series of contests that test a competitor's skill and ability.","ex":{"en":"He has been riding in horse trials for less than a year.","cn":"他参加赛马选拔赛还不到一年。"}},{"pos":"PHRASE 短语","cn":"通过反复试验；经过不断摸索","en":"If you do something by trial and error, you try several different methods of doing it until you find the method that works properly.","ex":{"en":"Many drugs were found by trial and error","cn":"很多药物都是通过反复试验才发现的。"}},{"pos":"PHRASE 短语","cn":"在受审中","en":"If someone is on trial, they are being tried in a court of law.","ex":{"en":"He is currently on trial accused of serious drugs charges","cn":"他目前正因严重的毒品控罪而受审。"}},{"pos":"PHRASE 短语","cn":"在测试中;在考察中;在考验中","en":"If you say that someone or something is on trial, you mean that they are in a situation where people are observing them to see whether they succeed or fail.","ex":{"en":"The President will be drawn into a damaging battle in which his credentials will be on trial.","cn":"总统将被卷入一场造成负面影响的争斗中，他的资格会因此受到考验。"}},{"pos":"PHRASE 短语","cn":"受审判","en":"If someone stands trial, they are tried in court for a crime they are accused of.","ex":{"en":"He was found to be mentally unfit to stand trial…","cn":"他被判定精神状况不宜接受审判。"}}]},"examples":[{"en":"Children learn to use computer programs by trial and error.","cn":"儿童通过反复摸索才学会运用计算机程序。"},{"en":"The men were arrested but not brought to trial.","cn":"这些人已被逮捕但并未送交法院审判。"}]},"treacly":{"media":{"uk":"media/uk/treacly__gb_1.mp3","us":"media/us/treacly__us_1.mp3"},"oxford":{"phon":"ˈtriːkli","pos":"adjective","senses":[{"en":"like treacle","cn":"像糖浆的；糖蜜似的","lab":"British English","ex":{"en":"a treacly brown liquid","cn":"糖浆状的棕色液体"}},{"en":"expressing feelings of love in a way that seems false or exaggerated","cn":"虚情假意的；过分多情的","ex":{"en":"treacly music","cn":"甜腻腻的音乐"}}]},"examples":[{"en":"a treacly brown liquid","cn":"糖浆状的棕色液体"},{"en":"treacly music","cn":"甜腻腻的音乐"}]},"trading":{"media":{"uk":"media/uk/trading__gb_1.mp3","us":"media/us/trading__us_1.mp3"},"oxford":{"phon":"ˈtreɪdɪŋ","pos":"noun","senses":[{"en":"the activity of buying and selling things","cn":"贸易；经商；营业；交易","ex":{"en":"new laws on Sunday trading (= shops being open on Sundays)","cn":"关于星期日营业的新法律"}}]},"examples":[{"en":"Shares worth $8 million changed hands during a day of hectic trading.","cn":"当日交投活跃，股票转手市值达 800 万元。"},{"en":"Supermarkets everywhere reported excellent trading in the run-up to Christmas.","cn":"各地超级市场报告说圣诞节前生意火爆。"}]},"transfer":{"media":{"uk":"media/uk/transfer__gb_1.mp3","us":"media/us/transfer__us_1.mp3"},"oxford":{"phon":"trænsˈfɜː(r)","pos":"verb","senses":[{"en":"to move from one place to another; to move something/somebody from one place to another","cn":"（使）转移，搬迁","g":"[intransitive, transitive]","lab":"especially North American English","sc":"to new place","ex":{"en":"The film studio is transferring to Hollywood.","cn":"这家电影制片厂正迁往好莱坞。"}},{"en":"to move from one job, school, situation, etc. to another; to arrange for somebody to move","cn":"（使）调动；转职；转学；改变（环境）","g":"[intransitive, transitive]","sc":"to new job/school/situation","ex":{"en":"Children usually transfer to secondary school at 11 or 12.","cn":"儿童通常在 11 或 12 岁时升读中学。"}},{"en":"to change to a different vehicle during a journey; to arrange for somebody to change to a different vehicle during a journey","cn":"（使在旅途中）转乘，换乘，倒车","g":"[intransitive, transitive]","sc":"to new vehicle","ex":{"en":"It was a relief, after transferring from ship to ship, to just sit and relax.","cn":"不断地换乘轮船之后能坐下来休息会儿真舒服。"}},{"en":"to copy information, music, an idea, etc. from one method of recording or presenting it to another; to be recorded or presented in a different way","cn":"转存，转录（资料、音乐等）；改编","g":"[transitive, intransitive]","sc":"information/music, etc.","ex":{"en":"You can transfer data to a memory stick in a few seconds.","cn":"你可以在几秒钟内将数据转存到 U 盘。"}},{"en":"if you transfer a feeling, a disease, or power, etc. from one person to another, the second person has it, often instead of the first","cn":"转移（感情）；传染（疾病）；让与，转让（权力等）","g":"[transitive]","sc":"feeling/disease/power","ex":{"en":"Joe had already transferred his affections from Lisa to Cleo.","cn":"乔已移情别恋，把爱意从莉萨转移到了克利奥身上。"}},{"en":"to officially arrange for something to belong to somebody else or for somebody else to control something","cn":"转让；让与","g":"[transitive]","sc":"property","ex":{"en":"He transferred the property to his son.","cn":"他把财产转让给了儿子。"}},{"en":"to move, or to move somebody, to a different sports team, especially a professional football (soccer) team","cn":"转会，使转会（尤指职业足球队）","g":"[intransitive, transitive]","lab":"especially British English","sc":"in sport","ex":{"en":"He transferred to Everton for £60 million.","cn":"他以 6 000 万英镑的转会费转到埃弗顿队。"}},{"en":"to send a phone call that you have received to another phone number","cn":"转接（某人的电话）","g":"[transitive]","sc":"phone call","ex":{"en":"I'll just transfer you to customer service.","cn":"我这就给你转接客户服务部。"}},{"en":"the act of moving somebody/something from one place, group or job to another; an occasion when this happens","cn":"搬迁；转移；调动；变换","g":"[uncountable, countable]","sc":"change of place/job/situation","ex":{"en":"electronic data transfer","cn":"电子数据传输"},"pos":"noun"},{"en":"an act of changing to a different place, vehicle or route when you are travelling","cn":"（旅途中的）中转，换乘，改变路线","g":"[uncountable, countable]","sc":"change of vehicle","ex":{"en":"The transfer from the airport to the hotel is included in the price.","cn":"票价包括从机场转车到旅馆的费用。"},"pos":"noun"},{"en":"a ticket that allows a passenger to continue their journey on another bus or train","cn":"转车票；换乘票","g":"[countable]","lab":"North American English","sc":"train/bus ticket","pos":"noun"},{"en":"the act of moving a sports player from one club or team to another","cn":"（运动员）转会","g":"[uncountable, countable]","sc":"in sport","ex":{"en":"It was the first goal he had scored since his transfer from Chelsea.","cn":"这是他从切尔西队转会过来之后的第一粒进球。"},"pos":"noun"},{"en":"a picture or design that can be removed from a piece of paper and stuck onto a surface, for example by being pressed or heated","cn":"转印图画，转印图案（利用挤压或加热，可从纸上转印到物体的表面）","g":"[countable]","lab":"especially British English","sc":"picture","pos":"noun"},{"en":"the process of using behaviour that has already been learnt in one situation in a new situation","cn":"迁移（将已习得的行为在新的情况下应用）","g":"[uncountable]","lab":"psychology","sc":"psychology","pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)转移;(使)迁移","en":"If you transfer something or someone from one place to another, or they transfer from one place to another, they go from the first place to the second.","ex":{"en":"Remove the wafers with a spoon and transfer them to a plate","cn":"用勺子抄起薄饼，把它们转盛到盘子里。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)转移，传播，移交","en":"If something is transferred, or transfers ,from one person or group of people to another, the second person or group gets it instead of the first.","ex":{"en":"I realized she'd transferred all her love from me to you","cn":"我意识到她已把所有的爱从我身上转移到了你身上。"}},{"pos":"N-VAR 可变名词","cn":"(技术)转让","en":"Technology transfer is the process or act by which a country or organization which has developed new technology enables another country or organization to use the technology.","ex":{"en":"The Philippines needs capital and technology transfer","cn":"菲律宾需要资本与技术转让。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(运动员)转会","en":"In professional sports, if a player transfers or is transferred from one club to another, they leave one club and begin playing for another.","ex":{"en":"...Nick Barmby who transferred from Spurs to Middlesbrough","cn":"从热刺队转会到米德尔斯伯勒队的尼克·巴尔姆比"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）调动;（使）换岗","en":"If you are transferred, or if you transfer ,to a different job or place, you move to a different job or start working in a different place.","ex":{"en":"I was transferred to the book department","cn":"我被调到图书部。"}},{"pos":"VERB 动词","cn":"转存;转录","en":"When information is transferred onto a different medium, it is copied from one medium to another.","ex":{"en":"Such information is easily transferred onto microfilm.","cn":"这种信息很容易转存到缩微胶卷上。"}},{"pos":"VERB 动词","cn":"转让，让与(财产、土地)","en":"When property or land is transferred, it stops being owned by one person or institution and becomes owned by another.","ex":{"en":"He has already transferred ownership of most of the works to a British foundation","cn":"他已把大部分作品的所有权转让给一家英国基金会。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)转乘;(使)换乘","en":"If you transfer or are transferred when you are on a journey, you change from one vehicle to another.","ex":{"en":"He likes to transfer from the bus to the Blue Line at 103rd Street in Watts","cn":"他喜欢在华兹区第 103 大街下公交车转乘地铁蓝线。"}},{"pos":"N-COUNT 可数名词","cn":"转印纸(纸上面印有图案，可通过加热或压力转印至其他材料上)","en":"Transfers are pieces of paper with a design on one side. The design can be transferred by heat or pressure onto material, paper, or china for decoration.","ex":{"en":"...gold letter transfers.","cn":"金字转印纸"}},{"pos":"N-COUNT 可数名词","cn":"换乘票;转车票;通票","en":"A transfer is a ticket that you get when you leave a bus or train that allows you to go on a different bus or train without paying again."}]},"examples":[{"en":"He transferred to UCLA after his freshman year.","cn":"他读完大学一年级后，转学到加利福尼亚大学洛杉矶分校。"},{"en":"( especially NAmE ) If I spend a semester in Madrid, will my credits transfer?","cn":"如果我在马德里上一学期的课，我的学分能转过来吗？"}]},"trillion":{"oxford":{"phon":"ˈtrɪljən","pos":"number","senses":[{"en":"1 000 000 000 000; one million million","cn":"万亿；兆"},{"en":"a very large amount","cn":"大量；无数","lab":"informal"},{"en":"one million million million; 1 000 000 000 000 000 000","cn":"百万兆","lab":"old-fashioned, British English，，"}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"万亿;兆","en":"A trillion is a million million.","ex":{"en":"Between July 1st and October 1st, the central bank printed over 2 trillion roubles.","cn":"在 7 月 1 日至 10 月1日之间，中央银行印发了逾两万亿卢布。"}}]},"media":{"uk":"media/uk/trillion__gb_1.mp3","us":"media/us/trillion__us_1.mp3"},"examples":[{"en":"In a short time the number of cells is more than a trillion.","cn":"不久细胞的数量就超过了一万亿。"},{"en":"Japan’s exports were worth $43 trillion last year.","cn":"去年日本的出口商品价值43万亿美元。"}]},"transcendental":{"oxford":{"phon":"ˌtrænsenˈdentl","pos":"adjective","senses":[{"en":"going beyond the usual limits of human knowledge, experience or reason, especially in a religious or spiritual way","cn":"（尤指宗教或精神方面）超验的，玄奥的","ex":{"en":"a transcendental experience","cn":"超验的感受"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"超验的;超越一般常识(或信念)的","en":"Transcendental refers to things that lie beyond the practical experience of ordinary people, and cannot be discovered or understood by ordinary reasoning.","ex":{"en":"...the transcendental nature of God.","cn":"上帝的超验本质"}}]},"media":{"uk":"media/uk/transcendental__gb_1.mp3","us":"media/us/transcendental__us_1.mp3"},"examples":[{"en":"a transcendental experience","cn":"超凡的感受"}]},"trainer":{"oxford":{"phon":"ˈtreɪnə(r)","pos":"noun","senses":[{"en":"a shoe that you wear for sports or as informal clothing","cn":"运动鞋；便鞋","g":"[usually plural]","lab":"both British English","ex":{"en":"a pair of trainers","cn":"一双运动鞋"}},{"en":"a person who teaches people or animals to perform a particular job or skill well, or to do a particular sport","cn":"教员；驯兽师；教练员","ex":{"en":"teacher trainers","cn":"培训师资的教员"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(休闲)运动鞋;跑鞋","en":"Trainers are shoes that people wear, especially for running and other sports."}]},"media":{"img":["media/pic/shoes_comp.jpg","media/thumb/trainer.jpg"],"uk":"media/uk/trainer__gb_1.mp3","us":"media/us/trainer__us_1.mp3"},"examples":[{"en":"Her trainer had decided she shouldn't run in the race.","cn":"她的教练决定她不应参加赛跑。"},{"en":"teacher trainers","cn":"培训师资的教员"}]},"tremolo":{"media":{"uk":"media/uk/tremolo__gb_1.mp3","us":"media/us/tremolo__us_1.mp3"},"oxford":{"phon":"ˈtremələʊ","pos":"noun","senses":[{"en":"a special effect in singing or playing a musical instrument made by repeating the same note or two notes very quickly","cn":"（演唱或乐器演奏的）震音"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（歌声或说话声中的）颤音,震音","en":"If someone's singing or speaking voice has a tremolo in it, it moves up and down instead of staying on the same note."}]}},"trace":{"media":{"uk":"media/uk/trace__gb_1.mp3","us":"media/us/trace__us_1.mp3"},"oxford":{"phon":"treɪs","pos":"verb","senses":[{"en":"to find or discover somebody/something by looking carefully for them/it","cn":"查出；找到；发现；追踪","ex":{"en":"We finally traced him to an address in Chicago.","cn":"我们终于追查到他在芝加哥的一个地址。"}},{"en":"to find the origin or cause of something","cn":"追溯；追究","ex":{"en":"She could trace her family tree back to the 16th century.","cn":"她能把本族家谱追溯到 16 世纪。"}},{"en":"to describe a process or the development of something","cn":"描绘（事物的过程或发展）；追述；记述","ex":{"en":"Her book traces the town's history from Saxon times to the present day.","cn":"她的书描述的是这个市镇从撒克逊时代到现在的历史。"}},{"en":"to draw a line or lines on a surface","cn":"画（线）","ex":{"en":"She traced a line in the sand.","cn":"她在沙地上画了一条线。"}},{"en":"to follow the shape or outline of something","cn":"绘出，勾画出（轮廓）","ex":{"en":"He traced the route on the map.","cn":"他在地图上勾画出了路线。"}},{"en":"to copy a map, drawing, etc. by drawing on tracing paper (= paper that you can see through) placed over it","cn":"（用透明纸覆盖在地图、绘画等上）复制，描摹"},{"en":"a mark, an object or a sign that shows that somebody/something existed or was present","cn":"痕迹；遗迹；踪迹","g":"[countable, uncountable]","ex":{"en":"It's exciting to discover traces of earlier civilizations.","cn":"发现早期文明的遗迹，真令人兴奋。"},"pos":"noun"},{"en":"a very small amount of something","cn":"微量；少许","g":"[countable]","ex":{"en":"The post-mortem revealed traces of poison in his stomach.","cn":"验尸发现他胃中有微量毒物。"},"pos":"noun"},{"en":"a line or pattern on paper or a screen that shows information that is found by a machine","cn":"描记图；轨迹；迹线；扫描线","g":"[countable]","lab":"specialist","ex":{"en":"The trace showed a normal heart rhythm.","cn":"描记图显示心率正常。"},"pos":"noun"},{"en":"a search to find out information about the identity of somebody/something, especially what number a phone call was made from","cn":"（对信息的）跟踪，追踪","g":"[countable]","ex":{"en":"The police ran a trace on the call.","cn":"警察对那次通话进行了追踪。"},"pos":"noun"},{"en":"one of the two long pieces of leather that fasten a carriage or cart to the horse that pulls it","cn":"挽绳；套绳","g":"[countable, usually plural]","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"追溯;查考;探索","en":"If you trace the origin or development of something, you find out or describe how it started or developed.","ex":{"en":"The exhibition traces the history of graphic design in America from the 19th century to the present","cn":"展览追溯了美国从19世纪至今的平面设计历史。"}},{"pos":"VERB 动词","cn":"查出;探出;找到","en":"If you trace someone or something, you find them after looking for them.","ex":{"en":"Police are anxious to trace two men seen leaving the house just before 8am","cn":"早上将近8点时有人看到两名男子离开那所房子，警方急于找到他们。"}},{"pos":"VERB 动词","cn":"(用手指或脚尖等在表面上)勾画…的轮廓，描绘，勾勒","en":"If you trace something such as a pattern or a shape, for example with your finger or toe, you mark its outline on a surface.","ex":{"en":"I traced the course of the river on the map.","cn":"我在地图上勾勒出这条河的流向。"}},{"pos":"VERB 动词","cn":"(把透明纸覆盖在底样上)映描，描摹","en":"If you trace a picture, you copy it by covering it with a piece of transparent paper and drawing over the lines underneath.","ex":{"en":"She learned to draw by tracing pictures out of old storybooks.","cn":"她通过描摹旧故事书上的图画学会了画画。"}},{"pos":"N-COUNT 可数名词","cn":"少许;微量","en":"A trace of something is a very small amount of it.","ex":{"en":"Wash them in cold water to remove all traces of sand","cn":"用冷水冲洗它们以清除所有的沙子。"}},{"pos":"N-COUNT 可数名词","cn":"痕迹;遗迹;踪迹;足迹","en":"A trace is a sign which shows you that someone or something has been in a place.","ex":{"en":"The local church has traces of fifteenth-century frescoes…","cn":"当地教堂仍留有 15 世纪壁画的遗迹。"}},{"pos":"PHRASE 短语","cn":"销声匿迹;迅速沉寂","en":"If you say that someone or something sinks without trace or sinks without a trace, you mean that they stop existing or stop being successful very suddenly and completely.","ex":{"en":"The Social Democratic Party has sunk without trace at these elections","cn":"社会民主党在这些选举中已销声匿迹。"}},{"pos":"","cn":"","en":"相关词组：trace back"}]},"examples":[{"en":"The police traced the call (= used special electronic equipment to find out who made the telephone call) to her ex-husband's number.","cn":"警方用追踪装置查出是她前夫的电话号码打出的电话。"},{"en":"Her book traces the town's history from Saxon times to the present day.","cn":"她的书描述的是这个市镇从撒克逊时代到现在的历史。"}]},"tricks":{"lemma":"trick"},"treasury":{"oxford":{"phon":"ˈtreʒəri","pos":"noun","senses":[{"en":"(in the UK, the US and some other countries) the government department that controls public money","cn":"（英国、美国和其他一些国家的）财政部","g":"[singular + singular or plural verb]"},{"en":"a place in a castle, etc. where valuable things are stored","cn":"（城堡等中的）金银财宝库，宝库","g":"[countable]","ex":{"en":"Semi-precious stones were found in the treasury of the old monastery.","cn":"在古老修道院的宝库中发现了半宝石。"}}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"(英、美等国的)财政部","en":"In Britain, the United States, and some other countries, the Treasury is the government department that deals with the country's finances.","ex":{"en":"The Treasury has long been predicting an upturn in consumer spending.","cn":"财政部早就预测消费者支出会出现上扬。"}},{"pos":"N-COUNT 可数名词","cn":"(城堡、教堂等的)宝库，珍藏室","en":"The treasury in a building such as a castle or a church is a room where valuable objects are displayed or stored."}]},"media":{"uk":"media/uk/treasury__gb_1.mp3","us":"media/us/treasury__us_1.mp3"}},"transcripts":{"lemma":"transcript","media":{"uk":"media/uk/transcript__gb_1.mp3","us":"media/us/transcript__us_1.mp3"}},"trajectory":{"media":{"uk":"media/uk/trajectory__gb_1.mp3","us":"media/us/trajectory__us_1.mp3","img":["media/ldoce/img/ldoce_248.png"]},"oxford":{"phon":"trəˈdʒektəri","pos":"noun","senses":[{"en":"the curved path of something that has been fired, hit or thrown into the air","cn":"（射体在空中的）轨道，弹道，轨迹","lab":"figurative","ex":{"en":"a missile’s trajectory","cn":"导弹的弹道"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"轨道;轨迹","en":"The trajectory of a moving object is the path that it follows as it moves.","ex":{"en":"...the trajectory of an artillery shell.","cn":"一枚炮弹的弹道"}},{"pos":"N-COUNT 可数名词","cn":"(事业等的)发展轨迹，起落","en":"The trajectory of something such as a person's career is the course that it follows over time.","ex":{"en":"...a relentlessly upward career trajectory.","cn":"扶摇直上的事业轨迹"}}]},"examples":[{"en":"( figurative ) My career seemed to be on a downward trajectory.","cn":"我的事业似乎在走下坡路。"},{"en":"My career seemed to be on a downward trajectory.","cn":""}]},"treating":{"lemma":"treat","media":{"uk":"media/uk/treat__gb_1.mp3","us":"media/us/treat__us_1.mp3"}},"tricking":{"lemma":"trick"},"transcendent":{"media":{"uk":"media/uk/transcendent__gb_1.mp3","us":"media/us/transcendent__us_1.mp3"},"oxford":{"phon":"trænˈsendənt","pos":"adjective","senses":[{"en":"going beyond the usual limits; extremely great","cn":"卓越的；杰出的；极其伟大的","ex":{"en":"a writer of transcendent genius","cn":"杰出的天才作家。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"超越的;卓越的;杰出的","en":"Something that is transcendent goes beyond normal limits or boundaries, because it is more significant than them.","ex":{"en":"...the idea of a transcendent God who stood apart from mankind.","cn":"独立于人类之外的至高无上的上帝的概念"}}]},"examples":[{"en":"the transcendence of God","cn":"上帝的至高无上"},{"en":"the transcendent genius of Mozart","cn":"莫扎特的超凡天才"}]},"trade":{"media":{"uk":"media/uk/trade__gb_1.mp3","us":"media/us/trade__us_1.mp3"},"oxford":{"phon":"treɪd","pos":"noun","senses":[{"en":"the activity of buying and selling or of exchanging goods or services between people or countries","cn":"贸易；买卖；商业；交易","g":"[uncountable]","lab":"North American English","ex":{"en":"international/foreign/global/world trade","cn":"国际／对外／全球／世界贸易"}},{"en":"a particular type of business","cn":"行业；职业；生意","g":"[countable]","ex":{"en":"the building/food/tourist trade","cn":"建筑／食品／旅游业"}},{"en":"a particular area of business and the people or companies that are connected with it","cn":"同业；同行；同人","g":"[singular + singular or plural verb]","ex":{"en":"They offer discounts to the trade (= to people who are working in the same business).","cn":"他们对同行业的人给予折扣。"}},{"en":"the amount of goods or services that you sell","cn":"营业额；交易量","g":"[uncountable, countable]","ex":{"en":"Trade was very good last month.","cn":"上月的交易量很大。"}},{"en":"a job, especially one that involves working with your hands and that requires special training and skills","cn":"（尤指手工）职业；手艺；行当","g":"[uncountable, countable]","ex":{"en":"He was a carpenter by trade.","cn":"他以木工为业。"}},{"en":"to buy and sell things","cn":"做买卖；做生意；从事贸易","g":"[intransitive, transitive]","ex":{"en":"The firm openly traded in arms.","cn":"这家公司公开买卖军火。"},"pos":"verb"},{"en":"to exist and operate as a business or company","cn":"营业；营运","g":"[intransitive]","ex":{"en":"The firm has now ceased trading.","cn":"这家商行现已停业。"},"pos":"verb"},{"en":"to be bought and sold, or to buy and sell something, on a stock exchange","cn":"（在证券交易所）交易，买卖","g":"[intransitive, transitive]","ex":{"en":"Shares were trading at under half their usual value.","cn":"那些股票以低于通常价值的一半买卖。"},"pos":"verb"},{"en":"to exchange something that you have for something that somebody else has","cn":"互相交换；以物易物","g":"[transitive]","ex":{"en":"to trade secrets/insults/jokes","cn":"互换秘密；对骂；互说笑话"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"贸易;买卖;交易","en":"Trade is the activity of buying, selling, or exchanging goods or services between people, firms, or countries.","ex":{"en":"The ministry had direct control over every aspect of foreign trade.","cn":"该政府部门直接掌控着外贸的各个方面。"}},{"pos":"VERB 动词","cn":"做买卖;做生意;从事贸易","en":"When people, firms, or countries trade, they buy, sell, or exchange goods or services between themselves.","ex":{"en":"They may refuse to trade, even when offered attractive prices","cn":"即便对方的报价很有吸引力,他们也有可能拒绝进行交易。"}},{"pos":"N-COUNT 可数名词","cn":"(某一)生意，行业","en":"A trade is a particular area of business or industry.","ex":{"en":"They've completely ruined the tourist trade for the next few years.","cn":"他们把今后几年的旅游业完全给毁了。"}},{"pos":"N-COUNT 可数名词","cn":"职业;手艺;行当","en":"Someone's trade is the kind of work that they do, especially when they have been trained to do it over a period of time.","ex":{"en":"He learnt his trade as a diver in the North Sea","cn":"他在北海学会了潜水员这一行的本事。"}},{"pos":"V-RECIP 相互动词","cn":"用…进行交换;互相交换","en":"If someone trades one thing for another or if two people trade things, they agree to exchange one thing for the other thing.","ex":{"en":"They traded land for goods and money","cn":"他们用土地换取了货物与金钱。"}},{"pos":"V-RECIP 相互动词","cn":"交换，对换(位置或处境)","en":"If you trade places with someone or if the two of you trade places, you move into the other person's position or situation, and they move into yours.","ex":{"en":"Mike asked George to trade places with him so he could ride with Tod","cn":"迈克要求乔治和他交换位置，让他和托德同坐一辆车。"}},{"pos":"VERB 动词","cn":"使(足球、棒球等职业运动员)转会","en":"In professional sports, for example football or baseball, if a player is traded from one team to another, they leave one team and begin playing for another.","ex":{"en":"He was traded from the Giants to the Yankees","cn":"他从巨人队转会到扬基队。"}},{"pos":"V-RECIP 相互动词","cn":"互相做;对打;对骂","en":"If two people or groups trade something such as blows, insults, or jokes, they hit each other, insult each other, or tell each other jokes.","ex":{"en":"Children would settle disputes by trading punches or insults in the schoolyard","cn":"儿童会通过在操场上对打或互骂的方式解决争端。"}},{"pos":"","cn":"","en":"相关词组：trade down trade in trade off trade on trade up"}]},"examples":[{"en":"Shoppers are trading down and looking for bargains.","cn":"到商店买东西的人都降低消费，寻找减价货。"},{"en":"They were attempting to trade off inflation against unemployment.","cn":"他们正力求在通货膨胀和失业之间进行协调。"}]},"transported":{"lemma":"transport","media":{"uk":"media/uk/transport__gb_1.mp3","us":"media/us/transport__us_1.mp3"}},"trainers":{"lemma":"trainer","media":{"img":["media/ldoce/img/trainers.jpg"]}},"trumpet":{"oxford":{"phon":"ˈtrʌmpɪt","pos":"noun","senses":[{"en":"a brass musical instrument made of a curved metal tube that you blow into, with three valves for changing the note","cn":"小号；喇叭","ex":{"en":"the shrill blast of a trumpet","cn":"刺耳的号声"}},{"en":"a thing like a trumpet in shape, especially the open flower of a daffodil","cn":"喇叭形物；（尤指）绽开的水仙花"},{"en":"to talk or write about something publicly in a proud or enthusiastic way","cn":"宣扬；鼓吹；吹嘘","g":"[transitive]","ex":{"en":"to trumpet somebody’s achievements","cn":"吹嘘某人的成就"},"pos":"verb"},{"en":"to make a loud noise","cn":"吼叫","g":"[intransitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"小号;喇叭","en":"A trumpet is a musical instrument of the brass family which plays quite high notes."},{"pos":"VERB 动词","cn":"大力鼓吹;积极宣扬;大力宣传","en":"If someone trumpets something that they are proud of or that they think is important, they speak about it publicly in a very forceful way.","ex":{"en":"The government has been trumpeting tourism as a growth industry","cn":"政府一直积极宣扬旅游业是快速发展型产业。"}},{"pos":"VERB 动词","cn":"(象)吼叫","en":"When an elephant trumpets, it makes a loud sound.","ex":{"en":"The elephants trumpeted and stamped their feet at their approach.","cn":"当他们靠近时，大象又吼又跺脚。"}},{"pos":"","cn":"","en":"blow your own trumpet→see: ;"}]},"media":{"img":["media/ldoce/img/trumpet.jpg","media/pic/brass_musicalinstruments_comp.jpg"],"uk":"media/uk/trumpet__gb_1.mp3","us":"media/us/trumpet__us_1.mp3"},"examples":[{"en":"Their marriage was trumpeted as the wedding of the year.","cn":"他们的联姻被宣扬成年度婚礼。"},{"en":"to trumpet somebody's achievements","cn":"吹嘘某人的成就"}]},"tropical":{"media":{"img":["media/ldoce/img/tropical.jpg","media/pic/tropical_fruit_comp.jpg"],"uk":"media/uk/tropical__gb_1.mp3","us":"media/us/tropical__us_1.mp3"},"oxford":{"phon":"ˈtrɒpɪkl","pos":"adjective","senses":[{"en":"coming from, found in or typical of the tropics","cn":"热带的；来自热带的；产于热带的","ex":{"en":"tropical fish/birds/fruit","cn":"热带鱼／鸟／水果"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"热带的;有热带特征的","en":"Tropical means belonging to or typical of the tropics.","ex":{"en":"...tropical diseases.","cn":"热带疾病"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"湿热的;典型热带气候的","en":"Tropical weather is hot and damp weather that people believe to be typical of the tropics."}]},"examples":[{"en":"a tropical island","cn":"位于热带地区的岛"},{"en":"tropical Africa","cn":"热带非洲"}]},"tremendous":{"media":{"uk":"media/uk/tremendous__gb_1.mp3","us":"media/us/tremendous__us_1.mp3"},"oxford":{"phon":"trəˈmendəs","pos":"adjective","senses":[{"en":"very great","cn":"巨大的；极大的","ex":{"en":"a tremendous explosion","cn":"巨大的爆炸声"}},{"en":"extremely good","cn":"极好的；精彩的；了不起的","ex":{"en":"It was a tremendous experience.","cn":"这是个了不起的经历。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"巨大的;极大的;大量的","en":"You use tremendous to emphasize how strong a feeling or quality is, or how large an amount is.","ex":{"en":"I felt a tremendous pressure on my chest","cn":"我感到胸口堵得难受。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精彩的;出色的;极好的","en":"You can describe someone or something as tremendous when you think they are very good or very impressive.","ex":{"en":"He was a tremendous person…","cn":"他是个非常了不起的人。"}}]},"examples":[{"en":"A tremendous amount of work has gone into the project.","cn":"大量的工作已投入到这项工程。"},{"en":"It was a tremendous experience.","cn":"这是个了不起的经历。"}]},"treaty":{"oxford":{"phon":"ˈtriːti","pos":"noun","senses":[{"en":"a formal agreement between two or more countries","cn":"（国家之间的）条约，协定","ex":{"en":"the Treaty of Rome","cn":"《罗马条约》"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(国家间的)条约，协定","en":"A treaty is a written agreement between countries in which they agree to do a particular thing or to help each other.","ex":{"en":"…the Treaty of Rome, which established the European Community.","cn":"建立了欧洲共同体的《罗马条约》"}}]},"media":{"uk":"media/uk/treaty__gb_1.mp3","us":"media/us/treaty__us_1.mp3"},"examples":[{"en":"Under the terms of the treaty , La Rochelle was ceded to the English.","cn":"根据这个条约的条款，拉罗谢尔割让给了英国人。"},{"en":"to draw up/sign/ratify a treaty","cn":"起草/签署/正式批准条约"}]},"translate":{"media":{"uk":"media/uk/translate__gb_1.mp3","us":"media/us/translate__us_1.mp3"},"oxford":{"phon":"trænzˈleɪt","pos":"verb","senses":[{"en":"to express the meaning of speech or writing in a different language","cn":"翻译；译","g":"[transitive, intransitive]","ex":{"en":"He translated the letter into English.","cn":"他把这封信译成了英文。"}},{"en":"to be changed from one language to another","cn":"被翻译；被译成","g":"[intransitive]","ex":{"en":"Most poetry does not translate well.","cn":"诗歌大多翻译不好。"}},{"en":"to change something into a different form; to lead to a particular result","cn":"（使）转变，变为","g":"[transitive, intransitive]","ex":{"en":"It's time to translate words into action.","cn":"是把言语化为行动的时候了。"}},{"en":"to understand something in a particular way or give something a particular meaning","cn":"（以某种方式）理解；给予（某种含义）","g":"[transitive, intransitive]","ex":{"en":"the various words and gestures that we translate as love","cn":"我们理解为爱的各种言语和姿势"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"翻译;译","en":"If something that someone has said or written is translated from one language into another, it is said or written again in the second language.","ex":{"en":"Only a small number of Kadare's books have been translated into English","cn":"卡达雷的书仅有一小部分译成了英文。"}},{"pos":"VERB 动词","cn":"(在另一语言中)意为，意思是","en":"If a name, a word, or an expression translates as something in a different language, that is what it means in that language.","ex":{"en":"His family's Cantonese nickname for him translates as Never Sits Still.","cn":"家人为他起的广东话绰号意思是Never Sits Still(从来坐不住)。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)转变为;(使)转化为","en":"If one thing translates or is translated into another, the second happens or is done as a result of the first.","ex":{"en":"Reforming Warsaw's stagnant economy requires harsh measures that would translate into job losses","cn":"重整华沙停滞的经济需要强硬措施，这会造成工作岗位的裁减。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(将…)理解为;(把…)解释为","en":"If you say that a remark, a gesture, or an action translates as something, or that you translate it as something, you decide that this is what its significance is.","ex":{"en":"'I love him' often translates as 'He's better than nothing'","cn":"“我爱他”经常解释为“有他总比没有强”。"}}]},"examples":[{"en":"Can you help me translate this legal jargon into plain English?","cn":"你能帮助我用浅显易懂的英语来说明这一法律术语吗？"},{"en":"I don't speak Greek so Dina offered to translate for me.","cn":"我不懂希腊语，于是戴娜主动给我翻译。"}]},"trap":{"media":{"uk":"media/uk/trap__gb_1.mp3","us":"media/us/trap__us_1.mp3","img":["media/ldoce/img/trap.jpg"]},"oxford":{"phon":"træp","pos":"noun","senses":[{"en":"a piece of equipment for catching animals","cn":"（捕捉动物的）陷阱，罗网，夹，捕捉器","sc":"for animals","ex":{"en":"a fox with its leg in a trap","cn":"被夹子夹住腿的狐狸"}},{"en":"a clever plan designed to trick somebody, either by capturing them or by making them do or say something that they did not mean to do or say","cn":"圈套；诡计","sc":"trick","ex":{"en":"She had set a trap for him and he had walked straight into it.","cn":"她给他设下圈套，他就径直钻了进去。"}},{"en":"an unpleasant situation from which it is hard to escape","cn":"（难以逃脱的）困境，牢笼","g":"[usually singular]","sc":"bad situation","ex":{"en":"the unemployment trap","cn":"失业的困境"}},{"en":"a light carriage with two wheels, pulled by a horse","cn":"双轮轻便马车","sc":"carriage","ex":{"en":"a pony and trap","cn":"一匹矮马拉的双轮轻便马车"}},{"en":"mouth","cn":"嘴","lab":"slang","sc":"mouth","ex":{"en":"Shut your trap! (= a rude way of telling somebody to be quiet)","cn":"闭上你的臭嘴！"}},{"en":"a cage from which a greyhound (= a type of dog) is let out at the start of a race","cn":"隔栏（赛狗开始时把狗从中放出）","sc":"for racing dog"},{"en":"a small area filled with sand on a golf course","cn":"（高尔夫球场上的）沙坑","lab":"both especially North American English","sc":"in golf"},{"en":"to put somebody in a dangerous place that they cannot get out of","cn":"使落入险境","g":"[usually passive]","sc":"in dangerous/bad situation","ex":{"en":"Help! I'm trapped!","cn":"救命啊！我给困住了！"},"pos":"verb"},{"en":"to keep somebody in a bad situation that they want to get out of but cannot","cn":"使处于困境","g":"[usually passive]","sc":"in dangerous/bad situation","ex":{"en":"He was trapped in an unhappy marriage.","cn":"他陷入不幸的婚姻之中。"},"pos":"verb"},{"en":"to have part of your body, your clothing, etc. held in a place so tightly that you cannot remove it and it may be injured or damaged","cn":"卡住；夹住；绊住；缠住","sc":"part of body/clothing","ex":{"en":"I trapped my coat in the car door.","cn":"我的外衣被汽车门夹住了。"},"pos":"verb"},{"en":"to force somebody/something into a place or situation that they cannot escape from, especially in order to catch them","cn":"把…逼进，迫使…进入（不能逃脱的地方）","sc":"catch","ex":{"en":"The escaped prisoners were eventually trapped in an underground garage and recaptured.","cn":"越狱逃犯终于给追逼到地下车库，再次被捕。"},"pos":"verb"},{"en":"to catch an animal in a trap","cn":"设陷阱捕捉，用捕捉器捕捉（动物）","sc":"catch","ex":{"en":"Raccoons used to be trapped for their fur.","cn":"人们过去经常设陷阱猎取浣熊，以获得其毛皮。"},"pos":"verb"},{"en":"to catch or keep something in a place and prevent it from escaping, especially so that you can use it","cn":"收集；吸收","sc":"catch","ex":{"en":"Solar panels trap energy from the sun.","cn":"太阳能电池板吸收太阳能。"},"pos":"verb"},{"en":"to trick somebody into something","cn":"使陷入圈套；使中计；使上当","sc":"trick","ex":{"en":"He felt he had been trapped into accepting the terms of the contract.","cn":"他觉得自己是中了圈套才接受这个合同条款的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(捕鸟兽的)陷阱，罗网，夹子，捕捉器","en":"A trap is a device which is placed somewhere or a hole which is dug somewhere in order to catch animals or birds."},{"pos":"VERB 动词","cn":"设陷阱捕捉","en":"If a person traps animals or birds, he or she catches them using traps.","ex":{"en":"The locals were encouraged to trap and kill the birds.","cn":"当地居民过去被鼓励设捕捉器捕杀这种鸟。"}},{"pos":"N-COUNT 可数名词","cn":"圈套;诡计;骗局","en":"A trap is a trick that is intended to catch or deceive someone.","ex":{"en":"He failed to keep a rendezvous after sensing a police trap…","cn":"他察觉到警方设了圈套以后就没有如约会面。"}},{"pos":"VERB 动词","cn":"诱骗;使上当;使中计","en":"If you trap someone into doing or saying something, you trick them so that they do or say it, although they did not want to.","ex":{"en":"Were you just trying to trap her into making some admission?","cn":"你刚才是想诱使她供认吗？"}},{"pos":"VERB 动词","cn":"诱捕；抓捕","en":"To trap someone, especially a criminal, means to capture them.","ex":{"en":"The police knew that to trap the killer they had to play him at his own game","cn":"警方知道要捉到凶手必须将计就计。"}},{"pos":"N-COUNT 可数名词","cn":"困境;窘境","en":"A trap is an unpleasant situation that you cannot easily escape from.","ex":{"en":"The Government has found it's caught in a trap of its own making.","cn":"政府发现自己作茧自缚。"}},{"pos":"VERB 动词","cn":"使困住;使受限制","en":"If you are trapped somewhere, something falls onto you or blocks your way and prevents you from moving or escaping.","ex":{"en":"The train was trapped underground by a fire","cn":"列车被大火困在地下。"}},{"pos":"VERB 动词","cn":"采集;储存;使存留","en":"When something traps gas, water, or energy, it prevents it from escaping.","ex":{"en":"Wool traps your body heat, keeping the chill at bay","cn":"毛织品能够保暖御寒。"}},{"pos":"N-COUNT 可数名词","cn":"双轮轻便马车","en":"A trap is a light carriage with two wheels pulled by horses in which people used to travel."},{"pos":"PHRASE 短语","cn":"落入陷阱；陷入误区","en":"If someone falls into the trap of doing something, they think or behave in a way which is not wise or sensible.","ex":{"en":"Many people fall into the trap of believing that home decorating must always be done on a large scale","cn":"很多人错误地认为家居装修总是要大动一番干戈。"}},{"pos":"PHRASE 短语","cn":"住嘴;闭嘴","en":"If someone tells you to shut your trap or keep your trap shut, they are telling you rudely that you should be quiet and not say anything."}]},"examples":[{"en":"The escaped prisoners were eventually trapped in an underground garage and recaptured.","cn":"越狱逃犯终于给追逼到地下汽车库，再次被捕。"},{"en":"He felt he had been trapped into accepting the terms of the contract.","cn":"他觉得自己是中了圈套才接受这合同条款的。"}]},"triumph":{"media":{"uk":"media/uk/triumph__gb_1.mp3","us":"media/us/triumph__us_1.mp3"},"oxford":{"phon":"ˈtraɪʌmf","pos":"noun","senses":[{"en":"a great success, achievement or victory","cn":"巨大成功；重大成就；伟大胜利","g":"[countable, uncountable]","ex":{"en":"one of the greatest triumphs of modern science","cn":"现代科学最重大的成就之一"}},{"en":"the feeling of great pleasure or joy that you get from a great success or victory","cn":"（巨大成功或胜利的）心满意足，喜悦，狂喜","g":"[uncountable]","ex":{"en":"a shout of triumph","cn":"喜悦的欢呼声"}},{"en":"an excellent example of how successful something can be","cn":"（成功的）典范，楷模","g":"[singular]","ex":{"en":"Her arrest was a triumph of international cooperation.","cn":"她的被捕是国际合作的典范。"}},{"en":"to defeat somebody/something; to be successful","cn":"打败；战胜；成功","ex":{"en":"As is usual in this kind of movie, good triumphs over evil in the end.","cn":"像这类电影的一贯结局一样，善良战胜了邪恶。"},"pos":"verb"},{"en":"a former British company, established in 1902, which made motor cycles and (later) cars. Triumph motor cycles were popular both in Britain and abroad from the 1920s. The original Triumph company began making cars in 1923 and the car and motorcycle businesses were separated in 1936. Its most successful models were the TR series of sports cars and the small, relatively cheap, Triumph Herald. Triumph cars stopped being made in the 1980s. Triumph motorcycles are still made by a company called Triumph Motorcycles Ltd that started in 1983.","cn":"凯旋：1902年成立的一家前英国公司，生产摩托车和（后来的）汽车。自1920年代以来，凯旋摩托车在英国和国外都很流行。最初的Triumph公司于1923年开始生产汽车，汽车和摩托车业务于1936年分离。其最成功的模型是TR系列跑车和相对便宜的小型Triumph Herald。胜利汽车在1980年代停止生产。凯旋摩托车仍由一家始于1983年的名为Triumph Motorcycles Ltd的公司生产。","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"非凡的成功;杰出的成就","en":"A triumph is a great success or achievement, often one that has been gained with a lot of skill or effort.","ex":{"en":"The championships proved to be a personal triumph for the coach, Dave Donovan","cn":"事实证明，在这次锦标赛中教练戴夫·多诺万取得了非凡的个人成就。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(成功或获胜时的)极大的满足，狂喜，骄傲","en":"Triumph is a feeling of great satisfaction and pride resulting from a success or victory.","ex":{"en":"Her sense of triumph was short-lived","cn":"她只感受了片刻成功的喜悦。"}},{"pos":"VERB 动词","cn":"成功;获胜;得胜","en":"If someone or something triumphs, they gain complete success, control, or victory, often after a long or difficult struggle.","ex":{"en":"All her life, Kelly had stuck with difficult tasks and challenges, and triumphed","cn":"凯莉一生经历了各种艰巨的任务与挑战，她都一一成功应对了。"}}]},"examples":[{"en":"As is usual in this kind of movie, good triumphs over evil in the end.","cn":"像这类电影的一贯结局一样，善良战胜了邪恶。"},{"en":"France triumphed 3–0 in the final.","cn":"法国队在决赛中以 3:0 获胜。"}]},"tricked":{"lemma":"trick"},"trait":{"oxford":{"phon":"treɪt","pos":"noun","senses":[{"en":"a particular quality in your personality","cn":"（人的个性的）特征，特性，特点","ex":{"en":"personality traits","cn":"个性特点"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"特征;特点;特性","en":"A trait is a particular characteristic, quality, or tendency that someone or something has.","ex":{"en":"The study found that some alcoholics had clear personality traits showing up early in childhood","cn":"研究发现一些酗酒者在童年早期就显现出鲜明的人格特征。"}}]},"media":{"uk":"media/uk/trait__gb_1.mp3","us":"media/us/trait__us_1.mp3"},"examples":[{"en":"personality traits","cn":"个性特点"},{"en":"a mental illness associated with particular personality traits","cn":"和某些性格特征有关的精神疾病"}]},"tradition":{"media":{"uk":"media/uk/tradition__gb_1.mp3","us":"media/us/tradition__us_1.mp3"},"oxford":{"phon":"trəˈdɪʃn","pos":"noun","senses":[{"en":"a belief, custom or way of doing something that has existed for a long time among a particular group of people; a set of these beliefs or customs","cn":"传统；传统的信仰（或风俗）","ex":{"en":"religious/cultural/ancient traditions","cn":"宗教／文化／古老传统"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"传统;传说","en":"A tradition is a custom or belief that has existed for a long time.","ex":{"en":"...the rich traditions of Afro-Cuban music, and dance","cn":"非裔古巴人丰富的音乐、舞蹈传统"}},{"pos":"PREP-PHRASE 短语介词","cn":"承袭…风格的;具有…特点的","en":"If you say that something or someone is in the tradition of a person or thing from the past, you mean that they have many features that remind you of that person or thing.","ex":{"en":"They're marvellous pictures in the tradition of Gainsborough.","cn":"这些是具有庚斯博罗风格的绝妙画作。"}}]},"examples":[{"en":"By tradition, children play tricks on 1 April.","cn":"按照传统风俗，儿童在 4 月 1 日捣乱戏弄别人。"},{"en":"There's a tradition in our family that we have a party on New Year's Eve.","cn":"我们家有个传统，新年除夕要办家庭聚会。"}]},"transforming":{"lemma":"transform"},"tropics":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"热带地区","en":"The tropics are the parts of the world that lie between two lines of latitude, the tropic of Cancer, 23½˚ north of the equator, and the tropic of Capricorn, 23½˚ south of the equator."}]}},"trousers":{"media":{"img":["media/pic/clothes_suit_comp.jpg","media/thumb/trousers.jpg"],"uk":"media/uk/trousers__gb_1.mp3","us":"media/us/trousers__us_1.mp3"},"oxford":{"phon":"ˈtraʊzəz","pos":"noun","senses":[{"en":"a piece of clothing that covers the lower body and is divided into two parts to cover each leg separately","cn":"裤子","ex":{"en":"a pair of grey trousers","cn":"一条灰裤子"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"裤子","en":"Trousers are a piece of clothing that you wear over your body from the waist downwards, and that cover each leg separately.","ex":{"en":"He was smartly dressed in a shirt, dark trousers and boots","cn":"他穿着衬衫和黑裤子，脚蹬皮靴，看上去很帅气。"}},{"pos":"","cn":"","en":"to wear the trousers→see: ;"}]},"examples":[{"en":"I was still in short trousers (= still only a boy) at the time.","cn":"我那时还在穿着短裤呢（仍然是个男孩）。"},{"en":"He dropped his trousers.","cn":"他脱了裤子。"}],"base":"trouser"},"tree":{"media":{"img":["media/ldoce/img/tree.jpg","media/pic/tree_bark_comp.jpg"],"uk":"media/uk/tree__gb_1.mp3","us":"media/us/tree__us_1.mp3"},"oxford":{"phon":"triː","pos":"noun","senses":[{"en":"a tall plant that can live a long time. Trees have a thick central wooden trunk from which branches grow, usually with leaves on them","cn":"树；树木；乔木","ex":{"en":"an oak/olive/apple tree","cn":"橡树；橄榄树；苹果树"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"树;树木;乔木","en":"A tree is a tall plant that has a hard trunk, branches, and leaves.","ex":{"en":"I planted those apple trees.","cn":"我栽了那些苹果树。"}},{"pos":"PHRASE 短语","cn":"走错路线；搞错方向；想法不对路","en":"If you say that someone is barking up the wrong tree, you mean that they are following the wrong course of action because their beliefs or ideas about something are incorrect.","ex":{"en":"Scientists in Switzerland realised that most other researchers had been barking up the wrong tree.","cn":"瑞士科学家意识到其他研究者大多研究方向不对头。"}},{"pos":"PHRASE 短语","cn":"只见树木，不见森林;只重细节，不顾整体","en":"If someone can't see the wood for the trees in British English, or can't see the forest for the trees in American English, they are very involved in the details of something and so they do not notice what is important about the thing as a whole."},{"pos":"","cn":"","en":"the top of the tree→see: ;"}]},"examples":[{"en":"They followed a path through the trees.","cn":"他们沿着林间小路走着。"},{"en":"to chop/cut down a tree","cn":"伐/砍倒一棵树"}]},"treatment":{"media":{"uk":"media/uk/treatment__gb_1.mp3","us":"media/us/treatment__us_1.mp3"},"oxford":{"phon":"ˈtriːtmənt","pos":"noun","senses":[{"en":"something that is done to cure an illness or injury, or to make somebody look and feel good","cn":"治疗；疗法；诊治","g":"[uncountable, countable]","lab":"British English","ex":{"en":"The drug is used in the treatment of depression.","cn":"该药用于治疗抑郁症。"}},{"en":"a way of behaving towards or dealing with a person or thing","cn":"对待；待遇","g":"[uncountable]","ex":{"en":"the brutal treatment of political prisoners","cn":"对政治犯的残酷虐待"}},{"en":"a way of dealing with or discussing a subject, work of art, etc.","cn":"处理；讨论；论述","g":"[uncountable, countable]","ex":{"en":"Shakespeare’s treatment of madness in ‘King Lear’","cn":"莎士比亚在《李尔王》中对疯癫的处理手法"}},{"en":"a process by which something is cleaned, or protected against something","cn":"（净化或防治）处理，加工","g":"[uncountable, countable]","ex":{"en":"a sewage treatment plant","cn":"污水处理厂"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"治疗;疗法;疗程","en":"Treatment is medical attention given to a sick or injured person or animal.","ex":{"en":"Many patients are not getting the medical treatment they need.","cn":"很多病人没有得到他们需要的医治。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"对待；待遇","en":"Your treatment of someone is the way you behave towards them or deal with them.","ex":{"en":"We don't want any special treatment","cn":"我们不想要任何特殊待遇。"}},{"pos":"N-VAR 可变名词","cn":"处理;治理;护理","en":"Treatment of something involves putting a particular substance onto or into it, in order to clean it, to protect it, or to give it special properties.","ex":{"en":"There should be greater treatment of sewage before it is discharged","cn":"污水排放之前应该进行更充分的处理。"}},{"pos":"PHRASE 短语","cn":"盛情款待;特别严厉的对待","en":"If you say that someone is given the full treatment, you mean either that they are treated extremely well or that they are treated extremely severely.","ex":{"en":"If you've got friends or family coming to stay, make it really special by giving them the full treatment","cn":"如果你有朋友或家人要过来住，那就搞得特别一些，给予他们以热情款待。"}}]},"examples":[{"en":"Shakespeare's treatment of madness in ‘King Lear’","cn":"莎士比亚在《李尔王》中对疯癫的处理手法"},{"en":"Guests at the health spa receive a range of beauty treatments.","cn":"客人在健身水疗馆可接受各种美容服务。"}]},"transporting":{"lemma":"transport","media":{"uk":"media/uk/transport__gb_1.mp3","us":"media/us/transport__us_1.mp3"}},"trot":{"media":{"uk":"media/uk/trot__gb_1.mp3","us":"media/us/trot__us_1.mp3"},"oxford":{"phon":"trɒt","pos":"verb","senses":[{"en":"to move forward at a speed that is faster than a walk and slower than a canter","cn":"快步；疾走；小跑","g":"[intransitive]","ex":{"en":"I could hear the sound of several horses trotting along in the lane.","cn":"我听到几匹马在小路上小跑的声音。"}},{"en":"to ride a horse in this way","cn":"骑马小跑","g":"[transitive]","ex":{"en":"She trotted her pony around the field.","cn":"她骑着小马绕场慢跑。"}},{"en":"to run or walk fast, taking short, quick steps","cn":"小步快跑；碎步急行","g":"[intransitive]","ex":{"en":"The children trotted into the room.","cn":"孩子们小跑着进了房间。"}},{"en":"to walk or go somewhere","cn":"步行；走；到…去","g":"[intransitive]","lab":"informal","ex":{"en":"The guide led the way and we trotted along behind him.","cn":"向导在前面带路，我们跟在他的后面走。"}},{"en":"a trotting speed, taking short, quick steps","cn":"（指速度）慢跑，小跑，小步快跑，疾走","g":"[singular]","ex":{"en":"The horse slowed to a trot.","cn":"那马放慢速度在小跑。"},"pos":"noun"},{"en":"a period of trotting","cn":"（指活动）小跑；一阵小跑","g":"[countable]","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"快步走;小步跑","en":"If you trot somewhere, you move fairly fast at a speed between walking and running, taking small quick steps.","ex":{"en":"I trotted down the steps and out to the shed","cn":"我小步跑下台阶，奔向外面的小屋。"}},{"pos":"VERB 动词","cn":"(马等)小跑;骑马小跑","en":"When an animal such as a horse trots, it moves fairly fast, taking quick small steps. You can also say that the rider of the animal is trotting .","ex":{"en":"Alan took the reins and the small horse started trotting","cn":"艾伦抓住缰绳，小马开始慢跑起来。"}},{"pos":"PHRASE 短语","cn":"接连地;持续地","en":"If something happens several times on the trot, it happens that number of times without a break.","ex":{"en":"She lost five games on the trot","cn":"她接连输了 5 场比赛。"}},{"pos":"","cn":"","en":"相关词组：trot out"}]},"examples":[{"en":"They trotted out the same old excuses for the lack of jobs in the area.","cn":"他们又用那老一套的借口解释这个地区缺少就业机会的问题。"},{"en":"The girl broke into a trot and disappeared around the corner.","cn":"那姑娘突然小步跑了起来，拐过街角不见了。"}]},"translation":{"media":{"uk":"media/uk/translation__gb_1.mp3","us":"media/us/translation__us_1.mp3"},"oxford":{"phon":"trænzˈleɪʃn","pos":"noun","senses":[{"en":"the process of changing something that is written or spoken into another language","cn":"翻译；译","g":"[uncountable]","ex":{"en":"an error in translation","cn":"误译"}},{"en":"a text or word that has been changed from one language into another","cn":"译文；译本；译作","g":"[countable, uncountable]","ex":{"en":"The usual translation of ‘glasnost’ is ‘openness’.","cn":"glasnost 一词通常译为 openness（公开性）。"}},{"en":"the process of changing something into a different form","cn":"转变；转化","g":"[uncountable]","ex":{"en":"the translation of theory into practice","cn":"从理论到实践的转化"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"译文;译本","en":"A translation is a piece of writing or speech that has been translated from a different language.","ex":{"en":"...MacNiece's excellent English translation of 'Faust'","cn":"麦克尼斯精彩的《浮士德》英文译本"}},{"pos":"PHRASE 短语","cn":"翻译中意义受损(或流失)","en":"If you say that a quality of something has been lost in translation, you mean that it is not very good as a result of being translated into another language or told in a different way.","ex":{"en":"Much of the wit is lost in translation…","cn":"很多诙谐的成分都在翻译中丢失了。"}}]},"examples":[{"en":"The usual translation of ‘glasnost’ is ‘openness’. * glasnost","cn":"一词通常译为 openness（公开性）。"},{"en":"He specializes in translation from Danish into English.","cn":"他专门从事把丹麦文译成英文的工作。"}]},"trick":{"oxford":{"phon":"trɪk","pos":"noun","senses":[{"en":"something that you do to make somebody believe something that is not true, or to annoy somebody as a joke","cn":"诡计；花招；骗局；把戏","sc":"something to cheat somebody","ex":{"en":"They had to think of a trick to get past the guards.","cn":"他们只好想出个计谋骗过岗哨。"}},{"en":"something that confuses you so that you see, understand, remember, etc. things in the wrong way","cn":"引起错觉（或记忆紊乱）的事物","sc":"something confusing","ex":{"en":"One of the problems of old age is that your memory can start to play tricks on you.","cn":"老年人的问题之一是记忆可能紊乱起来。"}},{"en":"a clever action that somebody/something performs as a way of entertaining people","cn":"戏法；把戏","sc":"entertainment","ex":{"en":"He amused the kids with conjuring tricks.","cn":"他变戏法逗得孩子们直乐。"}},{"en":"a way of doing something that works well; a good method","cn":"技巧；诀窍；窍门","g":"[usually singular]","sc":"good method","ex":{"en":"The trick is to pick the animal up by the back of its neck.","cn":"窍门在于抓住动物的后脖颈把它提起来。"}},{"en":"the cards that you play or win in a single part of a card game","cn":"一圈；一墩；一圈所打（或赢）的牌","sc":"in card games","ex":{"en":"I won six tricks in a row.","cn":"我接连赢了六墩牌。"}},{"en":"to make somebody believe something which is not true, especially in order to cheat them","cn":"欺骗；欺诈","ex":{"en":"I'd been tricked and I felt stupid.","cn":"我被人骗了，觉得自己真傻。"},"pos":"verb"},{"en":"intended to trick somebody","cn":"意在欺骗的；容易使人上当的","ex":{"en":"It was a trick question (= one to which the answer seems easy but actually is not).","cn":"那是个容易使人上当的问题。"},"pos":"adjective"},{"en":"weak and not working well","cn":"虚弱有毛病的","lab":"North American English","ex":{"en":"a trick knee","cn":"膝软"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"诡计;花招;骗局","en":"A trick is an action that is intended to deceive someone.","ex":{"en":"We are playing a trick on a man who keeps bothering me.","cn":"我们正在戏弄那个一直烦我的家伙。"}},{"pos":"VERB 动词","cn":"欺骗;哄骗","en":"If someone tricks you, they deceive you, often in order to make you do something.","ex":{"en":"Stephen is going to be pretty upset when he finds out how you tricked him","cn":"如果斯蒂芬发现你怎样欺骗了他，他会非常气愤。"}},{"pos":"N-COUNT 可数名词","cn":"把戏;绝技","en":"A trick is a clever or skilful action that someone does in order to entertain people.","ex":{"en":"He shows me card tricks.","cn":"他表演纸牌戏法给我看。"}},{"pos":"N-COUNT 可数名词","cn":"窍门;诀窍;技巧","en":"A trick is a clever way of doing something.","ex":{"en":"Tiffany revamped her sitting room with simple decorative tricks.","cn":"蒂法尼采用简单的装饰技巧将起居室翻新。"}},{"pos":"PHRASE 短语","cn":"奏效;达到目的","en":"If something does the trick, it achieves what you wanted.","ex":{"en":"Sometimes a few choice words will do the trick.","cn":"有时说几句尖酸刻薄的话就有人听了。"}},{"pos":"PHRASE 短语","cn":"千方百计;浑身解数;所有的办法","en":"If someone tries every trick in the book, they try every possible thing that they can think of in order to achieve something.","ex":{"en":"Companies are using every trick in the book to stay one step in front of their competitors.","cn":"各公司想方设法地保持比竞争者领先一步的优势。"}},{"pos":"PHRASE 短语","cn":"灯光造成的幻觉","en":"If you say that something is a trick of the light, you mean that what you are seeing is an effect caused by the way that the light falls on things, and does not really exist in the way that it appears.","ex":{"en":"Her head appears to be on fire but that is only a trick of the light.","cn":"她的头部看上去像是着火了，但那只是灯光造成的幻觉。"}},{"pos":"PHRASE 短语","cn":"无所(不)知;无事(不)晓;把握住任何机会","en":"If you say that someone does not miss a trick, you mean that they always know what is happening and take advantage of every situation.","ex":{"en":"When it comes to integrating their transport systems, the French don't miss a trick.","cn":"法国人从不放过任何整合其交通系统的机会。"}},{"pos":"PHRASE 短语","cn":"（行业）诀窍,门道，绝活","en":"The tricks of the trade are the quick and clever ways of doing something that are known by people who regularly do a particular activity.","ex":{"en":"To get you started, we have asked five successful writers to reveal some of the tricks of the trade.","cn":"为了让你开始写作，我们邀请了 5 位成功作家向你透露一些写作秘诀。"}},{"pos":"PHRASE 短语","cn":"故伎重演;耍老花招","en":"If you say that someone is up to their tricks or up to their old tricks, you disapprove of them because they are behaving in the dishonest or deceitful way in which they typically behave.","ex":{"en":"I have no respect for my father who, having remarried, is still up to his old tricks.","cn":"我对父亲没任何敬意，他已经再婚，却依然喜欢耍老把戏。"}},{"pos":"","cn":"","en":"you can't teach an old dog new tricks→see: ;"}]},"media":{"uk":"media/uk/trick__gb_1.mp3","us":"media/us/trick__us_1.mp3"},"examples":[{"en":"I don't know what it was that did the trick, but I am definitely feeling much better.","cn":"我不知道是什么起的作用，但是我确实觉得好多了。"},{"en":"Was there somebody standing there or was it a trick of the light?","cn":"是真的有人站在那儿还是光线引起的错觉？"}]},"trunks":{"lemma":"trunk"},"tree-lined":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"旁边(或两旁)有树的","en":"A tree-lined road or street has trees on either side.","ex":{"en":"...the broad, tree-lined avenues.","cn":"宽阔的林阴道"}}]},"media":{"uk":"media/ldoce/hwd/bre/5/tree_lined0205.mp3","us":"media/ldoce/hwd/ame/f/tree-lined.mp3"}},"trying":{"media":{"uk":"media/uk/trying__gb_1.mp3","us":"media/us/trying__us_1.mp3"},"oxford":{"phon":"ˈtraɪɪŋ","pos":"adjective","senses":[{"en":"annoying or difficult to deal with","cn":"令人厌烦的；难对付的","ex":{"en":"These are trying times for all of us.","cn":"对我们所有人来说，这是最难熬的时期。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难对付的;令人厌烦的;令人恼火的","en":"If you describe something or someone as trying, you mean that they are difficult to deal with and make you feel impatient or annoyed.","ex":{"en":"Support from those closest to you is vital in these trying times","cn":"在这些困难的时刻，最亲近的人给予你的支持至关重要。"}}]},"examples":[{"en":"These are trying times for all of us.","cn":"对我们所有人来说，这是最难熬的时期。"},{"en":"That child is very trying.","cn":"那个孩子非常难缠。"}],"base":"try"},"treatments":{"lemma":"treatment","media":{"uk":"media/uk/treatment__gb_1.mp3","us":"media/us/treatment__us_1.mp3"}},"troubled":{"media":{"uk":"media/uk/troubled__gb_1.mp3","us":"media/us/troubled__us_1.mp3"},"oxford":{"phon":"ˈtrʌbld","pos":"adjective","senses":[{"en":"worried and anxious","cn":"忧虑的；烦恼的；不安的","ex":{"en":"She looked into his troubled face.","cn":"她仔细打量着他那张布满愁容的脸。"}},{"en":"having a lot of problems","cn":"麻烦多的；混乱的；扰乱的","ex":{"en":"a troubled marriage","cn":"坎坷的婚姻"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"苦恼的;烦恼的;忧虑的","en":"Someone who is troubled is worried because they have problems.","ex":{"en":"Rose sounded deeply troubled","cn":"罗斯听起来颇为烦恼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"问题多的;动乱的;混乱的","en":"A troubled place, situation, organization, or time has many problems or conflicts.","ex":{"en":"There is much we can do to help this troubled country","cn":"我们可以做很多事情来帮助这个动荡不安的国家。"}},{"pos":"","cn":"","en":"to pour oil on troubled waters→see: ;"}]},"examples":[{"en":"She looked into his troubled face.","cn":"她仔细打量着他那张布满愁容的脸。"},{"en":"We live in troubled times.","cn":"我们生逢乱世。"}],"base":"trouble"},"treason":{"media":{"uk":"media/uk/treason__gb_1.mp3","us":"media/us/treason__us_1.mp3"},"oxford":{"phon":"ˈtriːzn","pos":"noun","senses":[{"en":"the crime of doing something that could cause danger to your country, such as helping its enemies during a war","cn":"危害国家罪，叛国罪（如战时通敌）","ex":{"en":"an act of high treason against the English crown","cn":"对英国的叛国行为"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"叛国罪；通敌罪","en":"Treason is the crime of betraying your country, for example by helping its enemies or by trying to remove its government using violence."}]},"examples":[{"en":"a treasonable act","cn":"叛国行为"},{"en":"Richter is accused of committing treason against the state.","cn":"里克特被控犯有叛国罪。"}]},"trunk":{"oxford":{"phon":"trʌŋk","pos":"noun","senses":[{"en":"the thick main stem of a tree, that the branches grow from","cn":"树干","g":"[countable]","ex":{"en":"an instrument made from a hollowed-out tree trunk","cn":"用挖空的树干制成的工具"}},{"en":"the space at the back of a car that you put bags, cases, etc. in","cn":"（汽车后部的）行李厢","g":"[countable]","lab":"North American English","ex":{"en":"He slammed the trunk shut.","cn":"他砰地关上了行李箱。"}},{"en":"the long nose of an elephant","cn":"象鼻","g":"[countable]"},{"en":"a piece of clothing covering the lower part of the body and sometimes the top part of the legs, worn by men and boys for swimming","cn":"（男式）游泳裤","g":"[plural]","lab":"North American English also"},{"en":"a large, strong box with a lid (= cover), used for storing or transporting clothes, books, etc.","cn":"大箱子；大衣箱；大书箱","g":"[countable]","ex":{"en":"I found the documents at the bottom of an old tin trunk in the attic.","cn":"我在阁楼上一个旧铁皮箱子的底部找到了那些文件。"}},{"en":"the main part of the human body apart from the head, arms and legs","cn":"（人的）躯干","g":"[countable, usually singular]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"树干","en":"The trunk of a tree is the large main stem from which the branches grow.","ex":{"en":"...the gnarled trunk of a birch tree.","cn":"白桦树粗糙多瘤的树干"}},{"pos":"N-COUNT 可数名词","cn":"旅行箱;衣箱","en":"A trunk is a large, strong case or box used for storing things or for taking on a journey."},{"pos":"N-COUNT 可数名词","cn":"象鼻","en":"An elephant's trunk is its very long nose that it uses to lift food and water to its mouth."},{"pos":"N-COUNT 可数名词","cn":"(汽车的)行李箱","en":"The trunk of a car is a covered space at the back or front in which you put luggage or other things."},{"pos":"N-PLURAL 复数名词","cn":"(男式)游泳裤","en":"Trunks are shorts that a man wears when he goes swimming.","ex":{"en":"I wear these trunks because they have a streamline effect in the water.","cn":"我穿这条游泳裤因为它在水中有流线效果。"}},{"pos":"N-COUNT 可数名词","cn":"(人体从颈部到腰部的)躯干","en":"Your trunk is the central part of your body, from your neck to your waist."}]},"media":{"img":["media/pic/trunk_comp.jpg","media/thumb/trunk.jpg"],"uk":"media/uk/trunk__gb_1.mp3","us":"media/us/trunk__us_1.mp3"},"examples":[{"en":"He left his bicycle leaning against a tree trunk .","cn":"他把他的自行车斜靠在树干上。"},{"en":"the trunk of an old oak tree","cn":"老橡树的树干"}]},"transition":{"media":{"uk":"media/uk/transition__gb_1.mp3","us":"media/us/transition__us_1.mp3"},"oxford":{"phon":"trænˈzɪʃn","pos":"noun","senses":[{"en":"the process or a period of changing from one state or condition to another","cn":"过渡；转变；变革；变迁","ex":{"en":"the transition from school to full-time work","cn":"从学校到全职工作的过渡阶段"}},{"en":"the process of starting to live your life as a person of a different sex, to match your gender identity","cn":"变性","ex":{"en":"She wrote to co-workers announcing her transition and asking them to refer to her with female pronouns.","cn":"她写信给同事宣布她的转变，并要求他们用女性代词来称呼她。"}},{"en":"to change or to make something change from one state or condition to another","cn":"（使）过渡，转变，变迁","g":"[intransitive, transitive]","ex":{"en":"They transitioned from print journalism to the digital world.","cn":"他们由纸媒过渡到了数字世界。"},"pos":"verb"},{"en":"to start living your life as a person of a different sex, to match your gender identity","cn":"变性；性别转换","g":"[intransitive]","ex":{"en":"The singer told fans about his decision to transition.","cn":"这位歌手向歌迷讲述了他转型的决定。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"转变;过渡;变革;变迁","en":"Transition is the process in which something changes from one state to another.","ex":{"en":"The transition to a multi-party democracy is proving to be difficult.","cn":"事实证明，向多党民主制的转型非常艰难。"}},{"pos":"VERB 动词","cn":"(从某一状态或活动)转变，过渡(到另一状态或活动)","en":"If someone transitions from one state or activity to another, they move gradually from one to the other.","ex":{"en":"Most of the discussion was on what needed to be done now as we transitioned from the security issues to the challenging economic issues","cn":"随着我们由安全议题转向具有挑战性的经济议题，讨论最多的就是目前需要做些什么。"}}]},"examples":[{"en":"This course is useful for students who are in transition (= in the process of changing) from one training programme to another.","cn":"对转换培训项目的学生来说，这一课程很有用。"},{"en":"He will remain head of state during the period of transition to democracy.","cn":"在向民主政权过渡时期，他仍将是国家首脑。"}]},"trip":{"media":{"uk":"media/uk/trip__gb_1.mp3","us":"media/us/trip__us_1.mp3"},"oxford":{"phon":"trɪp","pos":"noun","senses":[{"en":"a journey to a place and back again, especially a short one for pleasure or a particular purpose","cn":"（尤指短程往返的）旅行，旅游，出行","lab":"British English","ex":{"en":"Did you have a good trip?","cn":"你旅行顺利吗？"}},{"en":"the experience that somebody has if they take a powerful drug that affects the mind and makes them imagine things","cn":"（服用毒品后所产生的）幻觉，迷幻感受","lab":"slang","ex":{"en":"an acid (= LSD) trip","cn":"迷幻药产生的幻觉"}},{"en":"an act of falling or nearly falling down, because you hit your foot against something","cn":"绊；绊倒"},{"en":"to catch your foot on something and fall or almost fall","cn":"绊；绊倒","g":"[intransitive]","lab":"figurative","ex":{"en":"She tripped and fell.","cn":"她绊了一下摔倒了。"},"pos":"verb"},{"en":"to catch somebody’s foot and make them fall or almost fall","cn":"将…绊倒；使跌倒","g":"[transitive]","ex":{"en":"As I passed, he stuck out a leg and tried to trip me up.","cn":"我经过时，他伸出腿来想把我绊倒。"},"pos":"verb"},{"en":"to walk, run or dance with quick light steps","cn":"脚步轻快地走（或跑、跳舞）","g":"[intransitive]","lab":"literary","ex":{"en":"She said goodbye and tripped off along the road.","cn":"她说了声再见就连蹦带跳地沿着路走了。"},"pos":"verb"},{"en":"to release a switch, etc. or to operate something by doing so","cn":"触发（开关）；（松开开关）开动","g":"[transitive]","ex":{"en":"to trip a switch","cn":"打开开关"},"pos":"verb"},{"en":"to be under the influence of a drug that makes you hallucinate","cn":"（服用毒品后）产生幻觉","g":"[intransitive]","lab":"informal","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"旅行;出行;旅游","en":"A trip is a journey that you make to a particular place. →see usage note at:","ex":{"en":"On the Thursday we went out on a day trip","cn":"星期四我们出去玩了一天。"}},{"pos":"VERB 动词","cn":"绊倒;绊","en":"If you trip when you are walking, you knock your foot against something and fall or nearly fall.","ex":{"en":"She tripped and fell last night and broke her hip","cn":"她昨晚绊倒了，摔坏了髋骨。"}},{"pos":"VERB 动词","cn":"使绊;将…绊倒; 使跌倒","en":"If you trip someone who is walking or running, you put your foot or something else in front of them, so that they knock their own foot against it and fall or nearly fall.","ex":{"en":"One guy stuck his foot out and tried to trip me.","cn":"一个家伙把脚伸出来想要绊倒我。"}},{"pos":"N-COUNT 可数名词","cn":"(对权力等的)迷恋;(内疚、怀旧感等的)困扰","en":"If you say that someone is, for example, on a power trip, a guilt trip, or a nostalgia trip, you mean that their behaviour is motivated by power, guilt, or nostalgia.","ex":{"en":"There's such pressure to be happy in Hawaii, if you're unhappy you're on a guilt trip","cn":"就好像去夏威夷就一定要开心似的，如果你不开心，你会一个劲儿地感到愧疚。"}},{"pos":"N-COUNT 可数名词","cn":"(吸毒所致的)幻觉，迷幻感受","en":"A trip is an experience that someone has when their mind is affected by a drug such as LSD.","ex":{"en":"An anxious or depressed person can experience a really bad trip.","cn":"焦虑或抑郁的人吸毒后可能会有非常糟糕的幻觉。"}},{"pos":"VERB 动词","cn":"(服用毒品后)产生幻觉","en":"If someone is tripping, they are having an experience in which their mind is affected by a drug such as LSD.","ex":{"en":"One night I was tripping on acid.","cn":"有一天晚上我服用了迷幻药后正在幻游。"}},{"pos":"VERB 动词","cn":"轻快地走","en":"If someone trips somewhere, they walk there with light, quick steps.","ex":{"en":"A girl in a red smock tripped down the hill","cn":"一个身穿红色罩衫的女孩迈着轻快的步子下山。"}},{"pos":"","cn":"","en":"相关词组：trip up"}]},"examples":[{"en":"Read the questions carefully, because the examiners sometimes try to trip you up.","cn":"要仔细把问题看清楚，因为出卷人有时故意让你出错。"},{"en":"We had to make several trips to bring all the equipment over.","cn":"我们往返了几次才把全部设备运过来。"}]},"trickle":{"media":{"uk":"media/uk/trickle__gb_1.mp3","us":"media/us/trickle__us_1.mp3","img":["media/ldoce/img/ldoce_111.png"]},"oxford":{"phon":"ˈtrɪkl","pos":"verb","senses":[{"en":"to flow, or to make something flow, slowly in a thin stream","cn":"（使）滴，淌，小股流淌","g":"[intransitive, transitive]","ex":{"en":"Tears were trickling down her cheeks.","cn":"眼泪顺着她的面颊流了下来。"}},{"en":"to go, or to make something go, somewhere slowly or gradually","cn":"慢慢走；（使）缓慢移动","g":"[intransitive, transitive]","ex":{"en":"People began trickling into the hall.","cn":"人们开始缓步进入大厅。"}},{"en":"a small amount of liquid, flowing slowly","cn":"细流；涓流","ex":{"en":"There was a trickle of blood at the corner of his mouth.","cn":"他的嘴角有一道血。"},"pos":"noun"},{"en":"a small amount or number of something, coming or going slowly","cn":"稀稀疏疏缓慢来往的东西","g":"[usually singular]","ex":{"en":"a steady trickle of visitors","cn":"三三两两络绎不绝的游客"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)滴;(使)淌","en":"When a liquid trickles, or when you trickle it, it flows slowly in very small amounts.","ex":{"en":"A tear trickled down the old man's cheek","cn":"一滴眼泪沿着老人的脸颊淌了下来。"}},{"pos":"VERB 动词","cn":"(小批地)慢慢移动","en":"When people or things trickle in a particular direction, they move there slowly in small groups or amounts, rather than all together.","ex":{"en":"Some donations are already trickling in.","cn":"一些捐赠已经陆续到来。"}}]},"examples":[{"en":"Tears were trickling down her cheeks.","cn":"眼泪顺着她的面颊流了下来。"},{"en":"People began trickling into the hall.","cn":"人们开始缓步进入大厅。"}]},"travelers":{"oxford":{"phon":"ˈtrævələ(r)","pos":"noun","senses":[{"en":"a person who is travelling or who often travels","cn":"旅行者；旅游者；旅客；游客"},{"en":"( BrE ) a person who does not live in one place but travels around, especially as part of a group （","cn":"尤指结队而行的）漂泊者"}]}},"translators":{"lemma":"translator"},"treat":{"media":{"uk":"media/uk/treat__gb_1.mp3","us":"media/us/treat__us_1.mp3"},"oxford":{"phon":"triːt","pos":"verb","senses":[{"en":"to behave in a particular way towards somebody/something","cn":"以…态度对待；以…方式对待","sc":"behave towards somebody/something","ex":{"en":"to treat people with respect","cn":"尊重他人"}},{"en":"to consider something in a particular way","cn":"把…看作；把…视为","sc":"consider","ex":{"en":"I decided to treat his remark as a joke.","cn":"我决定把他的话当作戏言。"}},{"en":"to deal with or discuss something in a particular way","cn":"处理；讨论","sc":"consider","ex":{"en":"The question is treated in more detail in the next chapter.","cn":"下一章中对这一问题有更详尽的阐述。"}},{"en":"to give medical care or attention to a person, an illness, an injury, etc.","cn":"医疗；医治；治疗","lab":"especially British English","sc":"illness/injury","ex":{"en":"She was treated for sunstroke.","cn":"她因中暑而接受治疗。"}},{"en":"to use a chemical substance or process to clean, protect, preserve, etc. something","cn":"（利用化学物质或反应）处理，保护，保存","sc":"use chemical","ex":{"en":"to treat crops with insecticide","cn":"给庄稼喷洒杀虫剂"}},{"en":"to pay for something that somebody/you will enjoy and that you do not usually have or do","cn":"招待；款待；请（客）；买（可享受的东西）","sc":"pay for something pleasant","ex":{"en":"She treated him to lunch.","cn":"她请他吃午饭。"}},{"en":"something very pleasant that somebody can enjoy, especially something that you give somebody or do for them","cn":"乐事；乐趣；款待","ex":{"en":"When I was young chocolate was a treat.","cn":"我年轻的时候，吃巧克力是一种难得的享受。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"对待;看待;处理","en":"If you treat someone or something in a particular way, you behave towards them or deal with them in that way.","ex":{"en":"Artie treated most women with indifference","cn":"阿蒂对大多数女人都漠不关心。"}},{"pos":"VERB 动词","cn":"治疗;医治","en":"When a doctor or nurse treats a patient or an illness, he or she tries to make the patient well again.","ex":{"en":"Doctors treated her with aspirin","cn":"医生用阿司匹林为她治疗。"}},{"pos":"VERB 动词","cn":"处理;给…上保护层","en":"If something is treated with a particular substance, the substance is put onto or into it in order to clean it, to protect it, or to give it special properties.","ex":{"en":"About 70% of the cocoa acreage is treated with insecticide","cn":"大约 70% 的可可树林地喷过杀虫剂。"}},{"pos":"VERB 动词","cn":"请(客);招待;款待","en":"If you treat someone to something special which they will enjoy, you buy it or arrange it for them.","ex":{"en":"She was always treating him to ice cream","cn":"她总是请他吃冰激凌。"}},{"pos":"N-COUNT 可数名词","cn":"请客;款待","en":"If you give someone a treat, you buy or arrange something special for them which they will enjoy.","ex":{"en":"Lettie had never yet failed to return from town without some special treat for him.","cn":"莱蒂每次从城里回来都必定会给他带点特别的礼物。"}},{"pos":"N-SING 单数名词","cn":"请客;做东","en":"If you say that something is your treat, you mean that you are paying for it as a treat for someone else."},{"pos":"PHRASE 短语","cn":"很出色的东西","en":"If you say, for example, that something looks or works a treat, you mean that it looks very good or works very well.","ex":{"en":"The first part of the plan works a treat","cn":"计划的第一部分天衣无缝。"}},{"pos":"","cn":"","en":"to treat someone like dirt→see: ;"}]},"examples":[{"en":"You've never been to this area before? Then you're in for a real treat.","cn":"你以前从来没有到过这一地区？那么你一定会喜之不尽。"},{"en":"We took the kids to the zoo as a special treat.","cn":"我们特地带孩子们到动物园去，让他们开心一下。"}]},"triangle":{"media":{"img":["media/ldoce/img/triangle.jpg","media/pic/triangles_comp.jpg"],"uk":"media/uk/triangle__gb_1.mp3","us":"media/us/triangle__us_1.mp3"},"oxford":{"phon":"ˈtraɪæŋɡl","pos":"noun","senses":[{"en":"a flat shape with three straight sides and three angles; a thing in the shape of a triangle","cn":"三角形；三角形物体","ex":{"en":"Cut the sandwiches into triangles.","cn":"把三明治切成三角形。"}},{"en":"a simple musical instrument that consists of a long piece of metal bent into the shape of a triangle, that you hit with another piece of metal","cn":"三角铁（打击乐器）"},{"en":"a situation involving three people in a complicated relationship","cn":"三角关系","ex":{"en":"the romantic triangle at the centre of the novel","cn":"处于小说中心的爱情三角关系"}},{"en":"an instrument for drawing straight lines and angles, made from a flat piece of plastic or metal in the shape of a triangle with one angle of 90°","cn":"三角板；三角尺","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"三角(形);三角形物体","en":"A triangle is an object, arrangement, or flat shape with three straight sides and three angles.","ex":{"en":"This design is in pastel colours with three rectangles and three triangles…","cn":"这一设计由淡色的 3 个长方形和 3 个三角形构成。"}},{"pos":"N-COUNT 可数名词","cn":"三角铁(一种打击乐器)","en":"The triangle is a musical instrument that consists of a piece of metal shaped like a triangle. You play it by hitting it with a short metal bar."},{"pos":"N-COUNT 可数名词","cn":"三角关系","en":"If you describe a group of three people as a triangle, you mean that they are all connected with each other in a particular situation, but often have different interests.","ex":{"en":"She plays a French woman in a love triangle with Jonathan Pryce and Christopher Walken.","cn":"她扮演一位与乔纳森·普赖斯和克里斯托弗·沃肯有三角恋关系的法国女子。"}}]},"examples":[{"en":"Cut the sandwiches into triangles.","cn":"把三明治切成三角形。"},{"en":"( BrE ) a right-angled triangle","cn":"直角三角形"}]},"tragedy":{"media":{"uk":"media/uk/tragedy__gb_1.mp3","us":"media/us/tragedy__us_1.mp3"},"oxford":{"phon":"ˈtrædʒədi","pos":"noun","senses":[{"en":"a very sad event or situation, especially one that involves death","cn":"悲惨的事；不幸；灾难；惨案","ex":{"en":"It's a tragedy that she died so young.","cn":"她英年早逝是一大悲哀。"}},{"en":"a serious play with a sad ending, especially one in which the main character dies; plays of this type","cn":"悲剧；悲剧作品","ex":{"en":"Shakespeare’s tragedies","cn":"莎士比亚的悲剧"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不幸;灾难;惨剧","en":"A tragedy is an extremely sad event or situation.","ex":{"en":"They have suffered an enormous personal tragedy","cn":"他们遭逢了巨大的个人不幸。"}},{"pos":"N-VAR 可变名词","cn":"悲剧（作品）","en":"Tragedy is a type of literature, especially drama, that is serious and sad, and often ends with the death of the main character.","ex":{"en":"The story has elements of tragedy and farce.","cn":"这个故事兼有悲剧与闹剧的元素。"}}]},"examples":[{"en":"Tragedy struck the family when their son was hit by a car and killed.","cn":"这个家庭惨遭不幸，他们的儿子被汽车撞死了。"},{"en":"It's a tragedy that she died so young.","cn":"她英年早逝是一大悲哀。"}]},"try":{"media":{"uk":"media/uk/try__gb_1.mp3","us":"media/us/try__us_1.mp3"},"oxford":{"phon":"traɪ","pos":"verb","senses":[{"en":"to make an attempt or effort to do or get something","cn":"试图；想要；设法；努力","g":"[intransitive, transitive]","ex":{"en":"I don't know if I can come but I'll try.","cn":"我不知道是否能来，但我尽可能来。"}},{"en":"to use, do or test something in order to see if it is good, suitable, etc.","cn":"试；试用；试做；试验","g":"[transitive]","ex":{"en":"Have you tried this new coffee? It's very good.","cn":"你尝过这种新咖啡吗？好极啦。"}},{"en":"to examine evidence in court and decide whether somebody is innocent or guilty","cn":"审理；审讯；审判","g":"[transitive]","ex":{"en":"He was tried for murder.","cn":"他因谋杀罪而受审。"}},{"en":"an act of trying to do something","cn":"尝试；试图；努力","g":"[usually singular]","lab":"North American English","ex":{"en":"I doubt they'll be able to help but it's worth a try (= worth asking them).","cn":"我不敢肯定他们能够帮得上忙，但不妨试一试。"},"pos":"noun"},{"en":"an act of trying something new or different to see if it is good, suitable, etc.","cn":"试；试用；试做；试验","g":"[usually singular]","ex":{"en":"I don't think I'll be any good at tennis, but I'll give it a try.","cn":"我不认为我有打网球的特长，但是我会试一试。"},"pos":"noun"},{"en":"an act of scoring points by touching the ground behind your opponents’ goal line with the ball","cn":"在对方球门线后带球触地；持球触地得分","ex":{"en":"to score a try","cn":"带球触地得分"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"设法;尝试;努力","en":"If you try to do something, you want to do it, and you take action which you hope will help you to do it.","ex":{"en":"He secretly tried to block her advancement in the Party","cn":"他暗地里设法阻挠她在党内的晋升。"}},{"pos":"VERB 动词","cn":"设法做;尝试","en":"To try and do something means to try to do it.","ex":{"en":"He has started a privatisation programme to try and win support from the business community…","cn":"他启动了一套私有化方案，以设法赢得商界的支持。"}},{"pos":"VERB 动词","cn":"谋求;争取","en":"If you try for something, you make an effort to get it or achieve it.","ex":{"en":"My partner and I have been trying for a baby for two years","cn":"我和爱人两年来一直想要个孩子。"}},{"pos":"VERB 动词","cn":"试用;试做;尝试","en":"If you try something new or different, you use it, do it, or experience it in order to discover its qualities or effects.","ex":{"en":"It's best not to try a new recipe for the first time on such an important occasion","cn":"在这么重要的场合最好不要尝试以前从未做过的新菜谱。"}},{"pos":"VERB 动词","cn":"到(某处)试试;找(某人)试试","en":"If you try a particular place or person, you go to that place or person because you think that they may be able to provide you with what you want.","ex":{"en":"Have you tried the local music shops?","cn":"你到当地的音像店找过了吗？"}},{"pos":"VERB 动词","cn":"试着推开(门或窗)","en":"If you try a door or window, you try to open it.","ex":{"en":"Bob tried the door. To his surprise it opened.","cn":"鲍勃试着推了推门。令他吃惊的是，门竟然开了。"}},{"pos":"VERB 动词","cn":"审判;审讯;审理","en":"When a person is tried, he or she has to appear in a law court and is found innocent or guilty after the judge and jury have heard the evidence. When a legal case is tried, it is considered in a court of law.","ex":{"en":"He suggested that those responsible should be tried for crimes against humanity","cn":"他建议那些责任人应该以反人类罪受到审判。"}},{"pos":"N-COUNT 可数名词","cn":"(橄榄球的)达阵得分(在对方球门线内带球触地得分)","en":"In the game of rugby, a try is the action of scoring by putting the ball down behind the goal line of the opposing team.","ex":{"en":"The French, who led 21-3 at half time, scored eight tries.","cn":"上半场以 21:3 领先的法国队有 8 个达阵得分。"}},{"pos":"PHRASE 短语","cn":"没努力尝试;没竭尽全力","en":"If you say that something fails but not for want of trying or not for lack of trying, you mean that everything possible was done to make it succeed.","ex":{"en":"Not all is perfect, but it isn't for want of trying.","cn":"一切并非无可挑剔，但已经竭尽全力了。"}},{"pos":"","cn":"","en":"to try your best→see: ; to try your hand→see: ; to try your luck→see: ; to try someone's patience→see: ;"},{"pos":"","cn":"","en":"相关词组：try on try out try out for"}]},"examples":[{"en":"( informal ) ‘What's that behind you?’ ‘ Nice try (= at making me turn round), but you'll have to do better than that!’ “","cn":"看你身后是什么？” “好个鬼花招，不过你耍的手法还不够高明！”"},{"en":"‘Would you like to try some raw fish?’ ‘Why not? I'll try anything once! ’ “","cn":"你想尝点儿生鱼片吗？” “好哇，我什么都想尝一点儿！”"}]},"transnational":{"oxford":{"phon":"ˌtrænzˈnæʃnəl","pos":"adjective","senses":[{"en":"existing in or involving different countries","cn":"跨国的；多国的","ex":{"en":"transnational corporations","cn":"跨国公司"}}]},"media":{"uk":"media/uk/transnational__gb_1.mp3","us":"media/us/transnational__us_1.mp3"},"examples":[{"en":"transnational corporations","cn":"跨国公司"}]},"trauma":{"media":{"uk":"media/uk/trauma__gb_1.mp3","us":"media/us/trauma__us_1.mp3"},"oxford":{"phon":"ˈtrɔːmə","pos":"noun","senses":[{"en":"a mental condition caused by severe shock, stress or fear, especially when the harmful effects last for a long time","cn":"精神创伤","g":"[uncountable]","lab":"psychology","ex":{"en":"the effects of trauma and stress on the body","cn":"创伤和压力对身体的影响"}},{"en":"a very frightening or upsetting experience","cn":"痛苦经历；挫折","g":"[countable, uncountable]","ex":{"en":"She felt exhausted after the traumas of recent weeks.","cn":"她经受了最近几个星期的痛苦之后感到精疲力竭。"}},{"en":"an injury","cn":"损伤；外伤","g":"[uncountable, countable]","lab":"medical","ex":{"en":"The patient suffered severe brain trauma.","cn":"患者的大脑受到严重损伤。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"精神创伤;惊骇(或痛苦)经历","en":"Trauma is a very severe shock or very upsetting experience, which may cause psychological damage.","ex":{"en":"I'd been through the trauma of losing a house","cn":"我经历过失去房子的痛苦。"}}]},"examples":[{"en":"She felt exhausted after the traumas of recent weeks.","cn":"她经受了最近几个星期的痛苦之后感到精疲力竭。"},{"en":"The patient suffered severe brain trauma.","cn":"患者的大脑受到严重损伤。"}]},"tragic":{"media":{"uk":"media/uk/tragic__gb_1.mp3","us":"media/us/tragic__us_1.mp3"},"oxford":{"phon":"ˈtrædʒɪk","pos":"adjective","senses":[{"en":"making you feel very sad, usually because somebody has died or suffered a lot","cn":"悲惨的；悲痛的；可悲的","ex":{"en":"He was killed in a tragic accident at the age of 24.","cn":"他 24 岁时在一次悲惨的事故中丧命。"}},{"en":"connected with tragedy (= the style of literature)","cn":"悲剧的","g":"[only before noun]","ex":{"en":"a tragic actor/hero","cn":"悲剧演员／男主角"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"悲惨的;可悲的;可叹的","en":"A tragic event or situation is extremely sad, usually because it involves death or suffering.","ex":{"en":"It was just a tragic accident","cn":"它只是场不幸的事故。"}},{"pos":"ADJ 形容词","cn":"悲剧的","en":"Tragic is used to refer to tragedy as a type of literature.","ex":{"en":"...Michael Henchard, the tragic hero of 'The Mayor of Casterbridge'.","cn":"迈克尔·亨察德，《卡斯特桥市长》的悲剧主人公"}}]},"examples":[{"en":"Cuts in the health service could have tragic consequences for patients.","cn":"减少公共医疗卫生服务可能对病人造成悲惨的后果。"},{"en":"He was killed in a tragic accident at the age of 24.","cn":"他 24 岁时在一次悲惨的事故中丧命。"}]},"traits":{"lemma":"trait"},"trek":{"oxford":{"phon":"trek","pos":"noun","senses":[{"en":"a long, hard walk lasting several days or weeks, especially in the mountains","cn":"长途跋涉，艰难的旅程（尤指在山区）","ex":{"en":"They reached the refugee camp after an arduous two-day trek across the mountains.","cn":"经过两天的艰苦跋涉，他们翻山越岭，到达了难民营。"}},{"en":"a long walk","cn":"长途步行；远距离行走","lab":"informal","ex":{"en":"It's a long trek into town.","cn":"到商业区去要走很长的路。"}},{"en":"to make a long or difficult journey, especially on foot","cn":"（尤指徒步）长途跋涉","g":"[intransitive]","lab":"informal","ex":{"en":"I hate having to trek up that hill with all the groceries.","cn":"我很不愿意得带着这么多吃用杂物爬上那个山头。"},"pos":"verb"},{"en":"to spend time walking, especially in mountains and for pleasure and interest","cn":"（尤指在山中）远足，徒步旅行","g":"[intransitive, transitive]","ex":{"en":"We went trekking in Nepal.","cn":"我们去尼泊尔徒步旅行。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(通常指徒步)艰难旅行，跋涉，远足","en":"If you trek somewhere, you go on a journey across difficult country, usually on foot.","ex":{"en":"...trekking through the jungles","cn":"徒步穿过丛林"}},{"pos":"VERB 动词","cn":"(通常因疲惫而缓慢勉强地)行进，拖着腿走","en":"If you trek somewhere, you go there rather slowly and unwillingly, usually because you are tired.","ex":{"en":"They trekked from shop to shop in search of white knee-length socks.","cn":"他们拖着步子从一家商店走到另一家，寻找齐膝的白袜子。"}}]},"media":{"uk":"media/uk/trek__gb_1.mp3","us":"media/us/trek__us_1.mp3"},"examples":[{"en":"I hate having to trek up that hill with all the groceries.","cn":"我很不愿意得带着这么多吃用杂物爬上那个山头。"},{"en":"During the expedition, they trekked ten to thirteen hours a day.","cn":"在探险期间，他们每天都要走十到十三个小时。"}]},"travel":{"media":{"uk":"media/uk/travel__gb_1.mp3","us":"media/us/travel__us_1.mp3"},"oxford":{"phon":"ˈtrævl","pos":"verb","senses":[{"en":"to go from one place to another, especially over a long distance","cn":"长途行走；旅行；游历","g":"[intransitive, transitive]","ex":{"en":"I go to bed early if I'm travelling the next day.","cn":"如果第二天要去旅行我就早睡。"}},{"en":"to go or move at a particular speed, in a particular direction, or a particular distance","cn":"（以某速度、朝某方向或在某距离内）行进，转送，传播","g":"[intransitive]","ex":{"en":"to travel at 50 miles an hour","cn":"以每小时 50 英里的速度行进"}},{"en":"to be still in good condition after a long journey","cn":"经长途运输仍不变质；经得住长途运输","g":"[intransitive]","ex":{"en":"Some wines do not travel well.","cn":"有些葡萄酒经不住长途运输。"}},{"en":"to be equally successful in another place and not just where it began","cn":"盛行各地；广为流传","g":"[intransitive]","ex":{"en":"These recipes travel well and don't require unusual ingredients or equipment.","cn":"这些食谱很容易传播，不需要不寻常的原料或设备。"}},{"en":"to go fast","cn":"走得快；快速行进","g":"[intransitive]","ex":{"en":"Their car can really travel!","cn":"他们的车开得可真快！"}},{"en":"to take more than three steps while you are holding the ball, without bouncing it on the ground, which is against the rules of the game","cn":"（带球）走步；持球走","g":"[intransitive]"},{"en":"the act or activity of travelling","cn":"旅行；旅游；游历","g":"[uncountable]","lab":"figurative","ex":{"en":"air/rail/space travel","cn":"乘飞机／火车／航天器"},"pos":"noun"},{"en":"time spent travelling, especially in foreign countries and for pleasure","cn":"（出国）旅游，旅行","g":"[plural]","lab":"British English","ex":{"en":"The novel is based on his travels in India.","cn":"这部长篇小说是根据他的印度之行写成的。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(常指长途)旅行，行进","en":"If you travel, you go from one place to another, often to a place that is far away.","ex":{"en":"You had better travel to Helsinki tomorrow","cn":"你最好明天赶赴赫尔辛基。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(长途)旅行","en":"Travel is the activity of travelling.","ex":{"en":"Information on travel in New Zealand is available at the hotel…","cn":"新西兰的旅行信息可以在宾馆获取。"}},{"pos":"VERB 动词","cn":"周游;走遍;在…游历","en":"If you travel the world, the country, or the area, you go to many different places in the world or in a particular country or area.","ex":{"en":"Dr Ryan travelled the world gathering material for his book","cn":"瑞安博士周游世界为他的书搜集资料。"}},{"pos":"VERB 动词","cn":"(光、声音)传送，传播","en":"When light or sound from one place reaches another, you say that it travels to the other place.","ex":{"en":"When sound travels through water, strange things can happen","cn":"当声音在水中传播时，可能会发生奇怪的现象。"}},{"pos":"VERB 动词","cn":"(消息)传播，流传","en":"When news becomes known by people in different places, you can say that it travels to them.","ex":{"en":"News of his work traveled all the way to Asia","cn":"有关他研究成果的消息一路传到了亚洲。"}},{"pos":"N-PLURAL 复数名词","cn":"漫游;游历","en":"Someone's travels are the journeys that they make to places a long way from their home.","ex":{"en":"He also collects things for the house on his travels abroad.","cn":"他在国外旅游时也为家宅搜集物品作为摆设。"}},{"pos":"PHRASE 短语","cn":"轻装旅行","en":"If you travel light, you travel without taking much luggage."},{"pos":"PHRASE 短语","cn":"(食品等货物)宜于长途运输，经得起长途运输","en":"If goods such as food products travel well, they can be transported a long way without being damaged or their quality being spoiled.","ex":{"en":"Ripe fruit does not travel well, but unripe fruit can be transported worldwide.","cn":"熟透的水果不宜长途运输，但未成熟的水果却可以运往全世界。"}},{"pos":"PHRASE 短语","cn":"(思想、方法或样式)广为流传，盛行各地","en":"If you say that an idea, a method, or a style travels well, you mean that it can be appreciated or used by people in several different countries, and not just in the country where it began.","ex":{"en":"That brand of humour generally travels well.","cn":"那种风格的幽默通常在各地都喜闻乐见。"}}]},"examples":[{"en":"The pass allows unlimited travel on all public transport in the city.","cn":"持有乘车证可乘坐市内所有的公共交通工具，次数不限。"},{"en":"The novel is based on his travels in India.","cn":"这部长篇小说是根据他的印度之行写成的。"}]},"treks":{"lemma":"trek"},"tremendously":{"oxford":{"phon":"trəˈmendəsli","pos":"adverb","senses":[{"en":"to a very great degree","cn":"在很大程度上","ex":{"en":"tremendously exciting","cn":"极其令人兴奋"}},{"en":"extremely well","cn":"极好地；出色地；了不起地","ex":{"en":"This area of research has progressed tremendously in the past few years.","cn":"该领域的研究在过去几年中取得了巨大进展。"}}]},"media":{"uk":"media/uk/tremendously__gb_1.mp3","us":"media/us/tremendously__us_1.mp3"},"examples":[{"en":"tremendously exciting","cn":"极其令人兴奋"},{"en":"Suddenly, there was a tremendous bang, and the whole station shook.","cn":""}]},"trifle":{"media":{"uk":"media/uk/trifle__gb_1.mp3","us":"media/us/trifle__us_1.mp3"},"oxford":{"phon":"ˈtraɪfl","pos":"noun","senses":[{"en":"a cold dessert (= a sweet dish) made from cake and fruit with layers of jelly, custard and cream","cn":"屈莱弗，乳脂松糕（在蛋糕和水果上分层覆盖果冻、蛋奶酱和奶油）","g":"[countable, uncountable]","lab":"British English"},{"en":"slightly","cn":"略微；稍微","g":"[singular]","lab":"formal","ex":{"en":"She seemed a trifle anxious.","cn":"她似乎有点儿焦急。"}},{"en":"something that is not valuable or important","cn":"小事；琐事；不值钱的东西","g":"[countable]","lab":"formal","ex":{"en":"There’s no point worrying over such trifles.","cn":"为这些小事担心是没有意义的。"}}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"(尤用于缓和程度)有一点，稍微","en":"You can use a trifle to mean slightly or to a small extent, especially in order make something you say seem less extreme.","ex":{"en":"As a photographer, he'd found both locations just a trifle disappointing","cn":"作为摄影师，他感到两处景点都有点儿不尽如人意。"}},{"pos":"N-COUNT 可数名词","cn":"小事;琐事;无价值的东西","en":"A trifle is something that is considered to have little importance, value, or significance.","ex":{"en":"He had no money to spare on trifles","cn":"他没有闲钱买些小玩意儿。"}},{"pos":"N-VAR 可变名词","cn":"屈莱弗甜食，乳脂蛋糕（由松糕、果冻、水果和蛋奶沙司层叠制成的冷甜点，通常覆有奶油）","en":"Trifle is a cold dessert made of layers of sponge cake, jelly, fruit, and custard, and usually covered with cream."},{"pos":"","cn":"","en":"相关词组：trifle with"}]},"examples":[{"en":"$1 000 is a mere trifle to her. * 1 000","cn":"元对她来说不过是区区小数。"},{"en":"She seemed a trifle anxious.","cn":"她似乎有点儿焦急。"}]},"trinity":{"media":{"uk":"media/uk/trinity__gb_1.mp3","us":"media/us/trinity__us_1.mp3"},"oxford":{"phon":"ˈtrɪnəti","pos":"noun","senses":[{"en":"the union of Father, Son and Holy Spirit as one God","cn":"三位一体（圣父、圣子及圣灵合为上帝）"},{"en":"a group of three people or things","cn":"三人小组；三件一套；三合一","lab":"formal"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"(基督教圣父、圣子、圣灵的)三位一体","en":"In the Christian religion, the Trinity or the Holy Trinity is the union of the Father, the Son, and the Holy Spirit in one God."}]}},"transitional":{"media":{"uk":"media/uk/transitional__gb_1.mp3","us":"media/us/transitional__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(时期)过渡的","en":"A transitional period is one in which things are changing from one state to another.","ex":{"en":"...a transitional period following more than a decade of civil war","cn":"十多年的内战结束之后的过渡时期"}},{"pos":"ADJ 形容词","cn":"过渡性的;过渡时期的","en":"Transitional is used to describe something that happens or exists during a transitional period.","ex":{"en":"The main rebel groups have agreed to join in a meeting to set up a transitional government.","cn":"主要叛乱集团已同意参加会议讨论建立一个过渡政府。"}}]},"examples":[{"en":"a transitional period","cn":"过渡时期"},{"en":"a transitional government","cn":"过渡政府"}],"oxford":{"phon":"trænˈzɪʃənl","pos":"adjective","senses":[{"en":"connected with the process of changing from one state or condition to another","cn":"过渡的","ex":{"en":"a transitional period","cn":"过渡期"}}]}},"treacle":{"oxford":{"phon":"ˈtriːkl","pos":"noun","senses":[{"en":"a thick black, sweet, sticky liquid produced when sugar is refined (= made pure), used in cooking","cn":"（制糖时产生的）糖浆，糖蜜","lab":"North American English"},{"en":"a very sweet thick yellow liquid made from sugar","cn":"金黄色糖浆","lab":"British English also","ex":{"en":"a treacle tart","cn":"糖蜜馅饼"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"糖浆；糖蜜","en":"Treacle is a thick, sweet, sticky liquid that is obtained when sugar is processed. It is used in making cakes and puddings."}]},"media":{"uk":"media/uk/treacle__gb_1.mp3","us":"media/us/treacle__us_1.mp3"},"examples":[{"en":"a treacle tart","cn":"糖蜜馅饼"},{"en":"a film that does not turn into treacle","cn":"没有拍成煽情烂片的电影"}]},"transmission":{"media":{"uk":"media/uk/transmission__gb_1.mp3","us":"media/us/transmission__us_1.mp3"},"oxford":{"phon":"trænzˈmɪʃn","pos":"noun","senses":[{"en":"the act or process of passing something from one person, place or thing to another","cn":"传送；传递；传达；传播；传染","g":"[uncountable]","ex":{"en":"the transmission of the disease","cn":"这种疾病的传播"}},{"en":"the act or process of sending out an electronic signal or message or of broadcasting a radio or television programme","cn":"（电子信号或信息的）发射，发送；（电台或电视节目的）播送","g":"[uncountable]","ex":{"en":"the transmission of computer data along telephone lines","cn":"计算机数据沿电话线的传输"}},{"en":"a radio or television message or broadcast","cn":"（电台或电视）信息，广播","g":"[countable]","ex":{"en":"a live transmission from Sydney","cn":"来自悉尼的现场直播"}},{"en":"the system in a vehicle by which power is passed from the engine to the wheels","cn":"（车辆的）传动装置，变速器","g":"[uncountable, countable]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"传送;传递;传播;传染","en":"The transmission of something is the passing or sending of it to a different person or place.","ex":{"en":"Heterosexual contact is responsible for the bulk of HIV transmission.","cn":"艾滋病病毒大半是经异性性接触传播的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(电视、广播节目的)播送，播放","en":"The transmission of television or radio programmes is the broadcasting of them."},{"pos":"N-COUNT 可数名词","cn":"(电视、广播播送的)节目","en":"A transmission is a broadcast."},{"pos":"N-VAR 可变名词","cn":"(汽车等的)传动装置，变速器","en":"The transmission on a car or other vehicle is the system of gears and shafts by which the power from the engine reaches and turns the wheels.","ex":{"en":"The car was fitted with automatic transmission.","cn":"这辆车装配了自动变速器。"}}]},"examples":[{"en":"the transmission of computer data along telephone lines","cn":"计算机数据沿电话线的传输"},{"en":"a break in transmission (= of a radio or television broadcast) due to a technical fault","cn":"技术故障造成的播送中断"}]},"transform":{"oxford":{"phon":"trænsˈfɔːm","pos":"verb","senses":[{"en":"to change the form of something; to change in form","cn":"（使）改变形态","g":"[transitive, intransitive]","ex":{"en":"The photochemical reactions transform the light into electrical impulses.","cn":"光化学反应使光变为电脉冲。"}},{"en":"to completely change the appearance or character of something/somebody, especially so that it is better; to completely change in appearance or character","cn":"（使）改变外观（或性质）；（使）改观","g":"[transitive, intransitive]","ex":{"en":"A new colour scheme will transform your bedroom.","cn":"新的色彩调配将使你的卧室焕然一新。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"转换;改变;改造","en":"To transform something into something else means to change or convert it into that thing.","ex":{"en":"Your metabolic rate is the speed at which your body transforms food into energy","cn":"新陈代谢率是身体把食物转换为能量的速度。"}},{"pos":"VERB 动词","cn":"改善;使改观;使改头换面","en":"To transform something or someone means to change them completely and suddenly so that they are much better or more attractive.","ex":{"en":"The Minister said the Urban Development Corporation was now transforming the area","cn":"部长声称城市开发公司如今正使该地区改头换面。"}}]},"media":{"uk":"media/uk/transform__gb_1.mp3","us":"media/us/transform__us_1.mp3"},"examples":[{"en":"A new colour scheme will transform your bedroom.","cn":"新的色彩调配将使你的卧室焕然一新。"},{"en":"It was an event that would transform my life.","cn":"那是能够彻底改变我一生的一件事。"}]},"transformed":{"lemma":"transform"},"tribune":{"media":{"uk":"media/uk/tribune__gb_1.mp3","us":"media/us/tribune__us_1.mp3"},"oxford":{"phon":"ˈtrɪbjuːn","pos":"noun","senses":[{"en":"an official elected by the people in ancient Rome to defend their rights; a popular leader","cn":"（古罗马由平民选出的）保民官；受拥戴的领袖"},{"en":"a raised area that somebody stands on to make a speech or a raised area with seats, especially in a church","cn":"（公开演讲的）讲坛"},{"en":"an independent British left-wing political magazine, established in 1937, which represents the views of some members of the Labour Party. It used to support very left-wing policies but in recent times has become more moderate. In 2018 it moved from publishing every two weeks to publishing every two months.","cn":"论坛报：成立于1937年的英国独立左翼政治杂志，代表工党某些成员的观点。它曾经支持非常左翼的政策，但最近变得更加温和。在2018年，它从每两周发布一次转变为每两个月发布一次。","pos":""}]}},"trumpets":{"lemma":"trumpet"},"trend":{"oxford":{"phon":"trend","pos":"noun","senses":[{"en":"a general direction in which a situation is changing or developing","cn":"趋势；趋向；倾向；动向","ex":{"en":"social/economic/political/demographic trends","cn":"社会/经济/政治/人口趋势"}},{"en":"to change or develop in a general direction","cn":"趋向；倾向","ex":{"en":"Prices have been trending upwards.","cn":"价格有向上走的趋势。"},"pos":"verb"},{"en":"to be discussed a lot on social media within a short period of time","cn":"（在社交媒体上）迅速成为热门，迅速升温","ex":{"en":"See what's trending on Twitter in your local area right now.","cn":"看看眼下你当地的推特热门话题是什么。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"趋势;倾向;动向","en":"A trend is a change or development towards something new or different.","ex":{"en":"This is a growing trend.","cn":"这是日益显著的趋势。"}},{"pos":"N-COUNT 可数名词","cn":"规范;风尚;时尚","en":"To set a trend means to do something that becomes accepted or fashionable, and that a lot of other people copy.","ex":{"en":"The record has already proved a success and may well start a trend.","cn":"该唱片已证明大获成功，并且很可能会引导潮流。"}}]},"media":{"uk":"media/uk/trend__gb_1.mp3","us":"media/us/trend__us_1.mp3"},"examples":[{"en":"One region is attempting to buck (= oppose or resist) the trend of economic decline.","cn":"有一个地区试图在经济衰退的趋势中逆流而上。"},{"en":"The underlying trend of inflation is still upwards.","cn":"通货膨胀的潜在趋势仍然是上升的。"}]},"trouble":{"media":{"uk":"media/uk/trouble__gb_1.mp3","us":"media/us/trouble__us_1.mp3"},"oxford":{"phon":"ˈtrʌbl","pos":"noun","senses":[{"en":"a problem, worry, difficulty, etc. or a situation causing this","cn":"问题；忧虑；困难；苦恼","g":"[uncountable, countable]","sc":"problem/worry","ex":{"en":"We have trouble getting staff.","cn":"我们在招聘雇员方面有困难。"}},{"en":"a situation in which you can be criticized or punished","cn":"可能受到批评（或处罚）的情形","g":"[uncountable]","sc":"difficult/violent situation","ex":{"en":"If I don't get this finished in time, I'll be in trouble.","cn":"我如不按时把这完成就要倒霉了。"}},{"en":"a situation that is difficult or dangerous","cn":"困境；险境","g":"[uncountable]","sc":"difficult/violent situation","ex":{"en":"The company ran into trouble early on, when a major order was cancelled.","cn":"这家公司早些时候有一个大订单被撤销，因此陷入了困境。"}},{"en":"an angry or violent situation","cn":"纷争；动乱；骚乱","g":"[uncountable]","sc":"difficult/violent situation","ex":{"en":"The police were expecting trouble after the match.","cn":"警方预料比赛后会有骚乱。"}},{"en":"illness or pain","cn":"疾病；疼痛","g":"[uncountable]","sc":"illness/pain","ex":{"en":"back trouble","cn":"背痛"}},{"en":"something that is wrong with a machine, vehicle, etc.","cn":"（机器、车辆等的）故障","g":"[uncountable]","sc":"with machine","ex":{"en":"mechanical trouble","cn":"机械故障"}},{"en":"extra effort or work","cn":"额外努力（或工作）；烦扰；打扰；麻烦","g":"[uncountable]","sc":"extra effort","ex":{"en":"I don't want to put you to a lot of trouble.","cn":"我不想给你添很多的麻烦。"}},{"en":"to make somebody worried or upset","cn":"使忧虑；使烦恼；使苦恼","g":"[transitive]","sc":"make somebody worried","ex":{"en":"What is it that's troubling you?","cn":"是什么事使得你愁眉苦脸？"},"pos":"verb"},{"en":"to interrupt somebody because you want to ask them something","cn":"劳驾；费神；麻烦","g":"[transitive]","lab":"formal","sc":"interrupt","ex":{"en":"Sorry to trouble you, but could you tell me the time?","cn":"对不起打扰您一下，请问几点了？"},"pos":"verb"},{"en":"to make an effort to do something","cn":"费神；费事；费力","g":"[intransitive]","lab":"formal","sc":"make effort","ex":{"en":"He rushed into the room without troubling to knock.","cn":"他连门也懒得敲就闯进屋去。"},"pos":"verb"},{"en":"to cause pain","cn":"使疼痛；折磨","g":"[transitive]","sc":"cause pain","ex":{"en":"My back's been troubling me again.","cn":"我的背又在一直疼了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"麻烦;困难;问题","en":"You can refer to problems or difficulties as trouble .","ex":{"en":"I had trouble parking","cn":"我停车有困难。"}},{"pos":"N-SING 单数名词","cn":"麻烦;问题;引起麻烦的事","en":"If you say that one aspect of a situation is the trouble, you mean that it is the aspect which is causing problems or making the situation unsatisfactory.","ex":{"en":"The trouble is that these restrictions have remained while other things have changed","cn":"问题是其他事情都变了，而这些条条框框还在。"}},{"pos":"N-PLURAL 复数名词","cn":"苦恼;烦恼;忧虑","en":"Your troubles are the things that you are worried about.","ex":{"en":"She tells me her troubles. I tell her mine…","cn":"我和她互相倾诉烦恼。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"疾病;不适;疼痛","en":"If you have kidney trouble or back trouble, for example, there is something wrong with your kidneys or your back.","ex":{"en":"An unsuitable bed is the most likely cause of back trouble…","cn":"不合适的床最有可能引起背部疼痛。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"骚乱;动乱","en":"If there is trouble somewhere, especially in a public place, there is fighting or rioting there.","ex":{"en":"Riot police are being deployed throughout the city to prevent any trouble","cn":"正在全城部署防暴警察以防止发生骚乱。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"费事;不便","en":"If you tell someone that it is no trouble to do something for them, you are saying politely that you can or will do it, because it is easy or convenient for you.","ex":{"en":"It's no trouble at all; on the contrary, it will be a great pleasure to help you","cn":"根本不费事，恰恰相反，非常荣幸能帮到你。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"需劳神费力的人(或动物)","en":"If you say that a person or animal is no trouble, you mean that they are very easy to look after.","ex":{"en":"My little grandson is no trouble at all, but his 6-year-old elder sister is rude and selfish.","cn":"我的小孙子一点都不让人操心，但是他6岁大的姐姐却野蛮而又自私。"}},{"pos":"VERB 动词","cn":"使苦恼;使烦恼;使忧虑","en":"If something troubles you, it makes you feel rather worried.","ex":{"en":"Is anything troubling you?","cn":"有什么事情让你烦恼吗？"}},{"pos":"VERB 动词","cn":"使感到疼痛(或不适)","en":"If a part of your body troubles you, it causes you physical pain or discomfort.","ex":{"en":"The ulcer had been troubling her for several years.","cn":"溃疡已经折磨她好几年了。"}},{"pos":"VERB 动词","cn":"费心;劳神","en":"If you say that someone does not trouble to do something, you are critical of them because they do not behave in the way that they should do, and you think that this would require very little effort.","ex":{"en":"He yawns, not troubling to cover his mouth","cn":"他打了个哈欠，都懒得抬抬手遮一下嘴巴。"}},{"pos":"VERB 动词","cn":"麻烦;打扰","en":"You use trouble in expressions such as I'm sorry to trouble you when you are apologizing to someone for disturbing them in order to ask them something.","ex":{"en":"I'm sorry to trouble you, but I wondered if by any chance you know where he is","cn":"对不起打扰了，但我想打听一下您是否知道他在哪里。"}},{"pos":"PHRASE 短语","cn":"处于困境;惹麻烦;将受惩罚","en":"If someone is in trouble, they are in a situation in which a person in authority is angry with them or is likely to punish them because they have done something wrong.","ex":{"en":"He was in trouble with his teachers","cn":"老师们都想好好教训他。"}},{"pos":"PHRASE 短语","cn":"费力;费神","en":"If you take the trouble to do something, you do something which requires a small amount of additional effort.","ex":{"en":"It is worth taking the trouble to sieve the fruit by hand…","cn":"值得费点劲用手挑挑果子。"}},{"pos":"PHRASE 短语","cn":"得不偿失;费时又费力","en":"If you say that someone or something is more trouble than they are worth, you mean that they cause you a lot of problems or take a lot of time and effort and you do not achieve or gain very much in return.","ex":{"en":"Some grumbled that Johnson was more trouble than he was worth","cn":"有人抱怨说根本不值得为约翰逊浪费精力。"}}]},"examples":[{"en":"No, I don't know his number — I have quite enough trouble remembering my own.","cn":"不，我不知道他的号码，我光记自己的号码就够困难的了。"},{"en":"The company ran into trouble early on, when a major order was cancelled.","cn":"这家公司早些时候有一个大订单被撤销，因此陷入了困境。"}]},"traditionally":{"oxford":{"phon":"trəˈdɪʃənəli","pos":"adverb","senses":[{"en":"according to the beliefs, customs or way of life of a particular group of people, that have not changed for a long time","cn":"传统的；习俗的；惯例的","ex":{"en":"The festival is traditionally held in May.","cn":"这一节庆活动传统上在五月举行。"}},{"en":"by following older or accepted methods and ideas rather than modern or different ones","cn":"传统的；因袭的；守旧的","ex":{"en":"The study compared the results of mature and traditionally qualified students.","cn":"该研究比较了成熟学生和传统合格学生的结果。"}}]},"media":{"uk":"media/uk/traditionally__gb_1.mp3","us":"media/us/traditionally__us_1.mp3"},"examples":[{"en":"The festival is traditionally held in May.","cn":"这个节日按照传统是在五月份过的。"},{"en":"Housework has traditionally been regarded as women's work.","cn":"家务历来被视为女性的工作。"}]},"treats":{"lemma":"treat","media":{"uk":"media/uk/treat__gb_1.mp3","us":"media/us/treat__us_1.mp3"}},"truth":{"media":{"uk":"media/uk/truth__gb_1.mp3","us":"media/us/truth__us_1.mp3"},"oxford":{"phon":"truːθ","pos":"noun","senses":[{"en":"the true facts about something, rather than the things that have been invented or guessed","cn":"真相；实情；事实；真实情况","g":"[singular]","ex":{"en":"Do you think she's telling the truth?","cn":"你认为她在讲实话吗？"}},{"en":"the quality or state of being based on fact","cn":"真实；真实性","g":"[uncountable]","ex":{"en":"There is no truth in the rumours.","cn":"这些谣言毫无根据。"}},{"en":"a fact that is believed by most people to be true","cn":"真理","g":"[countable]","ex":{"en":"universal truths","cn":"普遍真理"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"实情;真相;事实","en":"The truth about something is all the facts about it, rather than things that are imagined or invented.","ex":{"en":"Is it possible to separate truth from fiction?…","cn":"有可能把事实与虚构分开吗？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"真实性;真实","en":"If you say that there is some truth in a statement or story, you mean that it is true, or at least partly true.","ex":{"en":"There is no truth in this story","cn":"这个故事纯属虚构。"}},{"pos":"N-COUNT 可数名词","cn":"真理","en":"A truth is something that is believed to be true.","ex":{"en":"It is an almost universal truth that the more we are promoted in a job, the less we actually exercise the skills we initially used to perform it.","cn":"这几乎是一条普遍的真理：我们在某一工作中越往上晋升，实际运用那些当初在工作中经常实践的技能的机会就越少。"}},{"pos":"PHRASE 短语","cn":"实际上;事实上","en":"You say in truth in order to indicate that you are giving your honest opinion about something.","ex":{"en":"In truth, we were both unhappy.","cn":"事实上，我们俩都不快乐。"}},{"pos":"PHRASE 短语","cn":"说实在的;坦白说","en":"You say to tell you the truth or truth to tell in order to indicate that you are telling someone something in an open and honest way, without trying to hide anything.","ex":{"en":"To tell you the truth, I was afraid to see him","cn":"坦白说，我害怕见他。"}}]},"examples":[{"en":"She laughed and chatted but was, in truth, not having much fun.","cn":"她虽然又是笑又是侃，但实际上玩得并不开心。"},{"en":"The truth (of the matter) is we can't afford to keep all the staff on.","cn":"实际情况是我们无力继续聘用所有的职员。"}]},"trifling":{"media":{"uk":"media/uk/trifling__gb_1.mp3","us":"media/us/trifling__us_1.mp3"},"oxford":{"phon":"ˈtraɪflɪŋ","pos":"adjective","senses":[{"en":"small and not important","cn":"琐碎的；微不足道的；无足轻重的；不重要的","ex":{"en":"trifling details","cn":"琐碎细节"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不重要的;微不足道的","en":"A trifling matter is small and unimportant.","ex":{"en":"The guests had each paid £250, no trifling sum…","cn":"客人每位付了250英镑，可不是一笔小数目。"}}]},"examples":[{"en":"trifling details","cn":"琐碎细节"},{"en":"a trifling sum","cn":"一小笔钱"}]},"traditional":{"media":{"uk":"media/uk/traditional__gb_1.mp3","us":"media/us/traditional__us_1.mp3"},"oxford":{"phon":"trəˈdɪʃənl","pos":"adjective","senses":[{"en":"being part of the beliefs, customs or way of life of a particular group of people, that have not changed for a long time","cn":"传统的；习俗的；惯例的","ex":{"en":"traditional dress/music/art/culture/dance","cn":"传统服装／音乐／艺术／文化／舞蹈"}},{"en":"following older methods and ideas rather than modern or different ones","cn":"传统的；因袭的；守旧的","lab":"sometimes disapproving","ex":{"en":"a traditional method/way of doing something","cn":"传统的做事方法／方式"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"传统的;习俗的;惯例的","en":"Traditional customs, beliefs, or methods are ones that have existed for a long time without changing.","ex":{"en":"...traditional teaching methods.","cn":"传统教学方法"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"因袭的;守旧的","en":"A traditional organization or person prefers older methods and ideas to modern ones.","ex":{"en":"We're still a traditional school in a lot of ways.","cn":"我们在很多方面仍是一所旧式学校。"}}]},"examples":[{"en":"The festival is traditionally held in May.","cn":"这个节日按照传统是在五月份过的。"},{"en":"It's traditional in America to eat turkey on Thanksgiving Day.","cn":"感恩节时吃火鸡是美国的传统。"}]},"transport":{"media":{"uk":"media/uk/transport__gb_1.mp3","us":"media/us/transport__us_1.mp3"},"oxford":{"phon":"ˈtrænspɔːt","pos":"noun","senses":[{"en":"a system for carrying people or goods from one place to another using vehicles, roads, etc.","cn":"交通运输系统","g":"[uncountable]","lab":"especially British English","ex":{"en":"air/freight/road transport","cn":"空运；货运；公路运输"}},{"en":"a vehicle or method of travel","cn":"交通车辆；运输工具；旅行方式","g":"[uncountable]","lab":"British English","ex":{"en":"Applicants must have their own transport.","cn":"申请人必须有自己的交通工具。"}},{"en":"the activity or business of carrying goods from one place to another using lorries, trains, etc.","cn":"运输；运送；输送；搬运","g":"[uncountable]","lab":"especially British English","ex":{"en":"The goods were damaged during transport.","cn":"货物在运输期间受损。"}},{"en":"a ship, plane or lorry used for carrying soldiers, supplies, etc. from one place to another","cn":"（运送部队、给养等的）运输船，运输机，运输卡车","g":"[countable]"},{"en":"strong feelings and emotions","cn":"强烈的情感；激情；激动","g":"[plural]","lab":"literary","ex":{"en":"to be in transports of delight","cn":"兴高采烈"}},{"en":"to take something/somebody from one place to another in a vehicle","cn":"（用交通工具）运输，运送，输送","ex":{"en":"to transport goods/passengers","cn":"运送货物／旅客"},"pos":"verb"},{"en":"to move something somewhere by means of a natural process","cn":"（以自然方式）运输，输送，传播","ex":{"en":"The seeds are transported by the wind.","cn":"这些种子是由风传播的。"},"pos":"verb"},{"en":"to make somebody feel that they are in a different place, time or situation","cn":"使产生身临其境的感觉","ex":{"en":"The book transports you to another world.","cn":"这本书会把你带到另一个世界。"},"pos":"verb"},{"en":"(in the past) to send somebody to a far away place as a punishment","cn":"（旧时）流放","ex":{"en":"British convicts were transported to Australia for life.","cn":"英国的囚犯被终生流放到澳大利亚。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"交通工具;运输工具","en":"Transport refers to any vehicle that you can travel in or carry goods in.","ex":{"en":"Have you got your own transport?","cn":"你有自己的交通工具吗？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"交通运输系统;公共交通(网)","en":"Transport is a system for taking people or goods from one place to another, for example using buses or trains.","ex":{"en":"The extra money could be spent on improving public transport","cn":"多余的资金可以用于改善公共交通系统。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"运输;运送","en":"Transport is the activity of taking goods or people from one place to another in a vehicle.","ex":{"en":"Local production virtually eliminates transport costs.","cn":"本地生产实际上消除了运输成本。"}},{"pos":"VERB 动词","cn":"运输;运送","en":"To transport people or goods somewhere is to take them from one place to another in a vehicle.","ex":{"en":"There's no petrol, so it's very difficult to transport goods","cn":"没有汽油，因此很难运输货物。"}},{"pos":"VERB 动词","cn":"使身处他境","en":"If you say that you are transported to another place or time, you mean that something causes you to feel that you are living in the other place or at the other time.","ex":{"en":"Dr Drummond felt that he had been transported into a world that rivalled the Arabian Nights","cn":"德拉蒙德博士觉得自己仿佛被带入了一个可与《天方夜谭》相媲美的世界。"}},{"pos":"N-COUNT 可数名词","cn":"(军用)运输工具;(尤指)运输机","en":"A military or troop transport is a military vehicle, especially a plane, that is used to carry soldiers or equipment."}]},"examples":[{"en":"British convicts were transported to Australia for life.","cn":"英国的囚犯被终生流放到澳大利亚。"},{"en":"Applicants must have their own transport.","cn":"申请人必须有自己的交通工具。"}]},"transformation":{"media":{"uk":"media/uk/transformation__gb_1.mp3","us":"media/us/transformation__us_1.mp3"},"oxford":{"phon":"ˌtrænsfəˈmeɪʃn","pos":"noun","senses":[{"en":"a complete change in somebody/something","cn":"（彻底的）变化，改观，转变，改革","g":"[countable, uncountable]","ex":{"en":"The way in which we work has undergone a complete transformation in the past decade.","cn":"在过去的十年里，我们的工作方式经历了彻底的变革。"}},{"en":"the process of making institutions and organizations more democratic","cn":"民主改革","g":"[uncountable]","ex":{"en":"a lack of transformation in the private sector","cn":"在私营部门缺乏民主改革"}}]},"examples":[{"en":"The way in which we work has undergone a complete transformation in the past decade.","cn":"在过去的十年里，我们的工作方式经历了彻底的变革。"},{"en":"What a transformation! You look great.","cn":"真是判若两人！你看上去真神气。"}]},"train":{"media":{"img":["media/pic/trains_comp.jpg","media/thumb/passengertrain.jpg","media/ldoce/img/fast.jpg"],"uk":"media/uk/train__gb_1.mp3","us":"media/us/train__us_1.mp3"},"oxford":{"phon":"treɪn","pos":"noun","senses":[{"en":"a number of connected coaches or trucks, pulled by an engine or powered by a motor in each one, taking people and goods from one place to another","cn":"火车；列车","ex":{"en":"to get on/off a train","cn":"上／下火车"}},{"en":"a number of people or animals moving in a line","cn":"列队行进的人（或动物）；队列；行列","ex":{"en":"a camel train","cn":"骆驼队"}},{"en":"a series of events or actions that are connected","cn":"一系列相关的事情（或行动）","g":"[usually singular]","ex":{"en":"His death set in motion a train of events that led to the outbreak of war.","cn":"他的死引发了一系列的事件，从而导致了战争的爆发。"}},{"en":"the part of a long formal dress that spreads out on the floor behind the person wearing it","cn":"拖裾，裙裾（长礼服的曳地部分）"},{"en":"to teach a person or an animal the skills for a particular job or activity; to be taught in this way","cn":"训练；培训；接受训练","g":"[transitive, intransitive]","ex":{"en":"highly trained professionals","cn":"训练有素的专业人士"},"pos":"verb"},{"en":"to prepare yourself for a particular activity, especially a sport, by doing a lot of exercise; to prepare a person or an animal in this way","cn":"进行…训练；（尤指）进行体育锻炼；训练（人或动物）","g":"[intransitive, transitive]","ex":{"en":"I train in the gym for two hours a day.","cn":"我每天在健身房锻炼两个小时。"},"pos":"verb"},{"en":"to develop a natural ability or quality so that it improves","cn":"教育；培养…的能力（或素质）","g":"[transitive]","ex":{"en":"An expert with a trained eye will spot the difference immediately.","cn":"训练有素、眼光敏锐的专家会马上发现差别所在。"},"pos":"verb"},{"en":"to make a plant grow in a particular direction","cn":"使（植物）朝某方向生长；修整","g":"[transitive]","ex":{"en":"Roses had been trained around the door.","cn":"玫瑰被修整得围绕着门口生长。"},"pos":"verb"},{"en":"to aim a gun, camera, light, etc. at somebody/something","cn":"把（枪口、照相机、灯光等）瞄准，对准","g":"[transitive]","ex":{"en":"He carefully trained his gun on the suspect.","cn":"他小心翼翼地将枪口瞄准了嫌疑人。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"火车;列车","en":"A train is a number of carriages, cars, or trucks which are all connected together and which are pulled by an engine along a railway. Trains carry people and goods from one place to another.","ex":{"en":"The train pulled into a station","cn":"列车驶入了一个车站。"}},{"pos":"N-COUNT 可数名词","cn":"(缓慢行进中的)行列，队列","en":"A train of vehicles, people, or animals is a long line of them travelling slowly in the same direction.","ex":{"en":"In the old days this used to be done with a baggage train of camels.","cn":"在过去，这往往由一队驮载行李的骆驼完成。"}},{"pos":"N-COUNT 可数名词","cn":"(想法、事件等的)(一)连串，(一)系列","en":"A train of thought or a train of events is a connected sequence, in which each thought or event seems to occur naturally or logically as a result of the previous one.","ex":{"en":"He lost his train of thought for a moment, then recovered it","cn":"他一时思维短路，然后又重新想了起来。"}},{"pos":"N-COUNT 可数名词","cn":"裙裾;拖裾","en":"The train of a woman's formal dress or wedding dress is the long part at the back of it which flows along the floor behind her."},{"pos":"PHRASE 短语","cn":"在进行中","en":"If a process or event is in train or has been set in train, it is happening or starting to happen.","ex":{"en":"In a moment the ceremony was in train…","cn":"仪式马上就要开始了。"}},{"pos":"PHRASE 短语","cn":"(问题、困难等)随之而来","en":"If something brings problems or difficulties in its train, the problems or difficulties occur as a natural or logical result of it.","ex":{"en":"The cars have brought in their train a host of other problems.","cn":"汽车随之带来其他一大堆问题。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(受)训练;(被)培训","en":"If someone trains you to do something, they teach you the skills that you need in order to do it. If you train to do something, you learn the skills that you need in order to do it.","ex":{"en":"The US was ready to train its troops to participate","cn":"美国准备训练军队参加。"}},{"pos":"VERB 动词","cn":"锻炼，培养(某一素质或能力)","en":"To train a natural quality or talent that someone has, for example their voice or musical ability, means to help them to develop it.","ex":{"en":"I see my degree as something which will train my mind and improve my chances of getting a job","cn":"我把学位视为可以锻炼心智、增加就业机会的东西。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(为体育活动)(使)进行训练(或锻炼)","en":"If you train for a physical activity such as a race or if someone trains you for it, you prepare for it by doing particular physical exercises.","ex":{"en":"Strachan is training for the new season","cn":"斯特罗恩正为新的赛季进行训练。"}},{"pos":"VERB 动词","cn":"训练(兽或鸟)","en":"If an animal or bird is trained to do particular things, it is taught to do them, for example in order to be able to work for someone or to be a good pet.","ex":{"en":"Sniffer dogs could be trained to track them down.","cn":"可以训练嗅探犬追捕他们。"}},{"pos":"VERB 动词","cn":"把…对准(或瞄准)","en":"If you train something such as a gun, a camera, or a light on a person or thing, you aim it at them and keep it towards them.","ex":{"en":"She trained her binoculars on the horizon","cn":"她将双筒望远镜对准地平线。"}},{"pos":"VERB 动词","cn":"(经整枝)使(植物)朝特定方向生长","en":"If you train a tree, bush, or plant in a particular direction, you tie it and cut it so that it grows in that direction.","ex":{"en":"Instead of training the shoots up the fence, lay them flat in both directions alongside it","cn":"不要让嫩枝爬上篱笆，要令其沿着篱笆伏地向两边长。"}},{"pos":"","cn":"","en":"相关词组：train up"}]},"examples":[{"en":"His death set in motion a train of events that led to the outbreak of war.","cn":"他的死引发了一系列的事件，从而导致了战争的爆发。"},{"en":"An expert with a trained eye will spot the difference immediately.","cn":"训练有素眼光敏锐的专家会马上发现差别所在。"}]},"transportation":{"media":{"uk":"media/uk/transportation__gb_1.mp3","us":"media/us/transportation__us_1.mp3"},"oxford":{"phon":"ˌtrænspɔːˈteɪʃn","pos":"noun","senses":[{"en":"a system for carrying people or goods from one place to another using vehicles, roads, etc.","cn":"交通运输系统","g":"[uncountable]","lab":"especially North American English","ex":{"en":"public transportation (= the system of buses, trains, etc. provided for people to travel from one place to another)","cn":"公共交通运输系统"}},{"en":"a vehicle or method of travel","cn":"交通车辆；运输工具；旅行方式","g":"[uncountable]","lab":"North American English","ex":{"en":"The city is providing free transportation to the stadium from downtown.","cn":"本市现在提供从市中心到体育场的免费交通。"}},{"en":"the activity or business of carrying goods from one place to another using trucks, trains, etc.","cn":"用卡车、火车等将货物从一个地方运送到另一个地方的活动或业务。","g":"[uncountable]","lab":"especially in British English","ex":{"en":"the transportation of heavy loads","cn":"重载运输"}},{"en":"(in the past) the act of sending criminals to a place that is far away as a form of punishment","cn":"（旧时的）流放"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"交通工具;运输工具","en":"Transportation refers to any type of vehicle that you can travel in or carry goods in.","ex":{"en":"The company will provide transportation.","cn":"公司会提供交通工具。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"交通运输系统;公共交通(网)","en":"Transportation is a system for taking people or goods from one place to another, for example using buses or trains.","ex":{"en":"Campuses are usually accessible by public transportation.","cn":"通常乘坐公共交通即可到达各个校区。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"运输;运送","en":"Transportation is the activity of taking goods or people from one place to another in a vehicle.","ex":{"en":"The baggage was being rapidly stowed away for transportation…","cn":"行李正在迅速装载等待运输。"}}]},"examples":[{"en":"The city is providing free transportation to the stadium from downtown.","cn":"本市现在提供从市中心到体育场的免费交通。"},{"en":"public transportation (= the system of buses, trains, etc. provided for people to travel from one place to another)","cn":"公共交通运输系统"}]},"traffic":{"media":{"uk":"media/uk/traffic__gb_1.mp3","us":"media/us/traffic__us_1.mp3"},"oxford":{"phon":"ˈtræfɪk","pos":"noun","senses":[{"en":"the vehicles that are on a road at a particular time","cn":"路上行驶的车辆；交通","lab":"British English","ex":{"en":"There's always a lot of traffic at this time of day.","cn":"每天这个时候总是有很多来往车辆。"}},{"en":"the movement of ships, trains, aircraft, etc. along a particular route","cn":"（沿固定路线的）航行，行驶，飞行","ex":{"en":"transatlantic traffic","cn":"横渡大西洋的航行"}},{"en":"the movement of people or goods from one place to another","cn":"运输；人流；货流","ex":{"en":"commuter/freight/passenger traffic","cn":"市郊间上下班运输；货运；客运"}},{"en":"the movement of messages and signals through an electronic communication system","cn":"信息流量；通信（量）","ex":{"en":"the computer servers that manage global internet traffic","cn":"管理全球互联网通信的计算机服务器"}},{"en":"illegal trade in something","cn":"（非法的）交易，买卖","ex":{"en":"the traffic in firearms","cn":"非法军火交易"}},{"en":"to move people illegally, especially in order to make them work in bad conditions without proper payment","cn":"非法贩卖人口（尤指迫使他们充当廉价劳工）","g":"[transitive, intransitive, usually passive]","ex":{"en":"The women had been trafficked and forced into sex work.","cn":"这些妇女被贩卖并被迫从事性工作。"},"pos":"verb"},{"en":"to buy and sell something illegally","cn":"（非法）进行…交易，做…买卖","g":"[transitive, intransitive]","ex":{"en":"Smugglers were trafficking arms across the border to the rebels.","cn":"走私分子越境将武器贩卖给叛乱者。"},"pos":"verb"},{"en":"to spread or try to encourage a harmful idea or type of behaviour","cn":"传播或试图鼓励有害的想法或行为类型","g":"[intransitive, transitive]","lab":"disapproving","ex":{"en":"We have no time for people who traffic in bigotry.","cn":"我们没有时间理会那些怀有偏执的人。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"车流;交通","en":"Traffic refers to all the vehicles that are moving along the roads in a particular area.","ex":{"en":"There was heavy traffic on the roads","cn":"道路上车流拥挤。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(海上、铁路或空中的)交通，通行;(客、货)运输量","en":"Traffic refers to the movement of ships, trains, or aircraft between one place and another. Traffic also refers to the people and goods that are being transported.","ex":{"en":"Air traffic had returned to normal","cn":"空中交通已恢复正常。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(毒品、赃物等的)非法买卖，非法交易","en":"Traffic in something such as drugs or stolen goods is an illegal trade in them.","ex":{"en":"Traffic in illicit drugs was now worth some 500 thousand million dollars a year.","cn":"如今每年非法毒品的交易值约在 5,000 亿美元。"}},{"pos":"VERB 动词","cn":"非法买卖(毒品、赃物等)","en":"Someone who traffics in something such as drugs or stolen goods buys and sells them even though it is illegal to do so.","ex":{"en":"The president said illegal drugs are hurting the entire world and anyone who traffics in them should be brought to justice.","cn":"总统称毒品正在危害整个世界，任何非法贩卖毒品的人都应依法受到惩处。"}}]},"examples":[{"en":"There's always a lot of traffic at this time of day.","cn":"每天这个时候总是有很多来往车辆。"},{"en":"the computer servers that manage global Internet traffic","cn":"管理全球互联网通信的计算机服务器"}]},"travelling":{"media":{"uk":"media/uk/travelling__gb_1.mp3","us":"media/us/travelling__us_1.mp3"},"oxford":{"phon":"ˈtrævəlɪŋ","pos":"adjective","senses":[{"en":"going from place to place","cn":"旅行的；巡回的；流动的","ex":{"en":"a travelling circus/exhibition/performer","cn":"巡回马戏团/展览/表演者"}},{"en":"belonging to a community of people who have no fixed home and move from place to place, for example Irish Travellers or Romani people","cn":"属于没有固定住所并从一个地方搬到另一个地方的人的社区，例如爱尔兰旅行者或罗姆人","lab":"British English","ex":{"en":"travelling people","cn":"不断迁移的人"}},{"en":"used when you travel","cn":"旅行用的","ex":{"en":"a travelling clock","cn":"旅行钟"}},{"en":"the act of travelling","cn":"旅行","ex":{"en":"The job requires a lot of travelling.","cn":"这个工作要求经常出差。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"巡回的;巡演的","en":"A travelling actor or musician, for example, is one who travels around an area or country performing in different places.","ex":{"en":"…troupes of travelling actors.","cn":"巡回剧团"}}]},"examples":[{"en":"a travelling circus/exhibition/performer, etc.","cn":"巡回马戏团、展览、表演者等"},{"en":"The job requires a lot of travelling.","cn":"这个工作要求经常出差。"}],"base":"travel"},"tried":{"lemma":"try","media":{"uk":"media/uk/tried__gb_1.mp3","us":"media/us/tried__us_1.mp3"}},"transparency":{"media":{"uk":"media/uk/transparency__gb_1.mp3","us":"media/us/transparency__us_1.mp3"},"oxford":{"phon":"trænsˈpærənsi","pos":"noun","senses":[{"en":"the quality of something, such as a situation or an argument, that makes it easy to understand","cn":"易懂；清楚；透明度","g":"[uncountable]","ex":{"en":"a need for greater transparency in legal documents","cn":"对法律文件更简明易懂的需求"}},{"en":"the quality of something, such as glass, that allows you to see through it","cn":"透明；透明性","g":"[uncountable]"},{"en":"a picture printed on a piece of film, usually in a frame, that can be shown on a screen by shining light through the film","cn":"幻灯片；透明正片","g":"[countable]","lab":"informal","ex":{"en":"an overhead transparency (= used with an overhead projector)","cn":"高射投影透明正片"}},{"en":"the quality in something, such as an excuse or a lie, that allows somebody to see the truth easily","cn":"显而易见；一目了然","g":"[uncountable]","ex":{"en":"They were shocked by the transparency of his lies.","cn":"他们感到震惊的是他竟睁着眼睛说瞎话。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(用于投影的)透明正片，幻灯片","en":"A transparency is a small piece of photographic film with a frame around it which can be projected onto a screen so that you can see the picture."},{"pos":"N-UNCOUNT 不可数名词","cn":"透明(性)","en":"Transparency is the quality that an object or substance has when you can see through it.","ex":{"en":"Cataracts is a condition that affects the transparency of the lenses.","cn":"白内障是一种影响晶状体透明性的疾病。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(过程、情形或陈述的)透明度，清晰度","en":"The transparency of a process, situation, or statement is its quality of being easily understood or recognized, for example because there are no secrets connected with it, or because it is expressed in a clear way.","ex":{"en":"The Chancellor emphasised his determination to promote openness and transparency in the Government's economic decision-making.","cn":"财政大臣强调了他促进政府经济决策公开透明的决心。"}}]},"examples":[{"en":"The police reforms will ensure greater transparency and accountability.","cn":"警察机构的改革将确保更大程度的透明度和问责性。"},{"en":"They were shocked by the transparency of his lies.","cn":"他们感到震惊的是他竟睁着眼睛说瞎话。"}]},"troublesome":{"media":{"uk":"media/uk/troublesome__gb_1.mp3","us":"media/us/troublesome__us_1.mp3"},"oxford":{"phon":"ˈtrʌblsəm","pos":"adjective","senses":[{"en":"causing trouble, pain, etc. over a long period of time","cn":"令人烦恼的；讨厌的；令人痛苦的","ex":{"en":"a troublesome cough/child/problem","cn":"烦人的咳嗽；让人心烦的孩子；棘手的问题"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人烦恼的;令人头疼的;烦人的","en":"You use troublesome to describe something or someone that causes annoying problems or difficulties.","ex":{"en":"He needed surgery to cure a troublesome back injury","cn":"他需要做手术来治好烦人的背伤。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(形势、问题等)麻烦的，困难的，棘手的","en":"A troublesome situation or issue is full of complicated problems or difficulties.","ex":{"en":"The economy has become a troublesome issue for the Conservative Party.","cn":"经济状况已成为保守党的一大难题。"}}]},"examples":[{"en":"a troublesome cough/child/problem","cn":"烦人的咳嗽；让人心烦的孩子；棘手的问题"},{"en":"a troublesome child","cn":"烦人的孩子"}]},"triangular":{"oxford":{"phon":"traɪˈæŋɡjələ(r)","pos":"adjective","senses":[{"en":"like a triangle in shape","cn":"三角的；三角形的"},{"en":"involving three people or groups","cn":"涉及三人的；三者的；三方的","ex":{"en":"a triangular contest in an election","cn":"竞选中三位候选人的角逐"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"三角(形)的","en":"Something that is triangular is in the shape of a triangle.","ex":{"en":"...cottages around a triangular green.","cn":"坐落在一块三角形绿地周围的小别墅"}},{"pos":"ADJ 形容词","cn":"三角关系的;三人间的;三方面的","en":"You can describe a relationship or situation as triangular if it involves three people or things.","ex":{"en":"One particular triangular relationship became the model of Simone's first novel.","cn":"一段特殊的三角关系成了西蒙娜第一本小说的原型。"}}]},"media":{"uk":"media/uk/triangular__gb_1.mp3","us":"media/us/triangular__us_1.mp3"},"examples":[{"en":"a triangular contest in an election","cn":"竞选中三位候选人的角逐"},{"en":"a triangular sporting competition","cn":"一项由三方参加的体育比赛"}]},"truce":{"media":{"uk":"media/uk/truce__gb_1.mp3","us":"media/us/truce__us_1.mp3"},"oxford":{"phon":"truːs","pos":"noun","senses":[{"en":"an agreement between enemies or opponents to stop fighting for an agreed period of time; the period of time that this lasts","cn":"停战协定；休战；停战期","ex":{"en":"to call/break a truce","cn":"宣布休战；破坏停战协定"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"停战(协定);休战(协定)","en":"A truce is an agreement between two people or groups of people to stop fighting or quarrelling for a short time.","ex":{"en":"The fighting of recent days has given way to an uneasy truce between the two sides","cn":"最近几天的交战结束了，双方达成了暂时的休战协议。"}}]},"examples":[{"en":"to call/break a truce","cn":"宣布休战；破坏停战协定"},{"en":"They agreed to call a truce .","cn":"他们同意宣布休战。"}]},"true":{"media":{"uk":"media/uk/true__gb_1.mp3","us":"media/us/true__us_1.mp3"},"oxford":{"phon":"truː","pos":"adjective","senses":[{"en":"connected with facts rather than things that have been invented or guessed","cn":"符合事实的；确实的；如实的","sc":"correct","ex":{"en":"Indicate whether the following statements are true or false.","cn":"标出下列说法是对还是错。"}},{"en":"real or exact, especially when this is different from how something seems","cn":"实质的，真正的（而非表面上的）","sc":"real","ex":{"en":"the true face of war (= what it is really like rather than what people think it is like)","cn":"战争的真实面目"}},{"en":"having the qualities or characteristics of the thing mentioned","cn":"名副其实的；真正的","g":"[usually before noun]","sc":"real","ex":{"en":"It was true love between them.","cn":"他们是真心相爱。"}},{"en":"used to admit that a particular fact or statement is correct, although you think that something else is more important","cn":"（承认事实或说法正确，但有更重要的考虑）确实，的确","sc":"admitting fact","ex":{"en":"It's true that he could do the job, but would he fit in with the rest of the team?","cn":"他确实能做这项工作，但他是否能和团队其他人配合得好呢？"}},{"en":"showing respect and support for a particular person or belief in a way that does not change, even in different situations","cn":"忠诚的；忠心耿耿的；忠实的","sc":"loyal","ex":{"en":"a true friend","cn":"忠实的朋友"}},{"en":"being an accurate version or copy of something","cn":"精确的；与正本无异的；逼真的","sc":"accurate","ex":{"en":"The movie is not true to the book.","cn":"这部电影并非忠于原著。"}},{"en":"straight and accurate","cn":"正而准","g":"[not usually before noun]","lab":"old-fashioned or literary","sc":"accurate","ex":{"en":"His aim was true (= he hit the target).","cn":"他瞄得很准。"}},{"en":"in a direct line","cn":"笔直地；不偏不斜地","sc":"straight","ex":{"en":"The arrow flew straight and true to the target.","cn":"箭不偏不斜地朝靶子飞去。"},"pos":"adverb"},{"en":"to tell the truth","cn":"直言相告；实话实说","sc":"correctly","ex":{"en":"He had spoken truer than he knew.","cn":"他说得比他知道的还确切。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"基于事实的;真实的;如实的;可信的","en":"If something is true, it is based on facts rather than being invented or imagined, and is accurate and reliable.","ex":{"en":"Everything I had heard about him was true","cn":"我听说的关于他的一切都是真实的。"}},{"pos":"ADJ 形容词","cn":"(感情)真实的，真挚的；（物品）真的，真正的,正品的","en":"You use true to emphasize that a person or thing is sincere or genuine, often in contrast to something that is pretended or hidden.","ex":{"en":"I allowed myself to acknowledge my true feelings","cn":"我愿意承认我的真实感情。"}},{"pos":"ADJ 形容词","cn":"纯粹的;真正的;名副其实的","en":"If you use true to describe something or someone, you approve of them because they have all the characteristics or qualities that such a person or thing typically has.","ex":{"en":"This country professes to be a true democracy…","cn":"这个国家自称是真正的民主政体。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"适用的;符合的;合理的","en":"If you say that a fact is true of a particular person or situation, you mean that it is valid or relevant for them.","ex":{"en":"I accept that the romance may have gone out of the marriage, but surely this is true of many couples","cn":"我同意婚姻里可能已经没有了浪漫这一说法，而且很多夫妻都的确如此。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"确实的;诚然的","en":"You can use true in order to admit that a fact or opinion is real or valid before indicating that you think that it is not important or relevant in the circumstances.","ex":{"en":"It's true she gets madly impatient with him, but what mother doesn't?…","cn":"她确实对他极其不耐烦，但哪个母亲不是这样呢？"}},{"pos":"ADJ 形容词","cn":"忠实的;忠诚的;恪守(诺言、思想等)的","en":"If you are true to someone, you remain committed and loyal to them. If you are true to an idea or promise, you remain committed to it and continue to act according to it.","ex":{"en":"David was true to his wife","cn":"戴维忠于妻子。"}},{"pos":"PHRASE 短语","cn":"(梦想、愿望或预言)成真，成为现实","en":"If a dream, wish, or prediction comes true, it actually happens.","ex":{"en":"Many of his predictions are coming true…","cn":"他的很多预言正成为现实。"}},{"pos":"PHRASE 短语","cn":"同样适用;在…情况下亦然","en":"If a general statement holds true in particular circumstances, or if your previous statement holds true in different circumstances, it is true or valid in those circumstances.","ex":{"en":"This law is known to hold true for galaxies at a distance of at least several billion light years.","cn":"据知，这条定律同样适用于距离至少几十亿光年之远的星系。"}},{"pos":"PHRASE 短语","cn":"好得令人难以置信","en":"If you say that something seems too good to be true, you are suspicious of it because it seems better than you had expected, and you think there may something wrong with it that you have not noticed.","ex":{"en":"On the whole the celebrations were remarkably good-humoured and peaceful. Indeed, it seemed almost too good to be true.","cn":"总体上，庆典活动一派快乐祥和。事实上，简直好得让人难以置信。"}},{"pos":"PHRASE 短语","cn":"栩栩如生;逼真;活灵活现","en":"If you say that something such as a story or a film is true to life, you approve of it because it seems real.","ex":{"en":"The opening scenes of this movie are just not true to life.","cn":"这部电影开场的几幕真是太假了。"}},{"pos":"","cn":"","en":"true colours→see: ; true to form→see: ; to ring true→see: ; tried and true→see: ;"}]},"examples":[{"en":"‘We could get it cheaper.’ ‘True, but would it be as good?’ “","cn":"我们可以买得再便宜一点儿。” “话是这么说，但是质量是不是一样好呢？”"},{"en":"‘I'm afraid you were quoted the wrong price.’ ‘I thought it was too good to be true.’ “","cn":"很抱歉，给你报错价了。” “我也觉得价格低得难以令人置信。”"}]},"tries":{"lemma":"try","media":{"uk":"media/uk/try__gb_1.mp3","us":"media/us/try__us_1.mp3"}},"treacherous":{"media":{"uk":"media/uk/treacherous__gb_1.mp3","us":"media/us/treacherous__us_1.mp3"},"oxford":{"phon":"ˈtretʃərəs","pos":"adjective","senses":[{"en":"that cannot be trusted; intending to harm you","cn":"不可信任的；背叛的；奸诈的","ex":{"en":"He was weak, cowardly and treacherous.","cn":"他软弱、胆怯、奸诈。"}},{"en":"dangerous, especially when seeming safe","cn":"有潜在危险的","ex":{"en":"The ice on the roads made driving conditions treacherous.","cn":"路上的冰对驾车构成了隐患。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奸诈的;背信弃义的;不可信任的","en":"If you describe someone as treacherous, you mean that they are likely to betray you and cannot be trusted.","ex":{"en":"He publicly left the party and denounced its treacherous leaders","cn":"他公开脱离该党，并谴责该党领袖背信弃义。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"危险的;变化无常的","en":"If you say that something is treacherous, you mean that it is very dangerous and unpredictable.","ex":{"en":"The current of the river is fast flowing and treacherous","cn":"这条河水流湍急，变幻莫测。"}}]},"examples":[{"en":"The ice on the roads made driving conditions treacherous.","cn":"路上的冰对驾车构成了隐患。"},{"en":"He was weak, cowardly and treacherous.","cn":"他软弱、胆怯、奸诈。"}]},"translator":{"oxford":{"phon":"trænzˈleɪtə(r)","pos":"noun","senses":[{"en":"a person who translates writing or speech into a different language, especially as a job","cn":"（尤指专职）翻译，译员，译者，翻译家","ex":{"en":"She works as a translator of technical texts.","cn":"她的工作是科技翻译。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(专职)翻译，译者，译员，翻译家","en":"A translator is a person whose job is translating writing or speech from one language to another."}]},"media":{"uk":"media/uk/translator__gb_1.mp3","us":"media/us/translator__us_1.mp3"},"examples":[{"en":"She works as a translator of technical texts.","cn":"她的工作是科技翻译。"}]},"trim":{"oxford":{"phon":"trɪm","pos":"verb","senses":[{"en":"to make something neater, smaller, better, etc., by cutting parts from it","cn":"修剪；修整","lab":"figurative","ex":{"en":"to trim your hair","cn":"理发"}},{"en":"to cut away unnecessary parts from something","cn":"切去，割掉，剪下，除去（不必要的部分）","ex":{"en":"Trim any excess fat off the meat.","cn":"把多余的肥膘从肉上切掉。"}},{"en":"to decorate something, especially around its edges","cn":"装饰，修饰，点缀（尤指某物的边缘）","g":"[usually passive]","ex":{"en":"gloves trimmed with fur","cn":"毛皮镶边的手套"}},{"en":"an act of cutting a small amount off something, especially hair","cn":"（尤指毛发的）修剪","g":"[countable, usually singular]","ex":{"en":"a wash and trim","cn":"洗头理发"},"pos":"noun"},{"en":"material that is used to decorate clothes, furniture, cars, etc., especially along the edges, by being a different colour, etc.","cn":"（衣服、家具、汽车等的）饰物，边饰，装饰配件","g":"[uncountable, singular]","ex":{"en":"The car is available with black or red trim (= the colour of the seats).","cn":"这款汽车的座椅有黑红两种颜色。"},"pos":"noun"},{"en":"looking thin, healthy and attractive","cn":"苗条的；修长的；健康优雅的","ex":{"en":"She has kept very trim.","cn":"她的身材保持得很苗条。"},"pos":"adjective"},{"en":"neat and well cared for","cn":"整齐的；精心照管的；井然有序的","ex":{"en":"a trim garden","cn":"精心管理的花园"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"整齐的;美观整洁的","en":"Something that is trim is neat, tidy, and attractive.","ex":{"en":"The neighbours' gardens were trim and neat.","cn":"邻居们的花园整洁美观。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"苗条的;修长的","en":"If you describe someone's figure as trim, you mean that it is attractive because there is no extra fat on their body.","ex":{"en":"The driver was a trim young woman of perhaps thirty.","cn":"司机是个大约 30 岁的身材苗条的年轻女子。"}},{"pos":"VERB 动词","cn":"修剪;剪","en":"If you trim something, for example someone's hair, you cut off small amounts of it in order to make it look neater and tidier.","ex":{"en":"My friend trims my hair every eight weeks","cn":"我朋友每 8 个星期为我修剪一次头发。"}},{"pos":"VERB 动词","cn":"削减;缩减","en":"If a government or other organization trims something such as a plan, policy, or amount, they reduce it slightly in extent or size.","ex":{"en":"American companies looked at ways they could trim these costs","cn":"美国公司研究了能够削减这些成本的方法。"}},{"pos":"VERB 动词","cn":"点缀；装饰；(以…）镶边","en":"If something such as a piece of clothing is trimmed with a type of material or design, it is decorated with it, usually along its edges.","ex":{"en":"...jackets, which are then trimmed with crocheted flowers","cn":"另外以钩花镶边的夹克"}},{"pos":"N-VAR 可变名词","cn":"装饰(物);镶边","en":"The trim on something such as a piece of clothing is a decoration, for example along its edges, that is in a different colour or material.","ex":{"en":"...a white satin scarf with black trim","cn":"黑边白缎围巾"}},{"pos":"PHRASE 短语","cn":"健康;身体状况良好","en":"When people are in trim or in good trim, they are in good physical condition.","ex":{"en":"He is already getting in trim for the big day","cn":"他已经在为那个重要的日子调整状态了。"}},{"pos":"","cn":"","en":"相关词组：trim away"}]},"media":{"uk":"media/uk/trim__gb_1.mp3","us":"media/us/trim__us_1.mp3"},"examples":[{"en":"Using the diet he's trimmed down from 90 kilos to 70.","cn":"通过控制饮食，他的体重从 90 公斤减到了 70 公斤。"},{"en":"The team need to get in trim for the coming season.","cn":"这个球队需要为下个赛季做好准备。"}]},"track":{"media":{"uk":"media/uk/track__gb_1.mp3","us":"media/us/track__us_1.mp3","img":["media/ldoce/img/track.jpg"]},"oxford":{"phon":"træk","pos":"noun","senses":[{"en":"rails (= metal bars) that a train moves along","cn":"轨道","g":"[countable, uncountable]","sc":"for train","ex":{"en":"railway/railroad tracks","cn":"铁路轨道"}},{"en":"a track with a number at a train station that a train arrives at or leaves from","cn":"（火车站有编号的）轨道，站台","g":"[countable]","lab":"North American English","sc":"for train","ex":{"en":"The train for Chicago is on track 9.","cn":"开往芝加哥的列车停靠在 9 号站台。"}},{"en":"a piece of ground with a special surface for people, cars, etc. to have races or to drive on","cn":"（赛跑、赛车等的）跑道","g":"[countable]","sc":"for races","ex":{"en":"a race track","cn":"赛道"}},{"en":"the sport of running on a track","cn":"径赛","g":"[uncountable]","lab":"North American English","sc":"for races","ex":{"en":"He loves sports and participates in track and basketball.","cn":"他爱好运动，参加径赛和打篮球。"}},{"en":"a rough path or road, usually one that has not been built but that has been made by people walking there","cn":"（人踩出的）小道，小径","g":"[countable]","sc":"rough path","ex":{"en":"a muddy track through the forest","cn":"穿过森林的泥泞小径"}},{"en":"marks left by a person, an animal or a moving vehicle","cn":"（人、动物或车辆留下的）足迹，踪迹；车辙","g":"[countable, usually plural]","sc":"marks on ground","ex":{"en":"We followed the bear's tracks in the snow.","cn":"我们跟着熊在雪地上留下的足迹走。"}},{"en":"the path or direction that somebody/something is moving in","cn":"（移动的）路径，路线，方向","g":"[countable]","sc":"direction/course","ex":{"en":"He switched tracks and went back to college.","cn":"他掉转方向回到学院。"}},{"en":"a recording of one song or piece of music","cn":"一首录制的歌曲（或乐曲）","g":"[countable]","sc":"recording","ex":{"en":"a track from their latest album","cn":"他们最新唱片专辑里的一首歌曲"}},{"en":"part of a computer disk or tape that music or information can be recorded on","cn":"（计算机磁盘或磁带的）音轨，声道","g":"[countable]","sc":"recording","ex":{"en":"a sixteen track recording studio","cn":"十六声道录音室"}},{"en":"the soundtrack of a film or video","cn":"（电影、视频的）声迹，声带","sc":"recording","ex":{"en":"The film is available with French and Spanish audio tracks.","cn":"这部电影有法语和西班牙语配音版的。"}},{"en":"a long, thin, straight piece of metal, wood or plastic that a curtain hangs from and moves along","cn":"（幕帘的）滑轨，滑道","g":"[countable]","sc":"for curtain"},{"en":"a continuous belt of metal plates around the wheels of a large vehicle such as a bulldozer that allows it to move over the ground","cn":"（推土机等的）履带","g":"[countable]","sc":"on large vehicle"},{"en":"to find somebody/something by following the marks, signs, information, etc., that they have left behind them","cn":"跟踪；追踪","g":"[transitive, intransitive]","sc":"follow","ex":{"en":"hunters tracking and shooting bears","cn":"追踪射猎熊的猎人"},"pos":"verb"},{"en":"to follow the movements of somebody/something, especially by using special electronic equipment","cn":"（尤指用特殊电子设备）跟踪，追踪","g":"[transitive]","sc":"follow","ex":{"en":"We continued tracking the plane on our radar.","cn":"我们继续用雷达追踪那架飞机。"},"pos":"verb"},{"en":"to follow the progress or development of somebody/something","cn":"跟踪（进展情况）","g":"[transitive]","sc":"follow","ex":{"en":"The research project involves tracking the careers of 400 graduates.","cn":"这个研究项目对 400 名毕业生的事业发展情况进行跟踪调查。"},"pos":"verb"},{"en":"to move in relation to the thing that is being filmed","cn":"跟踪摄影；移动摄影","g":"[intransitive]","sc":"of camera","ex":{"en":"The camera eventually tracked away.","cn":"摄影机最终将镜头推远。"},"pos":"verb"},{"en":"to put school students into groups according to their ability","cn":"按能力分班（或分组）","g":"[transitive]","lab":"North American English","sc":"school students","pos":"verb"},{"en":"to leave dirty marks behind you as you walk","cn":"留下（脏）足迹","g":"[transitive]","lab":"especially North American English","sc":"leave marks","ex":{"en":"Don't track mud on my clean floor.","cn":"别在我干净的地板上踩上泥脚印。"},"pos":"verb"},{"en":"to stay at the same level for a period of time","cn":"（一段时间内）保持（某一水平）；沿袭","g":"[intransitive]","sc":"of a statistic, number, etc.","ex":{"en":"Annual employment growth is tracking at 2%.","cn":"年度就业增长率保持在 2%。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小道;小径","en":"A track is a narrow road or path.","ex":{"en":"We set off once more, over a rough mountain track.","cn":"我们沿着一条崎岖的山间小路再度出发。"}},{"pos":"N-COUNT 可数名词","cn":"跑道;赛道","en":"A track is a piece of ground, often oval-shaped, that is used for races involving athletes, cars, bicycles, horses, or dogs called greyhounds.","ex":{"en":"The two men turned to watch the horses going round the track.","cn":"那两个男人转身观看赛马沿赛道而行。"}},{"pos":"N-COUNT 可数名词","cn":"铁轨;轨道","en":"Railway tracks are the rails that a train travels along.","ex":{"en":"A woman fell on to the tracks.","cn":"一名女子摔倒在铁轨上。"}},{"pos":"N-COUNT 可数名词","cn":"(CD、唱片或磁带上的一首)歌曲，乐曲","en":"A track is one of the songs or pieces of music on a CD, record, or tape.","ex":{"en":"Graeme Naysmith has produced two of the ten tracks on this album.","cn":"格雷姆·内史密斯创作了这张专辑十首歌中的两首。"}},{"pos":"N-PLURAL 复数名词","cn":"足迹;踪迹","en":"Tracks are marks left in the ground by the feet of animals or people.","ex":{"en":"The only evidence of pandas was their tracks in the snow","cn":"熊猫活动的唯一迹象是它们留在雪地上的足迹。"}},{"pos":"VERB 动词","cn":"跟踪;追踪","en":"If you track animals or people, you try to follow them by looking for the signs that they have left behind, for example the marks left by their feet.","ex":{"en":"He thought he had better track this wolf and kill it","cn":"他认为最好跟踪这只狼，杀了它。"}},{"pos":"VERB 动词","cn":"(以卫星、雷达等)追踪…的动向","en":"To track someone or something means to follow their movements by means of a special device, such as a satellite or radar.","ex":{"en":"Our radar began tracking the jets","cn":"我们的雷达开始追踪喷气式飞机的动向。"}},{"pos":"VERB 动词","cn":"追踪调查;探究","en":"If you track someone or something, you investigate them, because you are interested in finding out more about them.","ex":{"en":"If it's possible, track the rumour back to its origin","cn":"如果可能，应追查谣言的源头。"}},{"pos":"N-COUNT 可数名词","cn":"(同等年龄、能力的孩子组成的)班级，班组","en":"In a school, a track is a group of children of the same age and ability who are taught together."},{"pos":"VERB 动词","cn":"把(学生)按能力分班(或组)","en":"To track students means to divide them into groups according to their ability.","ex":{"en":"Students are already being tracked.","cn":"学生已经按能力分班了。"}},{"pos":"PHRASE 短语","cn":"掩盖行踪;隐匿身份(或活动)","en":"If someone covers their tracks, they hide or destroy evidence of their identity or their actions, because they want to keep them secret.","ex":{"en":"He covered his tracks, burnt letters and diaries","cn":"他掩盖形迹，烧毁了信件与日记。"}},{"pos":"PHRASE 短语","cn":"占优势;处于有利地位;了解内情","en":"If you say that someone has the inside track, you mean that they have an advantage, for example special knowledge about something.","ex":{"en":"Denver has the inside track among 10 sites being considered","cn":"丹佛在 10 个被考虑的地点之中具有优势。"}},{"pos":"PHRASE 短语","cn":"跟上…的进展;掌握…的最新消息","en":"If you keep track of a situation or a person, you make sure that you have the newest and most accurate information about them all the time.","ex":{"en":"With eleven thousand employees, it's very difficult to keep track of them all","cn":"对于一支 1.1 万人的员工队伍，很难及时了解到所有有人的动态。"}},{"pos":"PHRASE 短语","cn":"跟不上…的进展;不再掌握…的最新情况","en":"If you lose track of someone or something, you no longer know where they are or what is happening.","ex":{"en":"You become so deeply absorbed in an activity that you lose track of time","cn":"你会因过于专注某项活动而失去时间概念。"}},{"pos":"PHRASE 短语","cn":"(匆匆)离开","en":"If you make tracks, you leave the place where you are, especially when you are in a hurry.","ex":{"en":"We'd better make tracks soon, hadn't we?","cn":"我们最好马上就走，不是吗？"}},{"pos":"PHRASE 短语","cn":"在正确的轨道上","en":"If someone or something is on track, they are acting or progressing in a way that is likely to result in success.","ex":{"en":"It may take some time to get the British economy back on track","cn":"要使英国经济重新回到正轨可能需要一段时间。"}},{"pos":"PHRASE 短语","cn":"追踪;追查;探究","en":"If you are on the track of someone or something, you are trying to find them, or find information about them.","ex":{"en":"He was on the track of an escaped criminal","cn":"他正在追踪一名逃犯。"}},{"pos":"PHRASE 短语","cn":"循着正确/错误的路线;在正确/错误的道路上","en":"If you are on the right track, you are acting or progressing in a way that is likely to result in success. If you are on the wrong track, you are acting or progressing in a way that is likely to result in failure.","ex":{"en":"Guests are returning in increasing numbers — a sure sign that we are on the right track","cn":"回头客越来越多了——这显然表明我们的路走对了。"}},{"pos":"PHRASE 短语","cn":"(使)突然止步，突然停下","en":"If someone or something stops you in your tracks, or if you stop dead in your tracks, you suddenly stop moving because you are very surprised, impressed, or frightened.","ex":{"en":"This magnificent church cannot fail to stop you in your tracks…","cn":"这座宏伟的教堂一定会让你止步赞叹。"}},{"pos":"PHRASE 短语","cn":"(使)立即停止，立即中断","en":"If someone or something stops a process or activity in its tracks, or if it stops dead in its tracks, they prevent the process or activity from continuing.","ex":{"en":"Francis felt he would like to stop this conversation in its tracks…","cn":"弗朗西斯觉得他应该立即打断这一谈话。"}},{"pos":"","cn":"","en":"off the beaten track→see: ;"},{"pos":"","cn":"","en":"相关词组：track down"}]},"examples":[{"en":"The research project involves tracking the careers of 400 graduates.","cn":"这个研究项目对 400 名毕业生的事业发展情况进行跟踪调查。"},{"en":"Bank statements help you keep track of where your money is going.","cn":"银行账单有助于你了解你的资金使用情况。"}]},"truck":{"oxford":{"phon":"trʌk","pos":"noun","senses":[{"en":"a large vehicle for carrying heavy loads by road","cn":"卡车；货运汽车","lab":"especially North American English","ex":{"en":"a truck driver","cn":"卡车司机"}},{"en":"an open railway vehicle for carrying goods or animals","cn":"（铁路上运送货物或动物的）敞篷车，无盖车皮","lab":"British English","ex":{"en":"a cattle truck","cn":"敞篷运牛车厢"}},{"en":"a vehicle that is open at the back, used for carrying goods, soldiers, animals, etc.","cn":"（运送货物、士兵、动物等后面敞开的）载重汽车","ex":{"en":"a delivery/farm truck","cn":"送货车；农用卡车"}},{"en":"a vehicle for carrying things, that is pulled or pushed by hand","cn":"（运送东西的）手推车，手拉车"},{"en":"to take something somewhere by truck","cn":"用卡车装运","ex":{"en":"Water had to be trucked in to the town.","cn":"水必须用卡车运到镇上。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"卡车","en":"A truck is a large vehicle that is used to transport goods by road.","ex":{"en":"Now and then they heard the roar of a heavy truck.","cn":"他们不时地听到大卡车的轰鸣声。"}},{"pos":"N-COUNT 可数名词","cn":"(铁路)运货车皮，敞篷货运火车","en":"A truck is an open vehicle used for carrying goods on a railway.","ex":{"en":"They were loaded on the railway trucks to go to Liverpool.","cn":"它们被装上开往利物浦的货运火车。"}},{"pos":"VERB 动词","cn":"用卡车装运;用货车运送","en":"When something or someone is trucked somewhere, they are driven there in a lorry.","ex":{"en":"The liquor was sold legally and trucked out of the state.","cn":"该酒合法出售，用卡车运出了该州。"}},{"pos":"PHRASE 短语","cn":"不愿参与;不与…来往;不掺和","en":"If you say that you will have no truck with someone or something, you are refusing to be involved with them in any way.","ex":{"en":"He would have no truck with deceit","cn":"他不愿去骗人。"}}]},"media":{"img":["media/pic/trucks_comp.jpg","media/thumb/lorry.jpg","media/ldoce/img/lorry.jpg"],"uk":"media/uk/truck__gb_1.mp3","us":"media/us/truck__us_1.mp3"},"examples":[{"en":"We in this party will have no truck with illegal organizations.","cn":"我们党的成员绝不与非法组织有来往。"},{"en":"a delivery/garbage/farm truck","cn":"送货车；垃圾车；农用卡车"}]},"travelled":{"media":{"uk":"media/uk/travelled__gb_1.mp3","us":"media/us/travelled__us_1.mp3"},"oxford":{"phon":"ˈtrævld","pos":"adjective","senses":[{"en":"having travelled the amount mentioned","cn":"有过…次旅行的；到过…地方的","ex":{"en":"a much-travelled man","cn":"见多识广的人"}},{"en":"used the amount mentioned","cn":"（常有人或不常有人）走的","ex":{"en":"The path was steeper and less travelled than the previous one.","cn":"这条小路比刚才那条陡，走的人少。"}}]},"examples":[{"en":"The path was steeper and less travelled than the previous one.","cn":"这条小路比刚才那条陡，走的人少。"},{"en":"a much-travelled man","cn":"见多识广的人"}],"base":"travel"},"tract":{"media":{"uk":"media/uk/tract__gb_1.mp3","us":"media/us/tract__us_1.mp3"},"oxford":{"phon":"trækt","pos":"noun","senses":[{"en":"a system of connected organs or tissues along which materials or messages pass","cn":"（连通身体组织或器官的）道，束","lab":"biology","ex":{"en":"the digestive tract","cn":"消化道"}},{"en":"an area of land, especially a large one","cn":"大片土地；地带","ex":{"en":"vast tracts of forest","cn":"大片大片的森林"}},{"en":"a short piece of writing, especially on a religious, moral or political subject, that is intended to influence people’s ideas","cn":"（尤指宣扬宗教、伦理或政治的）短文，传单，小册子","lab":"sometimes disapproving","ex":{"en":"feminist tracts","cn":"女权主义小册子"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(土地等的)大片","en":"A tract of land is a very large area of land.","ex":{"en":"A vast tract of land is ready for development","cn":"一大片广阔的土地可待开发。"}},{"pos":"N-COUNT 可数名词","cn":"(宗教、道德或政治的)短文","en":"A tract is a short article expressing a strong opinion on a religious, moral, or political subject in order to try to influence people's attitudes.","ex":{"en":"She produced a feminist tract, 'Comments on Birth-Control', in 1930.","cn":"她 1930 年写了篇女性主义的短文《论节育》。"}},{"pos":"N-COUNT 可数名词","cn":"道;束","en":"A tract is a system of organs and tubes in an animal's or person's body that has a particular function, especially the function of processing a substance in the body.","ex":{"en":"Foods are broken down in the digestive tract","cn":"食物在消化道里分解。"}}]},"examples":[{"en":"vast tracts of forest","cn":"大片大片的森林"},{"en":"the digestive tract","cn":"消化道"}]},"traditions":{"lemma":"tradition"},"trickled":{"lemma":"trickle"},"trustees":{"lemma":"trusty"},"trudged":{"lemma":"trudge"},"tracks":{"lemma":"track"},"treated":{"lemma":"treat"},"tramped":{"lemma":"tramp"},"translating":{"lemma":"translate"},"trundling":{"lemma":"trundle"},"traveling":{"lemma":"travel"},"trips":{"lemma":"trip"},"tracking":{"lemma":"track","media":{"uk":"media/ldoce/hwd/bre/c/ld41tracking.mp3","us":"media/ldoce/hwd/ame/b/laadtracking.mp3"}},"trumped":{"lemma":"trump"},"traders":{"lemma":"trader"},"trembling":{"lemma":"tremble"},"treasures":{"lemma":"treasure"},"trials":{"lemma":"trial"},"trees":{"lemma":"tree"},"transmitted":{"lemma":"transmit"},"trains":{"lemma":"train","media":{"img":["media/pic/trains_comp.jpg"]}},"trainmen":{"oxford":{"phon":"ˈtreɪnmən","pos":"noun","senses":[{"en":"a member of the team of people operating a train","cn":"列车员；乘务员"}]}},"tracts":{"lemma":"tract"},"trusted":{"lemma":"trust"},"translations":{"lemma":"translation"},"trapped":{"lemma":"trap"},"troubles":{"lemma":"trouble","media":{"uk":"media/ldoce/hwd/bre/d/p028-000012232.mp3","us":"media/ldoce/hwd/ame/4/troubles__the_n.mp3"}},"trudging":{"lemma":"trudge"},"traitors":{"lemma":"traitor"},"tramping":{"oxford":{"phon":"ˈtræmpɪŋ","pos":"noun","senses":[{"en":"the activity of going for long walks over rough country, carrying all the food and equipment that you need","cn":"长途徒步旅行（带足食物和装备穿越崎岖地区）"}]},"base":"tramp"},"trombones":{"lemma":"trombone"},"translates":{"lemma":"translate"},"trained":{"lemma":"train"},"traversed":{"lemma":"traverse"},"tribes":{"lemma":"tribe"},"traveler":{"lemma":"traveller"},"traces":{"lemma":"trace"},"traced":{"lemma":"trace"},"travels":{"lemma":"travel"},"triviality":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"琐事;小事","en":"If you refer to something as a triviality, you think that it is unimportant and not serious.","ex":{"en":"He accused me of making a great fuss about trivialities","cn":"他指责我为丁点琐事大惊小怪。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is not important at all","cn":"琐事"},{"en":"the fact of not being at all important or serious","cn":"琐碎﹔平凡"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41triviality.mp3","us":"media/ldoce/hwd/ame/6/triviality.mp3"},"examples":[{"en":"I don't want to waste time on trivialities.","cn":"我不想把时间浪费在一些琐碎小事上。"},{"en":"His speech was one of great triviality.","cn":"他的讲话根本无足轻重。"}],"oxford":{"phon":"ˌtrɪviˈæləti","pos":"noun","senses":[{"en":"a matter that is not important","cn":"琐事；小事","g":"[countable]","ex":{"en":"I don't want to waste time on trivialities.","cn":"我不想把时间浪费在一些琐碎小事上。"}},{"en":"the state of being unimportant or of dealing with unimportant things","cn":"微不足道；琐碎；无足轻重","g":"[uncountable]","ex":{"en":"His speech was one of great triviality.","cn":"他的讲话根本无足轻重。"}}]}},"trill":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(鸟)啭鸣，唧啾","en":"If a bird trills, it sings with short, high-pitched, repeated notes.","ex":{"en":"At one point a bird trilled in the Conservatory.","cn":"有那么一刻，一只鸟儿在温室里啼叫。"}},{"pos":"VERB 动词","cn":"尖声地说(或笑)","en":"If you say that a woman trills, you mean that she talks or laughs in a high-pitched voice which sounds rather musical but which also sounds rather irritating.","ex":{"en":"'How adorable!' she trills.","cn":"“真可爱!”她尖声说。"}},{"pos":"N-COUNT 可数名词","cn":"颤音","en":"A trill is the playing of two musical notes repeatedly and quickly one after the other."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a short repeated high sound","cn":"连续发出短促尖声﹔发（颤音）"},{"en":"to say something in a high happy voice that sounds slightly false","cn":"欢快地尖声说"},{"en":"a musical sound made by quickly moving between two notes 〔","cn":"音乐的〕颤音"}]},"vocab":{"pos":"n v","senses":[{"en":"If you're fluent in Spanish, you are probably able to speak with a trill , or a fluttering r sound."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41trill2.mp3","us":"media/ldoce/hwd/ame/4/trill1.mp3"},"examples":[{"en":"The canary was trilling away happily.","cn":"那只金丝雀唧唧啾啾地欢唱个不停。"},{"en":"A phone trilled on the desk.","cn":"办公桌上的电话丁零零地响了。"}],"oxford":{"phon":"trɪl","pos":"noun","senses":[{"en":"a repeated short, high sound made, for example, by somebody’s voice or by a bird","cn":"（人的）颤声，短促尖声；（鸟的）啼啭，唧唧啾啾"},{"en":"the sound made when two notes next to each other in the musical scale are played or sung quickly several times one after the other","cn":"颤音","lab":"music"},{"en":"a sound, usually a /r/, produced by making the tongue vibrate against a part of the mouth","cn":"颤音","lab":"phonetics"},{"en":"to make repeated short, high sounds","cn":"（连续）发颤音，发短促的响声","g":"[intransitive]","ex":{"en":"A phone trilled on the desk.","cn":"办公桌上的电话丁零零地响了。"},"pos":"verb"},{"en":"to say something in a high, cheerful voice","cn":"欢快地高声说","g":"[transitive]","ex":{"en":"‘How wonderful!’ she trilled.","cn":"“太妙了！”她高兴地喊道。"},"pos":"verb"},{"en":"to pronounce a /r/ sound by making a trill","cn":"发 r 颤音","g":"[transitive]","lab":"phonetics","pos":"verb"}]}},"transporter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(大型或重型)运输车辆，运输机","en":"A transporter is a large vehicle or an aeroplane that is used for carrying very large or heavy objects, for example cars."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long vehicle that can carry one or more other vehicles 〔","cn":"运载其他车辆的〕运输车"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41transporter.mp3","us":"media/ldoce/hwd/ame/d/transporter.mp3","img":["media/thumb/transporter.jpg"]},"examples":[{"en":"a car transporter","cn":"装运汽车的运输车"}],"oxford":{"phon":"trænˈspɔːtə(r)","pos":"noun","senses":[{"en":"a large vehicle used for carrying heavy objects, for example other vehicles","cn":"大型载重运输车","ex":{"en":"a car transporter","cn":"装运汽车的运输车"}}]}},"trustworthy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可信赖的;值得信赖的；可靠的","en":"A trustworthy person is reliable, responsible, and can be trusted completely.","ex":{"en":"He is a trustworthy and level-headed leader.","cn":"他是个头脑冷静、值得信赖的领导。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone is trustworthy, you can trust them because they are honest","cn":""},{"en":"someone who is reliable can be trusted to do what they say they will do and not make any mistakes","cn":""},{"en":"someone who is responsible can be trusted to behave in a sensible way","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Trustworthy describes something you can believe in — it's completely reliable. Your favorite newspaper can be trustworthy — they always print the truth — and people can be trustworthy too. You only tell your secrets to a trustworthy friend."}]},"media":{"uk":"media/ldoce/hwd/bre/1/trustworthy0205.mp3","us":"media/ldoce/hwd/ame/1/trustworthy.mp3"},"oxford":{"phon":"ˈtrʌstwɜːði","pos":"adjective","senses":[{"en":"that you can rely on to be good, honest, sincere, etc.","cn":"值得信任的；可信赖的；可靠的","ex":{"en":"Mitchell was a solid and trustworthy man.","cn":"米切尔是一个坚定而值得信赖的人。"}}]}},"transgressor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"违犯者;违反者","en":"A transgressor is someone who has broken a particular rule or law or has done something that is generally considered unacceptable."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something that is against the rules of social behaviour or against a moral principle","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"You can use the noun transgressor for anyone who violates a rule or oversteps a boundary. You are being a transgressor , for example, when you bring your barking dog into the library."}]},"media":{"uk":"media/ldoce/hwd/bre/3/transgress0205.mp3","us":"media/ldoce/hwd/ame/0/transgress.mp3"},"examples":[{"en":"Orton’s plays transgress accepted social norms.","cn":""}],"oxford":{"phon":"trænzˈɡresə(r)","pos":"noun","senses":[{"en":"a person who goes beyond the limit of what is morally or legally acceptable","cn":"越轨；违背（道德）；违犯（法律）"}]}},"translucent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"半透明的","en":"If a material is translucent, some light can pass through it.","ex":{"en":"The building is roofed entirely with translucent corrugated plastic.","cn":"这座建筑完全用半透明瓦楞塑料封顶。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"透明般的","en":"You use translucent to describe something that has a glowing appearance, as if light is passing through it.","ex":{"en":"She had fair hair, blue eyes and translucent skin","cn":"她金发碧眼，皮肤透亮。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not transparent, but clear enough to allow light to pass through","cn":"半透明的"}]},"vocab":{"pos":"adj","senses":[{"en":"A translucent material lets light pass through, but objects on the other side can't be seen clearly. Think: Shrinky Dinks or stained glass."}]},"media":{"uk":"media/ldoce/hwd/bre/1/translucent0205.mp3","us":"media/ldoce/hwd/ame/4/translucent.mp3"},"examples":[{"en":"Blue veins showed through her translucent skin.","cn":"她半透明的皮肤下青筋显现。"}],"oxford":{"phon":"trænzˈluːsnt","pos":"adjective","senses":[{"en":"allowing light to pass through but not completely clear","cn":"半透明的","ex":{"en":"The sky was a pale translucent blue.","cn":"天空隐约呈淡蓝色。"}}]}},"trailblazer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"先驱(者);创始人","en":"A trailblazer is a person who is the leader in a particular field, especially who does a particular thing before anyone else does.","ex":{"en":"He has been the trailblazer and given British sprinters the belief that we are able to take on and beat the world's best.","cn":"他一直是开路先锋，让英国短跑选手相信我们能与世界上最好的运动员一决高下，并且击败他们。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is the first to discover or develop new methods of doing something","cn":"开路者﹔先驱﹐创始人"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41trailblazer.mp3","us":"media/ldoce/hwd/ame/d/trailblazer.mp3"},"examples":[{"en":"trailblazing scientific research","cn":"创新的科学研究"},{"en":"a trailblazer in the field of medical research","cn":"医学研究领域的先驱"}],"oxford":{"phon":"ˈtreɪlbleɪzə(r)","pos":"noun","senses":[{"en":"a person who is the first to do or discover something and so makes it possible for others to follow","cn":"创始人；先驱；拓荒者；开路先锋","ex":{"en":"a trailblazer in the field of genetic engineering","cn":"基因工程领域的开拓者"}}]}},"transitive":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(动词)及物的","en":"A transitive verb has a direct object."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a transitive verb must have an object, for example the verb ‘break’ in the sentence ‘I broke the cup’. Transitive verbs are marked [T] in this dictionary. 〔","cn":"动词〕及物的"}]},"vocab":{"pos":"adj n","senses":[{"en":"Use the adjective transitive when you're talking about a verb that needs both a subject and at least one object, like \"give\" in this sentence: \"I will give you a cupcake if you're really nice.\""}]},"media":{"uk":"media/ldoce/hwd/bre/1/transitive0205.mp3","us":"media/ldoce/hwd/ame/a/transitive.mp3"},"examples":[{"en":"In ‘She wrote a letter’, the verb ‘wrote’ is transitive and the word ‘letter’ is the direct object.","cn":"在 She wrote a letter 一句中，动词 wrote 是及物动词，letter 一词是直接宾语。"},{"en":"The verb is being used transitively.","cn":"这个动词在此用作及物动词。"}],"oxford":{"phon":"ˈtrænzətɪv","pos":"adjective","senses":[{"en":"used with a direct object","cn":"及物的","ex":{"en":"In ‘She wrote a letter’, the verb ‘wrote’ is transitive and the word ‘letter’ is the direct object.","cn":"在 She wrote a letter 一句中，动词 wrote 是及物动词，letter 一词是直接宾语。"}}]}},"tranquillizer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"安定药;镇静剂","en":"A tranquillizer is a drug that makes people feel calmer or less anxious. Tranquillizers are sometimes used to make people or animals become sleepy or unconscious."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drug used for making someone feel less anxious","cn":"镇静剂﹐安定药"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41tranquillizer.mp3","us":"media/ldoce/hwd/ame/f/ld41tranquillizer.mp3"},"examples":[{"en":"She's on (= is taking) tranquillizers.","cn":"她在服用镇静剂。"}],"oxford":{"phon":"ˈtræŋkwəlaɪzə(r)","pos":"noun","senses":[{"en":"a drug used to reduce anxiety (= worry and stress)","cn":"镇静剂","ex":{"en":"She's on (= regularly takes) tranquillizers.","cn":"她在服用镇静剂。"}}]}},"transferable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可转让的;可转移的","en":"If something is transferable, it can be passed or moved from one person or organization to another and used by them.","ex":{"en":"Use the transferable skills acquired from your previous working background…","cn":"先前工作中学到的技能能为现在所用的就多加利用。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get out of one train, bus, or plane and get into another in order to complete your journey","cn":""},{"en":"to change from one vehicle to another, as part of a journey, especially when all the other people in the vehicle do the same","cn":""},{"en":"to change from one thing to another so that you have something different from what you had before","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If something can be transferred from one person to another, it's transferable . That's good news, if you're talking about front-row tickets to the Mariah Carey concert."}]},"collocations":{"phrases":["VERBS be | become","ADV. easily, freely, highly, readily The shares are freely transferable. | fully, wholly | not necessarily","PREP. between Tickets are transferable between members of the same family. | from, to Skills which are not necessarily transferable from one"]},"media":{"uk":"media/ldoce/hwd/bre/5/ld44transfer.mp3","us":"media/ldoce/hwd/ame/5/ld44transfer.mp3"},"examples":[{"en":"We aim to provide our students with transferable skills (= that can be used in different jobs).","cn":"我们的目的是让学生掌握可用于不同工作的技术。"},{"en":"This ticket is not transferable (= it may only be used by the person who has bought it).","cn":"此票不得转让。"}],"oxford":{"phon":"trænsˈfɜːrəbl","pos":"adjective","senses":[{"en":"that can be moved from one place, person or use to another","cn":"可转移的；可调动的；可转让的；可转录的；可中转的","ex":{"en":"This ticket is not transferable (= it may only be used by the person who has bought it).","cn":"此票不得转让。"}}]}},"triumphal":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"庆祝胜利(或成功)的;以示凯旋的","en":"Triumphal is used to describe things that are done or made to celebrate a victory or great success.","ex":{"en":"He made a triumphal entry into the city","cn":"他以胜利者之姿进入了那座城市。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"done or made to celebrate a victory","cn":"庆祝胜利的﹐凯旋的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41triumphal.mp3","us":"media/ldoce/hwd/ame/c/triumphal.mp3"},"examples":[{"en":"a triumphal procession","cn":"庆祝胜利的游行"},{"en":"a triumphal arch","cn":"一座凯旋门"}],"oxford":{"phon":"traɪˈʌmfl","pos":"adjective","senses":[{"en":"done or made in order to celebrate a great success or victory","cn":"庆祝成功（或胜利）的；凯旋的","ex":{"en":"a triumphal parade","cn":"凯旋游行"}}]}},"tread":{"collins":{"senses":[{"pos":"VERB 动词","cn":"踩;踏；践踏","en":"If you tread on something, you put your foot on it when you are walking or standing.","ex":{"en":"Oh, sorry, I didn't mean to tread on your foot","cn":"哦，对不起，我不是故意踩你脚的。"}},{"pos":"VERB 动词","cn":"(以某种方式)步行，行走","en":"If you tread in a particular way, you walk that way.","ex":{"en":"She trod casually, enjoying the touch of the damp grass on her feet.","cn":"她信步而行，享受着湿漉漉的草地触及双脚的感觉。"}},{"pos":"N-SING 单数名词","cn":"脚步声","en":"A person's tread is the sound that they make with their feet as they walk.","ex":{"en":"We could now very plainly hear their heavy tread.","cn":"我们现在可以非常清楚地听到他们沉重的脚步声。"}},{"pos":"VERB 动词","cn":"（谨慎）行事","en":"If you tread carefully, you behave in a careful or cautious way.","ex":{"en":"If you are hoping to form a new relationship tread carefully and slowly to begin with","cn":"如果你希望建立新的关系，首先要慎重行事，不要着急。"}},{"pos":"N-COUNT 可数名词","cn":"(台阶或楼梯的)梯面，踏板","en":"The tread of a step or stair is its flat upper surface.","ex":{"en":"He walked up the stairs. The treads were covered with a kind of rubber and very quiet.","cn":"他走上楼梯。梯面上铺了一种橡胶，因此没有什么声响。"}},{"pos":"N-VAR 可变名词","cn":"(轮胎胎面、鞋底的)花纹","en":"The tread of a tyre or shoe is the pattern of thin lines cut into its surface that stops it slipping.","ex":{"en":"The fat, broad tyres had a good depth of tread.","cn":"这种宽大的轮胎有很深的胎面花纹。"}},{"pos":"PHRASE 短语","cn":"走钢丝般行事;小心地把握分寸","en":"If someone is treading a fine line or path, they are acting carefully because they have to avoid making a serious mistake, especially in a situation where they have to deal with two opposing demands.","ex":{"en":"They have to tread the delicate path between informing children and boring them","cn":"他们既要让孩子们了解情况，又不能让他们产生厌烦情绪，不得不小心把握分寸。"}},{"pos":"PHRASE 短语","cn":"(以…方式)行事;走(…的)路子","en":"If you tread a particular path, you take a particular course of action or do something in a particular way.","ex":{"en":"He continues to tread an unconventional path","cn":"他还是不按传统方式行事。"}},{"pos":"PHRASE 短语","cn":"踩水","en":"If someone who is in deep water treads water, they float in an upright position by moving their legs slightly."},{"pos":"PHRASE 短语","cn":"原地踏步;毫无进展","en":"If you say that someone is treading water, you mean that they are in an unsatisfactory situation where they are not progressing, but are just continuing doing the same things.","ex":{"en":"I could either tread water until I was promoted, which looked to be a few years away, or I could change what I was doing.","cn":"我要么原地踏步直到获得晋升(这看来得是几年以后的事了)，要么改变现在正做的事情。"}},{"pos":"","cn":"","en":"to tread on someone's toes→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put your foot on or in something while you are walking","cn":"踩﹐踏"},{"en":"to be very careful about what you say or do in a difficult situation","cn":"步步小心﹐言行谨慎"},{"en":"to press or crush something into the floor or ground with your feet","cn":"用力踩﹔踩烂"}]},"vocab":{"pos":"1 v n 2 v 3 n v 4 v","senses":[{"en":"When you tread on the earth, you walk on it. The next time your pal thinks you have it too easy, you might ask him, “Why don’t you tread in my shoes for a day?”"}]},"collocations":{"phrases":["ADJ. firm, heavy I heard his heavy tread moving about upstairs. | light, soft | measured, slow, steady","VERB + TREAD hear","TREAD + VERB move","PREP. with a &hellip; ~ A policeman walked by with a slow, measured tread.","PHRASES the tread of feet The streets have echoed to the tread of feet for more than ten centuries. 2 on a tyre","ADJ. tyre, wheel | deep, shallow | worn","TREAD + VERB be worn The tyre tread has been worn below the legal limit.","TREAD + NOUN depth, pattern, width"]},"media":{"img":["media/ldoce/img/tyre.jpg"],"uk":"media/ldoce/hwd/bre/8/tread_v0205.mp3","us":"media/ldoce/hwd/ame/3/tread1.mp3"},"examples":[{"en":"A restaurant has to tread the tricky path between maintaining quality and keeping prices down.","cn":"餐馆必须在保证质量和价格低廉之间走出一条困难的折衷之路。"},{"en":"The tyres were worn below the legal limit of 1.6 mm of tread.","cn":"这些轮胎磨损得已低于胎面 1.6 毫米的法定厚度。"}],"oxford":{"phon":"tred","pos":"verb","senses":[{"en":"to put your foot down while you are stepping or walking","cn":"踩；踏；践踏","g":"[intransitive]","lab":"especially British English","ex":{"en":"Ouch! You trod on my toe!","cn":"唉哟！你踩着我的脚指头了！"}},{"en":"to move, push or press something with your feet","cn":"踩碎；践踏","g":"[transitive]","ex":{"en":"Don't tread ash into the carpet!","cn":"别把烟灰踩进地毯里！"}},{"en":"to walk somewhere","cn":"行走；步行；走","g":"[transitive, intransitive]","lab":"formal or literary","ex":{"en":"Few people had trod this path before.","cn":"以前没有多少人走过这条小路。"}},{"en":"the way that somebody walks; the sound that somebody makes when they walk","cn":"步法；步态；脚步声","g":"[singular]","ex":{"en":"I heard his heavy tread on the stairs.","cn":"我听到他在楼梯上的沉重脚步声。"},"pos":"noun"},{"en":"the raised pattern on the surface of a tyre on a vehicle","cn":"（轮胎的）胎面；外胎花纹","g":"[countable, uncountable]","ex":{"en":"The tyres were worn below the legal limit of 1.6 mm of tread.","cn":"这些轮胎磨损得已低于胎面 1.6 毫米的法定厚度。"},"pos":"noun"},{"en":"the upper surface of a step or stair","cn":"（台阶或楼梯的）踏步板，梯面，踏面","g":"[countable]","pos":"noun"}]}},"traveller":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"旅行者;旅客","en":"A traveller is a person who is making a journey or a person who travels a lot.","ex":{"en":"Many air travellers suffer puffy ankles and feet during long flights.","cn":"很多坐飞机出行的旅客在长途飞行中脚踝和脚会浮肿。"}},{"pos":"N-COUNT 可数名词","cn":"流浪者;漂泊者;居无定所者","en":"A traveller is a person who travels from place to place, often living in a van or other vehicle, rather than living in one place."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is visiting a place for pleasure on holiday","cn":""},{"en":"someone who travels somewhere","cn":""},{"en":"someone who comes to visit a particular country, area, museum etc","cn":""}]},"collocations":{"phrases":["ADJ. business | commercial Her father was a commercial traveller who sold kitchenware. | frequent Attractive discounts are available to freq","VERB + TRAVELLER guide Local tribesmen earn their living guiding travellers across the mountains."]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdetraveller.mp3","us":"media/ldoce/hwd/ame/0/laadtraveller.mp3"},"examples":[{"en":"He passed the time chatting with fellow travellers.","cn":"他与同行的旅客闲聊消磨时间。"},{"en":"She is a frequent traveller to Belgium.","cn":"她经常到比利时去旅行。"}],"oxford":{"phon":"ˈtrævələ(r)","pos":"noun","senses":[{"en":"a person who is travelling or who often travels","cn":"旅行者；旅游者；旅客；游客","ex":{"en":"She is a frequent traveller to Belgium.","cn":"她经常到比利时去旅行。"}},{"en":"a person who does not live in one place but travels around, especially as part of a group; a member of the travelling community","cn":"（尤指结队而行的）漂泊者","lab":"British English","ex":{"en":"New Age travellers","cn":"经常迁移的新时代人"}}]}},"tryst":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"幽会","en":"A tryst is a meeting between lovers in a quiet secret place."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when people meet in order to discuss something","cn":""},{"en":"an organized event, especially one that continues for several days, at which a lot of people meet to discuss a particular subject and hear speeches about it","cn":""},{"en":"a large formal meeting of people who belong to a political party, or to an organization of people with the same interests","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A meeting is when people get together for any reason. But when they are sneaking to meet, notably as secret lovers, it's called a tryst ."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41tryst.mp3","us":"media/ldoce/hwd/ame/9/tryst.mp3"},"oxford":{"phon":"trɪst","pos":"noun","senses":[{"en":"a secret romantic meeting between two people","cn":"约会；幽会"}]}},"transatlantic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"跨(或横渡、横穿)大西洋的;(通常指)英美之间的","en":"Transatlantic flights or signals go across the Atlantic Ocean, usually between the United States and Britain.","ex":{"en":"Many transatlantic flights land there.","cn":"许多跨大西洋的航班在那里着陆。"}},{"pos":"ADJ 形容词","cn":"在(或来自)大西洋彼岸的;在(或来自)美国的","en":"Transatlantic is used to refer to something that happens, exists, or begins in the United States.","ex":{"en":"...transatlantic fashions.","cn":"大西洋彼岸的时尚"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"crossing the Atlantic Ocean","cn":"横跨大西洋的"},{"en":"involving countries on both sides of the Atlantic Ocean","cn":"大西洋两岸国家的"},{"en":"on the other side of the Atlantic Ocean","cn":"大西洋彼岸的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you fly from New York to Paris, you can describe the flight as transatlantic , since you'll be crossing the Atlantic Ocean."}]},"media":{"uk":"media/ldoce/hwd/bre/0/transatlantic0205.mp3","us":"media/ldoce/hwd/ame/c/transatlantic.mp3"},"examples":[{"en":"to speak with a transatlantic accent","cn":"说话带大西洋对岸的口音"},{"en":"a transatlantic alliance","cn":"大西洋两岸国家联盟"}],"oxford":{"phon":"ˌtrænzətˈlæntɪk","pos":"adjective","senses":[{"en":"crossing the Atlantic Ocean","cn":"横渡大西洋的；横越大西洋的","ex":{"en":"a transatlantic flight","cn":"横越大西洋的飞行"}},{"en":"connected with countries on both sides of the Atlantic Ocean","cn":"大西洋两岸国家的","ex":{"en":"a transatlantic alliance","cn":"大西洋两岸国家联盟"}},{"en":"on or from the other side of the Atlantic Ocean","cn":"在大西洋彼岸的；来自大西洋彼岸的","ex":{"en":"to speak with a transatlantic accent","cn":"说话带大西洋对岸的口音"}}]}},"transplant":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(器官)移植","en":"A transplant is a medical operation in which a part of a person's body is replaced because it is diseased.","ex":{"en":"He was recovering from a heart transplant operation.","cn":"他做了心脏移植手术，正在康复。"}},{"pos":"VERB 动词","cn":"移植(器官)","en":"If doctors transplant an organ such as a heart or a kidney, they use it to replace a patient's diseased organ.","ex":{"en":"The operation to transplant a kidney is now fairly routine.","cn":"肾脏移植手术如今已相当常见。"}},{"pos":"VERB 动词","cn":"使迁移;使移民;移种","en":"To transplant someone or something means to move them to a different place.","ex":{"en":"Marriage had transplanted Rebecca from London to Manchester","cn":"因为结婚，丽贝卡从伦敦移居到了曼彻斯特。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process of cutting into someone’s body to repair or remove a part that is damaged","cn":""},{"en":"an operation performed in a particular way on a particular part of the body. Procedure is used especially in medical English, for example by doctors and people who work in hospitals. In everyday English people usually say operation","cn":""},{"en":"an operation to remove an organ from one person’s body and put it into another person’s body","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"Use the verb transplant to describe what you do when you move a cactus into a bigger container, or what a doctor does when she places a donor organ — like a kidney or lung — into the body of a patient."}]},"collocations":{"phrases":["ADJ. bone-marrow, heart, heart-lung, kidney, liver, etc. | double, multi-organ, multiple","VERB + TRANSPLANT have, undergo She will have to have a heart-lung transplant within 48 hours. | carry out, do, perform | reject It is likel","TRANSPLANT + NOUN operation, surgery | surgeon | team | centre, unit | donor A suitable transplant donor has been found. | candidate, patien","PREP. for ~ a shortage of kidneys for transplant"]},"media":{"uk":"media/ldoce/hwd/bre/b/transplant_n0205.mp3","us":"media/ldoce/hwd/ame/f/l3transplant2.mp3"},"examples":[{"en":"Surgeons have successfully transplanted a liver into a four-year-old boy.","cn":"外科医生成功地给一个四岁的男孩移植了肝脏。"},{"en":"Japanese production methods have been transplanted into some British factories.","cn":"日本的生产方法已被引进到一些英国的工厂。"}],"oxford":{"phon":"trænsˈplɑːnt","pos":"verb","senses":[{"en":"to take an organ, skin, etc. from one person, animal, part of the body, etc. and put it into or onto another","cn":"移植（器官、皮肤等）","ex":{"en":"Surgeons have successfully transplanted a liver into a four-year-old boy.","cn":"外科医生成功地给一个四岁的男孩移植了肝脏。"}},{"en":"to move a growing plant and plant it somewhere else","cn":"移栽，移种，移植（植物）","ex":{"en":"The Dutch successfully transplanted trees to the East Indies.","cn":"荷兰人成功地把树移种到了东印度群岛。"}},{"en":"to move somebody/something to a different place or environment","cn":"使迁移；使移居","lab":"formal","ex":{"en":"Japanese production methods have been transplanted into some British factories.","cn":"日本的生产方法已被引进到一些英国的工厂。"}},{"en":"a medical operation in which a damaged organ, etc. is replaced with one from another person","cn":"（器官等的）移植","g":"[countable, uncountable]","lab":"British English","ex":{"en":"to have a heart transplant","cn":"接受心脏移植"},"pos":"noun"},{"en":"an organ, etc. that is used in a transplant operation","cn":"移植器官","g":"[countable]","ex":{"en":"There is always a chance that the body will reject the transplant.","cn":"身体总是有排斥移植器官的可能。"},"pos":"noun"}]}},"triple":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"三个的;三方的;三部分的","en":"Triple means consisting of three things or parts.","ex":{"en":"...a triple somersault","cn":"空翻三周"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)变成三倍;(使)增至三倍","en":"If something triples or if you triple it, it becomes three times as large in size or number.","ex":{"en":"I got a fantastic new job and my salary tripled","cn":"我得到了一份非常好的新工作，薪水涨到了原来的 3 倍。"}},{"pos":"PREDET 前置限定词","cn":"是…的三倍","en":"If something is triple the amount or size of another thing, it is three times as large.","ex":{"en":"The mine reportedly had an accident rate triple the national average","cn":"据报道,该矿事故发生率是全国平均水平的 3 倍。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having three parts or involving three groups, people, events etc","cn":"有三部分的﹔涉及三方的"},{"en":"three times more than a particular number","cn":"三倍的﹔三重的"},{"en":"to become larger in number, amount, or degree","cn":""}]},"vocab":{"pos":"1 adj n v 2 n v","senses":[{"en":"Triple means to multiply by three. If you triple the number two, you get six, and six is the triple of the number two."}]},"media":{"uk":"media/ldoce/hwd/bre/8/triple_las2_br.mp3","us":"media/ldoce/hwd/ame/4/triple1.mp3"},"examples":[{"en":"The amount of alcohol in his blood was triple the legal maximum.","cn":"他血液中的酒精含量为法定最高限量的三倍。"},{"en":"Its population is about triple that of Venice.","cn":"它的人口大约是威尼斯的三倍。"}],"oxford":{"phon":"ˈtrɪpl","pos":"adjective","senses":[{"en":"having three parts or involving three people or groups","cn":"三部分的；三人的；三组的","g":"[only before noun]","ex":{"en":"a triple heart bypass operation","cn":"心脏三处旁路手术"}},{"en":"three times as much or as many as something","cn":"三倍的；三重的","g":"[not before noun]","ex":{"en":"The amount of alcohol in his blood was triple the legal maximum.","cn":"他血液中的酒精含量为法定最高限量的三倍。"}},{"en":"to become, or to make something, three times as much or as many","cn":"成为三倍；使增至三倍","ex":{"en":"Output should triple by next year.","cn":"到明年产量应增至三倍。"},"pos":"verb"}]}},"travesty":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"嘲弄;歪曲;拙劣模仿","en":"If you describe something as a travesty of another thing, you mean that it is a very bad representation of that other thing.","ex":{"en":"Her research suggests that Smith's reputation today is a travesty of what he really stood for","cn":"她的研究表明史密斯今天的名声是对他过去真正主张的一种嘲弄。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when people are treated with great unfairness, especially in connection with their legal rights","cn":""},{"en":"a situation that is extremely unfair and morally wrong because it has completely the opposite result to the one it is supposed to have","cn":""},{"en":"a situation in which someone is wrongly punished for a crime that they were not responsible for","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A travesty is a cheap mockery, usually of something or someone serious, such as a travesty of justice."}]},"media":{"uk":"media/ldoce/hwd/bre/f/travesty0205.mp3","us":"media/ldoce/hwd/ame/b/travesty.mp3"},"examples":[{"en":"The trial was a travesty of justice.","cn":"这一审判是对正义的嘲弄。"},{"en":"Their marriage was a complete travesty.","cn":"他们的婚姻十分荒唐。"}],"oxford":{"phon":"ˈtrævəsti","pos":"noun","senses":[{"en":"something that does not have the qualities or values that it should have, and as a result is often considered wrong or offensive","cn":"嘲弄；歪曲","ex":{"en":"The trial was a travesty of justice.","cn":"这一审判是对正义的嘲弄。"}}]}},"trousseau":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"嫁妆","en":"A trousseau is a collection of clothes and other possessions that a bride brings with her when she gets married."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the clothes etc that a woman brings with her when she marries","cn":"嫁妆"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41trousseau.mp3","us":"media/ldoce/hwd/ame/6/trousseau.mp3"},"oxford":{"phon":"ˈtruːsəʊ","pos":"noun","senses":[{"en":"the clothes and other possessions collected by a woman who was soon going to get married, to begin her married life with","cn":"嫁妆"}]}},"traditionalist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"传统主义者","en":"A traditionalist is a person who supports the established customs and beliefs of his or her society or group, and does not want to change them."},{"pos":"ADJ 形容词","cn":"传统主义的;因循守旧的","en":"A traditionalist idea, argument, or organization supports the established customs and beliefs of a society or group, rather than modern ones."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to think and behave as if life is still like it was when you were young, especially because you do not like the modern world","cn":""},{"en":"a person or organization who is behind the times , is old-fashioned because they have not changed while the world around them has changed","cn":""},{"en":"having a very strong, old-fashioned attitude to moral behaviour","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A traditionalist wants things to stay the same. If you prefer vinyl albums to MP3 players, you just might be a traditionalist ."}]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdetraditionalist.mp3","us":"media/ldoce/hwd/ame/e/laadtraditionalist.mp3"},"oxford":{"phon":"trəˈdɪʃənəlɪst","pos":"noun","senses":[{"en":"a person who prefers tradition to modern ideas or ways of doing things","cn":"传统主义者","ex":{"en":"He was known for his traditionalist views.","cn":"他以其传统主义观点而闻名。"}},{"en":"preferring tradition to modern ideas or ways of doing things","cn":"传统主义者","ex":{"en":"traditionalist Catholics/Protestants","cn":"传统主义天主教徒/新教徒"},"pos":"adjective"}]}},"transgender":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"跨性别的；变性的","en":"Transgender people, such as transsexuals, do not have a straightforward gender identity.","ex":{"en":"...a three-year-project designed to overcome prejudice towards gay, lesbian, bisexual and transgender people.","cn":"为期三年旨在克服对男女同性恋者、双性恋者和跨性别者所持偏见的项目"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a general word for people who feel that they belong to the other sex, and not the sex they were born with, and who express this in their sexual behaviour","cn":"跨性别者〔认为自己的心理性别与生理性别不一致的人〕"}]},"vocab":{"pos":"adj","senses":[{"en":"A person who does not identify with conventional gender roles or identities might describe himself or herself using the adjective transgender ."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld42transgender.mp3","us":"media/ldoce/hwd/ame/b/ld42transgender.mp3"},"examples":[{"en":"transgender issues","cn":"关于变性的有争议的问题"},{"en":"the transgender community","cn":"跨性别群体"}],"oxford":{"phon":"trænzˈdʒendə(r)","pos":"adjective","senses":[{"en":"describing or relating to people whose gender identity does not match the sex they were said to have at birth","cn":"跨性别的","ex":{"en":"Sam identifies as a transgender man.","cn":"山姆自认是一名变性人。"}}]}},"tricky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难办的;难对付的;棘手的","en":"If you describe a task or problem as tricky, you mean that it is difficult to do or deal with.","ex":{"en":"Parking can be tricky in the town centre","cn":"在市中心泊车可能很困难。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"诡计多端的;奸诈的;狡猾的","en":"If you describe a person as tricky, you mean that they are likely to deceive you or cheat you."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not easy to do, understand, or deal with","cn":""},{"en":"difficult. Hard is less formal than difficult and is very common in spoken English","cn":""},{"en":"very difficult, because you have to use a lot of effort, or because it affects you emotionally","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/tricky0205.mp3","us":"media/ldoce/hwd/ame/f/tricky.mp3"},"examples":[{"en":"Getting it to fit exactly is a tricky business.","cn":"使这完全合适是件很难做到的事。"},{"en":"The equipment can be tricky to install.","cn":"这设备安装起来可能很费事。"}],"oxford":{"phon":"ˈtrɪki","pos":"adjective","senses":[{"en":"difficult to do or deal with","cn":"难办的；难对付的","ex":{"en":"a tricky situation","cn":"微妙的局势"}},{"en":"clever but likely to trick you","cn":"狡猾的；诡计多端的"}]}},"truthful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"说真话的;诚实的","en":"If a person or their comments are truthful, they are honest and do not tell any lies.","ex":{"en":"Most religions teach you to be truthful…","cn":"大部分宗教都教导人要诚实。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is honest says what they really think or what is really happening, and does not try to hide the truth or deceive people","cn":""},{"en":"someone who is truthful does not lie","cn":""},{"en":"showing your true feelings and what you really believe","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. very | absolutely, completely | not entirely, not quite I don't think you are being entirely truthful.","PREP. about She was completely truthful about her involvement in the affair."]},"media":{"uk":"media/ldoce/hwd/bre/d/truthful0205.mp3","us":"media/ldoce/hwd/ame/8/truthful.mp3"},"examples":[{"en":"They were less than truthful about their part in the crime.","cn":"他们对自己在这次犯罪中所担当的角色讲的绝非实情。"},{"en":"She answered all their questions truthfully.","cn":"她如实回答了他们的所有问题。"}],"oxford":{"phon":"ˈtruːθfl","pos":"adjective","senses":[{"en":"saying only what is true","cn":"诚实；讲真话；坦率","ex":{"en":"They were less than truthful about their part in the crime.","cn":"关于自己在这次犯罪中所起的作用，他们讲的绝非实情。"}},{"en":"giving the true facts about something","cn":"真实的；如实的","ex":{"en":"a truthful answer","cn":"坦诚的回答"}}]}},"trowel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(园艺用的)小铲子","en":"A trowel is a small garden tool which you use for digging small holes or removing weeds."},{"pos":"N-COUNT 可数名词","cn":"抹子;泥刀;瓦刀","en":"A trowel is a small tool with a flat blade that you use for spreading things such as cement and plaster onto walls and other surfaces."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a garden tool like a very small spade","cn":"小泥铲﹐小铲子〔一种园艺工具〕"},{"en":"a small tool with a flat blade, used for spreading cement on bricks etc 〔","cn":"泥瓦匠使用的〕泥刀﹐镘刀﹐抹子"},{"en":"to say things that make something seem much better, worse etc than it really is","cn":"夸张﹐言过其实"}]},"media":{"img":["media/ldoce/img/trowel.jpg","media/thumb/trowel.jpg"],"uk":"media/ldoce/hwd/bre/0/ld46trowel.mp3","us":"media/ldoce/hwd/ame/0/ld46trowel.mp3"},"examples":[{"en":"He was laying the flattery on with a trowel.","cn":"他吹捧得天花乱坠。"},{"en":"‘I really don’t feel too good,’ I croaked, laying it on with a trowel. “","cn":"我真的觉得不太舒服。”我哑着嗓子夸张地说。"}],"oxford":{"phon":"ˈtraʊəl","pos":"noun","senses":[{"en":"a small garden tool with a curved metal part for lifting plants and digging holes","cn":"小铲子（园艺工具）"},{"en":"a small tool with a flat metal part, used in building for spreading cement or plaster","cn":"（抹泥灰或砂浆用的）瓦刀，镘刀，抹子"}]}},"trapeze":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(马戏团的)高空秋千，空中吊杠","en":"A trapeze is a bar of wood or metal hanging from two ropes on which people in a circus swing and perform skilful movements."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short bar hanging from two ropes high above the ground, used by acrobat s 〔","cn":"杂技演员用的〕空中吊杠﹐高空秋千"}]},"vocab":{"pos":"n","senses":[{"en":"If you've been to the circus, you've probably seen a trapeze , a swing-like bar on ropes hanging high in the air. Trapeze performers do daring tricks while swinging far above the ground."}]},"media":{"uk":"media/ldoce/hwd/bre/5/trapeze0205.mp3","us":"media/ldoce/hwd/ame/5/trapeze.mp3"},"examples":[{"en":"a trapeze artist","cn":"高空秋千表演者"}],"oxford":{"phon":"trəˈpiːz","pos":"noun","senses":[{"en":"a wooden or metal bar hanging from two pieces of rope high above the ground, used especially by circus performers","cn":"（尤指马戏团演员使用的）高空秋千，吊架","ex":{"en":"a trapeze artist","cn":"高空秋千表演者"}}]}},"trivia":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"琐事；花边消息","en":"Trivia is unimportant facts or details that are considered to be amusing rather than serious or useful.","ex":{"en":"The two men chatted about such trivia as their favourite kinds of fast food","cn":"这两个男人闲聊了些诸如彼此最喜欢的快餐这样的琐事。"}},{"pos":"ADJ 形容词","cn":"(游戏或竞赛)益智问答的","en":"A trivia game or competition is one where the competitors are asked questions about interesting but unimportant facts in many subjects.","ex":{"en":"...a pub trivia game.","cn":"酒馆知识问答游戏"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"information or facts that are not important and have no real use or value","cn":""},{"en":"detailed facts about history, sport, famous people etc 〔","cn":"有关历史﹑体育运动﹑名人等的〕详细知识﹐细节"},{"en":"unimportant or useless details","cn":"琐事﹔微不足道的细节"}]},"vocab":{"pos":"n","senses":[{"en":"Can you name the twenty-third vice-president? Do you know all the state birds? If so, you must be good at trivia : facts that are interesting but not necessarily important."}]},"media":{"uk":"media/ldoce/hwd/bre/0/trivia0205.mp3","us":"media/ldoce/hwd/ame/e/trivia.mp3"},"examples":[{"en":"We spent the whole evening discussing domestic trivia.","cn":"我们整个晚上谈论家庭琐事。"},{"en":"a trivia quiz","cn":"知识面宽的问答比赛"}],"oxford":{"phon":"ˈtrɪviə","pos":"noun","senses":[{"en":"unimportant matters, details or information","cn":"琐事；细枝末节","ex":{"en":"We spent the whole evening discussing domestic trivia.","cn":"我们整个晚上谈论家庭琐事。"}},{"en":"facts about many subjects that are used in a game to test people’s knowledge","cn":"（智力测验比赛用的）各种科目的知识","ex":{"en":"a trivia quiz","cn":"知识面宽的问答比赛"}}]}},"trier":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"干劲十足的人;工作勤奋的人","en":"If you say that someone is a trier, you approve of them because they try very hard at things that they do, although they are not often successful.","ex":{"en":"He may not always achieve greatness but at least he's a trier.","cn":"他也许并非总能成就大事，但至少他竭尽所能。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who always makes a great effort, even if they do not often succeed","cn":"很努力的人"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41trier.mp3","us":"media/ldoce/hwd/ame/3/ld41trier.mp3"},"oxford":{"phon":"ˈtraɪə(r)","pos":"noun","senses":[{"en":"a person who tries very hard at what they are doing and does their best","cn":"工作尽心尽力的人；勤勤恳恳的人","ex":{"en":"He’s a real trier. He gets tired but he never gives up.","cn":"他是一个真正的尝试者。他很累，但他从不放弃。"}}]}},"transitory":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"短暂的;转瞬即逝的;昙花一现的","en":"If you say that something is transitory, you mean that it lasts only for a short time.","ex":{"en":"Most teenage romances are transitory.","cn":"绝大多数十几岁少年的恋情都转瞬即逝。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing or existing for only a short time","cn":"短暂的﹐一时的"}]},"vocab":{"pos":"adj","senses":[{"en":"If something is fleeting or lasts a short time, it is transitory . Your boss declared the company's restructuring to be transitory , and promised that the company would emerge stronger and better than ever."}]},"media":{"uk":"media/ldoce/hwd/bre/f/transitory0205.mp3","us":"media/ldoce/hwd/ame/e/transitory.mp3"},"examples":[{"en":"the transitory nature of his happiness","cn":"他的幸福昙花一现"}],"oxford":{"phon":"ˈtrænzətri","pos":"adjective","senses":[{"en":"continuing for only a short time","cn":"暂时的；片刻的；转瞬即逝的","ex":{"en":"the transitory nature of his happiness","cn":"他昙花一现的幸福"}}]}},"troika":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"三人领导小组;三头政治;三国集团","en":"Journalists sometimes refer to a group of three powerful politicians or states as a troika .","ex":{"en":"...leader of the troika of past, present and future presidents","cn":"前总统、现任总统与继任总统组成的三驾马车"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of three people, countries etc","cn":"三人组﹔三头政治﹔三国集团"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41troika.mp3","us":"media/ldoce/hwd/ame/9/troika.mp3"},"examples":[{"en":"the ruling troika","cn":"执政的三巨头"}],"oxford":{"phon":"ˈtrɔɪkə","pos":"noun","senses":[{"en":"a group of three politicians, organizations or countries working together","cn":"三人领导小组；三头政治；三巨头；三国集团"}]}},"trombonist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"长号手","en":"A trombonist is someone who plays the trombone."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large metal musical instrument that you play by blowing into it and sliding a long tube in and out to change the notes","cn":""}]},"media":{"img":["media/ldoce/img/trombone.jpg"],"uk":"media/ldoce/hwd/bre/7/trombone0205.mp3","us":"media/ldoce/hwd/ame/c/trombone.mp3"},"oxford":{"phon":"trɒmˈbəʊnɪst","pos":"noun","senses":[{"en":"a person who plays the trombone","cn":"长号手"}]}},"troubadour":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"行吟诗人，民谣歌手(12、13 世纪周游意大利及法国为贵族表演的诗人或歌手)","en":"Troubadours were poets and singers who used to travel around and perform to noble families in Italy and France in the twelfth and thirteenth centuries."},{"pos":"N-COUNT 可数名词","cn":"(尤指歌词在音乐中至关重要的)流行歌手","en":"People sometimes refer to popular singers as troubadours, especially when the words of their songs are an important part of their music."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of singer and poet who travelled around the palace s and castles of Southern Europe in the 12th and 13th centuries","cn":"游吟诗人〔12、13世纪游走于南欧的宫殿和城堡之间〕"}]},"vocab":{"pos":"n","senses":[{"en":"When we think of a troubadour what usually comes to mind is a lovestruck fellow serenading his sweetheart and hoping she'll appear on her balcony."}]},"media":{"uk":"media/ldoce/hwd/bre/9/troubadour0205.mp3","us":"media/ldoce/hwd/ame/1/troubadour.mp3"},"oxford":{"phon":"ˈtruːbədɔː(r)","pos":"noun","senses":[{"en":"a writer and performer of songs or poetry (after the French travelling performers of the eleventh to thirteenth centuries)","cn":"游吟诗人（因 11–13 世纪法国的巡回表演者而得名）"}]}},"triad":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"三合会(旧中国秘密组织)","en":"The Triads were Chinese secret societies in old China.","ex":{"en":"…gangs, known as the Triads.","cn":"称作“三合会”的帮派"}},{"pos":"N-COUNT 可数名词","cn":"三个一组;三件一套;三位一体","en":"A triad is a group of three similar things.","ex":{"en":"For the faculty, there exists the triad of responsibilities: teaching, research, and service.","cn":"教员要承担三重责任:教学、研究与服务。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a Chinese secret criminal group","cn":"三合会〔华人黑社会组织〕"},{"en":"a group of three people or things that are related or similar to each other","cn":"三人组合﹔三种事物的组合"}]},"vocab":{"pos":"n","senses":[{"en":"A triad is three things or people considered as one unit. A triad is a trio."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41triad.mp3","us":"media/ldoce/hwd/ame/a/triad.mp3"},"oxford":{"phon":"ˈtraɪæd","pos":"noun","senses":[{"en":"a group of three related people or things","cn":"三人组合；三位一体；三件一套","lab":"formal","ex":{"en":"the classic triad of the visual arts: sculpture, architecture and painting","cn":"视觉艺术的经典三位一体：雕塑、建筑和绘画"}},{"en":"a Chinese secret organization involved in criminal activity","cn":"三合会（中国秘密犯罪组织）"}]}},"treble":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)增加两倍;(使)成为三倍","en":"If something trebles or if you treble it, it becomes three times greater in number or amount than it was.","ex":{"en":"They will have to pay much more when rents treble in January","cn":"一月份房租增加两倍时，他们将被迫多付不少钱。"}},{"pos":"PREDET 前置限定词","cn":"是…的三倍","en":"If one thing is treble the size or amount of another thing, it is three times greater in size or amount.","ex":{"en":"More than 7 million shares changed hands, treble the normal daily average.","cn":"有 700 多万股换手，是通常日平均成交量的 3 倍。"}},{"pos":"N-COUNT 可数名词","cn":"男童高音；唱高音的男童声歌手","en":"A treble is a boy with a very high singing voice."},{"pos":"N-COUNT 可数名词","cn":"三连胜","en":"In sport, a treble is three successes one after the other, for example winning three horse races on the same day, or winning three competitions in the same season.","ex":{"en":"The win completed a treble for them – they already claimed a league and cup double this year.","cn":"此役获胜成就了他们的三冠王——此前他们已经拿下了今年的联赛和杯赛双料冠军。"}}]},"ldoce":{"phon":"hwd","pos":"predeterminer","senses":[{"en":"three times as big, as much, or as many as something else","cn":"三倍的﹐三重的"},{"en":"to become three times as big in amount, size, or number, or to make something increase in this way （","cn":"使）成三倍"},{"en":"the upper half of the whole range of musical notes 〔","cn":"音乐的〕高音部"}]},"vocab":{"pos":"1 adj v 2 adj n v","senses":[{"en":"Something that's treble has three parts or sections. You could describe a tricycle as a treble wheeled vehicle."}]},"collocations":{"phrases":["ADV. more than | almost, nearly","PREP. in Some goods have almost trebled in price. | to The figure has more than trebled to 67 per cent."]},"media":{"uk":"media/ldoce/hwd/bre/3/treble_predete0205.mp3","us":"media/ldoce/hwd/ame/4/ld41treble.mp3"},"examples":[{"en":"Cases of food poisoning have trebled in the last two years.","cn":"在过去的两年里，食物中毒事件增加了两倍。"},{"en":"Capital expenditure was treble the 2007 level.","cn":"资本支出是 2007 年的三倍。"}],"oxford":{"phon":"ˈtrebl","pos":"noun","senses":[{"en":"the high tones or part in music or a sound system","cn":"（音乐或音响系统的）高音，高音部","g":"[uncountable]","ex":{"en":"to turn up the treble on the stereo","cn":"把立体声唱机的高音音量调大"}},{"en":"a child’s high voice; a boy who sings with a treble voice","cn":"童声高音；唱高音的男童歌手","g":"[countable]"},{"en":"a musical part written for a treble voice","cn":"高音声部","g":"[singular]"},{"en":"three successes in a row","cn":"三连胜","g":"[singular]","lab":"British English","ex":{"en":"The victory completed a treble for the horse's owner.","cn":"这次胜利使得马主获得三连胜。"}},{"en":"to become, or to make something, three times as much or as many","cn":"成为三倍；使增至三倍","ex":{"en":"Cases of food poisoning have trebled in the last two years.","cn":"在过去的两年里，食物中毒事件增加了两倍。"},"pos":"verb"},{"en":"three times as much or as many","cn":"三倍的；三重的","ex":{"en":"Capital expenditure was treble the 2013 level.","cn":"资本支出是 2013 年的三倍。"},"pos":"determiner"},{"en":"high in tone","cn":"高音的；高声的","ex":{"en":"a treble voice","cn":"高嗓音"},"pos":"adjective"}]}},"trounce":{"collins":{"senses":[{"pos":"VERB 动词","cn":"轻松战胜;大胜;击溃","en":"If you trounce someone in a competition or contest, you defeat them easily or by a large score.","ex":{"en":"In Rugby League, Australia trounced France by sixty points to four.","cn":"在联盟橄榄球赛上，澳大利亚队以 60:4 的比分大胜法国队。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get more points, votes etc than someone. Beat is used especially in spoken English","cn":""},{"en":"to beat someone. Defeat is more formal than beat and is used especially in writing","cn":""},{"en":"to defeat someone completely in a game","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you trounce someone, you win decisively. If you win a chess match in three moves, you trounce your opponent."}]},"media":{"uk":"media/ldoce/hwd/bre/3/trounce0205.mp3","us":"media/ldoce/hwd/ame/d/trounce.mp3"},"examples":[{"en":"Brazil trounced Italy 5–1 in the final.","cn":"在决赛中巴西队以 5:1 狂胜意大利队。"},{"en":"We were trounced 13–0.","cn":"我们以0比13惨败。"}],"oxford":{"phon":"traʊns","pos":"verb","senses":[{"en":"to defeat somebody completely","cn":"彻底打败；击溃","ex":{"en":"Brazil trounced Italy 5–1 in the final.","cn":"在决赛中巴西队以 5:1 狂胜意大利队。"}}]}},"tribulation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"艰难;苦难;磨难","en":"You can refer to the suffering or difficulty that you experience in a particular situation as tribulations .","ex":{"en":"...the trials and tribulations of everyday life.","cn":"日常生活的磨炼与艰难"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"serious trouble or a serious problem","cn":"苦难﹐艰辛"}]},"vocab":{"pos":"n","senses":[{"en":"Tribulation is suffering or trouble, usually resulting from oppression. The tribulations of a coal miner include a dangerous work environment, lung disease from black dust and a cramped, dark work space."}]},"media":{"uk":"media/ldoce/hwd/bre/7/tribulation0205.mp3","us":"media/ldoce/hwd/ame/a/tribulation.mp3"},"examples":[{"en":"the tribulations of modern life","cn":"现代生活的苦恼"},{"en":"Even close friends were unaware of the tribulations she faced.","cn":"即使是亲近的朋友也不了解她所面对的种种艰辛。"}],"oxford":{"phon":"ˌtrɪbjuˈleɪʃn","pos":"noun","senses":[{"en":"great trouble, difficulty or mental pain","cn":"忧患；苦难；磨难；痛苦","ex":{"en":"the tribulations of modern life","cn":"现代生活的苦恼"}}]}},"trumped-up":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（罪名）捏造的，编造的，莫须有的","en":"Trumped-up charges are untrue, and made up in order to punish someone unfairly."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"not true. Untrue is more formal than not true","cn":""},{"en":"not true or not correct","cn":""},{"en":"if what someone says or believes is happening is not the case , it is not happening and what they say or believe is not true","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/trump_n0205.mp3","us":"media/ldoce/hwd/ame/7/trump1.mp3"},"examples":[{"en":"By wearing a simple but stunning dress, she had trumped them all.","cn":""},{"en":"They had trumped the whole thing up to get rid of him.","cn":""}],"oxford":{"phon":"ˌtrʌmpt ˈʌp","pos":"adjective","senses":[{"en":"falsely accusing them of doing something wrong","cn":"诬陷的；捏造的；编造的","ex":{"en":"She was arrested on a trumped-up charge.","cn":"她以莫须有的罪名被捕。"}}]}},"truss":{"collins":{"senses":[{"pos":"VERB 动词","cn":"扎紧;绑紧;捆紧","en":"To truss someone means to tie them up very tightly so that they cannot move.","ex":{"en":"She trussed him quickly with stolen bandage, and gagged his mouth.","cn":"她用偷来的绷带迅速把他绑紧，并塞住了他的嘴。"}},{"pos":"VERB 动词","cn":"(烹调前)把（鸡等的）腿和翅膀扎紧","en":"If you truss a bird such as a chicken, you prepare it for cooking by tying its legs and wings.","ex":{"en":"Put stuffing into the cavity and truss the bird.","cn":"把填料放到腔内，把鸟的腿和翅膀扎紧。"}},{"pos":"N-COUNT 可数名词","cn":"（治疗疝气用的）疝带","en":"A truss is a special belt with a pad that a man wears when he has a hernia in order to prevent it from getting worse."},{"pos":"","cn":"","en":"相关词组：truss up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tie someone’s arms, legs etc very firmly with rope so that they cannot move","cn":"捆紧…的手脚﹐把…绑起来"},{"en":"to prepare a chicken, duck etc for cooking by tying its legs and wings into position","cn":"把〔鸡﹑鸭等〕的腿和翅膀捆牢〔以便烹煮〕"},{"en":"a special belt worn to support a hernia (= medical problem that affects the muscles below your stomach ) 〔","cn":"疝病患者用的〕疝带"}]},"vocab":{"pos":"n v","senses":[{"en":"A truss is a framework that supports something, like a roof or a bridge. A steel beam that holds up a bridge is called a truss . Another kind of truss is a similar structure that's designed to support a roof."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41truss2.mp3","us":"media/ldoce/hwd/ame/7/truss1.mp3"},"examples":[{"en":"They trussed up their victim and left him for dead.","cn":"他们把受害人绑起来﹐丢下他不管死活。"}],"oxford":{"phon":"trʌs","pos":"noun","senses":[{"en":"a special belt with a thick piece of material, worn by somebody who has a hernia in order to support the muscles","cn":"疝带（疝病患者所用）"},{"en":"a frame made of pieces of wood or metal used to support a roof, bridge, etc.","cn":"（支撑屋顶、桥梁等的）桁架，构架"},{"en":"to tie up somebody’s arms and legs so that they cannot move","cn":"把（人的双臂和双腿）捆紧，缚牢","ex":{"en":"The guard had been gagged and trussed up.","cn":"警卫的嘴被堵住并被捆起来。"},"pos":"verb"},{"en":"to tie the legs and wings of a chicken, etc. before it is cooked","cn":"（在烹煮鸡等前）把腿和翅膀束紧","pos":"verb"}]}},"traverse":{"collins":{"senses":[{"pos":"VERB 动词","cn":"横穿;横越;穿过","en":"If someone or something traverses an area of land or water, they go across it.","ex":{"en":"I traversed the narrow pedestrian bridge.","cn":"我走过狭窄的人行天桥。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move across, over, or through something, especially an area of land or water","cn":"跨过﹐穿过﹐横越﹐横穿"},{"en":"a sideways movement across a very steep slope in mountain-climbing 〔","cn":"登山运动中爬陡坡时的〕横过山坡"}]},"vocab":{"pos":"n v","senses":[{"en":"The verb traverse means to travel across an extended area. \"Her dream was to traverse the country by car, so she could meet new people and see all the kitschy sites — like the giant roadside tire in Michigan or the shoe house in Pennsylvania.\""}]},"media":{"uk":"media/ldoce/hwd/bre/4/traverse_v0205.mp3","us":"media/ldoce/hwd/ame/d/l3traverse.mp3"},"examples":[{"en":"two minutes to traverse the park","cn":"两分钟横穿公园"}],"oxford":{"phon":"trəˈvɜːs","pos":"verb","senses":[{"en":"to cross an area of land or water","cn":"横过；横越；穿过；横渡","ex":{"en":"skiers traversing the slopes","cn":"穿越斜坡的滑雪者"}},{"en":"an act of moving sideways across a steep slope, not climbing up or down it; a place where this is possible or necessary","cn":"（在陡坡上的）侧向移动，横过，横越；可横越的地方","ex":{"en":"We began a traverse across the rock face.","cn":"我们开始穿越岩壁。"},"pos":"noun"}]}},"trample":{"collins":{"senses":[{"pos":"VERB 动词","cn":"践踏;无视;伤害","en":"To trample on someone's rights or values or to trample them means to deliberately ignore them.","ex":{"en":"They say loggers are destroying rain forests and trampling on the rights of natives","cn":"他们说伐木工人正在毁坏雨林，践踏土著居民的权利。"}},{"pos":"VERB 动词","cn":"踩伤;踩死","en":"If someone is trampled, they are injured or killed by being stepped on by animals or by other people.","ex":{"en":"Many people were trampled in the panic that followed","cn":"很多人在随后的恐慌中被踩伤。"}},{"pos":"VERB 动词","cn":"踩踏;踩坏","en":"If someone tramples something or tramples on it, they step heavily and carelessly on it and damage it.","ex":{"en":"They don't want people trampling the grass, pitching tents or building fires","cn":"他们不希望人们踩踏草坪、支帐篷或生火。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to step heavily on something, so that you crush it with your feet","cn":"踩﹐践踏"},{"en":"to behave in a way that shows that you do not care about someone’s rights or feelings","cn":"侵犯﹐无视〔某人的权利或情感〕"}]},"vocab":{"pos":"v n","senses":[{"en":"To trample is to forcefully walk right over something or someone. If you fall down during a footrace, another runner might trample you."}]},"collocations":{"phrases":["ADV. down crops that have been trampled down by walkers' feet | underfoot He saved a little girl from being trampled underfoot in the rush f","PREP. on (often figurative) The government is trampling on the views of ordinary people. | over Police officers had been trampling all over ","PHRASES be trampled to death"]},"media":{"uk":"media/ldoce/hwd/bre/9/trample0205.mp3","us":"media/ldoce/hwd/ame/6/trample.mp3"},"examples":[{"en":"People were trampled underfoot in the rush for the exit.","cn":"有人在拼命涌向出口时被踩在脚下。"},{"en":"He was trampled to death by a runaway horse.","cn":"他被一匹脱缰的马踩死了。"}],"oxford":{"phon":"ˈtræmpl","pos":"verb","senses":[{"en":"to step heavily on somebody/something so that you damage or harm them/it with your feet","cn":"踩碎；踩伤；践踏","g":"[transitive, intransitive]","ex":{"en":"People were trampled underfoot in the rush for the exit.","cn":"有人在拼命涌向出口时被踩在脚下。"}},{"en":"to ignore somebody’s feelings or rights and treat them as if they are not important","cn":"践踏，摧残（人权、心灵等）","g":"[intransitive]","ex":{"en":"The government is trampling on the views of ordinary people.","cn":"政府在践踏民意。"}}]}},"transient":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"短暂的;倏忽的;无常的","en":"Transient is used to describe a situation that lasts only a short time or is constantly changing.","ex":{"en":"...the transient nature of high fashion","cn":"顶级时装的瞬息万变性"}},{"pos":"N-COUNT 可数名词","cn":"临时旅客;流动短工;暂居者","en":"Transients are people who stay in a place for only a short time and then move somewhere else.","ex":{"en":"…a hotel for transients.","cn":"为过路客人开设的旅馆"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing for only a limited period of time","cn":""},{"en":"temporary – used especially about arrangements or information that people may decide to change in the future. Also used about licences or governments which are only arranged to last for a short time","cn":""},{"en":"temporary – used about something that you use for a short time until you can replace it with something better","cn":""}]},"vocab":{"pos":"1 adj n 2 adj","senses":[{"en":"Use the adjective transient to describe something that always changes or moves around, like how a teenage girl can have a temporary crush on one boy one week and another boy the next week."}]},"media":{"uk":"media/ldoce/hwd/bre/d/transient_adj0205.mp3","us":"media/ldoce/hwd/ame/9/transient1.mp3"},"examples":[{"en":"a city with a large transient population (= of students, temporary workers, etc.)","cn":"有大量流动人口的城市"},{"en":"the transient nature of speech","cn":"言语的即逝性"}],"oxford":{"phon":"ˈtrænziənt","pos":"adjective","senses":[{"en":"continuing for only a short time","cn":"暂时的；片刻的；转瞬即逝的","ex":{"en":"the transient nature of speech","cn":"言语的即逝性"}},{"en":"staying or working in a place for only a short time, before moving on","cn":"暂住的；过往的；临时的","ex":{"en":"a city with a large transient population (= of students, temporary workers, etc.)","cn":"有大量流动人口的城市"}},{"en":"a person who stays or works in a place for only a short time, before moving on","cn":"暂住某地的人；过往旅客；临时工","ex":{"en":"Most of the farm workers are transients.","cn":"大多数农场工人都是流动人口。"},"pos":"noun"}]}},"trusting":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"轻信的；容易相信别人的","en":"A trusting person believes that people are honest and sincere and do not intend to harm him or her.","ex":{"en":"She has an open, trusting nature","cn":"她天性坦率，容易相信别人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"always trusting other people, especially when this means you can be easily tricked","cn":""},{"en":"always trusting other people, especially when this means you are easily tricked - use this especially about people who are young or do not have much experience","cn":""},{"en":"willing to believe that other people are good and honest","cn":"容易相信他人的﹐轻信的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you're trusting , you tend to believe what people tell you. A trusting friend will tell you her deepest secrets and trust that you'll keep them to yourself."}]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdetrusting.mp3","us":"media/ldoce/hwd/ame/a/laadtrusting.mp3"},"examples":[{"en":"If you're too trusting, other people will take advantage of you.","cn":"如果你过于轻信，其他人就会打你的主意。"},{"en":"She’s so trusting of people.","cn":"她太容易相信别人。"}],"oxford":{"phon":"ˈtrʌstɪŋ","pos":"adjective","senses":[{"en":"tending to believe that other people are good, honest, etc.","cn":"轻信的；轻易信赖别人的","ex":{"en":"If you're too trusting, other people will take advantage of you.","cn":"如果你过于轻信，其他人就会打你的主意。"}}]},"base":"trust"},"tractor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拖拉机","en":"A tractor is a farm vehicle that is used to pull farm machinery and to provide the energy needed for the machinery to work."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong vehicle with large wheels, used for pulling farm machinery","cn":"拖拉机"}]},"vocab":{"pos":"n","senses":[{"en":"A tractor is a vehicle that's used on a farm or work site, often to pull a trailer or other equipment. A farmer might use a tractor to pull a plow through her corn field before planting."}]},"collocations":{"phrases":["ADJ. caterpillar | agricultural, farm","VERB + TRACTOR drive","TRACTOR + VERB plough, work the sound of a tractor ploughing in the field nearby","TRACTOR + NOUN driver | cab | shed","PREP. on a/the ~ a farmer on his tractor","PHRASES a tractor and trailer"]},"media":{"img":["media/ldoce/img/tractor.jpg","media/thumb/tractor.jpg"],"uk":"media/ldoce/hwd/bre/f/tractor0205.mp3","us":"media/ldoce/hwd/ame/9/tractor.mp3"},"oxford":{"phon":"ˈtræktə(r)","pos":"noun","senses":[{"en":"a powerful vehicle with two large and two smaller wheels, used especially for pulling farm machines","cn":"拖拉机；牵引机","ex":{"en":"a farmer on his tractor","cn":"拖拉机上的农夫"}},{"en":"the front part of a tractor-trailer, where the driver sits","cn":"（牵引式挂车的）牵引车，拖车头","lab":"North American English"}]}},"truffle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(通常带朗姆酒味的)圆形巧克力软糖","en":"A truffle is a soft round sweet made with chocolate and usually flavoured with rum."},{"pos":"N-COUNT 可数名词","cn":"松露;块菌","en":"A truffle is a round type of fungus which is expensive and considered very good to eat."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a black or light brown fungus that grows underground, and is a very expensive food","cn":"松露﹐块菌〔生长在地下的一种菌块﹐是非常昂贵的食物〕"},{"en":"a soft creamy sweet made with chocolate","cn":"松露巧克力"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Use the noun truffle when you're talking about a fancy French mushroom or a certain type of rich, fancy chocolate. Try not to combine the two types of truffles in the same dish!"}]},"media":{"uk":"media/ldoce/hwd/bre/7/truffle0205.mp3","us":"media/ldoce/hwd/ame/f/truffle.mp3"},"examples":[{"en":"a rum truffle","cn":"朗姆酒松露巧克力"}],"oxford":{"phon":"ˈtrʌfl","pos":"noun","senses":[{"en":"an expensive type of fungus that grows underground, used in cooking","cn":"块菌（生长于地下，可食用，价格昂贵）"},{"en":"a soft round sweet made of chocolate","cn":"圆形巧克力软糖"}]}},"transience":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"短暂;转瞬即逝;无常","en":"If you talk about the transience of a situation, you mean that it lasts only a short time or is constantly changing.","ex":{"en":"There is a sense of transience about her, a feeling that she has only stopped off here en route to another place.","cn":"她给人一种转瞬即逝的感觉，仿佛她只是在前往他处的途中在此略作停留。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing for only a limited period of time","cn":""},{"en":"temporary – used especially about arrangements or information that people may decide to change in the future. Also used about licences or governments which are only arranged to last for a short time","cn":""},{"en":"temporary – used about something that you use for a short time until you can replace it with something better","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If your grandmother is always talking about how quickly the years go by, she is focused on life's transience , or briefness."}]},"media":{"uk":"media/ldoce/hwd/bre/d/transient_adj0205.mp3","us":"media/ldoce/hwd/ame/9/transient1.mp3"},"examples":[{"en":"the transience of human life","cn":"人生的短暂"}],"oxford":{"phon":"ˈtrænziəns","pos":"noun","senses":[{"en":"the fact that something continues for only a short time","cn":"短暂的；转瞬即逝的；倏忽的","ex":{"en":"the transience of human life","cn":"人生的短暂"}}]}},"truncated":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(版本)缩减的，删节的，截短了的","en":"A truncated version of something is one that has been shortened.","ex":{"en":"The review body has produced a truncated version of its annual report.","cn":"该评论机构出版了其年报的删节版本。"}}]},"vocab":{"pos":"adj","senses":[{"en":"Truncated is an adjective that means \"cut short,\" like a truncated picnic, caused by the sudden downpour."}]}},"tribal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"部落的;部族的","en":"Tribal is used to describe things relating to or belonging to tribes and the way that they are organized.","ex":{"en":"They would go back to their tribal lands.","cn":"他们会回到自己部族的地盘上。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to a tribe or tribes","cn":"部落的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41tribal.mp3","us":"media/ldoce/hwd/ame/5/tribal.mp3"},"examples":[{"en":"tribal art","cn":"部落艺术"},{"en":"tribal leaders","cn":"部落首领"}],"oxford":{"phon":"ˈtraɪbl","pos":"adjective","senses":[{"en":"connected with a tribe or tribes","cn":"部落的；部族的","ex":{"en":"tribal art","cn":"部落艺术"}},{"en":"a member of a tribe, especially in South Asia","cn":"（尤指南亚的）部落成员","pos":"noun"}]}},"treasurer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"司库;财务主管;会计;出纳","en":"The treasurer of a society or organization is the person who is in charge of its finances and keeps its accounts."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is officially responsible for the money for an organization, club, political party etc 〔","cn":"机构﹑俱乐部﹑政党等的〕司库﹐财务主管"}]},"vocab":{"pos":"n","senses":[{"en":"A treasurer has the important job of tallying up funds received by an organization, handing out money for expenses, and keeping track of how much is left over."}]},"collocations":{"phrases":["ADJ. deputy | honorary the honorary treasurer of the rugby club | corporate","VERB + TREASURER act as, be, serve as He agreed to act as treasurer. | appoint, appoint sb (as), elect, elect sb (as) | resign as, retire as","PHRASES treasurer's report The treasurer's report gives a breakdown of the club's income and expenditure."]},"media":{"uk":"media/ldoce/hwd/bre/4/treasurer0205.mp3","us":"media/ldoce/hwd/ame/b/treasurer.mp3"},"oxford":{"phon":"ˈtreʒərə(r)","pos":"noun","senses":[{"en":"a person who is responsible for the money and accounts of a club or an organization","cn":"（俱乐部或组织的）司库，会计，出纳，财务主管","ex":{"en":"the treasurer of the rugby club","cn":"橄榄球俱乐部的财务主管"}}]}},"treatise":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(专题)论文","en":"A treatise is a long, formal piece of writing about a particular subject.","ex":{"en":"...Locke's Treatise on Civil Government.","cn":"洛克的《政府论》"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a serious book or article about a particular subject","cn":"专著﹐专题论文"}]},"vocab":{"pos":"n","senses":[{"en":"Our principal published her fifty-page \" Treatise on Gum Chewing\" days before she was carted away by men in white coats. Treatises are formal papers that treat a specific subject. Gum chewing shouldn't merit one."}]},"media":{"uk":"media/ldoce/hwd/bre/7/treatise0205.mp3","us":"media/ldoce/hwd/ame/0/treatise.mp3"},"examples":[{"en":"a treatise on medical ethics","cn":"一部医学伦理专著"}],"oxford":{"phon":"ˈtriːtɪs","pos":"noun","senses":[{"en":"a long and serious piece of writing on a particular subject","cn":"（专题）论文","ex":{"en":"‘A Treatise on Probability’ by John Maynard Keynes","cn":"约翰·梅纳德·凯恩斯的《概率论》"}}]}},"troglodyte":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"穴居人","en":"A troglodyte is someone who lives in a cave."},{"pos":"N-COUNT 可数名词","cn":"井底之蛙;见识短浅的人","en":"If you refer to someone as a troglodyte, you mean that they are unsophisticated and do not know very much about anything.","ex":{"en":"He dismissed advocates of a completely free market as economic troglodytes with no concern for the social consequences.","cn":"他认为那些鼓吹完全自由市场经济的人对经济只是一知半解，完全没有顾及到可能产生的社会后果。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who lived in a cave in prehistoric times 〔","cn":"史前的〕穴居人"}]},"vocab":{"pos":"n","senses":[{"en":"A troglodyte is a person who lives all alone, in seclusion. You could call this type a \"hermit\" or a \"recluse,\" but it's more fun to say troglodyte ."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41troglodyte.mp3","us":"media/ldoce/hwd/ame/5/troglodyte.mp3"},"oxford":{"phon":"ˈtrɒɡlədaɪt","pos":"noun","senses":[{"en":"a person living in a cave, especially in prehistoric times","cn":"（尤指史前时期的）穴居人"},{"en":"a person with bad social skills and low intelligence","cn":"不受欢迎的笨人；呆子","lab":"British English, informal，，"}]}},"transcription":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"笔录;转写","en":"Transcription of speech or text is the process of transcribing it."},{"pos":"N-COUNT 可数名词","cn":"(根据录音或笔记整理的)笔录本，文字本，转写本","en":"A transcription of a conversation or speech is a written text of it, based on a recording or notes.","ex":{"en":"The transcriptions of the text were available as early as 1960.","cn":"原文的转写本早在 1960 年就可获取。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you transcribe something","cn":"抄写﹔记录﹔转录﹔标音"},{"en":"an exact written or printed copy of something","cn":"抄本﹐副本﹐文字记录"}]},"vocab":{"pos":"1 n 2 n 3 n 4 n","senses":[{"en":"A transcription is the document made by copying down in writing something that you listen to, like audio tapes, an interview, or comments made during a meeting."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41transcription.mp3","us":"media/ldoce/hwd/ame/d/transcription.mp3"},"examples":[{"en":"This dictionary gives phonetic transcriptions of all headwords.","cn":"本词典所有词目都注出了音标。"},{"en":"The full transcription of the interview is attached.","cn":"现附上采访记录文本的全文。"}],"oxford":{"phon":"trænˈskrɪpʃn","pos":"noun","senses":[{"en":"the act or process of representing something in a written or printed form","cn":"抄写；誊写；打印","g":"[uncountable]","ex":{"en":"errors made in transcription","cn":"抄写错误"}},{"en":"a written or printed copy of words that have been spoken","cn":"抄本；誊本；打印本","g":"[countable]","ex":{"en":"The full transcription of the interview is attached.","cn":"现附上采访记录文本的全文。"}},{"en":"something that is represented in writing","cn":"书面标注的事物","g":"[countable]","ex":{"en":"This dictionary gives phonetic transcriptions of all headwords.","cn":"本词典所有词目都注出了音标。"}},{"en":"a change in the written form of a piece of music so that it can be played on a different instrument or sung by a different voice","cn":"（乐曲的）改编","g":"[countable]"}]}},"trivial":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"琐碎的;不重要的;微不足道的","en":"If you describe something as trivial, you think that it is unimportant and not serious.","ex":{"en":"The director tried to wave aside these issues as trivial details that could be settled later","cn":"主管试图对这些问题置之不理，认为都是些细枝末节的小事，可以稍后解决。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not important","cn":""},{"en":"not important, or not very important. These phrases sound a little more formal than unimportant","cn":""},{"en":"small and not very likely to have an important effect – used especially about changes, problems, injuries, damage, or differences","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that is trivial is not important or significant, such as the trivial details you shared with me about your trip to the post office this morning."}]},"collocations":{"phrases":["VERBS appear, be, look, seem | consider sth, deem sth, regard sth as","ADV. extremely, very | absolutely, completely | almost | a bit, comparatively, fairly, pretty, quite, rather, relatively | essentially makin"]},"media":{"uk":"media/ldoce/hwd/bre/f/trivial0205.mp3","us":"media/ldoce/hwd/ame/6/trivial.mp3"},"examples":[{"en":"I know it sounds trivial , but I'm worried about it.","cn":"我知道这事听起来微不足道，但我还是放心不下。"},{"en":"I'll try to fix it — but it's not trivial (= it may be difficult to fix).","cn":"我会设法修好，不过这并非易事。"}],"oxford":{"phon":"ˈtrɪviəl","pos":"adjective","senses":[{"en":"not important or serious; not worth considering","cn":"不重要的；琐碎的；微不足道的","ex":{"en":"a trivial detail","cn":"细枝末节"}}]}},"transaction":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(一笔)交易;业务","en":"A transaction is a piece of business, for example an act of buying or selling something."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a business agreement between two companies, especially when one company agrees to provide goods or services, and another company agrees to buy them","cn":""},{"en":"a business deal between two or more people or companies in which money is given and something is bought or sold","cn":""},{"en":"a business deal or action, such as buying or selling something","cn":"交易﹐业务﹐买卖"}]},"vocab":{"pos":"n","senses":[{"en":"A transaction is any kind of action involved in conducting business, or an interaction between people. When you go to the bank, fill out a form, and deposit your paycheck, you make a transaction ."}]},"collocations":{"phrases":["ADJ. cross-border, international | domestic | profitable | fraudulent, illegal The president had entered into fraudulent property transactio","VERB + TRANSACTION carry out, conduct, enter into, make | effect, handle to effect a transaction for a client | close, complete","TRANSACTION + VERB proceed, take place to ensure the transaction proceeds smoothly","TRANSACTION + NOUN charges, costs","PREP. ~ between The system records all transactions between the firm and its suppliers. | ~ in Transactions in land are frequently handled b"]},"media":{"uk":"media/ldoce/hwd/bre/2/transaction0205.mp3","us":"media/ldoce/hwd/ame/2/transaction.mp3"},"examples":[{"en":"financial transactions between companies","cn":"公司之间的财务往来"},{"en":"the transaction of government business","cn":"处理政府事务"}],"oxford":{"phon":"trænˈzækʃn","pos":"noun","senses":[{"en":"a piece of business that is done between people, especially an act of buying or selling","cn":"（一笔）交易，业务，买卖","g":"[countable]","ex":{"en":"financial transactions between companies","cn":"公司之间的财务往来"}},{"en":"the process of doing something","cn":"办理；处理","g":"[uncountable]","lab":"formal","ex":{"en":"the transaction of government business","cn":"处理政府事务"}}]}},"tricycle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(通常指儿童骑的)三轮脚踏车","en":"A tricycle is a cycle with three wheels, two at the back and one at the front. Tricycles are usually ridden by children."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bicycle with three wheels, especially for young children 〔","cn":"尤指幼儿骑的〕三轮自行车"}]},"vocab":{"pos":"n","senses":[{"en":"For many kids, their first vehicle is a tricycle , or a small three-wheeled bike."}]},"media":{"img":["media/ldoce/img/tricycle.jpg","media/thumb/tricycle.jpg"],"uk":"media/ldoce/hwd/bre/c/tricycle0205.mp3","us":"media/ldoce/hwd/ame/5/ld44tricycle.mp3"},"oxford":{"phon":"ˈtraɪsɪkl","pos":"noun","senses":[{"en":"a vehicle similar to a bicycle, but with one wheel at the front and two at the back","cn":"三轮脚踏车"}]}},"tram":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"有轨电车","en":"A tram is a public transport vehicle, usually powered by electricity from wires above it, which travels along rails laid in the surface of a street.","ex":{"en":"You can get to the beach easily from the centre of town by tram.","cn":"你从市中心乘有轨电车到海滩会很方便。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large vehicle that people pay to travel on","cn":""},{"en":"a bus with comfortable seats used for long journeys","cn":""},{"en":"a small bus with seats for six to twelve people","cn":""}]},"collocations":{"phrases":["ADJ. modern | electric, horse/horse-drawn, steam","VERB + TRAM catch, go on, take | miss | board, get on | get off","TRAM + VERB run The last tram ran through Glasgow in September 1962. | rattle | stop","TRAM + NOUN service, system | route | stop | ride | driver | car a conducted tour in an old tram car | shed | line, rail, track | ticket","PREP. by ~ There is easy access to the centre of the city by tram. | on a/the ~ They sat together on the rattling tram. | ~ from, ~ to"]},"media":{"uk":"media/ldoce/hwd/bre/6/tram0205.mp3","us":"media/ldoce/hwd/ame/c/tram.mp3","img":["media/thumb/tram.jpg"]},"examples":[{"en":"a tram route","cn":"有轨电车路线"}],"oxford":{"phon":"træm","pos":"noun","senses":[{"en":"a vehicle driven by electricity, that runs on rails along the streets of a town and carries passengers","cn":"有轨电车","ex":{"en":"a tram route","cn":"有轨电车路线"}}]}},"tryout":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"试用;试验","en":"If you give something a tryout, you try it or test it to see how useful it is.","ex":{"en":"The recycling scheme gets its first try-out in rural Dorset.","cn":"这些再循环方案在多塞特郡的农村地区首先试用。"}},{"pos":"N-COUNT 可数名词","cn":"(争取入队资格的)角逐赛，选拔赛;(争取角色的)试演","en":"If you are given a tryout for a sports team or an acting role, you compete or you perform a test in an attempt to be chosen.","ex":{"en":"…tryouts for the U.S. junior national athletics team.","cn":"入选美国国家少年体育队的选拔赛"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a time when people who want to be in a sports team, activity etc are tested, so that the best can be chosen 〔","cn":"体育队﹑活动等成员的〕挑选﹐选拔"},{"en":"a period of time during which a play, television show etc is shown to find out if people like it 〔","cn":"戏剧﹑电视节目等的〕试演﹐试播"}]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdetryout.mp3","us":"media/ldoce/hwd/ame/7/tryout.mp3"},"examples":[{"en":"baseball tryouts","cn":"棒球队员的选拔"}],"oxford":{"phon":"ˈtraɪaʊt","pos":"noun","senses":[{"en":"an act of testing how good or effective somebody/something is before deciding whether to use them/it in the future","cn":"检查衡量潜力；考核潜力","ex":{"en":"The play had a tryout in Oxford before it moved to London.","cn":"该剧在搬到伦敦之前曾在牛津进行过试演。"}},{"en":"a competition or series of tests to find the best players for a sports team or an important event","cn":"预赛；选拔赛","lab":"North American English"}]}},"trimaran":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"三体帆船","en":"A trimaran is a fast sailing boat similar to a catamaran, but with three hulls instead of two."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large boat with a sail, used for pleasure or sport","cn":""},{"en":"a boat that uses one or more sails","cn":""},{"en":"a small boat that you move through the water with oars","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41trimaran.mp3","us":"media/ldoce/hwd/ame/5/trimaran.mp3"},"oxford":{"phon":"ˈtraɪməræn","pos":"noun","senses":[{"en":"a fast sailing boat like a catamaran, but with three hulls instead of two","cn":"三体帆船"}]}},"treetop":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"树梢","en":"The treetops are the top branches of the trees in a wood or forest.","ex":{"en":"All they heard was the wind whispering through the treetops.","cn":"他们听到的只有风吹过树梢的飒飒声。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the branches at the top of a tree","cn":"树梢"}]},"media":{"uk":"media/ldoce/hwd/bre/0/treetop0205.mp3","us":"media/ldoce/hwd/ame/0/laadtreetop.mp3"},"examples":[{"en":"birds nesting in the treetops","cn":"在树梢上筑巢的鸟"}],"oxford":{"phon":"ˈtriːtɒp","pos":"noun","senses":[{"en":"the branches at the top of a tree","cn":"树梢","ex":{"en":"birds nesting in the treetops","cn":"在树梢上筑巢的鸟"}}]}},"treeless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无树木的;没有长树的","en":"A treeless area or place has no trees in it.","ex":{"en":"No shelter was available for miles around in this treeless landscape.","cn":"在这个光秃秃没有树木的地方，周围数英里内都没有掩蔽处。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a treeless area has no trees in it","cn":"无树木的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/treeless0205.mp3","us":"media/ldoce/hwd/ame/8/laadtreeless.mp3"},"examples":[{"en":"a treeless plain","cn":"没有树木的平原"},{"en":"a treeless landscape","cn":"没有树木的地貌"}],"oxford":{"phon":"ˈtriːləs","pos":"adjective","senses":[{"en":"without trees","cn":"无树木的","ex":{"en":"a treeless plain","cn":"没有树木的平原"}}]}},"truism":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"陈词滥调;不言自明的说法","en":"A truism is a statement that is generally accepted as obviously true and is repeated so often that it has become boring.","ex":{"en":"Orpington seems an example of the truism that nothing succeeds like success","cn":"奥尔平顿似乎验证了一个常理——一事成功百事顺。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement that is clearly true, so that there is no need to say it","cn":"自明之理﹐不言而喻的话"}]},"vocab":{"pos":"n","senses":[{"en":"Here's a truism for you: Only people who look up words they don't know can expand their vocabularies. Did you find that statement obvious, boring, and saying nothing new or interesting? That's the perfect description of a truism ."}]},"media":{"uk":"media/ldoce/hwd/bre/8/truism0205.mp3","us":"media/ldoce/hwd/ame/d/truism.mp3"},"examples":[{"en":"His speech was just a collection of clichés and truisms.","cn":"他的演说就是一堆陈词滥调和自明之理。"}],"oxford":{"phon":"ˈtruːɪzəm","pos":"noun","senses":[{"en":"a statement that is clearly true and does not therefore add anything interesting or important to a discussion","cn":"不言而喻的道理；自明之理；老生常谈","ex":{"en":"It has become a truism that every woman wants to choose how she delivers her baby.","cn":"每个女人都想选择自己的分娩方式，这已成为不言而喻的事实。"}}]}},"transitivity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(动词的)及物性","en":"The transitivity of a verb is whether or not it is used with a direct object."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a transitive verb must have an object, for example the verb ‘break’ in the sentence ‘I broke the cup’. Transitive verbs are marked [T] in this dictionary.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/transitive0205.mp3","us":"media/ldoce/hwd/ame/a/transitive.mp3"},"oxford":{"phon":"ˌtrænzəˈtɪvəti","pos":"noun","senses":[{"en":"the fact of a particular verb being either transitive or intransitive","cn":"（动词的）及物性","ex":{"en":"These codes indicate the transitivity of the verb.","cn":"这些代码表示动词的及物性。"}}]}},"tribe":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"(尤指发展中国家的)部落，部族(一些人不赞成此用法)","en":"Tribe is sometimes used to refer to a group of people of the same race, language, and customs, especially in a developing country. Some people disapprove of this use.","ex":{"en":"...three-hundred members of the Xhosa tribe.","cn":"300 名科萨族人"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"(从事相同活动或行为相同的)一伙(人)，一帮(人)","en":"You can use tribe to refer to a group of people who are all doing the same thing or who all behave in the same way.","ex":{"en":"...tribes of talented young people.","cn":"一群群才华出众的年轻人"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the main groups of people in the world, who have the same colour of skin and other physical features","cn":""},{"en":"a country and its people, or a group of people with the same history and language","cn":""},{"en":"the people who belong to a particular country, race, or area. The plural of this meaning of people is peoples","cn":""}]},"collocations":{"phrases":["ADJ. aboriginal, indigenous, native | desert, forest, hill | nomadic | backward, primitive | barbaric, hostile, warring","VERB + TRIBE belong to","PHRASES a member of a tribe"]},"media":{"uk":"media/ldoce/hwd/bre/6/tribe0205.mp3","us":"media/ldoce/hwd/ame/9/tribe.mp3"},"examples":[{"en":"One or two of the grandchildren will be there, but not the whole tribe.","cn":"一两个孙子孙女会去那里，但并不是所有的人。"},{"en":"tribes living in remote areas of the Amazonian rainforest","cn":"居住在亚马逊河雨林偏远地区的部落"}],"oxford":{"phon":"traɪb","pos":"noun","senses":[{"en":"a social group in a traditional society consisting of people with the same language, culture, religion, etc., living in a particular area and often having one leader known as a chief","cn":"部落","lab":"sometimes offensive","ex":{"en":"They were a nomadic horse-riding tribe.","cn":"他们是一个骑马的游牧部落。"}},{"en":"a group or class of people, especially of one profession","cn":"（尤指同一职业的）一伙（人），一帮（人），一类（人）","lab":"usually disapproving","ex":{"en":"He had a sudden outburst against the whole tribe of actors.","cn":"他突然对所有的演员非常反感。"}},{"en":"a group of related animals or plants","cn":"（动物或植物的）族，群","lab":"biology","ex":{"en":"a tribe of cats","cn":"猫族"}},{"en":"a large family","cn":"一大家人","lab":"informal or humorous","ex":{"en":"One or two of the grandchildren will be there, but not the whole tribe.","cn":"一两个孙子孙女会去那里，但并不是所有的人。"}}]}},"traitor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"背叛(信仰)者;背信弃义者","en":"If you call someone a traitor, you mean that they have betrayed beliefs that they used to hold, or that their friends hold, by their words or actions.","ex":{"en":"Some say he's a traitor to the working class.","cn":"一些人说他是工人阶级的叛徒。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指战时的)卖国贼，叛徒","en":"If someone is a traitor, they betray their country or a group of which they are a member by helping its enemies, especially during time of war.","ex":{"en":"...rumours that there were traitors among us who were sending messages to the enemy.","cn":"关于我们中间有叛徒向敌人通风报信的传言"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who helps the enemies of their country, for example by giving them secret information","cn":""},{"en":"someone who helps their country's enemies, especially when the enemy has taken control of that country","cn":""},{"en":"someone who is not loyal to their country, friends, or beliefs","cn":"卖国者﹔叛徒﹐背叛者"}]},"vocab":{"pos":"n","senses":[{"en":"A traitor says one thing but does another. If you promise a friend you'll keep his secret, but instead you blab it to everyone, you're a traitor."}]},"collocations":{"phrases":["VERB + TRAITOR turn He turned traitor and joined the opposition. | denounce sb as","PREP. ~ to He is seen as a traitor to the cause."]},"media":{"uk":"media/ldoce/hwd/bre/a/traitor0205.mp3","us":"media/ldoce/hwd/ame/d/traitor.mp3"},"examples":[{"en":"He was seen as a traitor to the socialist cause.","cn":"他被视为社会主义事业的叛徒。"},{"en":"She denied that she had turned traitor (= become a traitor ).","cn":"她否认自己叛变了。"}],"oxford":{"phon":"ˈtreɪtə(r)","pos":"noun","senses":[{"en":"a person who betrays their friends, their country, etc. by giving away secrets about them, by lying to or about them or by doing other things that will harm them","cn":"背叛者；叛徒；卖国贼","ex":{"en":"He was seen as a traitor to the socialist cause.","cn":"他被视为社会主义事业的叛徒。"}}]}},"troop":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"部队;军队;士兵","en":"Troops are soldiers, especially when they are in a large organized group doing a particular task.","ex":{"en":"The next phase of the operation will involve the deployment of more than 35,000 troops from a dozen countries","cn":"下一阶段的军事行动将要对来自 12 个国家的 35,000多名士兵进行部署。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"骑兵队;装甲团","en":"A troop is a group of soldiers within a cavalry or armoured regiment.","ex":{"en":"...a troop of enemy cavalry trotting towards the Dutch right flank.","cn":"敌方一支骑兵队正冲向荷兰军右翼"}},{"pos":"N-COUNT 可数名词","cn":"童子军中队","en":"A troop of boy scouts is a local group of them that meets regularly.","ex":{"en":"…a Scout troop.","cn":"一队童子军"}},{"pos":"N-COUNT 可数名词","cn":"一群;一队","en":"A troop of people or animals is a group of them.","ex":{"en":"Amy was aware of the little troop of travellers watching the two of them","cn":"埃米知道那一小队旅行者正在看着她们俩。"}},{"pos":"VERB 动词","cn":"(常指疲惫或忧伤地)成群移动，结队前行","en":"If people troop somewhere, they walk there in a group, often in a sad or tired way.","ex":{"en":"They all trooped back to the house for a rest","cn":"他们都成群结队地回到房子里休息。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"soldiers in an organized group","cn":"部队﹔军队"},{"en":"movements etc of troops","cn":"部队调动/撤离等"},{"en":"a group of soldiers, especially on horses or in tank s","cn":"一支部队﹔〔尤指〕骑兵部队﹐坦克部队"}]},"vocab":{"pos":"n v","senses":[{"en":"A troop is a squad or team of soldiers. Your great grandfather might claim that his was the first army troop to march into France during World War II."}]},"media":{"uk":"media/ldoce/hwd/bre/c/troop_n0205.mp3","us":"media/ldoce/hwd/ame/0/troop1.mp3"},"examples":[{"en":"They announced the withdrawal of 12 000 troops from the area.","cn":"他们宣布从这个地区撤军 12 000 人。"},{"en":"After lunch we all trooped down to the beach.","cn":"午餐后我们都成群结队走向海滩。"}],"oxford":{"phon":"truːp","pos":"adjective","senses":[{"en":"connected with soldiers, especially in large groups","cn":"军队；部队；士兵","ex":{"en":"troop movements","cn":"部队的调动"}},{"en":"soldiers, especially in large groups","cn":"军队；部队；士兵","g":"[plural]","ex":{"en":"They announced the withdrawal of 12 000 troops from the area.","cn":"他们宣布从这个地区撤军 12 000 人。"},"pos":"noun"},{"en":"one group of soldiers, especially in tanks or on horses","cn":"连队；坦克连；骑兵连","g":"[countable]","lab":"figurative","ex":{"en":"A troop of guests was moving towards the house.","cn":"一群客人朝那房子走去。"},"pos":"noun"},{"en":"a local group of Scouts","cn":"童子军中队","g":"[countable]","pos":"noun"},{"en":"to walk somewhere together as a group","cn":"成群结队而行；列队行进","ex":{"en":"After lunch we all trooped down to the beach.","cn":"午餐后我们都成群结队走向海滩。"},"pos":"verb"}]}},"traipse":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(常因疲惫或不愉快)不情愿地走","en":"If you traipse somewhere, you go there unwillingly, often because you are tired or unhappy.","ex":{"en":"If traipsing around shops does not appeal to you, perhaps using a catalogue will","cn":"如果不愿逛商店逛得腰酸腿疼，也许您会愿意使用商品目录。"}},{"pos":"VERB 动词","cn":"令人不快地走(或转悠);碍事地走(或转悠)","en":"If you talk about people traipsing somewhere, you mean that they are going there or moving about there in a way that annoys someone or gets in their way.","ex":{"en":"You will have to get used to a lot of people traipsing in and out of your home","cn":"你将不得不习惯许多人在你家进进出出。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to walk slowly and with heavy steps, especially because you are tired, it is difficult to walk, or you do not want to go somewhere","cn":""},{"en":"to walk a long way, especially when you are looking for something or visiting different places, so that you become tired","cn":""},{"en":"to walk somewhere in a slow or unwilling way because you are tired or bored","cn":"闲荡﹔疲惫地行走﹐拖沓地行走"}]},"vocab":{"pos":"v","senses":[{"en":"To traipse is to walk around with a sloppy or aimless attitude. A bored high school student might traipse through a museum on a class trip, for example."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41traipse.mp3","us":"media/ldoce/hwd/ame/6/traipse.mp3"},"examples":[{"en":"I’ve been traipsing around the shops all morning.","cn":"我整个上午一直在逛商店。"}],"oxford":{"phon":"treɪps","pos":"verb","senses":[{"en":"to walk somewhere slowly when you are tired and unwilling","cn":"疲惫地走；拖沓地行走；磨蹭","ex":{"en":"We spent the afternoon traipsing around the town.","cn":"我们拖着疲惫的身子在城里转了一下午。"}}]}},"trucker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"卡车司机","en":"A trucker is someone who drives a truck as their job."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who regularly drives, or someone who is driving a car, train, etc at a particular time","cn":""},{"en":"someone who drives a car – used especially when talking about car drivers in general","cn":""},{"en":"someone whose job is to drive a car for someone else","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/trucker0205.mp3","us":"media/ldoce/hwd/ame/1/trucker.mp3"},"oxford":{"phon":"ˈtrʌkə(r)","pos":"noun","senses":[{"en":"a person whose job is driving a truck","cn":"卡车司机"}]}},"tribute":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"致敬;颂词;献礼","en":"A tribute is something that you say, do, or make to show your admiration and respect for someone.","ex":{"en":"The song is a tribute to Roy Orbison","cn":"那首歌是对罗伊·奥比森的致敬。"}},{"pos":"N-SING 单数名词","cn":"(良好结果的)体现，证明","en":"If one thing is a tribute to another, the first thing is the result of the second and shows how good it is.","ex":{"en":"His success has been a tribute to hard work, to professionalism","cn":"他的成功充分体现了他的勤劳苦干和敬业精神。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to say that you admire someone or approve of something good that they have done","cn":""},{"en":"to tell someone that you are pleased or impressed because they have achieved something special","cn":""},{"en":"to tell someone that you like the way they look or that you are pleased with something that they have done","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A tribute is a sign of respect or admiration, an award to honor a person's accomplishments. A famous director receives a lifetime achievement award as a tribute to his many successful films."}]},"collocations":{"phrases":["ADJ. anniversary, birthday, centenary | final, last | fitting | lasting | affectionate, emotional, moving, warm | generous, glowing, handsom","VERB + TRIBUTE pay The couple paid tribute to the helicopter crew who rescued them. | lead The prime minister led the tributes to &lsquo;a g","TRIBUTE + VERB flood in Tributes flooded in when her death was announced.","TRIBUTE + NOUN album, concert 2 sign of how good sb/sth is","ADJ. great, remarkable","PREP. ~ to The bridge is a remarkable tribute to the skill of the Victorian railway engineers."]},"media":{"uk":"media/ldoce/hwd/bre/f/tribute0205.mp3","us":"media/ldoce/hwd/ame/b/tribute.mp3"},"examples":[{"en":"At her funeral her oldest friend paid tribute to her life and work.","cn":"在葬礼上，与她相识最久的老朋友对她的一生和工作给予了高度的赞扬。"},{"en":"This book is a fitting tribute to the bravery of the pioneers.","cn":"本书是对先驱们大无畏精神恰如其分的献礼。"}],"oxford":{"phon":"ˈtrɪbjuːt","pos":"noun","senses":[{"en":"an act, a statement or a gift that is intended to show your love or respect, especially for a dead person","cn":"（尤指对死者的）致敬，颂词；悼念；致哀；吊唁礼物","g":"[uncountable, countable]","ex":{"en":"At her funeral her oldest friend paid tribute to her life and work.","cn":"在她的葬礼上，与她相识最久的老朋友对她的一生和工作给予了高度的赞扬。"}},{"en":"showing the good effects or influence of something/somebody","cn":"（良好效果或影响的）体现，显示","g":"[singular]","ex":{"en":"His recovery is a tribute to the doctors' skill.","cn":"他的康复充分显示了各位医生高超的医术。"}},{"en":"(especially in the past) money given by one country or political leader to another, especially in return for protection or for not being attacked","cn":"（一国向他国交纳的）贡品，贡金","g":"[uncountable, countable]"}]}},"tripper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"旅行者;度假者","en":"A tripper is a person who is on a trip or on holiday.","ex":{"en":"...when the shops shut and the trippers go home.","cn":"当商店关门、度假者返程回家时"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a day tripper 〔","cn":"一日游的〕游客"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld44tripper.mp3","us":"media/ldoce/hwd/ame/a/ld41tripper.mp3"},"examples":[{"en":"a day tripper","cn":"一日游者"}],"oxford":{"phon":"ˈtrɪpə(r)","pos":"noun","senses":[{"en":"a person who is visiting a place for a short time for pleasure","cn":"（短程）旅游者","ex":{"en":"a day tripper","cn":"一日游者"}}]}},"transpose":{"collins":{"senses":[{"pos":"VERB 动词","cn":"调换…的位置；使换位","en":"If you transpose something from one place or situation to another, you move it there.","ex":{"en":"Genetic engineers transpose or exchange bits of hereditary material from one organism to the next","cn":"遗传工程师将某一生物的小段遗传物质调换到另一生物，或与其互换。"}},{"pos":"VERB 动词","cn":"互换…的顺序(或位置)","en":"If you transpose two things, you reverse them or put them in each other's place.","ex":{"en":"Many people inadvertently transpose digits of the ZIP code.","cn":"很多人疏忽之下会颠倒邮政编码中数字的顺序。"}},{"pos":"VERB 动词","cn":"使(乐曲)变调","en":"If you transpose a piece of music, you perform it or write it in a musical key which is different from the original one.","ex":{"en":"She could play any piece of music she heard and transpose it into any key.","cn":"她能把听过的任何乐曲变以任何调演奏出来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change the order or position of two or more things","cn":"变换﹐调换〔顺序或位置〕"},{"en":"to use a system or method in a different situation from the one you used it in originally","cn":"转移〔系统﹑方法等的使用环境〕"},{"en":"to write or perform a piece of music in a musical key that is different from the one that it was first written in","cn":"使〔乐曲〕变调﹐移调"}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"If you transpose something, you change the order. You could transpose the phrases in that first sentence by writing, \"You change the order if you transpose something.\""}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41transpose.mp3","us":"media/ldoce/hwd/ame/7/transpose.mp3"},"examples":[{"en":"The director transposes Shakespeare's play from 16th century Venice to present-day England.","cn":"导演把莎士比亚的戏剧从 16 世纪的威尼斯改成当代的英国。"}],"oxford":{"phon":"trænˈspəʊz","pos":"verb","senses":[{"en":"to change the order of two or more things","cn":"使掉换顺序","lab":"formal","ex":{"en":"Two letters were accidentally transposed and ‘gun’ got printed as ‘gnu’.","cn":"两个字母不小心调换了位置，“gun”打印成了“gnu”。"}},{"en":"to move or change something to a different place or environment or into a different form","cn":"使转移；使换位；使变形","lab":"formal","ex":{"en":"The director transposes Shakespeare's play from 16th century Venice to present-day England.","cn":"导演把莎士比亚的戏剧从 16 世纪的威尼斯改成当代的英国。"}},{"en":"to write or play a piece of music or a series of notes in a different key","cn":"使（乐曲）变调，移调","lab":"music"}]}},"transformer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"变压器","en":"A transformer is a piece of electrical equipment which changes a voltage to a higher or lower voltage."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment for changing electricity from one voltage to another","cn":"变压器"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun transformer when you're talking about a device that conducts electricity and controls the voltage that can travel between one circuit and another."}]},"media":{"uk":"media/ldoce/hwd/bre/4/transformer0205.mp3","us":"media/ldoce/hwd/ame/e/transformer.mp3"},"oxford":{"phon":"trænsˈfɔːmə(r)","pos":"noun","senses":[{"en":"a device for reducing or increasing the voltage of an electric power supply, usually to allow a particular piece of electrical equipment to be used","cn":"变压器"}]}},"trademark":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"商标","en":"A trademark is a name or symbol that a company uses on its products and that cannot legally be used by another company."},{"pos":"N-COUNT 可数名词","cn":"标志;特点","en":"If you say that something is the trademark of a particular person or place, you mean that it is characteristic of them or typically associated with them.","ex":{"en":"...the spiky punk hairdo that became his trademark.","cn":"成为他标志的朋克刺猬头"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special name, sign, or word that is marked on a product to show that it is made by a particular company, that cannot be used by any other company 〔","cn":"公司某一产品的〕商标"},{"en":"a particular way of behaving, dressing etc by which someone or something can be easily recognized 〔","cn":"人或物易被识别的〕标记﹐特征"}]},"vocab":{"pos":"n v","senses":[{"en":"A trademark is a distinctive feature of something or someone, and to trademark is to brand something, especially in a legal sense."}]},"media":{"uk":"media/ldoce/hwd/bre/3/trademark0205.mp3","us":"media/ldoce/hwd/ame/d/trademark.mp3"},"examples":[{"en":"‘Big Mac’ is McDonald's best-known trademark. “","cn":"巨无霸”是麦当劳最著名的商标。"},{"en":"‘Big Mac’ is McDonald's best-known trademark.","cn":""}],"oxford":{"phon":"ˈtreɪdmɑːk","pos":"noun","senses":[{"en":"a name, symbol or design that a company uses for its products and that cannot be used by anyone else","cn":"商标","ex":{"en":"‘Big Mac’ is McDonald's best-known trademark.","cn":"“巨无霸”是麦当劳最著名的商标。"}},{"en":"a special way of behaving or dressing that is typical of somebody and that makes them easily recognized","cn":"（人的行为或衣着的）特征，标记","ex":{"en":"Attention to detail is Anthea’s trademark.","cn":"注重细节是安西娅的特点。"}},{"en":"to register something as a trademark","cn":"把…注册为商标","ex":{"en":"They have trademarked the name in the US and the UK.","cn":"他们已在美国和英国将这个名称注册为商标。"},"pos":"verb"}]}},"trout":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"鳟鱼","en":"A trout is a fairly large fish that lives in rivers and streams."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a common river-fish, often used for food, or the flesh of this fish","cn":"鳟鱼〔一种常见河鱼〕﹔鳟鱼肉"},{"en":"an unpleasant or annoying old person, especially a woman","cn":"老家伙﹐老东西﹔〔尤指〕老太婆"}]},"collocations":{"phrases":["ADJ. fresh | wild | farmed | river, sea | smoked | brown, rainbow, salmon","VERB + TROUT eat, have | bake, cook, fry, grill | catch, fish for, land, tickle | farm","TROUT + NOUN fishing | farm, fishery | stream •"]},"media":{"img":["media/ldoce/img/trout.jpg","media/thumb/trout.jpg"],"uk":"media/ldoce/hwd/bre/1/trout0205.mp3","us":"media/ldoce/hwd/ame/8/trout.mp3"},"examples":[{"en":"Shall we have trout for dinner?","cn":"我们正餐吃鳟鱼好吗？"},{"en":"trout fishing","cn":"捕鳟鱼"}],"oxford":{"phon":"traʊt","pos":"noun","senses":[{"en":"a common freshwater fish that is used for food. There are several types of trout.","cn":"鲑；鲑鳟鱼；鳟鱼","g":"[countable, uncountable]","ex":{"en":"rainbow trout","cn":"虹鳟"}},{"en":"an offensive word for an annoying or angry old woman","cn":"恶婆子；讨厌的老太婆","g":"[countable, usually singular]","lab":"informal"}]}},"trigger":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(枪的)扳机","en":"The trigger of a gun is a small lever which you pull to fire it.","ex":{"en":"A man pointed a gun at them and pulled the trigger.","cn":"一名男子拿枪指着他们，接着扣动了扳机。"}},{"pos":"N-COUNT 可数名词","cn":"(炸弹的)引爆器","en":"The trigger of a bomb is the device which causes it to explode.","ex":{"en":"...trigger devices for nuclear weapons.","cn":"核武器的引爆器"}},{"pos":"VERB 动词","cn":"引爆;启动;触发","en":"To trigger a bomb or system means to cause it to work.","ex":{"en":"The thieves must have deliberately triggered the alarm and hidden inside the house","cn":"盗贼肯定是故意触发了报警器，然后躲在房子里。"}},{"pos":"VERB 动词","cn":"引起;发动;促使","en":"If something triggers an event or situation, it causes it to begin to happen or exist.","ex":{"en":"...the incident which triggered the outbreak of the First World War","cn":"导致第一次世界大战爆发的事件"}},{"pos":"N-COUNT 可数名词","cn":"诱因;起因;引发…的原因","en":"If something acts as a trigger for another thing such as an illness, event, or situation, the first thing causes the second thing to begin to happen or exist.","ex":{"en":"Stress may act as a trigger for these illnesses.","cn":"压力可能会成为引发这些疾病的原因。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something happen, especially something bad","cn":""},{"en":"to cause someone to do something, or cause something to happen. Make is less formal than cause , and is the usual word to use in everyday English","cn":""},{"en":"if someone or something is responsible for something bad, they caused it to happen","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A trigger is a metal lever that when pulled discharges a gun. You shoot the gun by pulling the trigger . Trigger can also mean the start of a process––violent protests might trigger a revolution."}]},"collocations":{"phrases":["VERB + TRIGGER pull, squeeze | tighten on Her finger tightened on the trigger as she heard footsteps approaching.","TRIGGER + NOUN finger","PHRASES have your finger on the trigger (= to be ready to shoot)"]},"media":{"uk":"media/ldoce/hwd/bre/f/trigger_v0205.mp3","us":"media/ldoce/hwd/ame/6/trigger1.mp3"},"examples":[{"en":"The trigger for the strike was the closure of yet another factory.","cn":"触发这次罢工的是再有一家工厂关闭。"},{"en":"Nuts can trigger off a violent allergic reaction.","cn":"坚果可以引起严重的过敏反应。"}],"oxford":{"phon":"ˈtrɪɡə(r)","pos":"verb","senses":[{"en":"to make something happen suddenly","cn":"发动；引起；触发","ex":{"en":"Nuts can trigger off a violent allergic reaction.","cn":"坚果可以引起严重的过敏反应。"}},{"en":"to cause a device to start functioning","cn":"开动；启动","ex":{"en":"to trigger an alarm","cn":"触发警报器"}},{"en":"to make somebody feel very upset or anxious by reminding them of a trauma or bad experience","cn":"通过提醒某人创伤或糟糕的经历来使他们感到非常沮丧或焦虑","ex":{"en":"Sometimes, the slightest things trigger me because they remind me of my mum.","cn":"有时，最细微的事情都会触动我，因为它们让我想起了我的妈妈。"}},{"en":"the part of a gun that you press in order to fire it","cn":"（枪的）扳机","ex":{"en":"to pull/squeeze the trigger","cn":"扣扳机"},"pos":"noun"},{"en":"something that is the cause of a particular reaction or development, especially a bad one","cn":"（尤指引发不良反应或发展的）起因，诱因","ex":{"en":"The trigger for the strike was the closure of yet another factory.","cn":"触发这次罢工的是又一家工厂被关闭了。"},"pos":"noun"}]}},"traditionalism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"传统主义","en":"Traditionalism is behaviour and ideas that support established customs and beliefs, rather than modern ones."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"belief in the importance of tradition s and customs","cn":"传统主义﹐崇尚传统"}]},"media":{"uk":"media/ldoce/hwd/bre/d/traditionalism0205.mp3","us":"media/ldoce/hwd/ame/5/traditionalism.mp3"},"oxford":{"phon":"trəˈdɪʃənəlɪzəm","pos":"noun","senses":[{"en":"the belief that customs and traditions are more important for a society than modern ideas","cn":"传统主义（认为传统习俗比现代思想对社会更重要）"}]}},"trotskyist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"托洛茨基分子;托派分子","en":"A Trotskyist is someone who supports the revolutionary left-wing ideas of Leon Trotsky."}]},"oxford":{"phon":"ˈtrɒtskiɪst","pos":"adjective","senses":[{"en":"connected with the political ideas of Leon Trotsky, especially that socialism should be introduced all over the world by means of revolution","cn":"托洛茨基分子"},{"en":"a supporter of the political ideas of Leon Trotsky, especially that socialism should be introduced all over the world by means of revolution","cn":"托洛茨基分子","pos":"noun"}]}},"trench":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"壕沟;沟渠","en":"A trench is a long narrow channel that is cut into the ground, for example in order to lay pipes or get rid of water."},{"pos":"N-COUNT 可数名词","cn":"战壕，堑壕(the trenches 常指第一次世界大战的西线战场)","en":"A trench is a long narrow channel in the ground used by soldiers in order to protect themselves from the enemy. People often refer to the battle grounds of the First World War in Northern France and Belgium as the trenches .","ex":{"en":"We fought with them in the trenches.","cn":"我们曾在一战西线战场上与他们并肩作战。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long narrow hole dug into the surface of the ground","cn":"壕沟﹔沟渠"},{"en":"a long narrow valley in the ground beneath the sea","cn":"海沟"},{"en":"a deep trench dug in the ground as a protection for soldiers","cn":"战壕﹐堑壕"}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"A trench is a deep and narrow hole, or ditch, in the ground, like the kind soldiers on frontlines might dig to give themselves shelter from the enemy."}]},"collocations":{"phrases":["ADJ. deep, narrow, shallow | muddy | defensive | enemy | communication, front-line","VERB + TRENCH dig","TRENCH + NOUN warfare","PREP. in the ~ life in the trenches in the First World War"]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdetrench.mp3","us":"media/ldoce/hwd/ame/a/trench.mp3"},"examples":[{"en":"life in the trenches","cn":"第一次世界大战期间的战壕生活"},{"en":"trench warfare","cn":"堑壕战"}],"oxford":{"phon":"trentʃ","pos":"noun","senses":[{"en":"a long, deep hole dug in the ground, for example for carrying away water","cn":"沟；渠","ex":{"en":"Workmen were digging a trench beside the road.","cn":"工人们正在路边挖沟渠。"}},{"en":"a long, deep hole dug in the ground in which soldiers can be protected from enemy attacks (for example in northern France and Belgium in the First World War)","cn":"战壕，堑壕（如第一次世界大战期间在法国北部和比利时开挖的）","ex":{"en":"life in the trenches","cn":"战壕生活"}},{"en":"a long, deep, narrow hole in the ocean floor","cn":"海沟；大洋沟"}]}},"tremble":{"collins":{"senses":[{"pos":"VERB 动词","cn":"颤抖;战栗;哆嗦","en":"If you tremble, you shake slightly because you are frightened or cold.","ex":{"en":"His mouth became dry, his eyes widened, and he began to tremble all over","cn":"他嘴唇发干，眼睛圆睁，全身开始颤抖起来。"}},{"pos":"VERB 动词","cn":"颤动;摇动;摇晃","en":"If something trembles, it shakes slightly.","ex":{"en":"He felt the earth tremble under him","cn":"他感到大地在脚下颤动。"}},{"pos":"VERB 动词","cn":"(通常因难过或紧张而声音)发颤，颤抖","en":"If your voice trembles, it sounds unsteady and uncertain, usually because you are upset or nervous.","ex":{"en":"His voice trembled, on the verge of tears.","cn":"他声音颤抖，泪水在眼眶里打转。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a person or part of their body shakes, they make small sudden continuous movements from side to side or up and down, especially because they are very frightened, cold, ill etc","cn":""},{"en":"to shake for a short time, especially because you think of something very unpleasant, or because you feel frightened or cold","cn":""},{"en":"to shake slightly in a way that you cannot control, especially because you are frightened, worried, or angry","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To tremble is to quiver or shake without meaning to. Your hands probably tremble when you're nervous."}]},"collocations":{"phrases":["ADV. badly, violently | helplessly, involuntarily, uncontrollably | a little, slightly | inside","VERB + TREMBLE begin to, start to I began to tremble uncontrollably. | make sb The thought made him tremble inside.","PREP. at She trembled at the thought of going back through those prison doors. | with trembling with anger","PHRASES tremble all over, tremble from head to foot/toe, tremble like a leaf"]},"media":{"uk":"media/ldoce/hwd/bre/f/tremble0205.mp3","us":"media/ldoce/hwd/ame/9/tremble1.mp3"},"examples":[{"en":"I trembled at the thought of having to make a speech.","cn":"我一想到得发表演讲心里就发怵。"},{"en":"She tried to control the trembling in her legs.","cn":"她竭力控制住颤抖的双腿。"}],"oxford":{"phon":"ˈtrembl","pos":"verb","senses":[{"en":"to shake in a way that you cannot control, especially because you are very nervous, excited, frightened, etc.","cn":"（因紧张、激动、惊慌等）颤抖，哆嗦，抖动，战栗","g":"[intransitive]","ex":{"en":"My legs were trembling with fear.","cn":"我吓得双腿直发抖。"}},{"en":"to shake slightly","cn":"颤动；轻轻摇晃","g":"[intransitive]","ex":{"en":"leaves trembling in the breeze","cn":"在微风中摇曳的树叶"}},{"en":"to be very worried or frightened","cn":"极担心；焦虑；恐惧","g":"[intransitive]","ex":{"en":"I trembled at the thought of having to make a speech.","cn":"我一想到得发表演讲心里就发怵。"}},{"en":"a feeling, movement or sound of trembling","cn":"颤抖；战栗；哆嗦","ex":{"en":"a tremble of fear","cn":"恐惧引起的颤抖"},"pos":"noun"}]}},"trestle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(桌面等的)支架，搁凳","en":"A trestle is a wooden or metal structure that is used, for example, as one of the supports for a table. It has two pairs of sloping legs which are joined by a flat piece across the top."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an A-shaped frame used as one of the two supports for a temporary table 〔","cn":"在两侧支撑临时桌面的〕A字形支架"},{"en":"a bridge with an A-shaped frame supporting it","cn":"栈桥"}]},"vocab":{"pos":"n","senses":[{"en":"A trestle is a special kind of tower built to support a bridge."}]},"media":{"uk":"media/ldoce/hwd/bre/6/trestle0205.mp3","us":"media/ldoce/hwd/ame/6/trestle.mp3"},"oxford":{"phon":"ˈtresl","pos":"noun","senses":[{"en":"a wooden or metal structure with two pairs of sloping legs. Trestles are used in pairs to support a flat surface, for example the top of a table.","cn":"（放置桌面等成对的）支架，条凳"}]}},"transistor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"晶体管","en":"A transistor is a small electronic part in something such as a television or radio, which controls the flow of electricity."},{"pos":"N-COUNT 可数名词","cn":"晶体管收音机","en":"A transistor or a transistor radio is a small portable radio."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece of electronic equipment in radios, televisions etc that controls the flow of electricity","cn":"晶体管"},{"en":"a transistor radio","cn":"晶体管收音机"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun transistor to describe the small metal device that helps send and amplify signals in a radio. Your grandpa might carry a transistor radio around on game day."}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdetransistor.mp3","us":"media/ldoce/hwd/ame/6/transistor.mp3"},"oxford":{"phon":"trænˈzɪstə(r)","pos":"noun","senses":[{"en":"a small electronic device used in computers, radios, televisions, etc. for controlling an electric current as it passes along a circuit","cn":"晶体管"},{"en":"a small radio with transistors","cn":"晶体管收音机","lab":"informal"}]}},"tributary":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"支流","en":"A tributary is a stream or river that flows into a larger one.","ex":{"en":"...the Napo river, a tributary of the Amazon.","cn":"纳波河，亚马孙河的一条支流"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a line of water that flows into the sea","cn":""},{"en":"a stream or river that flows into a larger river 〔","cn":"河流的〕支流"},{"en":"the wide part of a river where it goes into the sea","cn":""}]},"vocab":{"pos":"1 n adj 2 adj 3 adj","senses":[{"en":"A tributary is a branch that flows into the main stream, like the White River, the Arkansas River, the Yazoo River and the Red River — each a tributary of the mighty Mississippi."}]},"collocations":{"phrases":["TRIBUTARY + VERB feed sth The Thames is fed by several small tributaries."]},"media":{"uk":"media/ldoce/hwd/bre/1/tributary0205.mp3","us":"media/ldoce/hwd/ame/f/tributary1.mp3"},"examples":[{"en":"a tributary stream","cn":"支流"}],"oxford":{"phon":"ˈtrɪbjətri","pos":"noun","senses":[{"en":"a river or stream that flows into a larger river or a lake","cn":"（流入大河或湖泊的）支流","ex":{"en":"The Thames is fed by several small tributaries.","cn":"泰晤士河由几条小支流汇合而成。"}}]}},"troll":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(斯堪的纳维亚神话中居于洞穴或山上、专门偷小孩的)丑陋怪物，山精，巨怪","en":"In Scandinavian mythology, trolls are creatures who look like ugly people. They live in caves or on mountains and steal children."},{"pos":"VERB 动词","cn":"闲逛;游荡","en":"If you troll somewhere, you go there in a casual and unhurried way.","ex":{"en":"I trolled along to see Michael Frayn's play, 'Noises Off'","cn":"我慢悠悠地走着去看迈克尔·弗莱恩的戏剧《糊涂戏班》。"}},{"pos":"VERB 动词","cn":"随便浏览;随便翻翻","en":"If you troll through papers or files, you look through them in a fairly casual way.","ex":{"en":"Trolling through the files revealed a photograph of me drinking coffee in the office.","cn":"我随便浏览文件时发现了一张我在办公室喝咖啡的照片。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an imaginary creature in stories that looks like an ugly person 〔","cn":"传说中长相丑陋的〕怪物"},{"en":"someone who leaves offensive or upsetting messages on the Internet, just in order to get a reaction “","cn":"钓鱼者”﹐引战者﹐喷子〔仅仅为了引起别人的回应而在网络上发布攻击性或令人反感的内容的人〕"},{"en":"to try to remove something from a river, ocean etc by pulling a rope, line etc through the water","cn":"拖捞﹔拖钓"}]},"vocab":{"pos":"1 n 2 v n 3 v 4 v n","senses":[{"en":"A troll is a supernatural creature who is either very big or very small, ugly, and not very nice. You're most likely to read about a troll in a fairytale — perhaps trying to trick a beautiful princess into marrying him!"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41troll.mp3","us":"media/ldoce/hwd/ame/2/troll1.mp3"},"examples":[{"en":"He trolled the Internet for advice on the disease.","cn":"他搜索互联网寻求治疗这种病的建议。"},{"en":"Both candidates have been trolling for votes.","cn":"两个候选人一直都在拉票。"}],"oxford":{"phon":"trɒl","pos":"noun","senses":[{"en":"(in Scandinavian stories) a creature that looks like an ugly person. Some trolls are very large and evil, others are small and friendly but like to trick people.","cn":"（斯堪的纳维亚传说中的）山精，巨怪，友善顽皮的侏儒"},{"en":"a message to a discussion group on the internet that somebody deliberately sends to make other people angry; a person who sends a message like this","cn":"“投饵”，恶意挑衅的帖子（在互联网讨论组张贴）；“投饵” 人；发挑衅帖子的人","lab":"informal"},{"en":"to catch fish by pulling a line with bait on it through the water behind a boat","cn":"曳绳钓（鱼）；拖钓","g":"[intransitive]","lab":"especially North American English","pos":"verb"},{"en":"to search for or try to get something","cn":"搜查；搜索；设法得到","g":"[transitive, intransitive]","lab":"informal","ex":{"en":"He trolled the internet for advice on the disease.","cn":"他搜索互联网寻求治疗这种病的建议。"},"pos":"verb"},{"en":"to write false or offensive messages on the internet in order to make other people angry","cn":"（在网络上）发表虚假或冒犯的言论（以激怒别人），发恶意挑衅的帖子","g":"[intransitive, transitive]","ex":{"en":"Someone keeps posting snide comments on the forum, trolling for a reaction.","cn":"有人不断在论坛上发表讽刺评论，希望得到回应。"},"pos":"verb"}]}},"trad":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(基于 20 世纪 20 年代爵士乐的)传统爵士乐","en":"Trad or trad jazz is a kind of jazz based on the jazz that was played in the 1920s."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a style of jazz that was popular in the 1920s. One instrument plays complicated rhythm s and notes, and the rest of the instruments play regular rhythms.","cn":"传统爵士乐〔20世纪20年代流行的一种爵士乐风格﹐由一件乐器奏出复杂的节奏和音符﹐其余乐器演奏固定节奏〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41trad.mp3","us":"media/ldoce/hwd/ame/9/ld41trad.mp3"},"oxford":{"phon":"træd","pos":"noun","senses":[{"en":"traditional jazz in the style of the 1920s, with free playing (= improvisation) against a background of fixed rhythms and combinations of notes","cn":"传统爵士乐（有 20 世纪 20 年代的风格、固定的节奏及和声，可即兴发挥）"}]}},"trumpeter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小号手;号兵;小号吹奏者","en":"A trumpeter is someone who plays a trumpet."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who plays a trumpet","cn":"小号手﹐小号吹奏者"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41trumpeter.mp3","us":"media/ldoce/hwd/ame/8/ld41trumpeter.mp3"},"oxford":{"phon":"ˈtrʌmpɪtə(r)","pos":"noun","senses":[{"en":"a person who plays the trumpet","cn":"号手；号兵；小号吹奏者"}]}},"trawl":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(在大量相似物中)搜索，搜寻","en":"If you trawl through a large number of similar things, you search through them looking for something that you want or something that is suitable for a particular purpose.","ex":{"en":"A team of officers is trawling through the records of thousands of petty thieves","cn":"一组警员正在翻查数以千计的小偷小摸者的犯罪记录。"}},{"pos":"VERB 动词","cn":"用拖网捕(鱼)","en":"When fishermen trawl for fish, they pull a wide net behind their ship in order to catch fish.","ex":{"en":"They had seen him trawling and therefore knew that there were fish","cn":"他们曾见过他用拖网捕鱼，因此知道那里有鱼。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to look for information, a document, an Internet page etc on a computer","cn":""},{"en":"to look at a lot of pages on the Internet, looking for something that interests you","cn":""},{"en":"to try to find information by looking in a book, on a list, in computer records","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdetrawl.mp3","us":"media/ldoce/hwd/ame/0/trawl1.mp3"},"examples":[{"en":"A quick trawl through the newspapers yielded five suitable job adverts.","cn":"快速翻阅一下报纸便找到五则适合的招聘广告。"},{"en":"The police are trawling through their files for similar cases.","cn":"警方正在档案中查阅类似案件。"}],"oxford":{"phon":"trɔːl","pos":"verb","senses":[{"en":"to search through a large amount of information or a large number of people, places, etc. looking for a particular thing or person","cn":"查阅（资料）；搜集，搜罗，网罗（人或物）","g":"[transitive, intransitive]","ex":{"en":"She trawled the shops for bargains.","cn":"她到各商店搜罗便宜货。"}},{"en":"to fish for something by pulling a large net with a wide opening through the water","cn":"用拖网捕鱼","g":"[intransitive]"},{"en":"a search through a large amount of information, documents, etc.","cn":"（对资料、文件等的）查阅","ex":{"en":"A quick trawl through the newspapers yielded five suitable job adverts.","cn":"快速翻阅一下报纸便找到五则适合的招聘广告。"},"pos":"noun"},{"en":"a large net with a wide opening, that is dragged along the bottom of the sea by a boat in order to catch fish","cn":"（海上捕鱼用的）拖网","pos":"noun"}]}},"tradesman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"商人;手艺人；(尤指)店主","en":"A tradesman is a person, usually a man, who sells goods or services, especially one who owns and runs a shop."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who buys and sells goods or services, especially in a shop","cn":"商人﹐买卖人﹔〔尤指商店里的〕零售商﹐店主"},{"en":"someone who works at a job or trade that involves skill with your hands","cn":"手艺人﹐工匠"},{"en":"someone who goes to people’s houses to sell or deliver goods","cn":"上门推销商﹔送货员"}]},"collocations":{"phrases":["ADJ. skilled This is a job for a skilled tradesman. | local | self-employed | respectable He got into trouble for seducing the daughter of a","PHRASES tradesmen's entrance All deliveries should be made to the tradesmen's entrance."]},"media":{"uk":"media/ldoce/hwd/bre/3/tradesman0205.mp3","us":"media/ldoce/hwd/ame/7/tradesman.mp3"},"oxford":{"phon":"ˈtreɪdzmən","pos":"noun","senses":[{"en":"a person whose job involves going to houses to sell or deliver goods","cn":"上门推销商；送货员","ex":{"en":"All deliveries should be made to the tradesmen's entrance.","cn":"送货都必须到送货员专用入口。"}},{"en":"a person who sells goods, especially in a shop","cn":"（尤指在商店里售货的）商人；店主","lab":"especially British English"},{"en":"a person who works with their hands in a job that involves training and special skills, for example a carpenter or plumber","cn":"手艺人；工匠","ex":{"en":"This is a job for a skilled tradesman.","cn":"这是娴熟的工匠才能干的活。"}}]}},"triplet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"三胞胎中的一个","en":"Triplets are three children born at the same time to the same mother."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of three children born at the same time to the same mother","cn":"三胞胎中的一个"}]},"media":{"uk":"media/ldoce/hwd/bre/7/triplet0205.mp3","us":"media/ldoce/hwd/ame/e/triplet.mp3"},"oxford":{"phon":"ˈtrɪplət","pos":"noun","senses":[{"en":"one of three children born at the same time to the same mother","cn":"三胞胎中的一个"},{"en":"a group of three equal notes to be played or sung in the time usually taken to play or sing two of the same kind","cn":"三连音","lab":"music"}]}},"trucking":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"货车运输;货车运输业","en":"Trucking is the activity of transporting goods from one place to another using trucks.","ex":{"en":"...the deregulation of the trucking industry.","cn":"解除对货运行业的管制"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the business of taking goods from place to place by road","cn":"货车运输业"}]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdetrucking.mp3","us":"media/ldoce/hwd/ame/8/trucking.mp3"},"examples":[{"en":"trucking companies","cn":"货车运输公司"}],"oxford":{"phon":"ˈtrʌkɪŋ","pos":"noun","senses":[{"en":"the activity or business of taking something somewhere by truck","cn":"货车运输（业）","ex":{"en":"trucking companies","cn":"货车运输公司"}}]},"base":"truck"},"tranquillize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(用镇静剂)使安定，使镇静，使昏睡","en":"To tranquillize a person or an animal means to make them become calm, sleepy, or unconscious by means of a drug.","ex":{"en":"This powerful drug is used to tranquilize patients undergoing surgery.","cn":"这种强效药剂被用来麻醉手术病人。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a person or animal calm or unconscious by using a drug 〔","cn":"用药物〕使镇静[昏迷]"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41tranquillize.mp3","us":"media/ldoce/hwd/ame/a/ld41tranquillize.mp3"},"oxford":{"phon":"ˈtræŋkwəlaɪz","pos":"verb","senses":[{"en":"to make a person or an animal calm or unconscious, especially by giving them a drug (= a tranquillizer)","cn":"（尤指用镇静剂）使平静，使安定","ex":{"en":"A gamekeeper tranquillized the rhinoceros with a drugged dart.","cn":"一名猎场看守人用一支麻醉飞镖使犀牛镇静下来。"}}]}},"true-blue":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(思想观念)忠于右派的，坚决支持保守党的","en":"If you describe someone as true-blue, you mean that they are right-wing in their ideas and opinions.","ex":{"en":"Her husband is a true blue Tory.","cn":"她丈夫是坚定的保守党党员。"}},{"pos":"ADJ 形容词","cn":"忠贞不渝的;坚定不移的","en":"A true-blue supporter of something is someone who is very loyal and reliable."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"believing completely in the ideas of the British Conservative Party","cn":"忠于保守党思想的"},{"en":"completely loyal to a person or idea","cn":"非常忠诚的﹐忠心耿耿的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41true-blue.mp3","us":"media/ldoce/hwd/ame/6/true-blue.mp3"},"examples":[{"en":"a true-blue Californian","cn":"典型的加利福尼亚州人"},{"en":"true-blue Tory voters","cn":"忠于保守党的投票人"}],"oxford":{"phon":"ˌtruː ˈbluː","pos":"adjective","senses":[{"en":"strongly supporting the British Conservative Party","cn":"（英国）坚决支持保守党的，忠于保守党的","lab":"British English","ex":{"en":"true-blue Tory voters","cn":"忠于保守党的投票人"}},{"en":"being a strong supporter of a particular person, group, principle, etc.; being a typical example of something","cn":"（对人、团体、原则等）忠贞不渝的，坚定不移的；典型的；有代表性的","lab":"especially North American English","ex":{"en":"a true-blue Californian","cn":"典型的加利福尼亚人"}}]}},"trade-off":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"权衡;协调;交易;交换","en":"A trade-off is a situation where you make a compromise between two things, or where you exchange all or part of one thing for another.","ex":{"en":"The newspaper's headline indicates that there was a trade-off at the summit.","cn":"报纸的大字标题表明峰会上大家作出了妥协。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a balance between two opposing things, that you are willing to accept in order to achieve something 〔","cn":"两种对立事物之间的〕平衡﹐妥协﹐协调"}]},"media":{"uk":"media/ldoce/hwd/bre/6/trade_off0205.mp3","us":"media/ldoce/hwd/ame/2/trade-off.mp3"},"examples":[{"en":"a trade-off between increased production and a reduction in quality","cn":"对产量增加和质量下降的权衡"},{"en":"There has to be a trade-off between quality and quantity if we want to keep prices low.","cn":"如果我们想要保持低价﹐就必须在质量和数量之间求得平衡。"}],"oxford":{"phon":"ˈtreɪd ɒf","pos":"noun","senses":[{"en":"the act of balancing two things that are opposed to each other","cn":"（在相互对立的两者间的）权衡，协调","ex":{"en":"a trade-off between increased production and a reduction in quality","cn":"对产量增加和质量下降的权衡"}}]}},"tripe":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（可食用的）猪肚，牛肚，百叶","en":"Tripe is the stomach of a pig, cow, or ox which is eaten as food."},{"pos":"N-UNCOUNT 不可数名词","cn":"蠢话；废话;无聊文字","en":"You refer to something that someone has said or written as tripe when you think that it is silly and worthless.","ex":{"en":"I've never heard such a load of tripe in all my life.","cn":"我一辈子还从没听到过这样一堆废话。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the stomach of a cow or pig, used as food 〔","cn":"供食用的〕牛肚﹐猪肚"},{"en":"something someone says or writes that is stupid or untrue","cn":"瞎说[瞎写]的东西﹔废话﹐蠢话"}]},"media":{"uk":"media/ldoce/hwd/bre/4/tripe0205.mp3","us":"media/ldoce/hwd/ame/b/tripe.mp3"},"examples":[{"en":"What Charles was saying was utter tripe.","cn":"查尔斯的那些话完全是胡扯。"},{"en":"tripe and onions","cn":"洋葱烧牛肚"}],"oxford":{"phon":"traɪp","pos":"noun","senses":[{"en":"the lining of a cow’s or pig’s stomach, eaten as food","cn":"食用牛肚（或猪肚）；百叶","ex":{"en":"tripe and onions","cn":"洋葱炒牛肚"}},{"en":"something that somebody says or writes that you think is silly or not true, or not of good quality","cn":"废话；胡说；拙劣的文章","lab":"old-fashioned, informal，，","ex":{"en":"What a load of tripe!","cn":"真是一堆牛肚啊！"}}]}},"treasonable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"谋反的;涉及叛国罪的","en":"Treasonable activities are criminal activities which someone carries out with the intention of helping their country's enemies or removing its government using violence.","ex":{"en":"They were brought to trial for treasonable conspiracy.","cn":"他们因密谋叛国被送上法庭。"}}]},"examples":[{"en":"a treasonable act","cn":"叛国行为"}],"oxford":{"phon":"ˈtriːzənəbl","pos":"adjective","senses":[{"en":"that can be punished as treason","cn":"叛国的","ex":{"en":"a treasonable act","cn":"叛国行为"}}]}},"travail":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"艰苦劳动;难题","en":"You can refer to unpleasant hard work or difficult problems as travail .","ex":{"en":"He did whatever he could to ease their travail.","cn":"他为减轻他们的辛劳做了力所能及的一切。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a difficult or unpleasant situation, or very tiring work","cn":"艰难的处境﹔艰苦的劳动"}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"If you’ve had to bust your behind, burn the midnight oil, and shed blood, sweat, and tears to get where you are today, you could say you’ve endured significant travail . In other words, back-breakingly hard mental exertion or physical labor."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41travail.mp3","us":"media/ldoce/hwd/ame/e/travail1.mp3"},"examples":[{"en":"the travails of last year’s water shortage","cn":"去年缺水的困境"}],"oxford":{"phon":"ˈtræveɪl","pos":"noun","senses":[{"en":"an unpleasant experience or situation that involves a lot of hard work, difficulties and/or pain","cn":"艰苦劳动；煎熬；艰辛；痛苦","ex":{"en":"the travails of life in post-war Britain","cn":"战后英国生活的艰辛"}}]}},"trump":{"collins":{"senses":[{"pos":"N-UNCOUNT-COLL 不可数集合名词","cn":"(牌戏中的)王牌，主牌","en":"In a game of cards, trumps is the suit which is chosen to have the highest value in one particular game.","ex":{"en":"Hearts are trumps.","cn":"红桃是主。"}},{"pos":"N-COUNT 可数名词","cn":"(一张)王牌，主牌","en":"In a game of cards, a trump is a playing card which belongs to the suit which has been chosen as trumps.","ex":{"en":"He played a trump.","cn":"他吊主。"}},{"pos":"VERB 动词","cn":"胜过;压过","en":"If you trump what someone has said or done, you beat it by saying or doing something else that seems better.","ex":{"en":"The Socialists tried to trump this with their slogan","cn":"社会党党员设法用他们的口号把它压过去。"}},{"pos":"PHRASE 短语","cn":"王牌;绝招;杀手锏","en":"Your trump card is something powerful that you can use or do, which gives you an advantage over someone.","ex":{"en":"In the end, the Ten took their appeal to the Supreme Court; this, they had believed from the outset, would be their trump card","cn":"最后，10 个人上诉到最高法院：他们从一开始就认为这一招是他们的王牌。"}},{"pos":"PHRASE 短语","cn":"意外地胜利;意外地成功","en":"If you say that someone came up trumps, you mean that they did something successfully, often when they were not expected to.","ex":{"en":"Dwayne has come up trumps with a goal worthy of winning any match.","cn":"德韦恩意外地蒙进了一个可以拿下任何比赛的球。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the suit (= one of the four types of cards in a set ) chosen to have a higher value than the other suits in a particular card game 〔","cn":"纸牌戏中的〕王牌花色"},{"en":"a card from the suit that has been chosen to have a higher value than the other suits in a particular game 〔","cn":"纸牌戏中的〕王牌﹐将牌"},{"en":"something that you can do or use in a situation, which gives you an advantage","cn":"王牌﹐绝招﹐杀手锏"}]},"vocab":{"pos":"1 v n 2 n v","senses":[{"en":"To trump is to outrank or defeat someone or something, often in a highly public way. Safety might trump appearance when you're buying a car, or your desires may trump your brother's when it comes to making weekend plans."}]},"collocations":{"phrases":["TRUMP + NOUN card (often figurative) Vienna's trump cards include concerts in the palaces where Mozart made music. | suit • Note at CARD"]},"media":{"uk":"media/ldoce/hwd/bre/4/trump_n0205.mp3","us":"media/ldoce/hwd/ame/7/trump1.mp3"},"examples":[{"en":"I didn't honestly think he'd pass the exam but he came up trumps on the day.","cn":"说实话我以为他考试及不了格，但是那天他发挥出色，考得不错。"},{"en":"I played a trump and won the trick.","cn":"我打出一张主牌，赢了那一墩。"}],"oxford":{"phon":"trʌmp","pos":"noun","senses":[{"en":"(in some card games) a card that belongs to the suit (= one of the four sets in a pack of cards) that has been chosen for a particular game to have a higher value than the other three suits","cn":"（某些纸牌游戏的一张）王牌，主牌，将牌","g":"[countable]","ex":{"en":"I played a trump and won the trick.","cn":"我打出一张主牌，赢了那一墩。"}},{"en":"(in some card games) the suit that has been chosen for a particular game to have a higher value than the other three suits","cn":"（某些纸牌游戏的）王牌花色，主牌花色","g":"[uncountable + singular or plural verb]","ex":{"en":"What's trumps?","cn":"王牌是什么？"}},{"en":"to play a trump card that beats somebody else’s card","cn":"出王牌赢（牌）；出王牌压掉（他人的牌）","pos":"verb"},{"en":"to beat something that somebody says or does by saying or doing something even better","cn":"赢；胜过；打败","ex":{"en":"They were trumped by another firm that made a lower bid.","cn":"他们被另一家出价较低的公司击败。"},"pos":"verb"}]}},"trike":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"儿童三轮脚踏车","en":"A trike is a child's tricycle ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tricycle 〔","cn":"尤指幼儿骑的〕三轮自行车"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41trike.mp3","us":"media/ldoce/hwd/ame/2/trike.mp3"},"oxford":{"phon":"traɪk","pos":"noun","senses":[{"en":"a tricycle (= a vehicle similar to a bicycle, but with one wheel at the front and two at the back)","cn":"三轮脚踏车"}]}},"tremor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"轻微地震;小震","en":"A tremor is a small earthquake."},{"pos":"N-COUNT 可数名词","cn":"波动;风波","en":"If an event causes a tremor in a group or organization, it threatens to make the group or organization less strong or stable.","ex":{"en":"News of 160 redundancies had sent tremors through the community","cn":"将会裁员 160 人的消息在该团体中掀起了一阵骚动。"}},{"pos":"N-COUNT 可数名词","cn":"(身体或声音不由自主的)震颤，颤抖","en":"A tremor is a shaking of your body or voice that you cannot control.","ex":{"en":"He felt a tremor in his arms","cn":"他感到胳膊不由自主地颤动。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden shaking of the Earth’s surface","cn":""},{"en":"an earthquake – used especially in journalism","cn":""},{"en":"a small movement in the Earth’s surface in which the ground shakes slightly","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A tremor is a trembling or shaking in a person or the Earth. If you're scared about speaking in public you might have a tremor in your voice — or wish that an earthquake tremor would open up the floor and swallow you first."}]},"collocations":{"phrases":["ADJ. minor, slight | severe | earth 2 shaking movement","ADJ. faint, slight, small, tiny He felt a tiny tremor of excitement as he glimpsed the city lights. | violent | uncontrollable | nervous | i","VERB + TREMOR send Her expression sent an icy tremor through him. | feel She felt a tremor run down her back when she saw him. | control He ","TREMOR + VERB run A tremor ran through the audience. | shake sb/sth An uncontrollable tremor shook his mouth.","PREP. with/without a ~ He managed to make his short speech without a tremor. | ~ of a tremor of fear"]},"media":{"uk":"media/ldoce/hwd/bre/6/tremor0205.mp3","us":"media/ldoce/hwd/ame/c/tremor.mp3"},"examples":[{"en":"There was a slight tremor in his voice.","cn":"他的声音略微有点儿颤抖。"},{"en":"an earth tremor","cn":"地动"}],"oxford":{"phon":"ˈtremə(r)","pos":"noun","senses":[{"en":"a small earthquake in which the ground shakes slightly","cn":"轻微地震；小震；微震","lab":"figurative","ex":{"en":"an earth tremor","cn":"轻微地震"}},{"en":"a slight shaking movement in a part of your body caused, for example, by cold or fear","cn":"（由于寒冷或恐惧引起的）颤抖，战栗，哆嗦","ex":{"en":"There was a slight tremor in his voice.","cn":"他的声音略微有点儿颤抖。"}}]}},"transfusion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"同 blood transfusion","en":"A transfusion is the same as a blood transfusion ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process of putting blood from one person’s body into the body of someone else as a medical treatment","cn":"输血"},{"en":"the process of giving something important or necessary, such as money, to a group or organization that needs it 〔","cn":"资金的〕投入﹐注入"}]},"vocab":{"pos":"n","senses":[{"en":"A transfusion is when doctors put blood into a patient's vein. An accident victim might need a transfusion if he's lost blood."}]},"media":{"uk":"media/ldoce/hwd/bre/d/transfusion0205.mp3","us":"media/ldoce/hwd/ame/2/transfusion.mp3"},"examples":[{"en":"The project badly needs a transfusion of cash.","cn":"这个项目急需追加现金投资。"},{"en":"to transfuse blood into a patient","cn":"给病人输血"}],"oxford":{"phon":"trænsˈfjuːʒn","pos":"noun","senses":[{"en":"the process of putting new blood into the body of a person or an animal","cn":"输血"},{"en":"the act of investing extra money in a place or an activity that needs it","cn":"追加投资；（资金的）注入","ex":{"en":"The project badly needs a transfusion of cash.","cn":"这个项目急需追加现金投资。"}}]}},"treadle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(手纺车、缝纫机的)踏板","en":"The treadle on a spinning wheel or sewing machine is a lever that you operate with your foot in order to turn a wheel in the machine."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flat piece of metal or wood that you move with your foot to turn a wheel in a machine 〔","cn":"用脚踩踏使机器轮子转动的〕踏板"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41treadle.mp3","us":"media/ldoce/hwd/ame/0/treadle.mp3"},"oxford":{"phon":"ˈtredl","pos":"noun","senses":[{"en":"(especially in the past) a device worked by the foot to operate a machine","cn":"（尤指旧时驱动机器的）踏板","ex":{"en":"a treadle sewing machine","cn":"脚踏传动缝纫机"}}]}},"trade-in":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"折价贴换交易；以旧换新交易","en":"A trade-in is an arrangement in which someone buys something such as a new car or washing machine at a reduced price by giving their old one, as well as money, in payment.","ex":{"en":"...the trade-in value of the car.","cn":"这辆车的折价贴换交易价值"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a used car, piece of equipment etc that you give to a seller of a new one that you are buying as part of the payment 〔","cn":"以旧换新的〕折价旧物"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41trade-in.mp3","us":"media/ldoce/hwd/ame/3/trade-in.mp3"},"examples":[{"en":"the trade-in value of a car","cn":"一辆汽车的以旧换新抵价"},{"en":"Do you have a trade-in?","cn":"你有折价的旧物品吗？"}],"oxford":{"phon":"ˈtreɪd ɪn","pos":"noun","senses":[{"en":"a method of buying something by giving a used item as part of the payment for a new one; the used item itself","cn":"折旧贴换交易；以旧折价换新；折价旧物","ex":{"en":"the trade-in value of a car","cn":"一辆汽车的以旧换新抵价"}}]}},"troublemaker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"闹事者;捣乱分子;(尤指）煽动作乱者","en":"If you refer to someone as a troublemaker, you mean that they cause unpleasantness, quarrels, or fights, especially by encouraging people to oppose authority.","ex":{"en":"The regional governor has been given powers to outlaw strikes and expel suspected troublemakers.","cn":"地方长官被赋予禁止罢工、驱逐嫌疑闹事者的权力。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who deliberately causes problems, especially by complaining a lot or trying to make people fight or argue","cn":""},{"en":"someone who is difficult or awkward causes a lot of problems, because they behave in an unreasonable or unhelpful way","cn":""},{"en":"someone who deliberately causes problems or arguments","cn":"惹是生非者﹐捣蛋鬼"}]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdetroublemaker.mp3","us":"media/ldoce/hwd/ame/8/troublemaker.mp3"},"examples":[{"en":"a handful of troublemakers who are damaging the club’s reputation","cn":"正在毁坏俱乐部名声的一小撮惹事者"}],"oxford":{"phon":"ˈtrʌblmeɪkə(r)","pos":"noun","senses":[{"en":"a person who often causes trouble, especially by involving others in arguments or encouraging them to complain about people in authority","cn":"麻烦制造者；搬弄是非者；捣乱者；闹事者"}]}},"transfix":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使呆住;使动弹不得","en":"If you are transfixed by something, it captures all of your interest or attention, so that you are unable to think of anything else or unable to act.","ex":{"en":"We were all transfixed by the images of the war.","cn":"战争的种种景象令我们都呆住了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to surprise, interest, frighten etc someone so much that they do not move","cn":"使〔因惊讶﹑入迷﹑害怕等而〕不能动弹﹐使呆住"},{"en":"to make a hole through something or someone with a sharp pointed weapon","cn":"刺穿﹐戳破﹔钉住"}]},"vocab":{"pos":"v","senses":[{"en":"Use the verb transfix when something makes you freeze in fascination or fear. Your belly dancing moves might transfix your dance recital audience."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41transfix.mp3","us":"media/ldoce/hwd/ame/5/transfix.mp3"},"examples":[{"en":"Luisa stood transfixed with shock.","cn":"卢萨大吃一惊，站在那里呆若木鸡。"}],"oxford":{"phon":"trænsˈfɪks","pos":"verb","senses":[{"en":"to make somebody unable to move because they are afraid, surprised, etc.","cn":"使（因恐惧、惊愕等而）动弹不得；使惊呆","ex":{"en":"Luisa stood transfixed with shock.","cn":"路易莎大吃一惊，站在那里呆若木鸡。"}}]}},"trampoline":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(作为体育器械的)蹦床","en":"A trampoline is a piece of equipment on which you jump up and down as a sport. It consists of a large piece of strong cloth held by springs in a frame."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment that you jump up and down on as a sport. It consists of a metal frame with a piece of strong cloth stretched tightly over it.","cn":"蹦床﹐弹床〔一种体育器械〕"}]},"media":{"uk":"media/ldoce/hwd/bre/1/trampoline0205.mp3","us":"media/ldoce/hwd/ame/d/ld45trampoline.mp3","img":["media/thumb/trampoline.jpg"]},"oxford":{"phon":"ˌtræmpəˈliːn","pos":"noun","senses":[{"en":"a piece of equipment that is used in gymnastics for doing jumps in the air. It consists of a sheet of strong material that is attached by springs to a frame.","cn":"蹦床，跳床，弹床（体操器械）"},{"en":"to jump on a trampoline","cn":"在蹦床上弹跳","pos":"verb"}]}},"trail":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"乡间小路;林间小道","en":"A trail is a rough path across open country or through forests.","ex":{"en":"He was following a broad trail through the trees.","cn":"他沿着林间的一条阔路行进。"}},{"pos":"N-COUNT 可数名词","cn":"（特定）路线，路径","en":"A trail is a route along a series of paths or roads, often one that has been planned and marked out for a particular purpose.","ex":{"en":"...a large area of woodland with hiking and walking trails.","cn":"间有远足与散步路线的一大片林地"}},{"pos":"N-COUNT 可数名词","cn":"（一串）痕迹，足迹，踪迹","en":"A trail is a series of marks or other signs of movement or other activities left by someone or something.","ex":{"en":"Everywhere in the house was a sticky trail of orange juice","cn":"家里到处是泼洒的橙汁留下的黏糊糊的痕迹。"}},{"pos":"VERB 动词","cn":"跟踪;追踪;追猎","en":"If you trail someone or something, you follow them secretly, often by finding the marks or signs that they have left.","ex":{"en":"Two detectives were trailing him","cn":"两个侦探正在追踪他。"}},{"pos":"N-COUNT 可数名词","cn":"(竞选)巡游路线","en":"You can refer to all the places that a politician visits in the period before an election as their campaign trail .","ex":{"en":"During a recent speech on the campaign trail, he was interrupted by hecklers.","cn":"在最近的一次竞选巡游演讲中，他被起哄者中途打断。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)拖在后面;(使)下垂;(使)曳地","en":"If you trail something or it trails, it hangs down loosely behind you as you move along.","ex":{"en":"She came down the stairs slowly, trailing the coat behind her","cn":"她慢慢走下楼梯，大衣在身后拖曳着。"}},{"pos":"VERB 动词","cn":"(常指跟着别人)拖沓行走，没精打采地走","en":"If someone trails somewhere, they move there slowly, without any energy or enthusiasm, often following someone else.","ex":{"en":"He trailed through the wet Manhattan streets","cn":"他没精打采地走过曼哈顿湿漉漉的街道。"}},{"pos":"VERB 动词","cn":"(比分)落后","en":"If a person or team in a sports match or other contest is trailing, they have a lower score than their opponents.","ex":{"en":"He scored again, leaving Dartford trailing 3-0 at the break","cn":"他又进球了，使得中场休息时达特福德队以 3: 0 落后。"}},{"pos":"PHRASE 短语","cn":"追踪;寻找","en":"If you are on the trail of a person or thing, you are trying hard to find them or find out about them.","ex":{"en":"The police were hot on his trail","cn":"警方正全力追捕他。"}},{"pos":"See also:","cn":"","en":"→see: ;"},{"pos":"","cn":"","en":"相关词组：trail off"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if someone such as a police officer tails someone, they secretly follow that person to find out where they are going or what they are doing","cn":""},{"en":"to follow close behind someone, especially in order to watch or catch them","cn":""},{"en":"to follow someone or something very closely in order to watch all their movements without them realizing that they are being followed","cn":""}]},"collocations":{"phrases":["ADV. slowly | wearily","PREP. after I trailed wearily after the others. | around/round They spent their lives trailing around the country. | (along) behind 2 have a","ADV. badly Liverpool are now trailing badly in the league.","PREP. by They were trailing by 12 points until the last few minutes of the game."]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdetrail.mp3","us":"media/ldoce/hwd/ame/7/trail1.mp3"},"examples":[{"en":"‘I only hope … ’, she trailed off. “","cn":"我只希望 … ”她的声音越来越小，最后听不到了。"},{"en":"The kids trailed around after us while we shopped for clothes.","cn":"我们在商店买衣服时，孩子们无精打采地跟在后面。"}],"oxford":{"phon":"treɪl","pos":"noun","senses":[{"en":"a long line or series of marks that is left by somebody/something","cn":"（长串的）痕迹，踪迹，足迹","ex":{"en":"a trail of blood","cn":"一连串血迹"}},{"en":"a track, sign or smell that is left behind and that can be followed, especially in hunting","cn":"（尤指打猎时跟踪的）踪迹，足迹，臭迹","ex":{"en":"The hounds were following the fox's trail.","cn":"猎犬追踪着狐狸的气味。"}},{"en":"a path through the countryside","cn":"（乡间的）小路，小径","ex":{"en":"a trail through the forest","cn":"穿过森林的小路"}},{"en":"a route that is followed for a particular purpose","cn":"（特定）路线，路径","ex":{"en":"a tourist trail (= of famous buildings)","cn":"游览路线"}},{"en":"to pull something behind somebody/something, usually along the ground; to be pulled along in this way","cn":"（被）拖，拉","g":"[transitive, intransitive]","ex":{"en":"A jeep trailing a cloud of dust was speeding in my direction.","cn":"一辆吉普车拖着一股扬尘，朝我疾驰而来。"},"pos":"verb"},{"en":"to walk slowly because you are tired or bored, especially behind somebody else; to go from one place to another without enthusiasm","cn":"（尤指跟在他人后面）疲惫地走，没精打采地慢走，磨蹭；拖着步子（去某处）","g":"[intransitive]","ex":{"en":"The kids trailed around after us while we shopped for clothes.","cn":"我们在商店买衣服时，孩子们无精打采地跟在后面。"},"pos":"verb"},{"en":"to be losing a game or other contest","cn":"（在比赛或其他竞赛中）落后，失利，失败","g":"[intransitive, transitive]","ex":{"en":"United were trailing 2–0 at half-time.","cn":"联队在上半场结束时以 0:2 落后。"},"pos":"verb"},{"en":"to follow somebody/something by looking for signs that show you where they have been","cn":"跟踪；追踪","g":"[transitive]","ex":{"en":"The police trailed Dale for days.","cn":"警方跟踪了戴尔多日。"},"pos":"verb"},{"en":"to grow or hang downwards over something or along the ground; to move downwards over something","cn":"蔓生；蔓延；向下移动","g":"[intransitive]","ex":{"en":"trailing plants","cn":"蔓生植物"},"pos":"verb"},{"en":"to advertise a film, TV programme, etc. in advance","cn":"预告，前期宣传（电影、电视节目等）","g":"[transitive]","ex":{"en":"It was trailed heavily as the Big Film of the New Year.","cn":"大量的宣传造势称之为新年大片。"},"pos":"verb"}]}},"trafficker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指毒品的)非法买卖者","en":"A trafficker in particular goods, especially drugs, is a person who illegally buys or sells these goods.","ex":{"en":"They have been arrested as suspected drug traffickers.","cn":"他们已经作为贩毒嫌疑犯被拘捕。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who buys and sells illegal goods, especially drugs","cn":"做非法买卖的人﹐〔尤指〕毒品贩子"},{"en":"someone who takes people to another country and forces them to work","cn":"人贩子"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41trafficker.mp3","us":"media/ldoce/hwd/ame/3/trafficker.mp3"},"examples":[{"en":"a drugs trafficker","cn":"毒品贩子"}],"oxford":{"phon":"ˈtræfɪkə(r)","pos":"noun","senses":[{"en":"a person who buys and sells something illegally","cn":"（非法）进行…交易，做…买卖","ex":{"en":"a drugs trafficker","cn":"毒贩"}}]}},"tribalism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"部落制度;部族制度","en":"Tribalism is the state of existing as a tribe.","ex":{"en":"Apartheid used tribalism as the basis of its 'divide-and-rule' homeland policies.","cn":"南非种族隔离制将部落制度作为其对国土“分而治之”的政策基础。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"集团意识;部落意识;宗族主义","en":"You can use tribalism to refer to the loyalties that people feel towards particular social groups and to the way these loyalties affect their behaviour and their attitudes towards others.","ex":{"en":"His argument was that multi-party systems encourage tribalism.","cn":"他的论点是多党制会助长集团主义。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"behaviour and attitudes that are based on strong loyalty to your tribe","cn":"部落意识[习性]"},{"en":"the state of being organized into tribes","cn":"部落制度"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41tribalism.mp3","us":"media/ldoce/hwd/ame/b/tribalism.mp3"},"oxford":{"phon":"ˈtraɪbəlɪzəm","pos":"noun","senses":[{"en":"behaviour, attitudes, etc. that are based on supporting and being loyal to a tribe or other social group","cn":"部落习性；种族意识；部落主义"},{"en":"the state of being organized in a tribe or tribes","cn":"部落制度"}]}},"trio":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"三人组合;（尤指）三重唱;三个一组;三件一套","en":"A trio is a group of three people together, especially musicians or singers, or a group of three things that have something in common.","ex":{"en":"…classy American songs from a Texas trio…","cn":"由来自得克萨斯三人组合演唱的动听美国歌曲"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of three people or things","cn":"三人一组﹔三件一套"},{"en":"a piece of music for three performers","cn":"三重唱（曲）﹔三重奏（曲）"}]},"vocab":{"pos":"n","senses":[{"en":"Whether it’s birds, opera singers, aces, or golfers, you can use the word trio to refer to anything made up of three."}]},"media":{"uk":"media/ldoce/hwd/bre/9/trio0205.mp3","us":"media/ldoce/hwd/ame/8/trio.mp3"},"examples":[{"en":"a trio for piano, oboe and bassoon","cn":"钢琴、双簧管及大管三重奏"},{"en":"He was met by a trio of smiling executives.","cn":"迎接他的是三位面带笑容的主管。"}],"oxford":{"phon":"ˈtriːəʊ","pos":"noun","senses":[{"en":"a group of three people or things","cn":"三人小组；三件一套；三合一","g":"[countable + singular or plural verb]","ex":{"en":"A trio of English runners featured in the women’s 1 500 metres.","cn":"三名英国跑步选手在女子 1 500 米比赛中大放异彩。"}},{"en":"a group of three musicians or singers who play or sing together","cn":"三重奏乐团；三重唱组合","g":"[countable + singular or plural verb]"},{"en":"a piece of music for three musicians or singers","cn":"三重奏（曲）；三重唱（曲）","g":"[countable]","ex":{"en":"a trio for piano, oboe and bassoon","cn":"钢琴、双簧管及大管三重奏"}}]}},"tricolour":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"三色旗","en":"A tricolour is a flag which is made up of blocks of three different colours."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flag with three equal bands of different colours, especially the national flags of France or Ireland","cn":"三色旗〔有三条相同宽度色带的旗帜﹐尤指法国或爱尔兰国旗〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41tricolour.mp3","us":"media/ldoce/hwd/ame/2/ld41tricolour.mp3"},"oxford":{"phon":"ˈtrɪkələ(r)","pos":"noun","senses":[{"en":"a flag that has three bands of different colours, especially the French and Irish national flags","cn":"三色旗（尤指法国和爱尔兰的国旗）"}]}},"treachery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"背叛;变节;背信弃义","en":"Treachery is behaviour or an action in which someone betrays their country or betrays a person who trusts them.","ex":{"en":"He was deeply wounded by the treachery of close aides and old friends.","cn":"他因贴身助手和老朋友的背叛而深受伤害。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to be disloyal to your friends or to someone who trusts you, often causing serious harm to them as a result","cn":""},{"en":"to betray someone who trusts you, especially someone that you work with, by saying or doing something that will cause them a lot of harm and get you an advantage","cn":""},{"en":"to betray a group of people who trusted you to help them, in order to gain money or power for yourself","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Treachery is trickery, cheating, and deceit, like the treachery of your former friend who only stuck around until he stole your girlfriend and turned the whole grade against you."}]},"media":{"uk":"media/ldoce/hwd/bre/2/treachery0205.mp3","us":"media/ldoce/hwd/ame/1/treachery.mp3"},"examples":[{"en":"an act of treachery","cn":"背叛行为"},{"en":"the treachery of those who plotted against the king","cn":"密谋反对国王者的不忠行为"}],"oxford":{"phon":"ˈtretʃəri","pos":"noun","senses":[{"en":"behaviour that involves hurting somebody who trusts you, for example by telling their secrets to other people; an example of this","cn":"背叛；变节；背信弃义","ex":{"en":"an act of treachery","cn":"背叛行为"}}]}},"trachea":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"气管","en":"Your trachea is your windpipe ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the tube that takes air from your throat to your lungs","cn":"气管"}]},"vocab":{"pos":"n","senses":[{"en":"Trachea is another name for windpipe, which is the tube that connects your larynx to your primary bronchi, just before your lungs. You can't breathe without your trachea ."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41trachea.mp3","us":"media/ldoce/hwd/ame/e/trachea.mp3"},"oxford":{"phon":"trəˈkiːə","pos":"noun","senses":[{"en":"the tube in the body that carries air from the throat to the lungs","cn":"气管"}]}},"transference":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"转移;迁移;转存","en":"The transference of something such as power, information, or affection from one person or place to another is the action of transferring it.","ex":{"en":"It is a struggle for a transference of power","cn":"那是为权力移交进行的斗争。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process of moving someone or something from one place, position, job etc to another","cn":"调任﹐调职﹔转移﹔转让"},{"en":"the process of beginning to have the same unconscious feelings about someone in the present that you had for someone such as your parents in the past","cn":"移情"}]},"vocab":{"pos":"n","senses":[{"en":"Transference occurs when something carries over from one thing to another, like the transference of data between computers."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41transference.mp3","us":"media/ldoce/hwd/ame/b/transference.mp3"},"examples":[{"en":"the transference of heat from the liquid to the container","cn":"热量从液体到容器的传导"},{"en":"the transference of skills acquired at school to the workplace","cn":"将从学校学来的技能应用于职场"}],"oxford":{"phon":"ˈtrænsfərəns","pos":"noun","senses":[{"en":"the process of moving something from one place, person or use to another","cn":"转移；转递；调动；转让","ex":{"en":"the transference of heat from the liquid to the container","cn":"热量从液体到容器的传导"}}]}},"tradeoff":{"lemma":"trade-off"},"truncheon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"警棍","en":"A truncheon is a short, thick stick that is carried as a weapon by a policeman."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short thick stick that police officers carry as a weapon","cn":"警棍"}]},"vocab":{"pos":"n","senses":[{"en":"A truncheon is a short, thick club, mainly used by police officers. If you find yourself face-to-face with a truncheon , you better behave."}]},"collocations":{"phrases":["ADJ. rubber","VERB + TRUNCHEON be armed with, carry | draw | beat sb with Some of the prisoners were beaten about the head with rubber truncheons."]},"media":{"uk":"media/ldoce/hwd/bre/7/truncheon0205.mp3","us":"media/ldoce/hwd/ame/7/truncheon.mp3"},"oxford":{"phon":"ˈtrʌntʃən","pos":"noun","senses":[{"en":"a short thick stick that police officers carry as a weapon","cn":"警棍","ex":{"en":"Some of the prisoners were beaten about the head with rubber truncheons.","cn":"一些囚犯头部遭到橡皮警棍的击打。"}}]}},"trackball":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(旋动以移动光标的)跟踪球，轨迹球，光标运行球","en":"A trackball is a ball on some computers that you turn in order to move the cursor."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small ball connected to a computer, that you turn in order to move the cursor","cn":"跟踪球﹐轨迹球〔一种与计算机连接﹑用来控制光标移动的小球〕"}]},"media":{"uk":"media/ldoce/hwd/bre/7/trackball0205.mp3","us":"media/ldoce/hwd/ame/4/laadtrackball.mp3"},"oxford":{"phon":"ˈtrækbɔːl","pos":"noun","senses":[{"en":"a device containing a ball that is used instead of a mouse to move the cursor around the screen","cn":"跟踪球；光标运动球；轨迹球"}]}},"traumatize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使受精神创伤;使惊吓过度;使痛苦","en":"If someone is traumatized by an event or situation, it shocks or upsets them very much, and may cause them psychological damage.","ex":{"en":"My wife was traumatized by the experience","cn":"那次经历给我我妻子造成了精神创伤。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"extremely shocked by something very unpleasant or frightening that has happened","cn":""},{"en":"very shocked by something that is very bad or unpleasant","cn":""},{"en":"so shocked and upset by something terrible that has happened that you cannot continue with your life","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41traumatize.mp3","us":"media/ldoce/hwd/ame/6/traumatize.mp3"},"examples":[{"en":"He was traumatized by his war experiences.","cn":"战争经历使他的精神受到了创伤。"}],"oxford":{"phon":"ˈtrɔːmətaɪz","pos":"verb","senses":[{"en":"to shock and upset somebody very much, often making them unable to think normally or continue with their normal life","cn":"使受精神创伤","ex":{"en":"He was so traumatized by the attack that he could not work for a year.","cn":"这次袭击给他造成了严重的创伤，导致他一年无法工作。"}}]}},"traitorous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"谋叛的;背叛的;卖国的","en":"A traitorous action will betray or bring danger to a country or to the group of people that someone belongs to.","ex":{"en":"...the monstrous betrayal of men by their most traitorous companions.","cn":"最为背信弃义的同伴对他们令人发指的出卖"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not loyal to your country, friends, or beliefs","cn":"卖国的﹔叛变的﹐背叛的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you can't be trusted to keep your best friend's terrible secret, she's going to start thinking of you as traitorous , or completely unfaithful and unreliable."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41traitorous.mp3","us":"media/ldoce/hwd/ame/4/traitorous.mp3"},"oxford":{"phon":"ˈtreɪtərəs","pos":"adjective","senses":[{"en":"betraying your friends, your country, etc. by giving away secrets about them, by lying to or about them or by doing other things that will harm them","cn":"背叛的；叛国的；卖国的","ex":{"en":"traitorous behaviour","cn":"背叛行为"}}]}},"troops":{"lemma":"troop"},"trendy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"时髦的;时尚的;现代的","en":"If you say that something or someone is trendy, you mean that they are very fashionable and modern.","ex":{"en":"...a trendy London night club.","cn":"时髦的伦敦夜总会"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"赶时髦的;盲从的","en":"If you describe someone who follows new ideas as trendy, you disapprove of them because they are more interested in being fashionable than in thinking seriously about these ideas.","ex":{"en":"Trendy teachers are denying children the opportunity to study classic texts.","cn":"赶时髦的教师正在剥夺孩子学习经典课本的机会。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"popular at a particular time","cn":""},{"en":"modern and fashionable – often used in a slightly disapproving or joking way","cn":""},{"en":"fashionable and well-designed in an attractive way","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Trendy describes something that's stylish or popular, like skinny jeans or fancy coffee drinks."}]},"media":{"uk":"media/ldoce/hwd/bre/d/trendy_adj0205.mp3","us":"media/ldoce/hwd/ame/4/trendy.mp3"},"examples":[{"en":"young trendies from art college","cn":"艺术院校时髦的年轻人"},{"en":"trendy clothes","cn":"时髦的衣服"}],"oxford":{"phon":"ˈtrendi","pos":"adjective","senses":[{"en":"very fashionable","cn":"时髦的；流行的","ex":{"en":"trendy clothes","cn":"时髦的衣服"}},{"en":"a trendy person","cn":"爱时髦的人；赶时髦的人","ex":{"en":"young trendies from art college","cn":"艺术院校时髦的年轻人"},"pos":"noun"}]}},"trepidation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"惊恐;惶恐;焦虑;不安","en":"Trepidation is fear or anxiety about something that you are going to do or experience.","ex":{"en":"It was with some trepidation that I viewed the prospect of cycling across Uganda.","cn":"我带着些许惶恐考虑了一下骑自行车周游乌干达的可能性。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling of anxiety or fear about something that is going to happen","cn":"惊恐﹐惊惶﹐不安"}]},"vocab":{"pos":"n","senses":[{"en":"When plain old \"fear\" isn't enough to get across a deep feeling of dread about something on the horizon, use the more formal word trepidation ."}]},"media":{"uk":"media/ldoce/hwd/bre/2/trepidation0205.mp3","us":"media/ldoce/hwd/ame/0/trepidation.mp3"},"examples":[{"en":"With some trepidation , I opened the door.","cn":"我有些惴惴不安地打开了门。"}],"oxford":{"phon":"ˌtrepɪˈdeɪʃn","pos":"noun","senses":[{"en":"great worry or fear about something unpleasant that may happen","cn":"惊恐；恐惧；惊惶；不安","ex":{"en":"He knocked on the door with some trepidation.","cn":"他有些忐忑地敲了敲门。"}}]}},"tribesman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"部落男性成员","en":"A tribesman is a man who belongs to a tribe."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man who is a member of a tribe","cn":"男性部落成员"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41tribesman.mp3","us":"media/ldoce/hwd/ame/7/tribesman.mp3"},"oxford":{"phon":"ˈtraɪbzmən","pos":"noun","senses":[{"en":"a male member of a tribe","cn":"部落成员"}]}},"traction":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"牵引(术);牵引治疗","en":"Traction is a form of medical treatment, in which weights and pulleys are used to gently pull or stretch an injured part of the body for a period of time. You say that a person who is having this treatment is in traction .","ex":{"en":"Is there an alternative to traction for a broken leg?…","cn":"对于腿部骨折有什么方法替代牵引治疗吗？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(对车辆的)牵引力，拉力","en":"Traction is a particular form of power that makes a vehicle move."},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指车轮对地面的)附着摩擦力","en":"Traction is the grip that something has on the ground, especially the wheels of a vehicle."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process of treating a broken bone with special medical equipment that pulls it 〔","cn":"治疗骨折的〕牵引术"},{"en":"the force that prevents something such as a wheel sliding on a surface 〔","cn":"防止车轮在路面滑动的〕附着摩擦力"},{"en":"the type of power needed to make a vehicle move, or to pull a heavy load 〔","cn":"使汽车或重物等移动的〕牵引力"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"In medicine, traction is the act of pulling on bones or limbs in a certain way to help with healing. An arm in traction is temporarily tied up, but it is probably on the mend."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41traction.mp3","us":"media/ldoce/hwd/ame/c/ld44traction.mp3"},"examples":[{"en":"He spent six weeks in traction after he broke his leg.","cn":"他腿部骨折后做了六个星期的牵引治疗。"},{"en":"He was in traction (= receiving this kind of treatment ) for weeks after the accident.","cn":"事故后他接受了几个星期的牵引治疗。"}],"oxford":{"phon":"ˈtrækʃn","pos":"noun","senses":[{"en":"the action of pulling something along a surface; the power that is used for doing this","cn":"牵引；拖拉；牵引力；拉力"},{"en":"a way of treating a broken bone in your body that involves using special equipment to pull the bone gradually back into its correct place","cn":"牵引（使体内断骨复位的疗法）","ex":{"en":"He spent six weeks in traction after he broke his leg.","cn":"他腿部骨折后做了六个星期的牵引治疗。"}},{"en":"the force that stops something, for example the wheels of a vehicle, from sliding on the ground","cn":"（车轮等对地面的）附着摩擦力"},{"en":"the extent to which an idea, a product, etc. becomes popular or gains support","cn":"受欢迎（或得到支持）的程度","ex":{"en":"The president's message is gaining traction among undecided voters.","cn":"总统的观点在犹豫不决的选民中越来越受欢迎。"}}]}},"tremulous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(声音或动作)震颤的，颤抖的，打战的；（笑容）怯生生的，不自然的","en":"If someone's voice, smile, or actions are tremulous, they are unsteady because the person is uncertain, afraid, or upset.","ex":{"en":"She fidgeted in her chair as she took a deep, tremulous breath.","cn":"她在椅子上坐立不安，轻颤着深吸了一口气。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"shaking slightly, especially because you are nervous 〔","cn":"尤指因紧张而〕颤抖的﹐微微发抖的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something tremulous is shaky and quivering, usually from fear or lack of strength. If you're nervous at your first big job interview, your hands might be a little tremulous ."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41tremulous.mp3","us":"media/ldoce/hwd/ame/f/tremulous.mp3"},"examples":[{"en":"He was in a state of tremulous excitement.","cn":"他激动得直发抖。"},{"en":"a tremulous voice","cn":"颤抖的声音"}],"oxford":{"phon":"ˈtremjələs","pos":"adjective","senses":[{"en":"shaking slightly because you are nervous; causing you to shake slightly","cn":"（因紧张）颤抖的，战栗的；使打战的；使颤动的","ex":{"en":"a tremulous voice","cn":"颤抖的声音"}}]}},"transcend":{"collins":{"senses":[{"pos":"VERB 动词","cn":"超越;超出","en":"Something that transcends normal limits or boundaries goes beyond them, because it is more significant than them.","ex":{"en":"...issues like European union that transcend party loyalty.","cn":"诸如欧洲结盟这样超越党派忠诚的议题"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go beyond the usual limits of something","cn":"超越﹐超过﹐超出"}]},"vocab":{"pos":"v","senses":[{"en":"It would be nice to transcend the narrow limits of this brief definition, and go to greater lengths to describe this word's glories! Transcend means to move upward and beyond something."}]},"media":{"uk":"media/ldoce/hwd/bre/6/transcend0205.mp3","us":"media/ldoce/hwd/ame/c/transcend.mp3"},"examples":[{"en":"The desire for peace transcended political differences.","cn":"对和平的渴望超越了政治分歧。"}],"oxford":{"phon":"trænˈsend","pos":"verb","senses":[{"en":"to be or go beyond the usual limits of something","cn":"超出，超越（通常的界限）","ex":{"en":"His works by far transcend anything that has gone before.","cn":"他的作品远远超越了以往的任何作品。"}}]}},"triage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(事故、战斗等之后迅速查看伤者以决定哪些人应优先治疗的)伤病员鉴别分类，治疗类选法","en":"Triage is the process of quickly examining sick or injured people, for example after an accident or a battle, so that those who are in the most serious condition can be treated first.","ex":{"en":"...the triage process.","cn":"伤病员鉴别分类过程"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the method of deciding who receives medical treatment first, according to how seriously someone is injured","cn":"急救分类﹐伤员分类〔按伤者的伤势决定治疗的次序〕"}]},"vocab":{"pos":"n","senses":[{"en":"Grouping patients based on the severity of their injuries and the likelihood of their survival is called triage . In a triage situation, urgent cases are seen by doctors first, and non-life-threatening emergencies go last."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41triage.mp3","us":"media/ldoce/hwd/ame/a/laadtriage.mp3"},"oxford":{"phon":"ˈtriːɑːʒ","pos":"noun","senses":[{"en":"the process of deciding how seriously ill or injured a person is, so that the most serious cases can be treated first","cn":"分诊；患者鉴别分类；伤员鉴别分类"}]}},"trailer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拖车;挂车","en":"A trailer is a container on wheels which is pulled by a car or other vehicle and which is used for transporting large or heavy items."},{"pos":"N-COUNT 可数名词","cn":"(卡车或货车的)载货挂车","en":"A trailer is the long rear section of a lorry or truck, in which the goods are carried."},{"pos":"N-COUNT 可数名词","cn":"拖车式活动房屋(或工作室)","en":"A trailer is a long vehicle without an engine which people use as a home or as an office and which can be pulled behind a car."},{"pos":"N-COUNT 可数名词","cn":"(电影或电视节目的)预告片","en":"A trailer for a film or television programme is a set of short extracts which are shown to advertise it.","ex":{"en":"…a misleadingly violent trailer for the film.","cn":"让人误以为充满暴力色彩的该部影片的预告片"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an advertisement","cn":""},{"en":"an advertisement","cn":""},{"en":"an advertisement on television or radio","cn":""}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"A trailer is a wheeled vehicle that can't move on its own — it needs to be pulled by a car, truck, or other vehicle. Some bike-riding parents tow their small children behind them in bicycle trailers ."}]},"collocations":{"phrases":["ADJ. lorry | horse","VERB + TRAILER load | pull, tow","TRAILER + VERB carry sth a trailer carrying a motor boat","PREP. on/onto a/the ~ a broken-down car on a trailer","PHRASES a tractor and trailer"]},"media":{"img":["media/ldoce/img/trailer.jpg"],"uk":"media/ldoce/hwd/bre/6/brelasdetrailer.mp3","us":"media/ldoce/hwd/ame/c/trailer.mp3"},"examples":[{"en":"a car towing a trailer with a boat on it","cn":"拖着一辆载有小船的拖车的小汽车"},{"en":"a trailer park (= an area where trailers are parked and used as homes)","cn":"拖车式活动房屋停车场"}],"oxford":{"phon":"ˈtreɪlə(r)","pos":"noun","senses":[{"en":"a truck, or a container with wheels, that is pulled by another vehicle","cn":"拖车；挂车","ex":{"en":"a car towing a trailer with a boat on it","cn":"拖着一辆载有小船的拖车的小汽车"}},{"en":"a vehicle without an engine, that can be pulled by a car or truck or used as a home or an office when it is parked","cn":"（拖车式）活动房屋，活动工作室","lab":"North American English","ex":{"en":"a trailer park (= an area where trailers are parked and used as homes)","cn":"拖车式活动房屋停车场"}},{"en":"a small building for people to live in that is made in a factory and moved to a permanent place","cn":"活动住房","lab":"North American English"},{"en":"a series of short scenes from a film or television programme, shown in advance to advertise it","cn":"（电影或电视节目的）预告片","lab":"especially British English","ex":{"en":"He featured in the trailer for the movie.","cn":"他主演了这部电影的预告片。"}}]}},"troubleshooter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（公司或政府的）处理重大问题的人，解决难题的人","en":"A troubleshooter is a person whose job is to solve major problems or difficulties that occur in a company or government."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an independent person who is employed to come into an organization to deal with serious problems 〔","cn":"机构雇用的〕处理难题的人"},{"en":"computer software which asks you a series of questions to try to find the cause of a computer problem, and suggests possible solutions 〔","cn":"计算机的〕故障查找软件"}]},"vocab":{"pos":"n","senses":[{"en":"A troubleshooter is a person who fixes things or solves problems after zeroing in on their sources. When your car refuses to start, you may need to pay a mechanic to act as a troubleshooter ."}]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdetroubleshooter.mp3","us":"media/ldoce/hwd/ame/c/troubleshooter.mp3"},"oxford":{"phon":"ˈtrʌblʃuːtə(r)","pos":"noun","senses":[{"en":"a person who helps to solve problems in a company or an organization","cn":"（公司或机构中）解决困难者"}]}},"tractable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"驯服的;温顺的;易驾驭的;易处理的","en":"If you say that a person, problem, or device is tractable, you mean that they can be easily controlled or dealt with.","ex":{"en":"He could easily manage his tractable and worshipping younger brother.","cn":"他能轻而易举地管住听话并且崇拜自己的弟弟。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"easy to control or deal with","cn":"易控制的﹔易处理的"}]},"vocab":{"pos":"adj","senses":[{"en":"If your little brother quietly obeys your instructions and waits for you at the food court while you and your friends wander around the mall, he's probably a tractable child, meaning he's obedient, flexible, and responds well to directions."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41tractable.mp3","us":"media/ldoce/hwd/ame/5/tractable.mp3"},"examples":[{"en":"The issues have proved to be less tractable than expected.","cn":"结果这些问题比预想的要难以处理。"}],"oxford":{"phon":"ˈtræktəbl","pos":"adjective","senses":[{"en":"easy to deal with or control","cn":"易处理的；易驾驭的","ex":{"en":"This approach helps to make the issues more tractable.","cn":"这种方法有助于使问题更容易处理。"}}]}},"transmute":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)变形;(使)变化","en":"If something transmutes or is transmuted into a different form, it is changed into that form.","ex":{"en":"She ceased to think, as anger transmuted into passion","cn":"当怒火转化为激情，她停止了思考。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change one substance or type of thing into another","cn":"使变化﹐改变"}]},"vocab":{"pos":"v","senses":[{"en":"Transmute is a verb meaning to change in appearance or form. For example, magical creatures can transmute into other beings. When you slay a dragon, don’t be surprised if changes into a small, winged insect."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41transmute.mp3","us":"media/ldoce/hwd/ame/1/transmute.mp3"},"examples":[{"en":"It was once thought that lead could be transmuted into gold.","cn":"有人曾经认为铅可以变成黄金。"}],"oxford":{"phon":"trænzˈmjuːt","pos":"verb","senses":[{"en":"to change, or make something change, into something different","cn":"（使）变化，变质，变形","ex":{"en":"It was once thought that lead could be transmuted into gold.","cn":"有人曾经认为铅可以变成黄金。"}}]}},"truant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"逃学者;旷课者","en":"A truant is a pupil who stays away from school without permission."},{"pos":"VERB 动词","cn":"逃学;旷课","en":"If a pupil truants, he or she stays away from school without permission.","ex":{"en":"In his fourth year he was truanting regularly.","cn":"上四年级时，他频频旷课。"}},{"pos":"PHRASE 短语","cn":"逃学;旷课","en":"If a pupil plays truant, he or she stays away from school without permission.","ex":{"en":"She was getting into trouble over playing truant from school.","cn":"她因逃课而惹了麻烦。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to deliberately not go to school, work etc, when you should be there","cn":""},{"en":"if a child plays truant or plays hooky from school, they deliberately stay away from school without their parent's permission","cn":""},{"en":"if a student cuts classes, school etc, they deliberately do not go to the classes that they should go to","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A truant is a student who is out of school without permission. If you skip school to go shopping with your friends, you are a truant ."}]},"collocations":{"phrases":["ADJ. persistent | school","VERB + TRUANT play She often played truant and wrote her own sick notes.","TRUANT + NOUN officer"]},"media":{"uk":"media/ldoce/hwd/bre/e/truant0205.mp3","us":"media/ldoce/hwd/ame/6/truant.mp3"},"examples":[{"en":"A number of pupils have been truanting regularly.","cn":"不少小学生一直经常旷课。"},{"en":"persistent truants","cn":"老是逃学的学生"}],"oxford":{"phon":"ˈtruːənt","pos":"verb","senses":[{"en":"to stay away from school without permission","cn":"旷课；逃学","ex":{"en":"A number of pupils have been truanting regularly.","cn":"一些小学生经常逃学。"}},{"en":"a child who stays away from school without permission","cn":"旷课的小学生","pos":"noun"}]}},"trouser":{"collins":{"senses":[{"pos":"VERB 动词","cn":"捞取，得到(不义之财)","en":"If you say that someone trousers a sum of money, you mean that they receive it, usually when they do not deserve it or should not take it.","ex":{"en":"Many people think that ex-ministers are trousering £25,000 in fees simply for going to a few board meetings a year.","cn":"很多人认为前任部长们一年仅参加几次理事会就轻而易举地捞取了 25,000 英镑的报酬。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get a large amount of money – used to show disapproval","cn":"获得〔一大笔钱﹔含贬义〕"},{"en":"to make things happen or make people behave in the way that you want, by using your authority, skill, money etc","cn":""},{"en":"the ability or power to make things happen or make people behave in the way that you want","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld42trouser.mp3","us":"media/ldoce/hwd/ame/a/ld42trouser.mp3"},"examples":[{"en":"Even though he has in effect been sacked, he will trouser a £150,000 bonus.","cn":"尽管实际上已经被解雇﹐他仍能捞到15万英镑的奖金。"},{"en":"His trousers were slightly too short.","cn":""}],"oxford":{"phon":"ˈtraʊzə(r)","pos":"adjective","senses":[{"en":"used to describe part of a pair of trousers or a set of clothes that includes trousers","cn":"裤子的","ex":{"en":"trouser pockets","cn":"裤兜"}},{"en":"to take or earn an amount of money","cn":"收受；赚得","ex":{"en":"They can expect to trouser close to £35m from TV revenue alone.","cn":"他们预计仅通过电视收入就能获得近 3500 万英镑的收入。"},"pos":"verb"}]}},"transfigure":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(使)改容换貌;(使)容光焕发;美化","en":"To be transfigured means to be changed into something great or beautiful.","ex":{"en":"They are transfigured by the healing powers of art","cn":"他们因艺术的治疗效力而面貌一新。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change the way someone or something looks, especially so that they become more beautiful","cn":"使改观﹔美化"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41transfigure.mp3","us":"media/ldoce/hwd/ame/7/transfigure.mp3"},"examples":[{"en":"Her face was transfigured with joy.","cn":"她高兴得容光焕发。"}],"oxford":{"phon":"trænsˈfɪɡə(r)","pos":"verb","senses":[{"en":"to change the appearance of a person or thing so that they look more beautiful","cn":"使改观；美化…的外表","ex":{"en":"Ann’s whole face was transfigured by the early morning light.","cn":"安的整张脸都被清晨的阳光美化了。"}}]}},"transpiration":{"collins":{"senses":[{"pos":"","cn":"蒸腾作用","en":"Transpiration is the evaporation of water from a plant's leaves, stem, or flowers.","ex":{"en":"Plants release water through their leaves by transpiration.","cn":"植物通过蒸腾作用从叶片中释放水分。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process of passing water through the surface of a plant’s leaves","cn":"蒸腾（作用）"}]},"vocab":{"pos":"n","senses":[{"en":"Plants breathe through their stomata, little openings that allow transpiration , which is the outward passage of water vapor along with carbon dioxide. This vapor then evaporates into the air as part of the process of photosynthesis."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41transpiration.mp3","us":"media/ldoce/hwd/ame/1/transpiration.mp3"},"oxford":{"phon":"ˌtrænspɪˈreɪʃn","pos":"noun","senses":[{"en":"the process of water passing out from the surface of a plant or leaf","cn":"蒸腾（水分通过植物体表或叶子散失的过程）"}]}},"trainee":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"受培训者;实习生","en":"A trainee is someone who is employed at a low level in a particular job in order to learn the skills needed for that job.","ex":{"en":"He is a 24-year-old trainee reporter","cn":"他 24 岁，是一名实习记者。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is studying at a school, college, or university","cn":""},{"en":"someone who is learning a skill while working in a company or organization","cn":""},{"en":"someone who has recently started to learn something","cn":""}]},"collocations":{"phrases":["ADJ. management, teacher | graduate Many companies recruit graduate trainees to train as managers.","VERB + TRAINEE employ, recruit, take on","TRAINEE + VERB work","TRAINEE + NOUN accountant, dealer, manager, nurse, solicitor, teacher","PREP. as a ~ She joined as a management trainee."]},"media":{"uk":"media/ldoce/hwd/bre/d/trainee0205.mp3","us":"media/ldoce/hwd/ame/6/trainee.mp3"},"examples":[{"en":"a management trainee","cn":"管理培训生"},{"en":"a trainee teacher","cn":"实习教师"}],"oxford":{"phon":"ˌtreɪˈniː","pos":"noun","senses":[{"en":"a person who is being taught how to do a particular job","cn":"接受培训者；实习生；见习生","lab":"British English","ex":{"en":"a management trainee","cn":"管理培训生"}}]}},"trundle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(车辆)缓缓行进，艰难移动，曲折开进","en":"If a vehicle trundles somewhere, it moves there slowly, often with difficulty or an irregular movement.","ex":{"en":"The truck was trundling along the escarpment of the Zambesi valley…","cn":"卡车沿着赞比西山谷的绝壁缓缓行进。"}},{"pos":"VERB 动词","cn":"慢慢移动，缓慢滚动(尤指带轮的小体积重物)","en":"If you trundle something somewhere, especially a small, heavy object with wheels, you move or roll it along slowly.","ex":{"en":"The old man lifted the barrow and trundled it away","cn":"那个老头提起手推车，慢慢推走了。"}},{"pos":"VERB 动词","cn":"慢步走;迈着沉重的脚步走","en":"If you say that someone is trundling somewhere, you mean that they are walking slowly, often in a tired way or with heavy steps.","ex":{"en":"Girls trundle in carrying heavy book bags.","cn":"背着沉重书包的女孩们慢慢走进来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to push something with wheels while holding it with your hands","cn":""},{"en":"to push a round object along so that it turns over and over and moves forward","cn":""},{"en":"to push something heavy that has wheels, slowly and with difficulty","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/trundle0205.mp3","us":"media/ldoce/hwd/ame/d/trundle.mp3"},"examples":[{"en":"A long list of reasons was trundled out to justify their demands.","cn":"他们重复一大串理由，说明他们的要求正当。"},{"en":"A train trundled across the bridge.","cn":"一列火车隆隆驶过大桥。"}],"oxford":{"phon":"ˈtrʌndl","pos":"verb","senses":[{"en":"to move or roll somewhere slowly and noisily; to move something with wheels slowly and noisily, especially something heavy","cn":"（使缓慢、轰鸣地）移动，滚动","g":"[intransitive, transitive]","ex":{"en":"A train trundled across the bridge.","cn":"一列火车隆隆驶过大桥。"}},{"en":"to walk slowly with heavy steps","cn":"沉重缓慢地走","g":"[intransitive]"}]}},"trustee":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(财产)受托人，托管人","en":"A trustee is someone with legal control of money or property that is kept or invested for another person, company, or organization."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has control of money or property that is in a trust for someone else 〔","cn":"金钱或财产的〕受托人"},{"en":"a member of a group that controls the money of a company, college, or other organization 〔","cn":"公司﹑学院或其他机构的〕理事﹐董事"}]},"collocations":{"phrases":["ADJ. joint They act as joint trustees of the fund. | sole | independent | public | professional","VERB + TRUSTEE act as, be, serve as | appoint, appoint sb (as) | remove (sb as) | resign as","PREP. ~ for They hold the land as trustees for the infant.","PHRASES a board of trustees"]},"media":{"uk":"media/ldoce/hwd/bre/a/trustee0205.mp3","us":"media/ldoce/hwd/ame/2/trustee.mp3"},"oxford":{"phon":"trʌˈstiː","pos":"noun","senses":[{"en":"a person or an organization that has control of money or property that has been put into a trust for somebody","cn":"（财产的）受托人，信托机构","ex":{"en":"The bank will act as trustees for the estate until the child is 18.","cn":"银行将充当财产的信托机构，直到孩子 18 岁。"}},{"en":"a member of a group of people that controls the financial affairs and decides the policy of a charity or other organization","cn":"（慈善事业或其他机构的）受托人","ex":{"en":"the board of trustees","cn":"信托理事会"}}]}},"trough":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(喂家畜的)饲料槽，饮水槽","en":"A trough is a long narrow container from which farm animals drink or eat.","ex":{"en":"The old stone cattle trough still sits by the main entrance.","cn":"陈旧的石制牛食槽仍然放在大门口。"}},{"pos":"N-COUNT 可数名词","cn":"(两个大浪之间的)波谷","en":"A trough is a low area between two big waves on the sea.","ex":{"en":"The boat rolled heavily in the troughs between the waves.","cn":"船在波涛起伏的海浪中剧烈摇摆。"}},{"pos":"N-COUNT 可数名词","cn":"(商业活动等的)淡季，低谷","en":"A trough is a low point in a process that has regular high and low points, for example a period in business when people do not produce as much as usual.","ex":{"en":"Looking back afterwards you will see that this was not a terminal trough in your career","cn":"今后回想起来你就会明白，这并非你事业中一蹶不振的低谷。"}},{"pos":"N-COUNT 可数名词","cn":"低压槽","en":"A trough of low pressure is a long narrow area of low air pressure between two areas of higher pressure.","ex":{"en":"The trough of low pressure extended over about 1000 kilometres.","cn":"低压槽延伸约 1,000 公里。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long narrow open container that holds water or food for animals 〔","cn":"喂动物的〕食槽﹐饮水槽"},{"en":"a short period of low activity, low prices etc","cn":"低谷﹐萧条期"},{"en":"the hollow area between two waves","cn":"浪谷﹐波谷"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"If you live on a farm, you already know that a trough is what animals eat out of. The word actually refers to the shape of the container, and can mean anything that is low and hollowed out––a math curve, a depression in the ground."}]},"collocations":{"phrases":["ADJ. drinking, feeding | water | cattle, horse, pig 2 low point","ADJ. deep","VERB + TROUGH fall to, reach Inflation fell to a trough of 3.3%.","PHRASES from peak to trough The stock market fell by 48% from peak to trough. | the peaks and troughs the peaks and troughs of economic cycl"]},"media":{"uk":"media/ldoce/hwd/bre/c/trough0205.mp3","us":"media/ldoce/hwd/ame/c/trough.mp3"},"examples":[{"en":"There have been peaks and troughs in the long-term trend of unemployment.","cn":"长期以来失业率一直时起时伏。"},{"en":"The graph showed peaks and troughs of activity.","cn":"图表显示了活动的高峰和低谷。"}],"oxford":{"phon":"trɒf","pos":"noun","senses":[{"en":"a long, narrow open container for animals to eat or drink from","cn":"槽；饲料槽；饮水槽"},{"en":"a long narrow region of low air pressure between two regions of higher pressure","cn":"低压槽","lab":"specialist"},{"en":"a period of time when the level of something is low, especially a time when a business or the economy is not growing","cn":"低谷；（企业或经济的）低潮，萧条阶段","ex":{"en":"There have been peaks and troughs in the long-term trend of unemployment.","cn":"长期以来失业率一直时起时伏。"}},{"en":"a low area between two waves in the sea, or two hills","cn":"（海浪间的）波谷；（小山间的）槽谷，盆状洼地"}]}},"traumatic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"造成创伤的;惊骇的;痛苦的","en":"A traumatic experience is very shocking and upsetting, and may cause psychological damage.","ex":{"en":"I suffered a nervous breakdown. It was a traumatic experience","cn":"我曾经神经崩溃过。那是一次痛苦的经历。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel extremely upset or worried","cn":""},{"en":"a painful experience or memory makes you feel extremely upset and sad","cn":""},{"en":"an experience or event that is harrowing makes you feel extremely upset because it is very frightening or shocking","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something is traumatic if it's very upsetting, painful, or disturbing. The word is related to a Greek word meaning \"wound,\" so you can think of traumatic as something involving a wound, either physical or mental."}]},"collocations":{"phrases":["VERBS be | become, get","ADV. deeply, extremely, particularly, really, very this deeply traumatic incident in his past | fairly, quite, rather"]},"media":{"uk":"media/ldoce/hwd/bre/7/traumatic0205.mp3","us":"media/ldoce/hwd/ame/a/traumatic.mp3"},"examples":[{"en":"Divorce can be traumatic for everyone involved.","cn":"离婚对所有相关的人都会造成痛苦。"},{"en":"a traumatic experience","cn":"不幸的经历"}],"oxford":{"phon":"trɔːˈmætɪk","pos":"adjective","senses":[{"en":"extremely unpleasant and causing you to feel upset and/or anxious","cn":"痛苦的；极不愉快的","ex":{"en":"a traumatic experience","cn":"不幸的经历"}},{"en":"connected with or caused by trauma","cn":"创伤的；外伤的；损伤的","g":"[only before noun]","lab":"psychology or medical","ex":{"en":"traumatic amnesia","cn":"创伤性遗忘"}}]}},"trooper":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"骑兵;装甲团士兵","en":"A trooper is a soldier of low rank in the cavalry or in an armoured regiment in the army.","ex":{"en":"...a trooper from the 7th Cavalry","cn":"第七骑兵团的一名骑兵"}},{"pos":"N-COUNT 可数名词","cn":"(美国)州警(察)","en":"In the United States, a trooper is a police officer in a state police force.","ex":{"en":"Once long ago he had considered becoming a state trooper.","cn":"很久以前他曾考虑过当州警察。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a member of the police. In British English, police officer is used especially in more formal contexts, for example in news reports. In everyday English, British people still usually say policeman or policewoman","cn":""},{"en":"a man who is a member of the police","cn":""},{"en":"a woman who is a member of the police","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/trooper0205.mp3","us":"media/ldoce/hwd/ame/7/trooper.mp3"},"oxford":{"phon":"ˈtruːpə(r)","pos":"noun","senses":[{"en":"a soldier of low rank in the part of an army that uses tanks or horses","cn":"坦克兵；骑兵","ex":{"en":"He was a cavalry trooper before being injured at the battle of Corunna.","cn":"在科鲁纳战役中受伤之前，他是一名骑兵。"}},{"en":"(in the US) a member of a State police force","cn":"（美国）州警察","lab":"North American English"}]}},"trinket":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"廉价首饰;小装饰物","en":"A trinket is a pretty piece of jewellery or small ornament that is inexpensive.","ex":{"en":"She sold trinkets to tourists.","cn":"她向游客出售廉价饰品。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of jewellery or a small pretty object that is not valuable","cn":"廉价首饰﹔小饰物"}]},"vocab":{"pos":"n","senses":[{"en":"The word trinket refers to an inexpensive, flashy ornament or piece of jewelry. A rhinestone brooch to pin to your jacket is a showy trinket that won't break the bank."}]},"media":{"uk":"media/ldoce/hwd/bre/2/trinket0205.mp3","us":"media/ldoce/hwd/ame/8/trinket.mp3"},"oxford":{"phon":"ˈtrɪŋkɪt","pos":"noun","senses":[{"en":"a piece of jewellery or small attractive object that is not worth much money","cn":"（价值不高的）小首饰，小装饰物","ex":{"en":"On her dressing table there was a comb, a mirror and a few trinkets.","cn":"她的梳妆台上有一把梳子、一面镜子和几件小首饰。"}}]}},"trotter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(供食用的)猪蹄","en":"Trotters are pig's feet which you can cook and eat."},{"pos":"N-COUNT 可数名词","cn":"（受训参加拉车比赛的）快马","en":"A trotter is a horse that has been trained to move fast and to pull a carriage in races."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pig’s foot, especially when cooked and used as food 〔","cn":"用作食物的〕猪蹄"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41trotter.mp3","us":"media/ldoce/hwd/ame/f/ld41trotter.mp3"},"oxford":{"phon":"ˈtrɒtə(r)","pos":"noun","senses":[{"en":"a pig’s foot, especially when cooked and eaten as food","cn":"（尤指煮熟供食用的）猪蹄，猪脚"},{"en":"a horse that has been trained to trot fast in races","cn":"（受过快步马赛训练的）快步马"}]}},"treadmill":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"枯燥(或繁重)的工作","en":"You can refer to a task or a job as a treadmill when you have to keep doing it although it is unpleasant and exhausting.","ex":{"en":"Mr Stocks can expect a gruelling week on the publicity treadmill.","cn":"斯托克斯先生可以预见下一周会被枯燥繁重的宣传工作搞得焦头烂额。"}},{"pos":"N-COUNT 可数名词","cn":"踏车;跑步机","en":"A treadmill is a piece of equipment, for example an exercise machine, consisting of a wheel with steps around its edge or a continuous moving belt. The weight of a person or animal walking on it causes the wheel or belt to turn."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of exercise equipment that has a large belt around a set of wheels, that you can walk or run on while staying in the same place","cn":"跑步机"},{"en":"work or a way of life that seems very boring because you always have to do the same things","cn":"单调而枯燥的工作[生活]"},{"en":"a mill worked in the past by prisoners treading on steps fixed to a very large wheel 〔","cn":"过去由犯人踩动踏板使大轮转动的〕踏车磨粉机"}]},"media":{"img":["media/ldoce/img/treadmill.jpg","media/thumb/treadmill.jpg"],"uk":"media/ldoce/hwd/bre/8/treadmill0205.mp3","us":"media/ldoce/hwd/ame/8/treadmill.mp3"},"examples":[{"en":"I'd like to escape the office treadmill.","cn":"我想摆脱办公室的枯燥工作。"},{"en":"the treadmill of working in the office","cn":"单调枯燥的办公室工作"}],"oxford":{"phon":"ˈtredmɪl","pos":"noun","senses":[{"en":"work or a way of life that is boring or makes you tired because it involves always doing the same things","cn":"枯燥无味的工作（或生活方式）","g":"[singular]","ex":{"en":"I'd like to escape the office treadmill.","cn":"我想摆脱办公室的枯燥工作。"}},{"en":"(especially in the past) a large wheel turned by the weight of people or animals walking on steps around its inside edge, and used to operate machines","cn":"（由人或牲畜踩动踏板使之转动的）踏车","g":"[countable]"},{"en":"an exercise machine that has a moving surface that you can walk or run on while remaining in the same place","cn":"（锻炼身体的）跑步机，健走机","g":"[countable]","ex":{"en":"I try to do half an hour’s exercise on the treadmill every morning.","cn":"我尝试每天早上在跑步机上锻炼半小时。"}}]}},"trader":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"商人;证券交易人","en":"A trader is a person whose job is to trade in goods or stocks.","ex":{"en":"Market traders display an exotic selection of the island's produce.","cn":"集市上的商贩摆出了一系列具有异域风味的该岛农产品以供选择。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a company or person that sells goods to the public in a shop - used especially in business contexts","cn":""},{"en":"a person or company that sells goods in large quantities and at low prices, especially to other companies that then sell the goods to the public","cn":""},{"en":"a person or company that buys and sells large quantities of goods such as wine, or basic materials such as coal and wood","cn":""}]},"collocations":{"phrases":["ADJ. large China is now one of the largest traders in the world. | small, small-scale small market traders | local | foreign, international "]},"media":{"uk":"media/ldoce/hwd/bre/0/trader0205.mp3","us":"media/ldoce/hwd/ame/9/trader.mp3"},"examples":[{"en":"small/independent/local traders","cn":"小的/独立的/当地的商人"},{"en":"bond/currency traders","cn":"债券/货币交易人"}],"oxford":{"phon":"ˈtreɪdə(r)","pos":"noun","senses":[{"en":"a person who buys and sells things as a job","cn":"商人；经商者；买卖人","lab":"British English","ex":{"en":"small/independent/local traders","cn":"小的／独立的／当地的商人"}}]}},"trolley":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(购物或装行李用的)手推车","en":"A trolley is an object with wheels that you use to transport heavy things such as shopping or luggage.","ex":{"en":"A porter relieved her of the three large cases she had been pushing on a trolley.","cn":"搬运工帮她卸下了她一直用手推车推着的3个大箱子。"}},{"pos":"N-COUNT 可数名词","cn":"(运送食品饮料上桌的)小推车，台车","en":"A trolley is a small table on wheels which is used for serving drinks or food.","ex":{"en":"The waiter had brought the sweet trolley.","cn":"侍者已经推来了甜食推车。"}},{"pos":"N-COUNT 可数名词","cn":"担架车","en":"A trolley is a bed on wheels for moving patients in hospital.","ex":{"en":"She was left on a hospital trolley for 14 hours without even a glass of water.","cn":"她被放在一辆担架车上14个小时，连一杯水都没有喝。"}},{"pos":"N-COUNT 可数名词","cn":"有轨电车","en":"A trolley or trolley car is an electric vehicle for carrying people which travels on rails in the streets of a town.","ex":{"en":"He took a northbound trolley on State Street.","cn":"他在州街登上了一辆北行的有轨电车。"}},{"pos":"PHRASE 短语","cn":"丧失理智；举止不正常","en":"If you say that someone is off their trolley, you mean that their ideas or behaviour are very strange.","ex":{"en":"Is she off her trolley or what?","cn":"她是疯了还是怎么了？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large basket on wheels that you use for carrying bags, shopping etc","cn":"行李[购物]手推车"},{"en":"a small table on wheels used for serving food 〔","cn":"送食物上桌的〕手推车﹐台车"},{"en":"an electric vehicle for carrying passengers which moves along the street on metal tracks","cn":"有轨电车"}]},"collocations":{"phrases":["ADJ. laden, loaded The waiter was pushing a laden sweet trolley towards our table. | baggage, luggage, shopping | drinks, tea | dessert, swe","VERB + TROLLEY load, pile Passengers with trolleys piled high with luggage waited at the check-in desk. | push, wheel","TROLLEY + NOUN service On many trains, refreshments are provided by a trolley service.","PREP. on a/the ~ They brought breakfast to the room on a trolley."]},"media":{"img":["media/ldoce/img/supermarket_trolley.jpg"],"uk":"media/ldoce/hwd/bre/0/trolley0205.mp3","us":"media/ldoce/hwd/ame/7/trolley.mp3"},"examples":[{"en":"a shopping/supermarket/luggage trolley","cn":"购物/超市/行李手推车"},{"en":"a drinks trolley","cn":"饮料车"}],"oxford":{"phon":"ˈtrɒli","pos":"noun","senses":[{"en":"a small vehicle with wheels that can be pushed or pulled along and is used for carrying things","cn":"手推车；手拉车","lab":"British English","ex":{"en":"a shopping/supermarket/luggage trolley","cn":"购物／超市／行李手推车"}},{"en":"a small table on very small wheels, used for carrying or serving food or drink","cn":"（运或送食品、饮料的）小推车，台车","lab":"British English","ex":{"en":"a drinks trolley","cn":"饮料车"}},{"en":"a vehicle driven by electricity, that runs on rails along the streets of a town and carries passengers","cn":"有轨电车","lab":"both US English"}]}},"transcontinental":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"横贯大陆的;穿越大陆的;(美国英语中通常指)横穿美国的","en":"A transcontinental journey or route goes from one side of a continent to the other. In American English, transcontinental usually means from one side of the United States to the other.","ex":{"en":"...in mid-nineteenth-century America, before the transcontinental railroad was built.","cn":"19 世纪中期的美国，在横贯大陆的铁路建成之前"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"crossing a continent","cn":"横贯大陆的"}]},"vocab":{"pos":"adj","senses":[{"en":"When you fly from New York to California, you can describe your flight as transcontinental , crossing the continent of North America."}]},"media":{"uk":"media/ldoce/hwd/bre/f/transcontinent0205.mp3","us":"media/ldoce/hwd/ame/d/transcontinental.mp3"},"examples":[{"en":"a transcontinental railway/railroad","cn":"横贯大陆的铁路"},{"en":"a transcontinental railway","cn":"一条横贯大陆的铁路"}],"oxford":{"phon":"ˌtrænzˌkɒntɪˈnentl","pos":"adjective","senses":[{"en":"crossing a continent","cn":"横贯大陆的；穿越大陆的","ex":{"en":"a transcontinental railway/railroad","cn":"横贯大陆的铁路"}}]}},"trusty":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（长期以来）可靠的，可信赖的","en":"Trusty things, animals, or people are reliable and have always worked well in the past.","ex":{"en":"She still drives her trusty black Corvette.","cn":"她仍然开她那辆皮实可靠的黑色克尔维特车。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a trusty weapon, vehicle, animal etc is one that you have had for a long time and can depend on – often used humorously 〔","cn":"武器﹑车辆﹑动物等〕忠实可靠的〔常为幽默用法〕"},{"en":"a prisoner who is given special jobs or rights, because they behave in a way that can be trusted 〔","cn":"由于表现好而受到优待的〕模范囚犯"}]},"media":{"uk":"media/ldoce/hwd/bre/8/trusty_adj0205.mp3","us":"media/ldoce/hwd/ame/3/trusty.mp3"},"examples":[{"en":"She spent years touring Europe with her trusty old camera.","cn":"她带着她那架忠心耿耿的照相机在欧洲周游多年。"},{"en":"a trusty friend","cn":"忠实的朋友"}],"oxford":{"phon":"ˈtrʌsti","pos":"adjective","senses":[{"en":"that you have had a long time and have always been able to rely on","cn":"（长期以来）可信任的，可信赖的；忠实的","ex":{"en":"a trusty friend","cn":"忠实的朋友"}},{"en":"a prisoner who is given special advantages because of good behaviour","cn":"模范囚犯（由于表现好而受到优待）","pos":"noun"}]}},"triumvirate":{"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"三人工作组；（尤指）三人领导小组，三巨头","en":"A triumvirate is a group of three people who work together, especially when they are in charge of something.","ex":{"en":"...the triumvirate of women who worked together on the TV dramatisation of the novel.","cn":"合作把这部小说搬上电视的三位女负责人"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of three very powerful people","cn":"三头政治﹐三雄执政"}]},"vocab":{"pos":"n","senses":[{"en":"A triumvirate is a group of three men who share power. In America's early days, George Washington, Thomas Jefferson, and James Madison were a triumvirate — three men whose leadership helped shape America."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41triumvirate.mp3","us":"media/ldoce/hwd/ame/e/triumvirate.mp3"},"oxford":{"phon":"traɪˈʌmvərət","pos":"noun","senses":[{"en":"a group of three powerful people or groups who control something together","cn":"三人领导小组；三人统治集团；三方执政集团","ex":{"en":"They appointed a triumvirate of directors.","cn":"他们任命了三位董事。"}}]}},"traduce":{"collins":{"senses":[{"pos":"VERB 动词","cn":"诋毁;中伤;诽谤","en":"If someone has been traduced, unpleasant and untrue things have deliberately been said about them.","ex":{"en":"We have been traduced in the press as xenophobic bigots.","cn":"我们被新闻界诋毁为仇外的偏狭之徒。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to deliberately say things that are untrue or unpleasant","cn":"诽谤﹐中伤﹐诋毁"}]},"vocab":{"pos":"v","senses":[{"en":"To traduce is to badmouth someone or something. If you don't want people talking trash about you, then don't traduce them either — even if they started it."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41traduce.mp3","us":"media/ldoce/hwd/ame/a/traduce.mp3"},"oxford":{"phon":"trəˈdjuːs","pos":"verb","senses":[{"en":"to say things about somebody that are unpleasant or not true","cn":"诽谤；中伤；诋毁"}]}},"trawler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拖网渔船","en":"A trawler is a fishing boat that is used for trawling."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a fishing boat that uses a trawl net","cn":"拖网渔船"}]},"media":{"uk":"media/ldoce/hwd/bre/e/trawler0205.mp3","us":"media/ldoce/hwd/ame/0/trawler.mp3"},"oxford":{"phon":"ˈtrɔːlə(r)","pos":"noun","senses":[{"en":"a fishing boat that uses large nets that it drags through the sea behind it","cn":"拖网渔船"}]}},"trash":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"垃圾;废物","en":"Trash consists of unwanted things or waste material such as used paper, empty containers and bottles, and waste food.","ex":{"en":"The yards are overgrown and cluttered with trash…","cn":"院子里杂草丛生，垃圾成堆。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"毫无价值的东西;拙劣的作品","en":"If you say that something such as a book, painting, or film is trash, you mean that it is of very poor quality.","ex":{"en":"Pop music doesn't have to be trash, it can be art","cn":"流行音乐不必非得是垃圾，也可以是艺术。"}},{"pos":"VERB 动词","cn":"(故意)损坏，捣毁，糟蹋","en":"If someone trashes a place or vehicle, they deliberately destroy it or make it very dirty.","ex":{"en":"Would they trash the place when the party was over?","cn":"聚会结束时他们会把这地方搞得一团糟吗？"}},{"pos":"VERB 动词","cn":"痛贬;贬损","en":"If you trash people or their ideas, you criticize them very strongly and say that they are worthless.","ex":{"en":"People asked why the candidates spent so much time trashing each other.","cn":"人们问为什么候选人花这么多时间互相贬损。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things that people throw away, such as old food, dirty paper etc","cn":""},{"en":"rubbish","cn":""},{"en":"rubbish","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"Trash is rubbish or garbage — it's the stuff that gets thrown away. Your town might organize a clean-up day each year when people pick up trash in parks and neighborhoods."}]},"media":{"uk":"media/ldoce/hwd/bre/4/trash_v0205.mp3","us":"media/ldoce/hwd/ame/e/trash1.mp3"},"examples":[{"en":"I'm leaving my old toys here — if you don't want them, just trash them.","cn":"我把我的旧玩具留在这里，你不要就扔掉好了。"},{"en":"What's this trash you're watching?","cn":"你看的这个乌七八糟的节目是什么？"}],"oxford":{"phon":"træʃ","pos":"noun","senses":[{"en":"things that you throw away because you no longer want or need them","cn":"垃圾；废弃物","lab":"North American English","ex":{"en":"Don't forget to take out the trash.","cn":"别忘了把垃圾带走。"}},{"en":"objects, writing, ideas, etc. that you think are of poor quality","cn":"劣质品；拙劣的作品；糟粕；谬论","lab":"informal, disapproving，，","ex":{"en":"What's this trash you're watching?","cn":"你看的这个乌七八糟的节目是什么？"}},{"en":"an offensive word used to describe people that you do not respect","cn":"窝囊废；废物；没出息的人","lab":"North American English, informal，，"},{"en":"to damage or destroy something","cn":"破坏；损坏；毁坏","ex":{"en":"The band was famous for trashing hotel rooms.","cn":"这帮人以破坏旅馆房间出名。"},"pos":"verb"},{"en":"to criticize something/somebody very strongly","cn":"抨击；谴责","ex":{"en":"Several journalists attempted to trash his reputation.","cn":"几位记者试图抨击他名声不佳。"},"pos":"verb"},{"en":"to throw away something that you do not want","cn":"丢弃；把…抛弃","lab":"North American English","ex":{"en":"I'm leaving my old toys here—if you don't want them, just trash them.","cn":"我把我的旧玩具留在这里，你不要就扔掉好了。"},"pos":"verb"}]}},"transvestism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"易装癖","en":"Transvestism is the practice of wearing clothes normally worn by a person of the opposite sex, usually for pleasure."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone, especially a man, who enjoys dressing like a person of the opposite sex","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/transvestite0205.mp3","us":"media/ldoce/hwd/ame/7/transvestite.mp3"},"oxford":{"phon":"trænzˈvestɪzəm","pos":"noun","senses":[{"en":"the practice, especially by a man, of dressing in clothes usually worn by the opposite sex","cn":"异性装扮癖,易装癖"}]}},"trilogy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(小说、戏剧或电影的)三部曲","en":"A trilogy is a series of three books, plays, or films that have the same subject or the same characters.","ex":{"en":"…Laurie Lee's trilogy of autobiographical novels.","cn":"劳里·李的自传体小说三部曲"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a series of three plays, books etc that are about the same people or subject 〔","cn":"戏剧﹑图书等的〕三部曲"}]},"vocab":{"pos":"n","senses":[{"en":"If you’ve just started a trilogy of books, you’ll be reading for a while. A trilogy is something that has three parts, so you'll have three books to read."}]},"media":{"uk":"media/ldoce/hwd/bre/b/trilogy0205.mp3","us":"media/ldoce/hwd/ame/7/trilogy.mp3"},"examples":[{"en":"part 2 of a trilogy","cn":"三部曲的第二部"}],"oxford":{"phon":"ˈtrɪlədʒi","pos":"noun","senses":[{"en":"a group of three books, films, etc. that have the same subject or characters","cn":"（书籍、电影等的）三部曲；三部剧"}]}},"trespass":{"collins":{"senses":[{"pos":"VERB 动词","cn":"擅自进入，非法侵入(他人土地)","en":"If someone trespasses, they go onto someone else's land without their permission.","ex":{"en":"They were trespassing on private property","cn":"他们擅自闯入私人房屋。"}},{"pos":"VERB 动词","cn":"干涉;妨碍；插手","en":"If you say that someone is trespassing on something, you mean that they are involving themselves in something that is not their concern.","ex":{"en":"They were acting to prevent the state from trespassing on family matters such as sex education.","cn":"他们正采取行动以阻止国家干涉诸如性教育之类的家庭问题。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go or come into a place. Enter is more formal than go in","cn":""},{"en":"to enter a place. Go in/into is the usual phrase to use in everyday English","cn":""},{"en":"to enter a place – used when you are already in that place","cn":""}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"To trespass is to illegally enter someone's property or overstep your bounds in another way."}]},"media":{"uk":"media/ldoce/hwd/bre/2/trespass_n0205.mp3","us":"media/ldoce/hwd/ame/9/trespass1.mp3"},"examples":[{"en":"I mustn't trespass on your time any longer.","cn":"我不能再占用你的时间了。"},{"en":"He told me I was trespassing on private land.","cn":"他说我在擅闯私人土地。"}],"oxford":{"phon":"ˈtrespəs","pos":"verb","senses":[{"en":"to enter land or a building that you do not have permission or the right to enter","cn":"擅自进入，非法侵入（他人的土地或建筑物）","g":"[intransitive]","ex":{"en":"He told me I was trespassing on private land.","cn":"他说我在擅闯私人土地。"}},{"en":"to do something wrong","cn":"做错事","g":"[intransitive]","lab":"old use"},{"en":"the act or crime of entering land or a building that you do not have permission or the right to enter","cn":"擅自进入，非法侵入（他人的土地或建筑物）","g":"[uncountable, countable]","pos":"noun"},{"en":"something that you do that is morally wrong","cn":"罪过","g":"[countable]","lab":"old use","pos":"noun"}]}},"trouper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指经验老到的）演员，表演者","en":"You can refer to an actor or other performer as a trouper, especially when you want to suggest that they have a lot of experience and can deal with difficult situations in a professional way.","ex":{"en":"Like the old trouper he is, he timed his entry to perfection.","cn":"他是个老演员，出场时间把握得恰到好处。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has a lot of experience of work in the entertainment business","cn":"有经验的演员﹐老演员﹐老艺人﹔台柱子"},{"en":"someone who works hard and keeps trying, even when the situation is difficult","cn":"任劳任怨的人"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41trouper.mp3","us":"media/ldoce/hwd/ame/3/trouper.mp3"},"oxford":{"phon":"ˈtruːpə(r)","pos":"noun","senses":[{"en":"an actor or other person who has a lot of experience and who you can depend on","cn":"角儿；台柱子演员；可靠的人；主心骨"}]}},"tribunal":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"(审理特定案件的)特别法庭，审理委员会","en":"A tribunal is a special court or committee that is appointed to deal with particular problems.","ex":{"en":"His case comes before an industrial tribunal in March.","cn":"他的讼案将于3月在劳资法庭受审。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of court that is given official authority to deal with a particular situation or problem","cn":"特别法庭﹔审理委员会"}]},"vocab":{"pos":"n","senses":[{"en":"A tribunal is like a court. If you've done something wrong and you get caught it's likely you'll be brought before a tribunal , although not all tribunals are there to determine guilt."}]},"collocations":{"phrases":["ADJ. independent | international, local, village | higher, inferior | industrial, military, transport, war crimes | appeal/appeals, appellat","VERB + TRIBUNAL set up A war crimes tribunal was set up to prosecute those charged with atrocities. | go to The dismissed workers decided to","TRIBUNAL + VERB be in session, hold a session The tribunal held its first session later that month. | hear sth | conclude sth, decide sth, f","TRIBUNAL + NOUN decision | hearing | procedure, proceedings | representation | chairman, member","PREP. at a/the ~ The police gave evidence at the tribunal. | before a/the ~ No legal aid was available to cover representation before tribun"]},"media":{"uk":"media/ldoce/hwd/bre/5/tribunal0205.mp3","us":"media/ldoce/hwd/ame/2/tribunal.mp3"},"examples":[{"en":"an international war crimes tribunal","cn":"国际战争罪法庭"},{"en":"a military tribunal","cn":"军事法庭"}],"oxford":{"phon":"traɪˈbjuːnl","pos":"noun","senses":[{"en":"a type of court with the authority to deal with a particular problem or disagreement","cn":"特别法庭；裁判所","ex":{"en":"an international war crimes tribunal","cn":"国际战争罪法庭"}}]}},"tripartite":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"分为三部分的;涉及三方的","en":"You can use tripartite to describe something that has three parts or that involves three groups of people.","ex":{"en":"...tripartite meetings between Government ministers, trades union leaders and industrialists.","cn":"政府部长、工会领袖和工厂主之间的三方会谈"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"involving three parts, groups etc","cn":"三方之间的"},{"en":"tripartite agreement/talks etc a tripartite agreement between France, Britain, and Germany","cn":"法国﹑英国和德国之间的三方协定"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41tripartite.mp3","us":"media/ldoce/hwd/ame/f/tripartite.mp3"},"oxford":{"phon":"traɪˈpɑːtaɪt","pos":"adjective","senses":[{"en":"having three parts or involving three people, groups, etc.","cn":"有三部分的；涉及三人的；三方参加的","ex":{"en":"a tripartite division","cn":"包括三部分的划分"}}]}},"triumphant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(成功或获胜后)欢欣鼓舞的，狂喜的","en":"Someone who is triumphant has gained a victory or succeeded in something and feels very happy about it.","ex":{"en":"Duncan and his triumphant soldiers celebrate their military victory…","cn":"邓肯和他那些欢欣鼓舞的士兵们庆祝他们取得了军事胜利。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"showing pleasure and pride because of a victory or success 〔","cn":"因胜利或成功而〕扬扬得意的﹐耀武扬威的"},{"en":"having gained a victory or success","cn":"胜利的﹐成功的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you're triumphant , you're proud of a huge success, like your triumphant victory at your ping-pong tournament."}]},"collocations":{"phrases":["VERBS appear, be, feel, look, seem, sound | emerge, return The Democrats have emerged triumphant from the political crisis.","ADV. positively There was a positively triumphant note in her voice. | almost | ultimately Hers is a moving and ultimately triumphant story."]},"media":{"uk":"media/ldoce/hwd/bre/b/triumphant0205.mp3","us":"media/ldoce/hwd/ame/e/triumphant.mp3"},"examples":[{"en":"They emerged triumphant in the September election.","cn":"他们在九月份的选举中大获全胜。"},{"en":"a triumphant smile","cn":"得意扬扬的笑容"}],"oxford":{"phon":"traɪˈʌmfənt","pos":"adjective","senses":[{"en":"very successful in a way that causes great pleasure","cn":"高奏凯歌的；大获全胜的；巨大成功的","ex":{"en":"They emerged triumphant in the September election.","cn":"他们在九月份的选举中大获全胜。"}},{"en":"showing great pleasure or joy about a victory or success","cn":"欢欣鼓舞的；扬扬得意的；耀武扬威的","ex":{"en":"a triumphant smile","cn":"得意扬扬的笑容"}}]}},"transgress":{"collins":{"senses":[{"pos":"VERB 动词","cn":"违犯道德(或行为)准则","en":"If someone transgresses, they break a moral law or a rule of behaviour.","ex":{"en":"If a politician transgresses, that is not the fault of the media.","cn":"如果政客行为失检，那可不是媒体的责任。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something that is against the rules of social behaviour or against a moral principle","cn":"违反（社会规范）﹔越轨﹔违背（道德）"}]},"vocab":{"pos":"v","senses":[{"en":"When you go beyond the boundaries, either physically or morally, you transgress . A river will transgress its banks as it floods, and students who cheat transgress school rules."}]},"media":{"uk":"media/ldoce/hwd/bre/3/transgress0205.mp3","us":"media/ldoce/hwd/ame/0/transgress.mp3"},"examples":[{"en":"Orton’s plays transgress accepted social norms.","cn":"奥顿的戏剧违背了公认的社会准则。"}],"oxford":{"phon":"trænzˈɡres","pos":"verb","senses":[{"en":"to go beyond the limit of what is morally or legally acceptable","cn":"越轨；违背（道德）；违犯（法律）","ex":{"en":"They had transgressed the bounds of decency.","cn":"他们已经超越了正派的界限。"}}]}},"trigger-happy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好动武的;爱动用武器的;爱开枪的;以开枪为乐的","en":"If you describe someone as trigger-happy, you disapprove of them because they are too ready and willing to use violence and weapons, especially guns.","ex":{"en":"They were gunned down by members of the trigger-happy National Guard…","cn":"他们被那些肆意开枪的国民卫队士兵枪杀了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is trigger-happy is much too willing to use weapons, especially guns","cn":"动辄开枪的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41trigger-happy.mp3","us":"media/ldoce/hwd/ame/1/trigger-happy.mp3"},"examples":[{"en":"a trigger-happy cop","cn":"一名动不动就开枪的警察"}],"oxford":{"phon":"ˈtrɪɡə hæpi","pos":"adjective","senses":[{"en":"too willing and quick to use violence, especially with guns","cn":"以开枪为乐的；好斗的；爱动武的；动辄开枪的","ex":{"en":"trigger-happy troops","cn":"好战的部队"}}]}},"truculent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"暴躁的;易怒的;好斗的;尖刻的","en":"If you say that someone is truculent, you mean that they are bad-tempered and aggressive."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"bad-tempered and always willing to argue with people","cn":"脾气暴躁的﹔爱争吵的﹔寻衅的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you are quick to argue, always looking for a fight, and hard to please, you are truculent . You can also write a truculent essay, and fans upset by a loss can become truculent ."}]},"media":{"uk":"media/ldoce/hwd/bre/d/truculent0205.mp3","us":"media/ldoce/hwd/ame/b/truculent.mp3"},"examples":[{"en":"a truculent attitude","cn":"凶狠的态度"}],"oxford":{"phon":"ˈtrʌkjələnt","pos":"adjective","senses":[{"en":"tending to argue or become angry; slightly aggressive","cn":"爱争吵的；粗暴的；好斗的；寻衅的","ex":{"en":"‘What do you want?’ he asked, sounding slightly truculent.","cn":"“你想要什么？”他问道，听起来有些好斗。"}}]}},"tragicomedy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"悲喜剧","en":"A tragi-comedy is a play or other written work that is both sad and amusing."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a play or a story that is both sad and funny","cn":"悲喜剧"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41tragicomedy.mp3","us":"media/ldoce/hwd/ame/5/tragicomedy.mp3"},"oxford":{"phon":"ˌtrædʒiˈkɒmədi","pos":"noun","senses":[{"en":"a play that is both funny and sad; plays of this type","cn":"悲喜剧；悲喜剧作品"},{"en":"an event or a situation that is both funny and sad","cn":"悲喜交加的事情（或局面）"}]}},"trickery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"欺骗;欺诈;耍花招","en":"Trickery is the use of dishonest methods in order to achieve something.","ex":{"en":"They are notorious for resorting to trickery in order to impress their clients.","cn":"他们为了打动客户不惜坑蒙拐骗，因而声名狼藉。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of deceiving someone, especially by telling them lies","cn":""},{"en":"the act of deceiving someone - use this to show strong disapproval","cn":""},{"en":"a situation in which someone is tricked into doing something that results in them being punished","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When tricks of any kind are used to fool or deceive someone, especially for financial gain, that's trickery ."}]},"media":{"uk":"media/ldoce/hwd/bre/5/trickery0205.mp3","us":"media/ldoce/hwd/ame/1/trickery.mp3"},"oxford":{"phon":"ˈtrɪkəri","pos":"noun","senses":[{"en":"the use of dishonest methods to trick people in order to achieve what you want","cn":"欺骗；欺诈；耍花招；招摇撞骗","ex":{"en":"She clearly suspected some kind of trickery.","cn":"她显然怀疑有什么诡计。"}}]}},"tragicomic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"又悲又喜的","en":"Something that is tragi-comic is both sad and amusing at the same time."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a play or a story that is both sad and funny","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41tragicomedy.mp3","us":"media/ldoce/hwd/ame/5/tragicomedy.mp3"},"oxford":{"phon":"ˌtrædʒiˈkɒmɪk","pos":"adjective","senses":[{"en":"connected with plays that are both funny and sad","cn":"悲喜剧的","ex":{"en":"The play is a tragicomic masterpiece.","cn":"该剧是一部悲喜剧的杰作。"}},{"en":"both funny and sad","cn":"悲喜交集的","ex":{"en":"the tragicomic failure of his dreams","cn":"他的梦想悲喜剧般的失败"}}]}},"transcendence":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"超越","en":"Transcendence is the quality of being able to go beyond normal limits or boundaries.","ex":{"en":"...the transcendence of class differences.","cn":"对阶级差别的超越"}}]},"vocab":{"pos":"n","senses":[{"en":"Transcendence is the act of rising above something to a superior state. If you were at a concert where the rock star jumped into the audience, the concert (and audience) may have achieved a state of transcendence ."}]},"examples":[{"en":"the transcendence of God","cn":"上帝的至高无上"}],"oxford":{"phon":"trænˈsendəns","pos":"noun","senses":[{"en":"the ability to go beyond the usual limits; existence or experience beyond the normal or physical level","cn":"超越；超卓；卓越","ex":{"en":"the transcendence of God","cn":"上帝的超凡"}}]}},"truancy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"逃学;旷课","en":"Truancy is when children stay away from school without permission.","ex":{"en":"Schools need to reduce levels of truancy.","cn":"学校需要减少旷课人数。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when students deliberately stay away from school without permission","cn":"逃学﹐旷课"}]},"vocab":{"pos":"n","senses":[{"en":"If you pretend you're sick to stay home from school and then sneak out to a baseball game, that's truancy , meaning it’s an unauthorized absence."}]},"collocations":{"phrases":["ADJ. persistent","VERB + TRUANCY combat, tackle measures to combat persistent truancy in our schools | reduce | condone parents who condone their children's t","TRUANCY + NOUN level, rate"]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41truancy.mp3","us":"media/ldoce/hwd/ame/b/truancy.mp3"},"examples":[{"en":"the school’s truancy rate","cn":"学校的旷课率"}],"oxford":{"phon":"ˈtruːənsi","pos":"noun","senses":[{"en":"the practice of staying away from school without permission","cn":"旷课；逃学","ex":{"en":"Truancy rates at the school are very high.","cn":"学校的逃学率非常高。"}}]}},"tripod":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"三脚架","en":"A tripod is a stand with three legs that is used to support something such as a camera or a telescope."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a support with three legs, used for a piece of equipment, camera etc","cn":"三脚架"}]},"vocab":{"pos":"n","senses":[{"en":"A tripod is a three-legged support for a camera. Once you try using a tripod for taking photographs, your sharp, beautiful pictures might make it hard to do without it."}]},"media":{"img":["media/ldoce/img/tripod.jpg"],"uk":"media/ldoce/hwd/bre/1/tripod0205.mp3","us":"media/ldoce/hwd/ame/f/tripod.mp3"},"oxford":{"phon":"ˈtraɪpɒd","pos":"noun","senses":[{"en":"a support with three legs for a camera, telescope, etc.","cn":"（照相机、望远镜等的）三脚架"}]}},"trouble-free":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"顺利的;没问题的;没困难的","en":"Something that is trouble-free does not cause any problems or difficulties.","ex":{"en":"The carnival got off to a virtually trouble-free start with the police reporting only one arrest.","cn":"狂欢节开幕进行得几乎是一帆风顺，警方只报告了一例拘捕。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"without any problems","cn":"没有困难的﹐没有问题的﹐没有忧虑的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/trouble_free0205.mp3","us":"media/ldoce/hwd/ame/f/trouble-free.mp3"},"examples":[{"en":"We ensure that you have a trouble-free and enjoyable holiday.","cn":"我们确保让您度过一个称心如意的愉快假期。"}]},"transmitter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(电视、广播节目的)发射机","en":"A transmitter is a piece of equipment that is used for broadcasting television or radio programmes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"equipment that sends out radio or television signals 〔","cn":"发送无线电或电视信号的〕发报机﹐发射机"},{"en":"someone or something that passes something on to another person or thing","cn":"传送者﹐传输者﹐传播者﹐传播媒介"}]},"collocations":{"phrases":["ADJ. radar, radio, television/TV | voice They discovered voice transmitters hidden in the wall. | FM, long-wave, medium-wave, short-wave, VH","VERB + TRANSMITTER be equipped/fitted with","TRANSMITTER + VERB emit sth, send out sth The receiver picks up pulses emitted by the transmitter."]},"media":{"uk":"media/ldoce/hwd/bre/7/transmitter0205.mp3","us":"media/ldoce/hwd/ame/7/transmitter.mp3"},"examples":[{"en":"Emphasis was placed on the school as a transmitter of moral values.","cn":"人们强调学校为道德价值观的传输者。"},{"en":"What is the main transmitter of the virus?","cn":"这种病毒的主要传播媒介是什么？"}],"oxford":{"phon":"trænzˈmɪtə(r)","pos":"noun","senses":[{"en":"a piece of equipment used for sending electronic signals, especially radio or television signals","cn":"（尤指电台或电视信号的）发射机，发射台，发报台","ex":{"en":"They discovered radio transmitters hidden in the wall.","cn":"他们发现了隐藏在墙上的无线电发射器。"}},{"en":"a person or thing that transmits something from one person or thing to another","cn":"传送者；传输者；传播者；传染媒介","lab":"formal","ex":{"en":"Emphasis was placed on the school as a transmitter of moral values.","cn":"人们强调学校为道德价值观的传输者。"}}]}},"trilby":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(男子的)软毡帽","en":"A trilby or a trilby hat is a man's hat which is made of felt and has a groove along the top from front to back."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man’s soft felt hat 〔","cn":"男子戴的〕软毡帽"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41trilby.mp3","us":"media/ldoce/hwd/ame/b/laadtrilby.mp3","img":["media/thumb/trilby.jpg"]},"oxford":{"phon":"ˈtrɪlbi","pos":"noun","senses":[{"en":"a man’s soft hat with a narrow brim and the top part pushed in from front to back","cn":"（男式）软毡帽"}]}},"troupe":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"(巡回演出的)演出团，歌舞团，戏班子","en":"A troupe is a group of actors, singers, or dancers who work together and often travel around together, performing in different places.","ex":{"en":"...troupes of travelling actors.","cn":"巡回演出演员组成的剧团"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of singers, actors, dancers etc who work together","cn":"演出团﹐剧团﹐歌舞团"}]},"media":{"uk":"media/ldoce/hwd/bre/c/troop_n0205.mp3","us":"media/ldoce/hwd/ame/0/troop1.mp3"},"oxford":{"phon":"truːp","pos":"noun","senses":[{"en":"a group of actors, singers, etc. who work together","cn":"（演员、歌手等的）班子，表演团"}]}},"trappings":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"(权力、财富、工作等带来的)装点之物，额外实惠","en":"The trappings of power, wealth, or a particular job are the extra things, such as decorations and luxury items, that go with it.","ex":{"en":"The family were in government for several generations and evidently loved the trappings of power.","cn":"那个家族好几代人都曾在政府任职，显然对随权力而来的各种额外实惠情有独钟。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things such as money, influence, possessions etc that are related to a particular type of person, job, or way of life 〔","cn":"象征身份﹑职业或生活方式的〕标志"}]},"vocab":{"pos":"n","senses":[{"en":"Big house, shiny new car, a custom-made suit, an expensive watch, cool sunglasses... If you have these things, you have the trappings of success, which means you own things that give you the outward appearance of success."}]},"collocations":{"phrases":["ADJ. external, outward, visible She scorns the visible trappings of success, preferring to live unnoticed.","PHRASES all the trappings They enjoyed all the trappings of wealth. | the trappings of power/success"]},"media":{"uk":"media/ldoce/hwd/bre/4/trappings0205.mp3","us":"media/ldoce/hwd/ame/5/trappings.mp3"},"examples":[{"en":"They enjoyed all the trappings of wealth.","cn":"他们享有所有象征财富的东西。"},{"en":"the trappings of power","cn":"权力的标志"}],"oxford":{"phon":"ˈtræpɪŋz","pos":"noun","senses":[{"en":"the possessions, clothes, etc. that are connected with a particular situation, job or social position","cn":"（与某一处境、职业或社会地位有关的）身外之物，标志，服装","ex":{"en":"They enjoyed all the trappings of wealth.","cn":"他们享有所有象征财富的东西。"}}]}},"trite":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"陈腐的;老一套的","en":"If you say that something such as an idea, remark, or story is trite, you mean that it is dull and boring because it has been said or told too many times.","ex":{"en":"The movie is teeming with obvious and trite ideas","cn":"这部电影充斥着平铺直叙的陈腐观点。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used too much and therefore no longer interesting or effective","cn":""},{"en":"no longer interesting or exciting because of having been used too much","cn":""},{"en":"a trite remark, idea etc has been used so often, that is seems boring or not sincere","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When you want to indicate that something is silly or overused, you would call it trite . A love song with lyrics about holding hands in the sunshine? Totally trite ."}]},"media":{"uk":"media/ldoce/hwd/bre/e/trite0205.mp3","us":"media/ldoce/hwd/ame/f/trite.mp3"},"examples":[{"en":"Her remarks sounded trite and ill-informed.","cn":"她的发言听起来没有新意﹐也不专业。"}],"oxford":{"phon":"traɪt","pos":"adjective","senses":[{"en":"boring because it has been expressed so many times before; not original","cn":"老生常谈的；陈腐的；老一套的","ex":{"en":"As trite as it sounds, I had forgotten what greenness was until I saw those palms.","cn":"尽管听起来很老套，但在我看到那些棕榈树之前，我已经忘记了绿色是什么。"}}]}},"tranquil":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平静的;安静的;宁静的","en":"Something that is tranquil is calm and peaceful.","ex":{"en":"The tranquil atmosphere of The Connaught allows guests to feel totally at home","cn":"康诺特酒店的宁静氛围让客人完全找到了宾至如归的感觉。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not making a loud sound","cn":""},{"en":"quiet – especially because you do not want people to hear or be disturbed","cn":""},{"en":"quiet and pleasant to listen to","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When a place or your state of mind is peaceful, quiet and serene, it is tranquil ."}]},"collocations":{"phrases":["VERBS be, lie, look, seem The village lay tranquil in the evening sunlight. | become | remain","ADV. extremely, very, wonderfully | perfectly, quite | fairly, rather"]},"media":{"uk":"media/ldoce/hwd/bre/4/tranquil0205.mp3","us":"media/ldoce/hwd/ame/3/tranquil.mp3"},"examples":[{"en":"She led a tranquil life in the country.","cn":"她过着恬静的乡村生活。"},{"en":"the tranquil waters of the lake","cn":"平静无波的湖水"}],"oxford":{"phon":"ˈtræŋkwɪl","pos":"adjective","senses":[{"en":"quiet and peaceful","cn":"安静的；平静的；安宁的","ex":{"en":"a tranquil scene","cn":"静谧的景象"}}]}},"treasure":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"金银财宝","en":"Treasure is a collection of valuable old objects such as gold coins and jewels that has been hidden or lost.","ex":{"en":"It was here, the buried treasure, she knew it was.","cn":"就在这里，那些埋藏在地下的财宝，她知道就在这里。"}},{"pos":"N-COUNT 可数名词","cn":"珍品，珍宝(尤指艺术品和文物)","en":"Treasures are valuable objects, especially works of art and items of historical value.","ex":{"en":"The house was large and full of art treasures.","cn":"房子很大，里面摆满了艺术珍品。"}},{"pos":"VERB 动词","cn":"珍藏;珍视;珍爱","en":"If you treasure something that you have, you keep it or care for it carefully because it gives you great pleasure and you think it is very special.","ex":{"en":"She treasures her memories of those joyous days.","cn":"她珍视那段快乐时光的记忆。"}},{"pos":"N-COUNT 可数名词","cn":"得力助手;好帮手","en":"If you say that someone is a treasure, you mean that they are very helpful and useful to you.","ex":{"en":"Charlie? Oh, he's a treasure, loves children.","cn":"查理？噢，他是个不可多得的好帮手，非常喜欢孩子。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"valuable personal possessions such as jewellery, cameras, and important documents","cn":""},{"en":"very valuable works of art, especially ones that are very old","cn":""},{"en":"a group of valuable things such as gold, silver, jewels etc","cn":"金银财宝"}]},"vocab":{"pos":"n v","senses":[{"en":"Treasure is usually associated with riches — gold, jewels, doubloons — the stuff contained in pirates' treasure chests. However, you can also treasure things with purely sentimental value — like your pet rock or your blankie."}]},"collocations":{"phrases":["ADJ. buried, hidden, lost, sunken | pirate, Roman, royal | vast a vast treasure of medieval manuscripts","VERB + TREASURE hunt for, look for, search for | dig up, discover, find, uncover, unearth | hide","TREASURE + NOUN chest, house, trove (figurative) This book is a treasure house of information on Arctic birds. | hunter, hunting","PHRASES a hoard of treasure 2 sth that is very valuable","ADJ. great, priceless | rare | ancient | forgotten, hidden, secret, unexpected Many forgotten treasures have been discovered in the attics o","VERB + TREASURE discover, find, uncover, unearth"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdetreasure.mp3","us":"media/ldoce/hwd/ame/8/treasure1.mp3"},"examples":[{"en":"the priceless art treasures of the Uffizi Gallery","cn":"乌菲齐美术馆收藏的无价艺术瑰宝"},{"en":"This ring is my most treasured possession.","cn":"这枚戒指是我最珍爱的财产。"}],"oxford":{"phon":"ˈtreʒə(r)","pos":"noun","senses":[{"en":"a collection of valuable things such as gold, silver and jewellery","cn":"金银财宝；珠宝；财富","g":"[uncountable]","ex":{"en":"buried treasure","cn":"埋藏的财宝"}},{"en":"a highly valued object","cn":"极贵重的物品；珍宝；宝物；珍品","g":"[countable, usually plural]","ex":{"en":"the priceless art treasures of the Uffizi Gallery","cn":"乌菲齐美术馆收藏的无价艺术瑰宝"}},{"en":"a person who is much loved or valued","cn":"备受宠爱（或器重）的人；心肝宝贝儿","g":"[singular]","ex":{"en":"Liz is an absolute treasure—I couldn’t do without her.","cn":"莉兹绝对是一个宝藏——我离不开她。"}},{"en":"to have or keep something that you love and that is extremely valuable to you","cn":"珍视；珍爱；珍重；珍藏","ex":{"en":"I treasure his friendship.","cn":"我珍重他的友谊。"},"pos":"verb"}]}},"trice":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"立即;转眼之间;瞬间","en":"If someone does something in a trice, they do it very quickly.","ex":{"en":"He will sew it up in a trice","cn":"他眨眼间就能缝补好。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"very quickly or soon","cn":"一刹那，瞬间"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld44trice.mp3","us":"media/ldoce/hwd/ame/8/ld44trice.mp3"},"examples":[{"en":"He was gone in a trice.","cn":"转眼之间他就没影儿了。"},{"en":"He should be here in a trice.","cn":"他应该很快就到这儿了。"}]},"trashy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"质量低劣的;蹩脚的;廉价的","en":"If you describe something as trashy, you think it is of very poor quality.","ex":{"en":"I was reading some trashy romance novel.","cn":"我正在读一本写得很烂的言情小说。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"of extremely bad quality","cn":"质量极其粗劣的﹔毫无价值的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/trashy0205.mp3","us":"media/ldoce/hwd/ame/8/trashy.mp3"},"examples":[{"en":"trashy TV shows","cn":"无聊的电视节目"},{"en":"trashy novels","cn":"垃圾小说"}],"oxford":{"phon":"ˈtræʃi","pos":"adjective","senses":[{"en":"of poor quality; with no value","cn":"蹩脚的；无价值的","ex":{"en":"trashy TV shows","cn":"无聊的电视节目"}}]}},"trickster":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"骗子;(常指)诈骗钱财的人","en":"A trickster is a person who deceives or cheats people, often in order to get money from them."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who deceives or cheats people","cn":"骗子"},{"en":"confidence trickster British English a slick, fast-talking confidence trickster","cn":"一名花言巧语﹑口若悬河的骗子"}]},"media":{"uk":"media/ldoce/hwd/bre/a/trickster0205.mp3","us":"media/ldoce/hwd/ame/b/trickster.mp3"},"oxford":{"phon":"ˈtrɪkstə(r)","pos":"noun","senses":[{"en":"a person who tricks or cheats people","cn":"骗子","ex":{"en":"He sold the car to a trickster who paid with a worthless stolen cheque.","cn":"他把车卖给了一个骗子，骗子用偷来的一张毫无价值的支票付款。"}}]}},"transit":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"运输;运送;载运","en":"Transit is the carrying of goods or people by vehicle from one place to another.","ex":{"en":"During their talks, the two presidents discussed the transit of goods between the two countries.","cn":"会谈中，两位总统讨论了两国间货物运输的问题。"}},{"pos":"ADJ 形容词","cn":"中转的;过境的;临时的","en":"A transit area is an area where people wait or where goods are kept between different stages of a journey.","ex":{"en":"...refugees arriving at the two transit camps.","cn":"到达两个临时难民营的难民"}},{"pos":"N-UNCOUNT 不可数名词","cn":"交通运输系统","en":"A transit system is a system for moving people or goods from one place to another, for example using buses or trains.","ex":{"en":"The president wants to improve the nation's highways and mass transit systems.","cn":"总统希望改善该国的公路与公共交通系统。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the business of taking large quantities of goods from one place to another","cn":""},{"en":"while being taken from one place to another","cn":""},{"en":"the process of moving goods or people from one place to another 〔","cn":"货物或人的〕运输"}]},"vocab":{"pos":"1 n v 2 n v","senses":[{"en":"Transit means “journey,” and saying you’re \"in transit \" means you’re on your way somewhere. Before we had cell phones, one of the upsides of being in transit was that no one could get in touch with you."}]},"collocations":{"phrases":["ADJ. air, rail, road, sea | mass An improved mass transit system would cut traffic on the roads. | rapid","TRANSIT + NOUN point The port has become a transit point in the drug trade. | camp a transit camp for refugees | lounge The passengers had b","PREP. in ~ Many of the goods were damaged in transit. | ~ between goods in transit between factory and store | ~ from, ~ to in transit from "]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdetransit.mp3","us":"media/ldoce/hwd/ame/1/transit.mp3"},"examples":[{"en":"The ship is currently transiting the Gulf of Mexico.","cn":"这艘船现在正穿越墨西哥湾。"},{"en":"the transit lounge at Vienna airport","cn":"维也纳机场中转候机室"}],"oxford":{"phon":"ˈtrænzɪt","pos":"noun","senses":[{"en":"the process of being moved or carried from one place to another","cn":"运输；运送；搬运；载运","g":"[uncountable]","ex":{"en":"The cost includes transit.","cn":"成本中包括运费。"}},{"en":"the act of going through a place on the way to somewhere else","cn":"通过；经过；通行；过境；中转","g":"[uncountable, countable, usually singular]","ex":{"en":"the transit lounge at Vienna airport","cn":"维也纳机场中转候机室"}},{"en":"the system of buses, trains, etc. that people use to travel from one place to another","cn":"交通运输系统","g":"[uncountable]","lab":"North American English","ex":{"en":"the city’s mass/public transit system","cn":"城市的公共交通运输系统"}},{"en":"to pass across or through an area","cn":"穿过；经过；越过","ex":{"en":"The ship is currently transiting the Gulf of Mexico.","cn":"这艘船现在正穿越墨西哥湾。"},"pos":"verb"},{"en":"a type of large van that is used for delivering goods, carrying equipment, etc.","cn":"全顺商用车","ex":{"en":"Transit vans used by gas engineers","cn":"天然气工程师使用的运输车"}}]}},"transept":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(十字形教堂的)耳堂","en":"In a cathedral or church, the transept is the part which projects to the north or south of the main part of the building."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the two parts of a church that are built out from the main area of the church to form a cross shape 〔","cn":"建在教堂主体两边以形成十字形的〕耳堂"}]},"vocab":{"pos":"n","senses":[{"en":"A transept is the section of a building that runs perpendicular to its main part, forming a kind of cross shape. Many transepts are found in churches."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41transept.mp3","us":"media/ldoce/hwd/ame/0/transept.mp3"},"oxford":{"phon":"ˈtrænsept","pos":"noun","senses":[{"en":"either of the two wide parts of a church in the shape of a cross, that are built at right angles to the main central part","cn":"（十字形教堂的）耳堂","ex":{"en":"the north/south transept of the cathedral","cn":"大教堂的北[南]耳堂。"}}]}},"trenchant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（批评、评论等）鲜明的，犀利的，尖锐的，中肯的","en":"You can use trenchant to describe something such as a criticism or comment that is very clear, effective, and forceful.","ex":{"en":"He was shattered and bewildered by this trenchant criticism","cn":"他因这番尖锐的批评而万念俱灰，茫然不知所措。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"expressed very strongly, effectively, and directly without worrying about offending people","cn":"尖锐的﹐犀利的﹐锐利的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you're trenchant , it means you think or say smart, sharply worded things that cut right to the heart of the matter. A trenchant observation is one that makes people scratch their chins thoughtfully, or wince with embarrassment for whomever you're talking about, or both."}]},"media":{"uk":"media/ldoce/hwd/bre/1/trenchant0205.mp3","us":"media/ldoce/hwd/ame/f/trenchant.mp3"},"examples":[{"en":"Stockman became one of the president’s most trenchant critics.","cn":"斯托克曼成了总统最尖锐的批评者之一。"}],"oxford":{"phon":"ˈtrentʃənt","pos":"adjective","senses":[{"en":"expressed strongly and effectively, in a clear way","cn":"尖锐的；有效的；鲜明的","ex":{"en":"His trenchant views on the subject are well known.","cn":"他对这个问题的尖锐观点是众所周知的。"}}]}},"trudge":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（尤指因疲惫或沮丧）拖着沉重的脚步走，步履艰难地走","en":"If you trudge somewhere, you walk there slowly and with heavy steps, especially because you are tired or unhappy.","ex":{"en":"We had to trudge up the track back to the station.","cn":"我们不得不沿路艰难地走回车站。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to walk in a slow tired way because it is difficult to continue walking, or you do not want to go somewhere","cn":""},{"en":"to walk slowly in a tired way – often used about a horse, donkey etc","cn":""},{"en":"to walk very slowly and noisily without lifting your feet off the ground","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"The noun trudge describes a long, difficult walk. You know those stories your grandparents tell about how they used to walk six miles uphill in the brutal cold every morning just to get to school? They're describing a trudge ."}]},"collocations":{"phrases":["ADV. slowly trudging slowly back to the office | wearily He trudged wearily on down the road. | along, back, home, off, on trudging along in","PREP. across, along, around, down, through, up We trudged slowly through the fields."]},"media":{"uk":"media/ldoce/hwd/bre/d/trudge0205.mp3","us":"media/ldoce/hwd/ame/1/trudge1.mp3"},"examples":[{"en":"He trudged the last two miles to the town.","cn":"他步履艰难地走完最后两英里到了城里。"},{"en":"The men trudged up the hill, laden with supplies.","cn":"这些人背着补给品疲惫地往山上爬。"}],"oxford":{"phon":"trʌdʒ","pos":"verb","senses":[{"en":"to walk slowly or with heavy steps, because you are tired or carrying something heavy","cn":"（因疲劳或负重而）步履沉重地走，缓慢地走，费力地走","ex":{"en":"He trudged the last two miles to the town.","cn":"他步履艰难地走完最后两英里到了城里。"}},{"en":"a long walk that makes you tired","cn":"长途跋涉；疲惫的长途步行","pos":"noun"}]}},"trigonometry":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"三角学","en":"Trigonometry is the branch of mathematics that is concerned with calculating the angles of triangles or the lengths of their sides."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of mathematics concerned with the relationship between the angles and sides of triangle s 〔","cn":"数学中的〕三角学"}]},"vocab":{"pos":"n","senses":[{"en":"Trigonometry is the branch of math that focuses on triangles. A student who loves trigonometry may have a career as a mathematician in her future, or as a musician specializing in playing the triangle (just kidding)."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41trigonometry.mp3","us":"media/ldoce/hwd/ame/3/trigonometry.mp3"},"oxford":{"phon":"ˌtrɪɡəˈnɒmətri","pos":"noun","senses":[{"en":"the type of mathematics that deals with the relationship between the sides and angles of triangles","cn":"三角学"}]}},"trance":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"催眠状态;出神状态","en":"A trance is a state of mind in which someone seems to be asleep and to have no conscious control over their thoughts or actions, but in which they can see and hear things and respond to commands given by other people.","ex":{"en":"Like a man in a trance, Blake found his way back to his rooms","cn":"布莱克神思恍惚地回到了自己的房间。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a state in which you behave as if you were asleep but are still able to hear and understand what is said to you","cn":"催眠状态"},{"en":"a state in which you are thinking about something so much that you do not notice what is happening around you","cn":"心神恍惚﹔出神﹐发呆"},{"en":"a type of popular electronic dance music with a fast beat and long continuous notes played on a synthesizer","cn":"迷幻电子乐〔一种用电子音乐合成器演奏的流行电子舞曲〕"}]},"vocab":{"pos":"n v","senses":[{"en":"If your eyes are open but you're not fully awake and in control, you may be in trance. Someone might have hypnotized you, or just a glimpse of your latest heartthrob might send you into a trance ."}]},"collocations":{"phrases":["ADJ. catatonic, deep | light | hypnotic, mesmeric","VERB + TRANCE fall into, go into | put sb into | come out of, awake/wake from","TRANCE + NOUN state","PREP. in a ~ In a deep trance, the subject is taken back to an earlier stage of their life."]},"media":{"uk":"media/ldoce/hwd/bre/2/trance0205.mp3","us":"media/ldoce/hwd/ame/6/trance.mp3"},"examples":[{"en":"to go/fall into a trance","cn":"进入/陷入昏睡状态"},{"en":"She went into a deep hypnotic trance.","cn":"她陷入了深度催眠状态。"}],"oxford":{"phon":"trɑːns","pos":"noun","senses":[{"en":"a state in which somebody seems to be asleep but is aware of what is said to them, for example if they are hypnotized","cn":"昏睡状态；催眠状态","g":"[countable]","ex":{"en":"to go/fall into a trance","cn":"进入／陷入昏睡状态"}},{"en":"a state in which you are thinking so much about something that you do not notice what is happening around you","cn":"出神；发呆","g":"[countable]","ex":{"en":"She drove, gripping the wheel in a trance, hardly aware of her surroundings.","cn":"她开着车，神情恍惚地握着方向盘，简直没留意置身何处。"}},{"en":"a type of electronic dance music with hypnotic rhythms and sounds","cn":"迷幻音乐","g":"[uncountable]"}]}},"trophy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(竞赛、赛跑等的)奖品，奖杯","en":"A trophy is a prize, for example a silver cup, that is given to the winner of a competition or race."},{"pos":"N-IN-NAMES 名称名词","cn":"(用于一些竞赛或赛跑的名称后)…杯，…奖","en":"Trophy is used in the names of some competitions and races in which the winner receives a trophy.","ex":{"en":"He finished third in the Tote Gold Trophy.","cn":"他在托特黄金大奖赛中获得季军。"}},{"pos":"N-COUNT 可数名词","cn":"胜利纪念品;战利品","en":"A trophy is something that you keep in order to show that you have done something very difficult.","ex":{"en":"His office was lined with animal heads, trophies of his hunting hobby.","cn":"他办公室挂满了兽头，都是他业余打猎获得的战利品。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is given to the person who wins a competition, game, or race","cn":""},{"en":"a special silver or gold container, shaped like a large cup with two handles, that is given to the winner of a sports competition","cn":""},{"en":"a round flat piece of metal that is given to someone who has won a race, game, or competition","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A trophy is a prize given for winning a competition. Often made of metal or plastic meant to look like it, a trophy may not have much monetary value, but the pride it gives the person who receives it can be priceless."}]},"collocations":{"phrases":["ADJ. major | coveted, prestigious, prized | quiz, racing, sporting, swimming, etc. | championship","VERB + TROPHY lift, pick up, receive, take, win Britain has not lifted the trophy since it last hosted the event. | award, present | defend ","TROPHY + NOUN cabinet | winner","PREP. ~ for He picked up a trophy for best news editor."]},"media":{"img":["media/ldoce/img/trophy.jpg","media/thumb/trophy.jpg"],"uk":"media/ldoce/hwd/bre/f/trophy0205.mp3","us":"media/ldoce/hwd/ame/6/trophy.mp3"},"examples":[{"en":"We don't need a trophy building for our business.","cn":"我们的企业不需要豪华奢侈的建筑。"},{"en":"walls lined with banners and athletic trophies","cn":"布满锦旗和运动奖杯的墙"}],"oxford":{"phon":"ˈtrəʊfi","pos":"noun","senses":[{"en":"an object such as a silver cup that is given as a prize for winning a competition","cn":"（颁发给竞赛获胜者的）奖品，奖杯，奖座","ex":{"en":"a trophy cabinet","cn":"奖杯柜"}},{"en":"used in the names of some competitions and races in which a trophy is given to the winner","cn":"（用于竞赛或赛跑名称）奖，奖杯"},{"en":"an object that you keep to show that you were successful in something, especially hunting or war","cn":"（尤指狩猎或战争中获得的）纪念品，战利品"},{"en":"an impressive or beautiful thing or person that you have in order to make other people admire you","cn":"炫耀的；摆阔的；招摇的","ex":{"en":"We don't need a trophy building for our business.","cn":"我们的企业不需要豪华奢侈的建筑。"},"pos":"adjective"}]}},"trombone":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"长号;伸缩长号","en":"A trombone is a large musical instrument of the brass family. It consists of two long oval tubes, one of which can be pushed backwards and forwards to play different notes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large metal musical instrument that you play by blowing into it and sliding a long tube in and out to change the notes","cn":"长号﹐伸缩长号〔一种乐器〕"}]},"collocations":{"phrases":["ADJ. muted | bass, tenor | slide •"]},"media":{"img":["media/ldoce/img/trombone.jpg","media/thumb/trombone.jpg"],"uk":"media/ldoce/hwd/bre/7/trombone0205.mp3","us":"media/ldoce/hwd/ame/c/trombone.mp3"},"oxford":{"phon":"trɒmˈbəʊn","pos":"noun","senses":[{"en":"a large brass musical instrument that you blow into, with a sliding tube used to change the note","cn":"长号"}]}},"troopship":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"运兵舰;军队运输船","en":"A troopship is a ship on which large numbers of soldiers are taken from one place to another."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a ship used for moving soldiers","cn":"部队运输船﹐运兵船"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41troopship.mp3","us":"media/ldoce/hwd/ame/2/troopship.mp3"},"oxford":{"phon":"ˈtruːpʃɪp","pos":"noun","senses":[{"en":"a ship used for transporting soldiers","cn":"部队运输船；运兵船"}]}},"transact":{"collins":{"senses":[{"pos":"VERB 动词","cn":"办理，处理(生意、交易等)","en":"If you transact business, you enter into a deal with someone, for example by buying or selling something.","ex":{"en":"This would free them to transact business across state lines","cn":"这将使他们能够跨越州界进行交易。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do business with someone","cn":"办理（业务）﹐做（交易）"}]},"vocab":{"pos":"v","senses":[{"en":"The verb transact is almost always used with the word \"business.\" To transact business is to conduct it, as when a shopkeeper sells groceries to a customer."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41transact.mp3","us":"media/ldoce/hwd/ame/2/transact.mp3"},"examples":[{"en":"buyers and sellers transacting business","cn":"进行交易的买方和卖方"},{"en":"Most deals are transacted over the phone.","cn":"大多数生意都是在电话里成交的。"}],"oxford":{"phon":"trænˈzækt","pos":"verb","senses":[{"en":"to do business with a person or an organization","cn":"（与人或组织）做业务，做交易","ex":{"en":"There are new rules about how they transact business with customers.","cn":"有新规定说明他们如何与客户进行交易。"}}]}},"transsexual":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"易性癖者;变性人","en":"A transsexual is a person who has decided that they want to live as a person of the opposite sex, and so has changed their name and appearance in order to do this. Transsexuals sometimes have an operation to change their sex."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man who wants to be a woman and has medical treatment to make him into one, or a woman who wants to be a man and has medical treatment to make her into one","cn":"变性人﹐变性男[女]"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41transsexual.mp3","us":"media/ldoce/hwd/ame/c/transsexual.mp3"},"oxford":{"phon":"trænzˈsekʃuəl","pos":"noun","senses":[{"en":"a person whose gender identity does not match the sex they were said to have at birth, especially a person who has a medical treatment such as hormones or surgery to change their body","cn":"（尤指经医疗手段的）变性人，跨性别者"}]}},"tranche":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(股票的)(一)份，(一)部分","en":"In economics, a tranche of shares in a company, or a tranche of a company, is a number of shares in that company.","ex":{"en":"On February 12th he put up for sale a second tranche of 32 state-owned companies.","cn":"2 月 12 日他把第二批 32 家国有企业的股票抛向市场。"}},{"pos":"N-COUNT 可数名词","cn":"(一)片;(一)部分;(一)组","en":"A tranche of something is a piece, section, or part of it. A tranche of things is a group of them.","ex":{"en":"They risk losing the next tranche of funding","cn":"他们冒着失去下一笔资金的风险。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"part of a larger sum of money or group of shares 〔","cn":"款额或股票的〕一部分﹐一份"}]},"vocab":{"pos":"n","senses":[{"en":"A tranche is a piece or a part of something, usually money. An installment of a loan is a tranche ."}]},"media":{"uk":"media/ldoce/hwd/bre/a/tranche1004.mp3","us":"media/ldoce/hwd/ame/b/tranche1004a.mp3"},"examples":[{"en":"The second tranche of the loan would be repaid over three years.","cn":"贷款的第二期将于三年内还清。"}],"oxford":{"phon":"trɑːnʃ","pos":"noun","senses":[{"en":"one of the parts into which an amount of money or a number of shares in a company is divided","cn":"（款额或股份的）一份，一部分","ex":{"en":"the first tranche of the company’s new share issue","cn":"公司第一期新股发行"}}]}},"traceable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可归因于…的;由…造成的;与…有关的","en":"If one thing is traceable to another, there is evidence to suggest that the first thing was caused by or is connected to the second thing.","ex":{"en":"The probable cause of his death is traceable to an incident in 1724","cn":"他的死亡很可能是由 1724 年的一起事件造成的。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get or see something that you have been searching for","cn":""},{"en":"to find something that was hidden or that people did not know about before","cn":""},{"en":"to find the exact position of something","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If something is traceable , it can be tracked or detected — like an email address or evidence of a crime."}]},"media":{"uk":"media/ldoce/hwd/bre/8/trace_n0205.mp3","us":"media/ldoce/hwd/ame/f/trace1.mp3"},"examples":[{"en":"Most telephone calls are traceable.","cn":"大多数电话都可查出是从哪里打来的。"},{"en":"She had given up all hope of tracing her missing daughter.","cn":""}],"oxford":{"phon":"ˈtreɪsəbl","pos":"adjective","senses":[{"en":"if something is traceable, you can find out where it came from, where it has gone, when it began or what its cause was","cn":"可追溯的；可追踪的；可追本溯源的","ex":{"en":"Most telephone calls are traceable.","cn":"大多数电话都可查出是从哪里打来的。"}}]}},"travelogue":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"旅行见闻讲座;旅行纪录片","en":"A travelogue is a talk or film about travel or about a particular person's travels."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a film or piece of writing that describes travel in a particular country, or a particular person’s travels","cn":"旅行纪录片﹔旅行见闻录﹐游记"}]},"media":{"uk":"media/ldoce/hwd/bre/5/travelogue0205.mp3","us":"media/ldoce/hwd/ame/5/travelogue.mp3"},"oxford":{"phon":"ˈtrævəlɒɡ","pos":"noun","senses":[{"en":"a film, broadcast or piece of writing about travel","cn":"旅行纪录片；旅游广播节目；游记"}]}},"trellis":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(支撑攀缘植物的)棚，架","en":"A trellis is a frame which supports climbing plants."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a frame made of long narrow pieces of wood that cross each other, used to support climbing plants 〔","cn":"用以支撑攀缘植物的〕棚﹐架"}]},"vocab":{"pos":"n v","senses":[{"en":"A trellis is a type of structure used to guide and support climbing plants such as ivy."}]},"media":{"uk":"media/ldoce/hwd/bre/1/trellis0205.mp3","us":"media/ldoce/hwd/ame/c/trellis.mp3"},"oxford":{"phon":"ˈtrelɪs","pos":"noun","senses":[{"en":"a light frame made of long, narrow pieces of wood that cross each other, used to support climbing plants","cn":"（支撑攀缘植物的）棚，架；攀缘架"}]}},"trivialize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"贬低;轻视;使显得琐碎(或简单)","en":"If you say that someone trivializes something important, you disapprove of them because they make it seem less important, serious, and complex than it is.","ex":{"en":"It never ceases to amaze me how the business world continues to trivialize the world's environmental problems.","cn":"商界一直不重视世界环境问题，总让我惊讶不已。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to write or talk about something in a way that makes it seem less serious or important than it really is","cn":""},{"en":"to pretend that a problem, illness etc is less important or serious than it really is","cn":""},{"en":"to say or do something that makes someone's efforts or achievements seem unimportant or useless","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you trivialize something, you make it seem less important than it really is. Some people complain that TV news tends to trivialize complicated political stories."}]},"media":{"uk":"media/ldoce/hwd/bre/2/trivialize0205.mp3","us":"media/ldoce/hwd/ame/7/trivialize.mp3"},"examples":[{"en":"The article trivializes the whole issue of equal rights.","cn":"文章对平等权利这个大问题轻描淡写。"},{"en":"The debate has been trivialized by the media.","cn":"那场辩论在媒体的报道中变得无关紧要。"}],"oxford":{"phon":"ˈtrɪviəlaɪz","pos":"verb","senses":[{"en":"to make something seem less important, serious, difficult, etc. than it really is","cn":"使显得琐碎（或不重要、不难等）；轻视","ex":{"en":"It is important not to trivialize children’s worries.","cn":"不轻视孩子的烦恼很重要。"}}]}},"triceps":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(上臂部的)三头肌","en":"Your triceps is the muscle in the back part of your upper arm."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the large muscle at the back of your upper arm 〔","cn":"手臂上的〕三头肌"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41triceps.mp3","us":"media/ldoce/hwd/ame/3/triceps.mp3"},"oxford":{"phon":"ˈtraɪseps","pos":"noun","senses":[{"en":"the large muscle at the back of the top part of the arm","cn":"三头肌"}]}},"tracker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"追踪者;追捕者;会循迹追踪的动物","en":"A tracker is a person or animal that finds other people or animals by following the marks left by their feet and other signs that show where they have been."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who follows and finds other people, especially by following the marks that they have left on the ground","cn":"追踪者﹐跟踪者"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41tracker.mp3","us":"media/ldoce/hwd/ame/7/laadtracker.mp3"},"oxford":{"phon":"ˈtrækə(r)","pos":"noun","senses":[{"en":"a person who can find people or wild animals by following the marks that they leave on the ground","cn":"追踪者；跟踪者；追踪人（或野兽）的人","ex":{"en":"The trackers located the rhino and darted it with tranquillizing drugs.","cn":"追踪者找到了犀牛，并向它注射了镇静药物。"}},{"en":"a device that follows and records the movements of somebody/something","cn":"追踪器","ex":{"en":"Electronic trackers show how far the animals range in search of food.","cn":"电子追踪器显示动物的觅食范围。"}},{"en":"an investment fund that aims to follow in value a stock market index or group of indexes","cn":"追踪器：旨在追踪股票市场指数或一组指数价值的投资基金","lab":"finance","ex":{"en":"Forget about fund managers and individual shares: choose an index tracker instead.","cn":"忘记基金经理和个股：选择指数跟踪器。"}}]}},"trapper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指为获取毛皮)设陷阱捕兽者","en":"A trapper is a person who traps animals, especially for their fur."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who traps wild animals, especially for their fur 〔","cn":"尤指为获取毛皮的〕设陷阱捕兽者"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41trapper.mp3","us":"media/ldoce/hwd/ame/5/trapper.mp3"},"oxford":{"phon":"ˈtræpə(r)","pos":"noun","senses":[{"en":"a person who traps and kills animals, especially for their fur","cn":"捕杀动物者（尤指为获取毛皮）"}]}},"transpire":{"collins":{"senses":[{"pos":"VERB 动词","cn":"被发现；为人所知","en":"When it transpires that something is the case, people discover that it is the case.","ex":{"en":"It transpired that Paolo had left his driving licence at home","cn":"后来才知道保罗把驾照忘在家里了。"}},{"pos":"VERB 动词","cn":"发生(有些讲英语的人认为该用法不正确)","en":"When something transpires, it happens. Some speakers of English consider this use to be incorrect.","ex":{"en":"Nothing is known as yet about what transpired at the meeting.","cn":"会上到底发生了什么现在还没人知道。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something that people knew nothing about comes out , people find out about it, especially as a result of an official inquiry","cn":""},{"en":"if new information or a new fact comes to light or is brought to light , people find out about it","cn":""},{"en":"if facts emerge from a meeting or an inquiry, people find out about them","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"Transpire is a fancy way of saying \"happen.\" \"What's transpiring ?\" — however — just doesn't have the same ring as \"What's happening?\""}]},"media":{"uk":"media/ldoce/hwd/bre/b/transpire0205.mp3","us":"media/ldoce/hwd/ame/d/transpire.mp3"},"examples":[{"en":"You're meeting him tomorrow? Let me know what transpires.","cn":"你明天和他见面吗？把见面的情况告诉我。"},{"en":"It transpired that the gang had had a contact inside the bank.","cn":"据报这伙歹徒在银行里有内应。"}],"oxford":{"phon":"trænˈspaɪə(r)","pos":"verb","senses":[{"en":"if it transpires that something has happened or is true, it is known or has been shown to be true","cn":"公开；透露；为人所知","g":"[transitive]","ex":{"en":"It transpired that the gang had had a contact inside the bank.","cn":"据报这伙歹徒在银行里有内应。"}},{"en":"to happen","cn":"发生","g":"[intransitive]","ex":{"en":"You're meeting him tomorrow? Let me know what transpires.","cn":"你明天和他见面吗？把见面的情况告诉我。"}},{"en":"when plants or leaves transpire, water passes out from their surface","cn":"（植物）水分蒸发，蒸腾","g":"[intransitive, transitive]","lab":"biology"}]}},"transverse":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"横的;横向的;横断的;横切的","en":"Transverse is used to describe something that is at right angles to something else."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"lying or placed across something","cn":"横向的﹐横的"}]},"vocab":{"pos":"adj","senses":[{"en":"If something is transverse it goes sideways or at an angle. You might take a transverse path cutting across the park — it's a short cut if you're in a hurry, because you don't have to walk the entire length."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41transverse.mp3","us":"media/ldoce/hwd/ame/9/transverse.mp3"},"examples":[{"en":"A transverse bar joins the two posts.","cn":"一根横杆连接着两根立柱。"},{"en":"a transverse beam","cn":"横梁"}],"oxford":{"phon":"ˈtrænzvɜːs","pos":"adjective","senses":[{"en":"placed across something","cn":"横（向）的；横断的；横切的","ex":{"en":"A transverse bar joins the two posts.","cn":"一根横杆连接着两根立柱。"}}]}},"transcribe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"笔录;转写","en":"If you transcribe a speech or text, you write it out in a different form from the one in which it exists, for example by writing it out in full from notes or from a tape recording.","ex":{"en":"She is transcribing, from his dictation, the diaries of Simon Forman","cn":"她正根据他的口述记录西蒙·福曼的日记。"}},{"pos":"VERB 动词","cn":"(为适合其他乐器演奏而)改编(乐曲)","en":"If you transcribe a piece of music for an instrument which is not the one for which it was originally written, you rewrite it so that it can be played on that instrument.","ex":{"en":"He gave up trying to write for the guitar and decided to transcribe the work for piano.","cn":"他放弃了为吉他谱曲，决定把作品改编成钢琴曲。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to write down exactly what someone else has written","cn":""},{"en":"to copy the whole of a piece of writing using exactly the same words as the original","cn":""},{"en":"to copy a short piece of written information such as a list or an address","cn":""}]},"vocab":{"pos":"1 v 2 v 3 v 4 v","senses":[{"en":"If someone asks you to transcribe something, they want you to listen to it and write down what was said, word for word. Speeches, interviews, and trials are often transcribed for records."}]},"media":{"uk":"media/ldoce/hwd/bre/f/transcribe0205.mp3","us":"media/ldoce/hwd/ame/5/transcribe.mp3"},"examples":[{"en":"How many official documents have been transcribed into Braille for blind people?","cn":"有多少官方文件已经转成盲文供盲人阅读？"},{"en":"Clerks transcribe everything that is said in court.","cn":"书记员把在法庭上所有的话都记录在案。"}],"oxford":{"phon":"trænˈskraɪb","pos":"verb","senses":[{"en":"to record thoughts, speech or data in a written form, or in a different written form from the original","cn":"记录；抄录；把…转成（另一种书写形式）","ex":{"en":"Clerks transcribe everything that is said in court.","cn":"书记员把法庭上所说的话全都记录在案。"}},{"en":"to show the sounds of speech using a special phonetic alphabet","cn":"用音标标音","lab":"specialist"},{"en":"to write a piece of music in a different form so that it can be played by a different musical instrument or sung by a different voice","cn":"改编（乐曲，以适合其他乐器或声部）","ex":{"en":"a piano piece transcribed for the guitar","cn":"为吉他改编的钢琴曲"}}]}},"transmit":{"collins":{"senses":[{"pos":"VERB 动词","cn":"传送;传递;播送","en":"When radio and television programmes, computer data, or other electronic messages are transmitted, they are sent from one place to another, using wires, radio waves, or satellites.","ex":{"en":"The game was transmitted live in Spain and Italy","cn":"这场比赛在西班牙和意大利进行了现场直播。"}},{"pos":"VERB 动词","cn":"传播，传染(疾病)","en":"If one person or animal transmits a disease to another, they have the disease and cause the other person or animal to have it.","ex":{"en":"...mosquitoes that transmit disease to humans","cn":"传染疾病给人类的蚊子"}},{"pos":"VERB 动词","cn":"传达，传输(思想、感情)","en":"If you transmit an idea or feeling to someone else, you make them understand and share the idea or feeling.","ex":{"en":"The message they are transmitting to their daughters is very different from that of previous generations…","cn":"他们向女儿传输的信息与上几代人截然不同。"}},{"pos":"VERB 动词","cn":"传导(声、电等)","en":"If an object or substance transmits something such as sound or electrical signals, the sound or signals are able to pass through it.","ex":{"en":"These thin crystals transmit much of the power","cn":"这些薄薄的晶体传导了大部分的动力。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to send out electronic signals, messages etc using radio, television, or other similar equipment","cn":"传输﹐发送﹐传送〔电子信号﹑信息等〕"},{"en":"to send or pass something from one person, place or thing to another","cn":"传递﹐传播"},{"en":"if an object or substance transmits sound or light, it allows sound or light to travel through or along it","cn":"传播〔声音或光〕"}]},"vocab":{"pos":"v","senses":[{"en":"If you’re an international spy, you might transmit secret messages using a special code written in invisible ink. If you aren’t a spy, you could probably just use email. Whatever your circumstances, when you transmit information, you send."}]},"collocations":{"phrases":["ADV. actively | easily, readily | genetically, sexually the study of genetically transmitted diseases","PREP. from, through The disease cannot be transmitted through coughing or sneezing. | to The infection can be transmitted from a mother to h","ADV. automatically | electronically","PREP. from, to automatically transmitting data from one part of the system to another"]},"media":{"uk":"media/ldoce/hwd/bre/0/transmit0205.mp3","us":"media/ldoce/hwd/ame/d/transmit.mp3"},"examples":[{"en":"The ceremony was transmitted live by satellite to over fifty countries.","cn":"典礼通过卫星向五十多个国家进行了实况转播。"},{"en":"Parents can unwittingly transmit their own fears to their children.","cn":"父母自己的恐惧有可能在无意中感染了孩子。"}],"oxford":{"phon":"trænzˈmɪt","pos":"verb","senses":[{"en":"to send an electronic signal, radio or television broadcast, etc.","cn":"传送；输送；发射；播送","g":"[transitive, intransitive]","ex":{"en":"signals transmitted from a satellite","cn":"从卫星传送来的信号"}},{"en":"to pass something from one person to another","cn":"传播；传染","g":"[transitive]","lab":"formal","ex":{"en":"sexually transmitted diseases","cn":"性传播疾病"}},{"en":"to allow heat, light, sound, etc. to pass through","cn":"传（热、声等）；透（光等）；使通过","g":"[transitive]","lab":"specialist","ex":{"en":"Steam only transmits heat when it condenses.","cn":"蒸汽只有在冷凝时才传导热能。"}}]}},"tramp":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"流浪汉;流浪乞丐;游民","en":"A tramp is a person who has no home or job, and very little money. Tramps go from place to place, and get food or money by asking people or by doing casual work."},{"pos":"VERB 动词","cn":"(长时间地)拖着沉重的步子走","en":"If you tramp somewhere, you walk there slowly and with regular, heavy steps, for a long time.","ex":{"en":"They put on their coats and tramped through the falling snow","cn":"他们穿上外套，拖着沉重的步子行走在飞雪中。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"沉重的脚步声","en":"The tramp of people is the sound of their heavy, regular walking.","ex":{"en":"He heard the slow, heavy tramp of feet on the stairs.","cn":"他听到楼梯上传来缓慢沉重的脚步声。"}},{"pos":"N-COUNT 可数名词","cn":"荡妇;淫娃","en":"If someone refers to a woman as a tramp, they are insulting her, because they think that she is immoral in her sexual behaviour."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has no home or regular work","cn":""},{"en":"a person, usually a man, who has no home or regular job and asks people for money on the streets","cn":""},{"en":"a woman with no home or job who carries all her possessions around with her in a bag","cn":""}]},"vocab":{"pos":"1 v n 2 n v 3 n","senses":[{"en":"Tramp means to walk or stomp heavily. Your midnight tramp to the kitchen for milk and cookies doesn't thrill your downstairs neighbors."}]},"media":{"uk":"media/ldoce/hwd/bre/4/tramp_v0205.mp3","us":"media/ldoce/hwd/ame/c/tramp1.mp3"},"examples":[{"en":"We tramped across the wet grass to look at the statue.","cn":"我们踏过湿漉漉的草地去看那座雕像。"},{"en":"She's been tramping the streets looking for a job.","cn":"她一直在大街上四处奔走寻找工作。"}],"oxford":{"phon":"træmp","pos":"noun","senses":[{"en":"a person with no home or job who travels from place to place, usually asking people in the street for food or money","cn":"流浪汉；流浪乞丐","g":"[countable]","ex":{"en":"An old tramp was sitting on a bench.","cn":"一个老流浪汉坐在长椅上。"}},{"en":"the sound of somebody’s heavy steps","cn":"沉重的脚步声","g":"[singular]","ex":{"en":"the tramp of marching feet","cn":"行进中沉重的脚步声"}},{"en":"a long walk","cn":"长途步行；远距离行走","g":"[countable, usually singular]","ex":{"en":"We had a long tramp home.","cn":"我们是经过长途跋涉回家的。"}},{"en":"an offensive word for somebody, usually a woman, who is thought to have many sexual partners","cn":"荡妇；淫妇","lab":"North American English, old-fashioned, offensive，，，，"},{"en":"to walk with heavy or noisy steps, especially for a long time","cn":"（尤指长时间地）重步行走，踏，踩","ex":{"en":"We tramped across the wet grass to look at the statue.","cn":"我们踏过湿漉漉的草地去看那座雕像。"},"pos":"verb"}]}},"transvestite":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(通常指男性)易装癖者","en":"A transvestite is a person, usually a man, who enjoys wearing clothes normally worn by people of the opposite sex."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone, especially a man, who enjoys dressing like a person of the opposite sex","cn":"有异性装扮癖的人﹐易装癖者"}]},"vocab":{"pos":"n adj","senses":[{"en":"A man who identifies himself as a transvestite likes to wear clothing that is typically thought of as feminine or womanly."}]},"media":{"uk":"media/ldoce/hwd/bre/2/transvestite0205.mp3","us":"media/ldoce/hwd/ame/7/transvestite.mp3"},"oxford":{"phon":"trænzˈvestaɪt","pos":"noun","senses":[{"en":"a person, especially a man, who enjoys dressing in clothes usually worn by the opposite sex","cn":"有异性装扮癖的人，易装癖者（尤指男性）"}]}},"trimming":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"装饰(物);镶边","en":"The trimming on something such as a piece of clothing is the decoration, for example along its edges, that is in a different colour or material.","ex":{"en":"...the lace trimming on her satin nightgown.","cn":"她缎子睡衣上的蕾丝花边"}},{"pos":"N-PLURAL 复数名词","cn":"(切取所需部分以后的)下脚料，剩余物","en":"Trimmings are pieces of something, usually food, which are left over after you have cut what you need.","ex":{"en":"Use any pastry trimmings to decorate the apples.","cn":"用剩余的油酥面皮装饰苹果。"}},{"pos":"PHRASE 短语","cn":"种种额外的东西;外加的种种配搭","en":"If you say that something comes with all the trimmings, you mean that it has many extra things added to it to make it more special.","ex":{"en":"They were married with all the trimmings, soon after graduation.","cn":"他们毕业后不久就大操大办地结婚了。"}}]},"examples":[{"en":"a splendid feast of turkey with all the trimmings","cn":"备有各种配料的丰盛火鸡大餐"},{"en":"a white blouse with blue trimming","cn":"有蓝色饰边的白衬衫"}],"oxford":{"phon":"ˈtrɪmɪŋ","pos":"noun","senses":[{"en":"the extra things that it is traditional to have for a special meal or occasion","cn":"（菜肴的）配料；额外的事物","g":"[plural]","lab":"North American English also","ex":{"en":"a splendid feast of turkey with all the trimmings","cn":"备有各种配料的丰盛火鸡大餐"}},{"en":"the small pieces of something that are left when you have cut something","cn":"修剪下来的东西；剪屑","g":"[plural]","ex":{"en":"hedge trimmings","cn":"树篱修剪下来的碎枝叶"}},{"en":"material that is used to decorate something, for example along its edges","cn":"装饰材料；镶边饰物","g":"[uncountable, countable, usually plural]","ex":{"en":"a white blouse with blue trimming","cn":"有蓝色饰边的白衬衫"}}]},"base":"trim"},"triptych":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"三拼画;三拼浮雕","en":"A triptych is a painting or a carving on three panels that are usually joined together by hinges."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a religious picture painted on three pieces of wood that are joined together","cn":"三联画〔画在三块相连木板上的宗教题材绘画〕"}]},"vocab":{"pos":"n","senses":[{"en":"Artists sometimes create a triptych , a series of three panels that are meant to be displayed together."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41triptych.mp3","us":"media/ldoce/hwd/ame/8/triptych.mp3"},"oxford":{"phon":"ˈtrɪptɪk","pos":"noun","senses":[{"en":"a picture that is painted or carved on three pieces of wood placed side by side, especially one over an altar in a church","cn":"三联画；三联雕刻；（尤指）三折圣像画"}]}},"trove":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41trove.mp3","us":"media/ldoce/hwd/ame/1/trove.mp3"}}});
